def _project_type_is_tv_series(project_type: str | None) -> bool:
    """Episode count applies only to TV series projects."""
    from project_settings import project_type_is_tv_series

    return project_type_is_tv_series(project_type)


PROJECT_STATUS_ACTIVE = "active"
PROJECT_STATUS_ARCHIVED = "archived"
PROJECT_STATUS_PENDING = "pending"
PROJECT_STATUS_VALUES: frozenset[str] = frozenset(
    {PROJECT_STATUS_ACTIVE, PROJECT_STATUS_ARCHIVED, PROJECT_STATUS_PENDING}
)


def normalize_project_status(raw: str | None) -> str:
    s = (raw or "").strip().lower()
    if s in PROJECT_STATUS_VALUES:
        return s
    return PROJECT_STATUS_ACTIVE


def project_status_label(status: str | None) -> str:
    return {
        PROJECT_STATUS_ACTIVE: "Active",
        PROJECT_STATUS_ARCHIVED: "Archived",
        PROJECT_STATUS_PENDING: "Pending",
    }.get((status or "").strip().lower(), "Active")


def project_type_icon_bucket(project_type: str | None) -> str:
    """Map free-text project type to icon bucket: film, tv, commercial, default."""
    from project_settings import normalize_project_type_slug

    slug = normalize_project_type_slug(project_type)
    if slug == "tv_series":
        return "tv"
    s = (project_type or "").strip().lower()
    if s == "tv series" or ("tv" in s and "series" in s):
        return "tv"
    if slug in ("feature_film", "short_film", "documentary"):
        return "film"
    if slug in ("commercial", "music_video"):
        return "commercial"
    if "commercial" in s or "music video" in s:
        return "commercial"
    if any(k in s for k in ("feature", "documentary", "short film", "film")):
        return "film"
    return "default"


def project_status_badge_label_ui(status: str | None) -> str:
    st = normalize_project_status(status)
    if st == PROJECT_STATUS_PENDING:
        return "On Hold"
    if st == PROJECT_STATUS_ARCHIVED:
        return "Archived"
    return "Active"


def project_status_badge_modifier_ui(status: str | None) -> str:
    st = normalize_project_status(status)
    if st == PROJECT_STATUS_PENDING:
        return "on-hold"
    if st == PROJECT_STATUS_ARCHIVED:
        return "completed"
    return "active"


