def _vfx_vendor_norm(vendor: str | None) -> str:
    """Normalize vendor string for comparisons (matches editor non-external default)."""
    s = str(vendor or "").strip().lower().replace("-", "_").replace(" ", "_")
    while "__" in s:
        s = s.replace("__", "_")
    return s


