def group_users_by_job_title(users) -> list[tuple[str, list]]:
    """Group directory users by job title for task assignee pickers."""
    if not users:
        return []
    buckets: dict[str, list] = defaultdict(list)
    seen_in_bucket: dict[str, set[int]] = defaultdict(set)
    for u in users:
        titles = u.assigned_job_titles() if hasattr(u, "assigned_job_titles") else []
        if not titles:
            jt = getattr(u, "job_title", None)
            titles = [jt] if jt else []
        if not titles:
            label = "No job title"
            if u.id not in seen_in_bucket[label]:
                buckets[label].append(u)
                seen_in_bucket[label].add(u.id)
            continue
        for jt in titles:
            label = (jt.name if jt and (jt.name or "").strip() else None) or "No job title"
            if u.id not in seen_in_bucket[label]:
                buckets[label].append(u)
                seen_in_bucket[label].add(u.id)
    for lst in buckets.values():
        lst.sort(key=lambda x: (getattr(x, "name", None) or "").lower())
    return sorted(buckets.items(), key=lambda kv: kv[0].lower())


def job_title_picker_groups(categories: list) -> list[tuple[str, list]]:
    """Build (category_name, job_titles[]) for searchable picker optgroups."""
    groups: list[tuple[str, list]] = []
    for cat in categories:
        if not getattr(cat, "is_active", True):
            continue
        titles = sorted(
            [
                jt
                for jt in (getattr(cat, "job_titles", None) or [])
                if getattr(jt, "is_active", True)
            ],
            key=lambda jt: (getattr(jt, "name", None) or "").lower(),
        )
        if titles:
            groups.append((cat.name, titles))
    return groups


def job_title_picker_json(
    groups: list[tuple[str, list]],
    categories: list | None = None,
    title_meta: dict | None = None,
) -> list[dict]:
    """Serialize grouped job titles for client-side category/title pickers."""
    from project_settings import parse_linked_post_scope_keys, post_scope_key_set

    valid_scope_keys = post_scope_key_set()
    cat_by_name = {str(getattr(c, "name", "") or ""): c for c in (categories or [])}
    meta_by_id = title_meta or {}

    def scope_keys_for_category_name(cat_name: str) -> list[str]:
        cat = cat_by_name.get(cat_name)
        if cat is None:
            return []
        linked = (
            cat.linked_scope_keys_list()
            if hasattr(cat, "linked_scope_keys_list")
            else parse_linked_post_scope_keys(getattr(cat, "linked_post_scope_keys", None))
        )
        return [key for key in linked if key in valid_scope_keys]

    out = []
    for cat_name, titles in groups:
        cat = cat_by_name.get(cat_name)
        row = {
            "category": cat_name,
            "is_active": bool(getattr(cat, "is_active", True)) if cat else True,
            "titles": [],
        }
        for jt in titles:
            extra = meta_by_id.get(int(jt.id), {})
            row["titles"].append(
                {
                    "id": jt.id,
                    "name": jt.name,
                    "is_active": bool(getattr(jt, "is_active", True)),
                    "user_type": getattr(jt, "user_type", None) or "employee",
                    "scope_keys": scope_keys_for_category_name(cat_name),
                    "category_name": extra.get("category_name") or cat_name,
                    "employment_codes": [
                        c.get("code") for c in (extra.get("employment_chips") or []) if c.get("code")
                    ],
                    "scope_names": [
                        c.get("name") for c in (extra.get("scope_chips") or []) if c.get("name")
                    ],
                }
            )
        out.append(row)
    return out


