def _normalized_account_role_key(raw: str | None) -> str:
    """Lowercase role string with spaces/dashes folded to underscores (matches form values)."""
    if not raw:
        return ""
    return re.sub(r"[\s\-]+", "_", raw.strip().lower())


def account_role_is_administrator(role: str | None) -> bool:
    """True when the access role is Administrator or Super user (same privileges)."""
    return _normalized_account_role_key(role) in (ROLE_ADMIN, ROLE_SUPER_USER)


def _normalized_guest_access_level(raw: str | None) -> str:
    level = (raw or GUEST_ACCESS_VIEWER).strip().lower()
    if level in GUEST_ACCESS_LEVELS:
        return level
    return GUEST_ACCESS_VIEWER


def account_is_guest(acc: Account | None) -> bool:
    return acc is not None and _normalized_account_role_key(acc.role) == ROLE_GUEST


def guest_access_level_for(acc: Account | None) -> str:
    if acc is None:
        return GUEST_ACCESS_VIEWER
    return _normalized_guest_access_level(getattr(acc, "guest_access_level", None))


def guest_effective_role_key(acc: Account | None) -> str:
    from permissions import GUEST_ROLE_APPROVER, GUEST_ROLE_REVIEWER, GUEST_ROLE_VIEWER

    level = guest_access_level_for(acc)
    if level == GUEST_ACCESS_APPROVER:
        return GUEST_ROLE_APPROVER
    if level == GUEST_ACCESS_REVIEWER:
        return GUEST_ROLE_REVIEWER
    return GUEST_ROLE_VIEWER

