def _display_name_from_email(email: str) -> str:
    local = email.split("@", 1)[0] if email else ""
    label = local.replace(".", " ").replace("_", " ").strip()
    return label.title() if label else "User"


def _safe_next_url(target: str | None) -> str:
    if target and target.startswith("/") and not target.startswith("//"):
        return target
    return url_for("index")


def create_app() -> Flask:
    app = Flask(__name__)
    app.config["APP_NAME"] = os.environ.get("APP_NAME", "BIGbang Studios")
    test_db_uri = (os.environ.get("TASK_MANAGER_TEST_DATABASE") or "").strip()
    if test_db_uri:
        app.config["TESTING"] = True
    if not app.config.get("TESTING"):
        security_support_mod.enforce_production_config()
    app.config["SECRET_KEY"] = security_support_mod.resolve_secret_key()
    security_support_mod.configure_secure_session(app)
    # Local development: pick up template/static edits without a full restart.
    if not security_support_mod.is_production_env():
        app.config["TEMPLATES_AUTO_RELOAD"] = True
        app.config["SEND_FILE_MAX_AGE_DEFAULT"] = 0
        app.jinja_env.auto_reload = True
    app.config["ALLOW_PUBLIC_REGISTER"] = security_support_mod.resolve_allow_public_register()
    configured_roots = security_support_mod.parse_allowed_storage_roots()
    app.config["ALLOWED_STORAGE_ROOTS"] = list(configured_roots) if configured_roots else []
    db_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "instance", "app.db")
    os.makedirs(os.path.dirname(db_path), exist_ok=True)
    upload_root = os.path.join(os.path.dirname(db_path), "uploads", "avatars")
    os.makedirs(upload_root, exist_ok=True)
    app.config["PROFILE_AVATAR_UPLOAD_FOLDER"] = upload_root
    chat_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "chat")
    os.makedirs(chat_upload_root, exist_ok=True)
    scene_ref_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "scene_refs")
    os.makedirs(scene_ref_upload_root, exist_ok=True)
    vfx_version_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "vfx_versions")
    os.makedirs(vfx_version_upload_root, exist_ok=True)
    episode_script_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "episode_scripts")
    os.makedirs(episode_script_upload_root, exist_ok=True)
    episode_media_upload_root = os.path.join(os.path.dirname(db_path), "uploads")
    os.makedirs(episode_media_upload_root, exist_ok=True)
    script_document_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "script_documents")
    os.makedirs(script_document_upload_root, exist_ok=True)
    delivery_doc_upload_root = os.path.join(os.path.dirname(db_path), "uploads", "delivery_docs")
    os.makedirs(delivery_doc_upload_root, exist_ok=True)
    shooting_scene_thumbnail_upload_root = os.path.join(
        os.path.dirname(db_path), "uploads", "shooting_scene_thumbnails"
    )
    os.makedirs(shooting_scene_thumbnail_upload_root, exist_ok=True)
    shooting_day_report_upload_root = os.path.join(
        os.path.dirname(db_path), "uploads", "shooting_day_reports"
    )
    os.makedirs(shooting_day_report_upload_root, exist_ok=True)
    # Uploads stay under instance/ (outside /static); never serve raw trees as static files.
    app.config["UPLOAD_ROOT"] = os.path.dirname(upload_root)
    if test_db_uri:
        app.config["SQLALCHEMY_DATABASE_URI"] = test_db_uri
        app.config["TESTING"] = True
    else:
        app.config["SQLALCHEMY_DATABASE_URI"] = f"sqlite:///{db_path}?timeout=30"
    app.config["SQLALCHEMY_TRACK_MODIFICATIONS"] = False
    app.config.setdefault(
        "CHAT_CONFERENCE_PROVIDER",
        (os.environ.get("CHAT_CONFERENCE_PROVIDER") or "jitsi").strip().lower(),
    )
    app.config.setdefault(
        "CHAT_CONFERENCE_JITSI_BASE_URL",
        (os.environ.get("CHAT_CONFERENCE_JITSI_BASE_URL") or "https://meet.jit.si").strip(),
    )

    db.init_app(app)
    _csrf = security_support_mod.configure_csrf(app)
    app.extensions["csrf"] = _csrf
    security_support_mod.register_security_headers(app)

    # --- i18n (English / Arabic) ---
    app.config["BABEL_DEFAULT_LOCALE"] = i18n_support_mod.DEFAULT_LOCALE
    app.config["BABEL_SUPPORTED_LOCALES"] = list(i18n_support_mod.SUPPORTED_LOCALES)
    app.config["BABEL_TRANSLATION_DIRECTORIES"] = os.path.join(
        app.root_path, "translations"
    )

    def _select_locale() -> str:
        return i18n_support_mod.session_lang()

    babel = Babel(app, locale_selector=_select_locale)

    socketio.init_app(
        app,
        cors_allowed_origins=security_support_mod.socketio_cors_origins(),
        manage_session=False,
        always_connect=True,
    )

