    class User(db.Model):
        __tablename__ = "users"

        id = db.Column(db.Integer, primary_key=True)
        name = db.Column(db.String(120), nullable=False)
        email = db.Column(db.String(255), nullable=False, unique=True)
        account_id = db.Column(db.Integer, db.ForeignKey("accounts.id"), nullable=True, unique=True)
        job_title_id = db.Column(db.Integer, db.ForeignKey("job_titles.id"), nullable=True)
        phone = db.Column(db.String(40), nullable=True)
        employment_type_code = db.Column(db.String(40), nullable=True, index=True)
        company = db.Column(db.String(160), nullable=True)
        department_code = db.Column(db.String(40), nullable=True, index=True)
        avatar_kind = db.Column(db.String(16), nullable=False, default="preset")
        avatar_preset = db.Column(db.String(8), nullable=False, default="01")
        avatar_upload = db.Column(db.String(255), nullable=True)
        created_at = db.Column(db.DateTime, default=now_local)

        account = db.relationship("Account", backref=db.backref("directory_user", uselist=False))
        job_title = db.relationship("JobTitle", backref=db.backref("users", lazy=True))
        user_job_title_links = db.relationship(
            "UserJobTitle",
            back_populates="user",
            cascade="all, delete-orphan",
            order_by="UserJobTitle.sort_order",
            lazy=True,
        )

        def assigned_job_titles(self) -> list:
            links = self.user_job_title_links or []
            titles = [link.job_title for link in links if link.job_title is not None]
            if titles:
                return titles
            if self.job_title is not None:
                return [self.job_title]
            return []

        def assigned_job_title_ids(self) -> list[int]:
            return [int(jt.id) for jt in self.assigned_job_titles() if jt.id is not None]

        def lead_job_title_label(self) -> str:
            """Job title shown in team previews — highest editorial priority wins."""
            titles = self.assigned_job_titles()
            if not titles:
                return ""

            def _prio(name: str) -> int:
                n = (name or "").strip().lower()
                if "film editor" in n:
                    return 0
                if "main editor" in n:
                    return 1
                if "post-producer" in n or "post producer" in n:
                    return 2
                compact = n.replace(" ", "").replace("-", "")
                if "postproducer" in compact:
                    return 2
                if "editor" in n:
                    return 3
                return 4

            best = min(titles, key=lambda jt: (_prio(jt.name or ""), (jt.name or "").lower()))
            return (best.name or "").strip()
        tasks = db.relationship(
            "Task",
            foreign_keys="Task.user_id",
            backref=db.backref("assignee", foreign_keys="Task.user_id"),
            lazy=True,
            cascade="all, delete-orphan",
        )
        requested_tasks = db.relationship(
            "Task",
            foreign_keys="Task.requested_by_id",
            back_populates="requested_by",
            lazy=True,
        )

