    def _utc_now() -> datetime:
        """Naive Africa/Cairo wall time for ORM columns (same as :func:`now_local`)."""
        return now_local()

    def _cairo_now_aware() -> datetime:
        """Current instant as timezone-aware Cairo (for deltas vs stored naive rows)."""
        return datetime.now(CAIRO_TZ)

    def _ensure_cairo_aware(dt: datetime | None) -> datetime | None:
        """Interpret naive datetimes as Cairo wall time; return timezone-aware Cairo."""
        if dt is None:
            return None
        if dt.tzinfo is None:
            return dt.replace(tzinfo=CAIRO_TZ)
        return dt.astimezone(CAIRO_TZ)

    def isoformat_stored_instant(dt: datetime | None) -> str:
        """ISO-8601 string for JSON (naive = Cairo wall clock; no trailing Z)."""
        if dt is None or not isinstance(dt, datetime):
            return ""
        if dt.tzinfo is not None:
            dt = dt.astimezone(CAIRO_TZ).replace(tzinfo=None)
        return dt.replace(microsecond=0).isoformat(timespec="seconds")

    def _epoch_ms_from_stored_naive(dt: datetime | None) -> float:
        if dt is None or not isinstance(dt, datetime):
            return 0.0
        if dt.tzinfo is None:
            aware = dt.replace(tzinfo=CAIRO_TZ)
        else:
            aware = dt.astimezone(CAIRO_TZ)
        return float(aware.timestamp() * 1000.0)

    def format_datetime_cairo(dt: date | datetime | None, fmt: str = "%Y-%m-%d %H:%M") -> str:
        """Format stored naive Cairo datetime for server-rendered HTML."""
        if dt is None:
            return "—"
        if isinstance(dt, date) and not isinstance(dt, datetime):
            return dt.isoformat()
        if not isinstance(dt, datetime):
            return "—"
        if dt.tzinfo is not None:
            dt = dt.astimezone(CAIRO_TZ).replace(tzinfo=None)
        return dt.strftime(fmt)

    def _notification_unresolved_filter():
        """Treat NULL is_resolved as open (SQLite / legacy rows)."""
        return or_(Notification.is_resolved.is_(False), Notification.is_resolved.is_(None))

    def _notification_critical_dashboard_filter():
        """Unresolved rows that count on the dashboard /criticals page."""
        sev = db.func.lower(db.func.coalesce(Notification.severity, ""))
        et = db.func.lower(db.func.coalesce(Notification.entity_type, ""))
        return or_(
            sev == "critical",
            and_(sev == "error", et == "shooting_day_critical"),
        )

    def _notification_rule_key(rule: str, entity_type: str, entity_id: int, user_id: int) -> str:
        return f"{rule}:{entity_type}:{int(entity_id)}:{int(user_id)}"

    def _notification_alloc_rule_key(
        rule: str, entity_type: str, entity_id: int, user_id: int
    ) -> str | None:
        """Choose a unique rule_key, or None if an unresolved row already exists for this event."""
        et = (entity_type or "").strip() or "unknown"
        eid = int(entity_id or 0)
        uid = int(user_id)
        r = (rule or "").strip() or "rule"
        base_rk = _notification_rule_key(r, et, eid, uid)
        if (
            Notification.query.filter_by(rule_key=base_rk)
            .filter(_notification_unresolved_filter())
            .first()
            is not None
        ):
            return None
        if Notification.query.filter_by(rule_key=base_rk).first() is None:
            return base_rk
        return _notification_rule_key(
            f"{r}#{int(_utc_now().timestamp() * 1000)}", et, eid, uid
        )

    def _directory_user_display_name(user_id: int | None) -> str:
        if user_id is None:
            return "—"
        u = db.session.get(User, int(user_id))
        if u is None:
            return f"User {int(user_id)}"
        return (u.name or f"User {u.id}").strip()

    def _format_cairo_display(ts: datetime | None) -> str:
        if ts is None:
            return ""
        aware = _ensure_cairo_aware(ts)
        if aware is None:
            return ""
        return aware.strftime("%Y-%m-%d %H:%M")

    def _critical_note_audit_parts(note: ShootingDayCriticalNote) -> list[str]:
        """Human audit trail: date + who added / edited / solved."""
        parts: list[str] = []
        created_s = _format_cairo_display(note.created_at)
        created_by = ""
        if note.created_by_user_id is not None:
            created_by = (_directory_user_display_name(int(note.created_by_user_id)) or "").strip()
            if created_by in ("—",):
                created_by = ""
        if created_s and created_by:
            parts.append(f"{created_s}, added by {created_by}")
        elif created_s:
            parts.append(f"{created_s}, added")
        elif created_by:
            parts.append(f"added by {created_by}")

        updated_s = _format_cairo_display(note.updated_at)
        updated_by = ""
        if note.updated_by_user_id is not None:
            updated_by = (_directory_user_display_name(int(note.updated_by_user_id)) or "").strip()
            if updated_by in ("—",):
                updated_by = ""
        if updated_s and updated_by:
            parts.append(f"{updated_s}, edited by {updated_by}")
        elif updated_s:
            parts.append(f"{updated_s}, edited")
        elif updated_by:
            parts.append(f"edited by {updated_by}")

        solved_s = _format_cairo_display(note.solved_at)
        solved_by = ""
        if note.solved_by_user_id is not None:
            solved_by = (_directory_user_display_name(int(note.solved_by_user_id)) or "").strip()
            if solved_by in ("—",):
                solved_by = ""
        if solved_s and solved_by:
            parts.append(f"{solved_s}, solved by {solved_by}")
        elif solved_s:
            parts.append(f"{solved_s}, solved")
        elif solved_by:
            parts.append(f"solved by {solved_by}")
        return parts

    def _critical_note_audit_label(note: ShootingDayCriticalNote) -> str:
        return " · ".join(_critical_note_audit_parts(note))

    def _resolve_notification_sender(
        *,
        actor: Account | None = None,
        sender_user_id: int | None = None,
        sender_label: str | None = None,
    ) -> tuple[int | None, str]:
        if sender_label:
            label = sender_label.strip()
            return sender_user_id, label or "System"
        if sender_user_id is not None:
            return int(sender_user_id), _directory_user_display_name(int(sender_user_id))
        if actor is not None:
            uid = directory_user_id_for_account(actor)
            name = (getattr(actor, "display_name", None) or actor.username or "User").strip()
            return uid, name or "User"
        return None, "System"

    def _record_notification_log(
        *,
        notification_id: int | None,
        recipient_user_id: int,
        title: str,
        message: str,
        n_type: str,
        severity: str,
        entity_type: str,
        entity_id: int,
        project_id: int | None,
        rule_key: str,
        created_at=None,
        sender_user_id: int | None = None,
        sender_name: str = "",
    ) -> None:
        recipient_name = _directory_user_display_name(int(recipient_user_id))
        db.session.add(
            NotificationLog(
                notification_id=int(notification_id) if notification_id else None,
                sender_user_id=int(sender_user_id) if sender_user_id is not None else None,
                sender_name=(sender_name or "System").strip() or "System",
                recipient_user_id=int(recipient_user_id),
                recipient_name=recipient_name,
                type=(n_type or "activity").strip() or "activity",
                severity=(severity or "info").strip() or "info",
                title=(title or "").strip(),
                message=(message or "").strip(),
                entity_type=(entity_type or "").strip(),
                entity_id=int(entity_id or 0),
                project_id=int(project_id) if project_id is not None else None,
                rule_key=(rule_key or "").strip(),
                created_at=created_at or _utc_now(),
            )
        )

    def _create_notification(
        *,
        recipient_user_id: int,
        title: str,
        message: str,
        n_type: str = "activity",
        severity: str = "info",
        entity_type: str = "",
        entity_id: int = 0,
        project_id: int | None = None,
        rule: str = "",
        rule_key: str | None = None,
        created_at=None,
        actor: Account | None = None,
        sender_user_id: int | None = None,
        sender_label: str | None = None,
    ) -> Notification | None:
        """Create a user notification and append an audit log row."""
        uid = int(recipient_user_id)
        et = (entity_type or "").strip() or "unknown"
        eid = int(entity_id or 0)
        rk = rule_key
        if not rk:
            rk = _notification_alloc_rule_key((rule or "").strip() or "rule", et, eid, uid)
        if rk is None:
            return None
        when = created_at or _utc_now()
        if rule_key:
            existing = Notification.query.filter_by(rule_key=rk).first()
            if existing is not None:
                existing.type = (n_type or "activity").strip() or "activity"
                existing.severity = (severity or "info").strip() or "info"
                existing.title = (title or "").strip()
                existing.message = scrub_notification_template_tags(message or "")
                existing.entity_type = et
                existing.entity_id = eid
                existing.project_id = int(project_id) if project_id is not None else None
                existing.is_read = False
                existing.is_acknowledged = False
                existing.is_resolved = False
                existing.created_at = when
                db.session.flush()
                s_uid, s_name = _resolve_notification_sender(
                    actor=actor, sender_user_id=sender_user_id, sender_label=sender_label
                )
                _record_notification_log(
                    notification_id=int(existing.id),
                    recipient_user_id=uid,
                    title=existing.title,
                    message=existing.message,
                    n_type=existing.type,
                    severity=existing.severity,
                    entity_type=existing.entity_type,
                    entity_id=int(existing.entity_id or 0),
                    project_id=(int(existing.project_id) if existing.project_id is not None else None),
                    rule_key=existing.rule_key,
                    sender_user_id=s_uid,
                    sender_name=s_name,
                    created_at=when,
                )
                return existing
        n = Notification(
            user_id=uid,
            type=(n_type or "activity").strip() or "activity",
            severity=(severity or "info").strip() or "info",
            title=(title or "").strip(),
            message=scrub_notification_template_tags(message or ""),
            entity_type=et,
            entity_id=eid,
            project_id=int(project_id) if project_id is not None else None,
            is_read=False,
            is_acknowledged=False,
            is_resolved=False,
            rule_key=rk,
            created_at=when,
        )
        db.session.add(n)
        db.session.flush()
        s_uid, s_name = _resolve_notification_sender(
            actor=actor, sender_user_id=sender_user_id, sender_label=sender_label
        )
        _record_notification_log(
            notification_id=int(n.id),
            recipient_user_id=uid,
            title=n.title,
            message=n.message,
            n_type=n.type,
            severity=n.severity,
            entity_type=n.entity_type,
            entity_id=int(n.entity_id or 0),
            project_id=n.project_id,
            rule_key=n.rule_key,
            created_at=when,
            sender_user_id=s_uid,
            sender_name=s_name,
        )
        return n

    def _project_team_user_ids(project_id: int | None) -> list[int]:
        if project_id is None:
            return []
        rows = ProjectMember.query.filter_by(project_id=int(project_id)).all()
        return sorted({int(m.user_id) for m in rows if m.user_id is not None})

    _NOTIFICATION_TEMPLATE_RE = re.compile(r"{{\s*([a-zA-Z0-9_]+)(?:\|default\(\"([^\"]*)\"\))?\s*}}")
    _NOTIFICATION_IF_ELSE_RE = re.compile(
        r"\{%-?\s*if\s+([a-zA-Z0-9_]+)\s*-?%\}(.*?)"
        r"\{%-?\s*else\s*-?%\}(.*?)"
        r"\{%-?\s*endif\s*-?%\}",
        re.DOTALL,
    )
    _NOTIFICATION_IF_RE = re.compile(
        r"\{%-?\s*if\s+([a-zA-Z0-9_]+)\s*-?%\}(.*?)"
        r"\{%-?\s*endif\s*-?%\}",
        re.DOTALL,
    )
    _NOTIFICATION_TAG_RE = re.compile(r"\{%-?\s*.*?\s*-?%\}", re.DOTALL)

    def _notification_ctx_truthy(ctx: dict, key: str) -> bool:
        val = ctx.get(key)
        return val not in (None, "", False, 0)

    def scrub_notification_template_tags(text: str | None) -> str:
        """Remove leftover Jinja control tags from stored/rendered notification text."""
        cleaned = _NOTIFICATION_TAG_RE.sub("", text or "")
        cleaned = re.sub(r"[ \t]+\n", "\n", cleaned)
        cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
        return cleaned.strip()

    def render_notification_template(template_string: str | None, context: dict | None) -> str:
        ctx = context or {}

        def repl(match) -> str:
            key = match.group(1)
            default = match.group(2)
            val = ctx.get(key)
            if val is None or val == "":
                return default or ""
            return str(val)

        text = _NOTIFICATION_TEMPLATE_RE.sub(repl, template_string or "")

        def if_else_repl(match: re.Match[str]) -> str:
            return match.group(2) if _notification_ctx_truthy(ctx, match.group(1)) else match.group(3)

        def if_repl(match: re.Match[str]) -> str:
            return match.group(2) if _notification_ctx_truthy(ctx, match.group(1)) else ""

        # Support simple one-level {% if var %}…{% else %}…{% endif %} used in event defaults.
        for _ in range(4):
            nxt = _NOTIFICATION_IF_ELSE_RE.sub(if_else_repl, text)
            nxt = _NOTIFICATION_IF_RE.sub(if_repl, nxt)
            if nxt == text:
                break
            text = nxt

        return scrub_notification_template_tags(text)

    def _notification_json(raw: str | None, fallback):
        try:
            data = json.loads(raw or "")
            return data if isinstance(data, type(fallback)) else fallback
        except (TypeError, ValueError):
            return fallback

    def _managed_audit(
        *,
        rule: NotificationRule | None,
        event_key: str,
        project_id: int | None,
        actor_user_id: int | None,
        recipient_ids: list[int] | None = None,
        title: str | None = None,
        body: str | None = None,
        cta_url: str | None = None,
        status: str = "sent",
        error: str = "",
    ) -> None:
        db.session.add(
            NotificationRuleAuditLog(
                rule_id=int(rule.id) if rule is not None else None,
                event_key=(event_key or "").strip(),
                project_id=int(project_id) if project_id is not None else None,
                actor_id=int(actor_user_id) if actor_user_id is not None else None,
                resolved_recipient_ids=json.dumps(sorted({int(x) for x in (recipient_ids or [])})),
                title_rendered=title,
                body_rendered=body,
                cta_url=cta_url,
                status=status,
                error=error or "",
                created_at=now_local(),
            )
        )

    def _managed_user_titles(user: User | None) -> list[str]:
        if user is None:
            return []
        titles = user.assigned_job_titles() if hasattr(user, "assigned_job_titles") else []
        if not titles and getattr(user, "job_title", None) is not None:
            titles = [user.job_title]
        return [(t.name or "").strip() for t in titles if t is not None and (t.name or "").strip()]

    def _managed_user_matches_job_title(user: User, wanted: list[str]) -> bool:
        needles = [(x or "").strip().casefold() for x in wanted if (x or "").strip()]
        if not needles:
            return False
        for title in _managed_user_titles(user):
            hay = title.casefold()
            if any(n in hay for n in needles):
                return True
        return False

    def _managed_project_members(project: Project | None) -> list[User]:
        if project is None:
            return []
        rows = (
            ProjectMember.query.filter_by(project_id=int(project.id))
            .options(joinedload(ProjectMember.user).joinedload(User.job_title))
            .all()
        )
        return [m.user for m in rows if m.user is not None]

    def _managed_user_matches_project_role(user: User, role: str) -> bool:
        role_key = (role or "").strip().casefold().replace(" ", "_")
        acc = db.session.get(Account, int(user.account_id)) if user.account_id else None
        acc_role = _normalized_account_role_key(acc.role) if acc is not None else ""
        titles = " ".join(_managed_user_titles(user)).casefold()
        if role_key == "admin":
            return bool(acc and acc.is_admin)
        if role_key == "producer":
            return acc_role == ROLE_PRODUCER or "producer" in titles
        if role_key == "post_producer":
            return "post producer" in titles or "head of post" in titles or acc_role == ROLE_PRODUCER
        if role_key == "production_manager":
            return "production manager" in titles or "production coordinator" in titles
        if role_key == "supervisor":
            return "supervisor" in titles
        if role_key == "client":
            return acc_role == "guest" or "client" in titles
        return False

    def _managed_context_user_id(context: dict, keys: tuple[str, ...]) -> int | None:
        for key in keys:
            val = context.get(key)
            if val is None:
                continue
            if isinstance(val, User):
                return int(val.id)
            try:
                return int(val)
            except (TypeError, ValueError):
                continue
        return None

    def resolve_notification_recipients(
        rule: NotificationRule,
        project: Project | None,
        actor: Account | None,
        context: dict | None,
    ) -> list[User]:
        cfg = _notification_json(rule.recipient_config_json, {})
        ctx = context or {}
        members = _managed_project_members(project)
        out: dict[int, User] = {}

        if cfg.get("all_project_members"):
            for u in members:
                out[int(u.id)] = u

        for uid in cfg.get("user_ids", []) or []:
            try:
                u = db.session.get(User, int(uid))
            except (TypeError, ValueError):
                u = None
            if u is not None:
                out[int(u.id)] = u

        wanted_titles = cfg.get("job_titles", []) or []
        if wanted_titles:
            for u in members:
                if _managed_user_matches_job_title(u, wanted_titles):
                    out[int(u.id)] = u

        wanted_scopes = set(cfg.get("post_scopes", []) or [])
        if wanted_scopes:
            from project_settings import collect_user_post_scope_keys

            for u in members:
                if collect_user_post_scope_keys(u) & wanted_scopes:
                    out[int(u.id)] = u

        wanted_roles = cfg.get("project_roles", []) or []
        if wanted_roles:
            for u in members:
                if any(_managed_user_matches_project_role(u, role) for role in wanted_roles):
                    out[int(u.id)] = u

        dynamic_map = {
            "assigned_user": ("assigned_user_id", "assigned_to_id", "task_user_id", "user_id"),
            "requested_by": ("requested_by_id",),
            "created_by": ("created_by_id",),
            "department_assigned_user": ("department_assigned_user_id",),
            "editing_item_assigned_editor": ("editing_item_assigned_editor_id", "editor_user_id"),
            "color_assigned_user": ("color_assigned_user_id", "colorist_user_id"),
            "vfx_assigned_user": ("vfx_assigned_user_id", "vfx_artist_user_id"),
        }
        for dyn in cfg.get("dynamic", []) or []:
            uid = _managed_context_user_id(ctx, dynamic_map.get(dyn, (f"{dyn}_id",)))
            if uid is not None:
                u = db.session.get(User, int(uid))
                if u is not None:
                    out[int(u.id)] = u

        if rule.exclude_actor:
            actor_uid = directory_user_id_for_account(actor) if actor is not None else None
            if actor_uid is not None:
                out.pop(int(actor_uid), None)
        return sorted(out.values(), key=lambda u: (u.name or "").lower())

    def _managed_conditions_pass(rule: NotificationRule, context: dict | None) -> tuple[bool, str]:
        cfg = _notification_json(rule.condition_config_json, {})
        ctx = context or {}
        for key, expected in (cfg.get("equals") or {}).items():
            if str(ctx.get(key, "")) != str(expected):
                return False, f"{key} != {expected}"
        for key, expected in (cfg.get("truthy") or {}).items():
            if bool(ctx.get(key)) is not bool(expected):
                return False, f"{key} truthy check failed"
        return True, ""

    def _managed_dedupe_hit(rule: NotificationRule, project_id: int | None, title: str, body: str) -> bool:
        if not rule.dedupe_enabled or int(rule.dedupe_window_minutes or 0) <= 0:
            return False
        cutoff = now_local() - timedelta(minutes=int(rule.dedupe_window_minutes or 30))
        q = NotificationRuleAuditLog.query.filter(
            NotificationRuleAuditLog.event_key == rule.event_key,
            NotificationRuleAuditLog.status.in_(("sent", "sent_test")),
            NotificationRuleAuditLog.created_at >= cutoff,
            NotificationRuleAuditLog.title_rendered == title,
            NotificationRuleAuditLog.body_rendered == body,
        )
        if project_id is not None:
            q = q.filter(NotificationRuleAuditLog.project_id == int(project_id))
        return q.first() is not None

    def _managed_event_key_from_legacy_rule(rule: str | None) -> str:
        raw = (rule or "").strip()
        if not raw:
            return "legacy_notification"
        prefix = re.split(r"[|:#]", raw, maxsplit=1)[0].strip()
        specific = {
            "shooting_day_critical": "critical_note_added",
            "shooting_day_critical_solved": "critical_note_solved",
            "vfx_dept_assign": "vfx_shot_assigned",
            "vfx_dept_status": "vfx_shot_status_changed",
            "vfx_sent_dept": "vfx_shot_sent_to_department",
            "vfx_unassigned": "vfx_shot_unassigned",
            "color_edit_upload": "handoff_file_uploaded",
            "color_edit_delete": "handoff_file_deleted",
            "color_sent": "editing_item_sent_to_color",
            "color_item_assigned": "color_item_assigned",
        }
        # Exact token match (not startswith) so "shooting_day_critical_solved"
        # does not collide with "shooting_day_critical".
        if prefix in specific:
            return specific[prefix]
        if raw.startswith("vfx_client_"):
            return "vfx_client_review_action"
        if raw.startswith("mr_copy_finished"):
            return "machine_room_copy_finished"
        if raw.startswith("mr_convert_started"):
            return "machine_room_convert_started"
        if raw.startswith("mr_convert_declined"):
            return "machine_room_convert_declined"
        if raw.startswith("mr_convert_finished"):
            return "machine_room_convert_finished"
        if raw.startswith("mr_copy_cancelled"):
            return "machine_room_copy_cancelled"
        if raw.startswith("mr_convert_cancelled"):
            return "machine_room_convert_cancelled"
        safe = re.sub(r"[^a-zA-Z0-9_]+", "_", prefix).strip("_").lower()
        return safe or "legacy_notification"

    def send_managed_notification(
        event_key: str,
        *,
        project: Project | None = None,
        actor: Account | None = None,
        context: dict | None = None,
        fallback_title: str | None = None,
        fallback_body: str | None = None,
        fallback_url: str | None = None,
        fallback_recipient_user_ids: list[int] | None = None,
        test_recipient_user_ids: list[int] | None = None,
        is_test: bool = False,
    ) -> list[User]:
        ctx = dict(context or {})
        if project is not None:
            ctx.setdefault("project_id", int(project.id))
            ctx.setdefault("project_name", project.name or "Project")
        actor_uid = directory_user_id_for_account(actor) if actor is not None else None
        actor_name = (getattr(actor, "display_name", None) or getattr(actor, "username", None) or "System").strip() if actor is not None else "System"
        ctx.setdefault("actor_id", actor_uid or "")
        ctx.setdefault("actor_name", actor_name)
        ctx.setdefault("current_date", today_cairo().isoformat())
        ctx.setdefault("current_time", now_local().strftime("%H:%M"))

        project_id = int(project.id) if project is not None else (int(ctx["project_id"]) if str(ctx.get("project_id", "")).isdigit() else None)
        rule = NotificationRule.query.filter_by(event_key=(event_key or "").strip()).first()
        if rule is None:
            _managed_audit(
                rule=None,
                event_key=event_key,
                project_id=project_id,
                actor_user_id=actor_uid,
                recipient_ids=fallback_recipient_user_ids or [],
                title=fallback_title,
                body=fallback_body,
                cta_url=fallback_url,
                status="failed",
                error="missing_rule",
            )
            recipients = []
            for uid in fallback_recipient_user_ids or []:
                u = db.session.get(User, int(uid))
                if u is not None:
                    recipients.append(u)
            if not recipients or not fallback_title or not fallback_body:
                return []
            title = fallback_title
            body = cg.notification_message_with_action(fallback_body, "Open", fallback_url) if fallback_url else fallback_body
        else:
            if not rule.is_enabled:
                _managed_audit(
                    rule=rule,
                    event_key=event_key,
                    project_id=project_id,
                    actor_user_id=actor_uid,
                    status="skipped_disabled",
                )
                return []
            ok, why = _managed_conditions_pass(rule, ctx)
            if not ok:
                _managed_audit(
                    rule=rule,
                    event_key=event_key,
                    project_id=project_id,
                    actor_user_id=actor_uid,
                    status="skipped_no_recipients",
                    error=why,
                )
                return []
            recipients = resolve_notification_recipients(rule, project, actor, ctx)
            if test_recipient_user_ids is not None:
                recipients = [u for u in (db.session.get(User, int(uid)) for uid in test_recipient_user_ids) if u is not None]
            title = render_notification_template(rule.title_template, ctx).strip()
            body_raw = render_notification_template(rule.body_template, ctx).strip()
            cta_label = render_notification_template(rule.cta_label_template, ctx).strip()
            cta_url = render_notification_template(rule.cta_url_template, ctx).strip()
            body = cg.notification_message_with_action(body_raw, cta_label, cta_url) if cta_label and cta_url else body_raw
            if _managed_dedupe_hit(rule, project_id, title, body):
                _managed_audit(
                    rule=rule,
                    event_key=event_key,
                    project_id=project_id,
                    actor_user_id=actor_uid,
                    recipient_ids=[int(u.id) for u in recipients],
                    title=title,
                    body=body,
                    cta_url=cta_url,
                    status="skipped_dedupe",
                )
                return []

        if not recipients:
            if fallback_recipient_user_ids:
                for uid in fallback_recipient_user_ids:
                    u = db.session.get(User, int(uid))
                    if u is not None:
                        recipients.append(u)
                if rule is not None and rule.exclude_actor:
                    actor_uid = directory_user_id_for_account(actor) if actor is not None else None
                    if actor_uid is not None:
                        recipients = [u for u in recipients if int(u.id) != int(actor_uid)]
            if not recipients:
                _managed_audit(
                    rule=rule,
                    event_key=event_key,
                    project_id=project_id,
                    actor_user_id=actor_uid,
                    title=title,
                    body=body,
                    status="skipped_no_recipients",
                )
                return []

        sent: list[User] = []
        rule_id = int(rule.id) if rule is not None else 0
        explicit_severity = (ctx.get("notification_severity") or "").strip().lower()
        if explicit_severity in ("critical", "error", "warning", "info"):
            severity = explicit_severity
        else:
            severity = {"low": "info", "normal": "info", "high": "warning", "urgent": "error"}.get(
                rule.priority if rule is not None else "normal",
                "info",
            )
        for u in recipients:
            n = _create_notification(
                recipient_user_id=int(u.id),
                title=title,
                message=body,
                n_type="activity",
                severity=severity,
                entity_type=(ctx.get("entity_type") or event_key or "notification"),
                entity_id=int(ctx.get("entity_id") or ctx.get("task_id") or ctx.get("editing_item_id") or ctx.get("shot_id") or 0),
                project_id=project_id,
                rule_key=f"managed:{event_key}:{rule_id}:{int(project_id or 0)}:{int(ctx.get('approval_request_id') or ctx.get('entity_id') or ctx.get('task_id') or ctx.get('editing_item_id') or 0)}:{int(u.id)}:{'test' if is_test else 'live'}:{int(now_local().timestamp()) if (is_test or rule is None or not rule.dedupe_enabled) else ''}",
                actor=actor,
            )
            if n is not None:
                sent.append(u)
                if u.account_id:
                    emit_notification_to_account(
                        int(u.account_id),
                        {
                            "type": "managed_notification",
                            "title": title,
                            "message": body,
                            "project_id": project_id,
                            "href": fallback_url or ctx.get("href") or "",
                        },
                    )
        _managed_audit(
            rule=rule,
            event_key=event_key,
            project_id=project_id,
            actor_user_id=actor_uid,
            recipient_ids=[int(u.id) for u in sent],
            title=title,
            body=body,
            cta_url=(render_notification_template(rule.cta_url_template, ctx).strip() if rule is not None else fallback_url),
            status="sent_test" if is_test else "sent",
        )
        return sent

    def _notification_emit_to_project(
        *,
        project_id: int | None,
        rule: str,
        n_type: str,
        severity: str,
        title: str,
        message: str,
        entity_type: str,
        entity_id: int,
        extra_user_ids: Sequence[int] | None = None,
        actor: Account | None = None,
    ) -> None:
        """Create one notification per project team member (user-specific rows)."""
        if project_id is None:
            return
        uid_list = _notification_recipient_user_ids(
            int(project_id), extra_user_ids, actor=actor
        )
        if not uid_list:
            return
        eid = int(entity_id or 0)
        et = (entity_type or "").strip() or "unknown"
        r = (rule or "").strip() or "rule"
        event_key = _managed_event_key_from_legacy_rule(r)
        project = db.session.get(Project, int(project_id))
        if project is not None:
            sent = send_managed_notification(
                event_key,
                project=project,
                actor=actor,
                context={
                    "project_id": int(project_id),
                    "project_name": project.name or "Project",
                    "entity_type": et,
                    "entity_id": eid,
                    "notification_title": title,
                    "notification_body": message,
                    "notification_severity": (severity or "info").strip().lower(),
                    "legacy_rule": r,
                    "task_id": eid if et == "task" else 0,
                    "shot_id": eid if et == "vfx_shot" else 0,
                    "delivery_id": eid if et == "delivery" else 0,
                    "booking_id": eid if et == "booking" else 0,
                },
                fallback_title=title,
                fallback_body=message,
                fallback_url="",
                fallback_recipient_user_ids=uid_list,
            )
            if sent:
                db.session.flush()
                _notification_push_realtime_for_project(project_id, actor=actor)
                return
        sender_uid, sender_name = _resolve_notification_sender(actor=actor)
        for uid in uid_list:
            _create_notification(
                recipient_user_id=uid,
                title=title,
                message=message,
                n_type=n_type,
                severity=severity,
                entity_type=et,
                entity_id=eid,
                project_id=int(project_id),
                rule=r,
                actor=actor,
            )
        db.session.flush()
        _notification_push_realtime_for_project(project_id, actor=actor)

    def _notification_push_realtime_for_project(
        project_id: int | None, *, actor: Account | None = None
    ) -> None:
        """Ask connected clients to refresh the notification panel."""
        if project_id is None:
            return
        pid = int(project_id)
        for uid in _notification_recipient_user_ids(pid, actor=actor):
            acc_id = _directory_user_account_id(uid)
            if acc_id is None:
                continue
            try:
                emit_notification_to_account(
                    acc_id,
                    {"type": "notifications_changed", "project_id": pid},
                )
            except Exception:
                app.logger.exception("notifications_changed push failed")

    def _machine_room_actor_label(actor: Account | None) -> str:
        if actor is None:
            return "Machine Room"
        return (actor.display_name or actor.email or "Machine Room").strip()

    def _notify_machine_project_team(
        *,
        project_id: int,
        rule: str,
        title: str,
        message: str,
        entity_type: str,
        entity_id: int,
        severity: str = "info",
        n_type: str = "activity",
        actor: Account | None = None,
    ) -> None:
        """Activity notification for project team (non–Machine Room when actor is MR)."""
        _notification_emit_to_project(
            project_id=project_id,
            rule=rule,
            n_type=n_type,
            severity=severity,
            title=title,
            message=message,
            entity_type=entity_type,
            entity_id=int(entity_id),
            actor=actor,
        )

    def _is_inhouse_post_producer_job_title(name: str | None) -> bool:
        n = (name or "").strip().lower()
        if not n:
            return False
        if n in ("post-producer in-house", "post producer in-house"):
            return True
        has_post = "post-producer" in n or "post producer" in n
        compact = n.replace(" ", "").replace("-", "")
        if not has_post and "postproducer" not in compact:
            return False
        return "in-house" in n or "in house" in n or "inhouse" in compact

    def _vfx_inhouse_post_producer_project_user_ids(project_id: int) -> set[int]:
        out: set[int] = set()
        for m in (
            ProjectMember.query.filter_by(project_id=int(project_id))
            .options(joinedload(ProjectMember.user).joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title))
            .all()
        ):
            u = m.user
            if u is None:
                continue
            for jt in u.assigned_job_titles():
                if _is_inhouse_post_producer_job_title(jt.name):
                    out.add(int(u.id))
                    break
        return out

    def _directory_user_account_id(user_id: int) -> int | None:
        u = db.session.get(User, int(user_id))
        if u is None or u.account_id is None:
            return None
        return int(u.account_id)

    def _directory_user_is_machine_room_role(user_id: int) -> bool:
        acc_id = _directory_user_account_id(user_id)
        if acc_id is None:
            return False
        acc = db.session.get(Account, acc_id)
        return acc is not None and _normalized_account_role_key(acc.role) == ROLE_MACHINE_ROOM

    def _machine_room_role_directory_user_ids() -> list[int]:
        """Directory user ids for every account with the Machine Room role."""
        out: set[int] = set()
        for acc in Account.query.filter(Account.role.isnot(None)).all():
            if _normalized_account_role_key(acc.role) != ROLE_MACHINE_ROOM:
                continue
            uid = directory_user_id_for_account(acc)
            if uid is not None:
                out.add(int(uid))
        return sorted(out)

    def _notify_machine_room_role_accounts(
        *,
        rule: str,
        title: str,
        message: str,
        entity_type: str,
        entity_id: int,
        project_id: int | None = None,
        severity: str = "warning",
        n_type: str = "activity",
        actor: Account | None = None,
    ) -> int:
        """Create one notification per Machine Room role account. Returns rows created."""
        created = 0
        pid = int(project_id) if project_id is not None else None
        for uid in _machine_room_role_directory_user_ids():
            n = _create_notification(
                recipient_user_id=uid,
                title=title,
                message=message,
                n_type=n_type,
                severity=severity,
                entity_type=entity_type,
                entity_id=int(entity_id),
                project_id=pid,
                rule=rule,
                actor=actor,
                sender_label="System",
            )
            if n is None:
                continue
            created += 1
            acc_id = _directory_user_account_id(uid)
            if acc_id is None:
                continue
            try:
                emit_notification_to_account(
                    acc_id,
                    {"type": "notifications_changed", "project_id": pid},
                )
            except Exception:
                app.logger.exception("machine room role notification push failed")
        return created

    def _notification_recipient_user_ids(
        project_id: int,
        extra_user_ids: Sequence[int] | None = None,
        *,
        actor: Account | None = None,
    ) -> list[int]:
        base = set(_project_team_user_ids(project_id))
        for x in extra_user_ids or ():
            try:
                base.add(int(x))
            except (TypeError, ValueError):
                continue
        uid_list = sorted(base)
        if actor is not None and _normalized_account_role_key(actor.role) == ROLE_MACHINE_ROOM:
            uid_list = [uid for uid in uid_list if not _directory_user_is_machine_room_role(uid)]
        return uid_list

    def _notify_vfx_dept_shot_assigned(
        project_id: int,
        shot: VfxShot,
        new_artist_user_id: int,
        old_artist_user_id: int | None,
        *,
        assigned_by: Account | None = None,
    ) -> None:
        """Notify the newly-assigned VFX artist only.

        Per product decision: when user A assigns a shot to user B, only B is
        notified. The assignor never sees a notification about their own
        action, and supervisors / in-house post producers are not broadcast
        on a single-shot assignment. The `assigned_by` argument is kept for
        the message body (so B knows who assigned them).
        """
        new_i = int(new_artist_user_id)
        old_i = int(old_artist_user_id) if old_artist_user_id is not None else None
        if old_i == new_i:
            return
        # Suppress self-assignment self-notification (e.g. an artist picks
        # their own shot through the supervisor UI).
        assigner_uid = (
            directory_user_id_for_account(assigned_by) if assigned_by is not None else None
        )
        if assigner_uid is not None and int(assigner_uid) == new_i:
            return

        proj = db.session.get(Project, int(project_id))
        proj_name = (proj.name if proj else None) or "Project"
        if assigned_by is not None:
            sender = (assigned_by.username or "").strip() or assigned_by.display_login
        else:
            sender = "Someone"
        code = shot.shot_code or f"Shot {shot.id}"
        eid = int(shot.id)
        dept_href = url_for("vfx_department_workspace", project_id=int(project_id))

        title = f"Shot assigned: {code}"
        msg = f"{code} was assigned to you on {proj_name} by {sender}."
        rule = f"vfx_dept_assign_{shot.id}_{new_i}"
        et = "vfx_shot"
        managed = send_managed_notification(
            "vfx_shot_assigned",
            project=proj,
            actor=assigned_by,
            context={
                "project_id": int(project_id),
                "project_name": proj_name,
                "entity_type": et,
                "entity_id": eid,
                "shot_id": eid,
                "shot_code": code,
                "vfx_artist_user_id": new_i,
                "vfx_artist_name": _directory_user_display_name(new_i),
                "notification_title": title,
                "notification_body": msg,
            },
            fallback_title=title,
            fallback_body=msg,
            fallback_url=dept_href,
            fallback_recipient_user_ids=[new_i],
        )
        if managed or NotificationRule.query.filter_by(event_key="vfx_shot_assigned").first() is not None:
            db.session.flush()
            return
        rk = _notification_alloc_rule_key(rule, et, eid, new_i)
        if rk is not None:
            _create_notification(
                recipient_user_id=new_i,
                title=title,
                message=msg,
                n_type="info",
                severity="info",
                entity_type=et,
                entity_id=eid,
                project_id=int(project_id),
                rule_key=rk,
                actor=assigned_by,
            )
            artist_acc_id = _directory_user_account_id(new_i)
            if artist_acc_id is not None:
                emit_notification_to_account(
                    artist_acc_id,
                    {
                        "type": "vfx_shot_assigned",
                        "title": title,
                        "message": msg,
                        "project_id": int(project_id),
                        "shot_id": eid,
                        "href": dept_href,
                    },
                )
        db.session.flush()

    def _notify_vfx_dept_shot_status_change(
        shot: VfxShot,
        *,
        old_mgmt: str,
        new_mgmt: str,
        actor: Account | None = None,
    ) -> None:
        """Targeted notification + dept-panel push when a shot's mgmt_status changes.

        Recipients are the *assigned artist* and the *assigned supervisor* on the
        shot (only) — minus the actor who triggered the change. The whole
        project team is **not** broadcast (issue #9 dedupe). A Socket.IO
        `vfx_shot_status` event is also pushed to every connection of those
        users (and the actor themselves), so any open `/vfx-department/<pid>`
        tab can refresh its panels immediately instead of waiting for the
        120 s poll.
        """
        new_s = (new_mgmt or "").strip().lower()
        old_s = (old_mgmt or "").strip().lower()
        if new_s == old_s:
            return
        if new_s not in VFX_MGMT_STATUSES:
            return

        project_id = int(shot.project_id)
        eid = int(shot.id)
        code = shot.shot_code or f"Shot {shot.id}"

        artist_uid = getattr(shot, "assigned_artist_user_id", None)
        sup_uid = getattr(shot, "assigned_supervisor_user_id", None)
        actor_uid = directory_user_id_for_account(actor) if actor is not None else None

        # Skip self-notifications: if the actor is the artist or supervisor
        # they don't get a notification about their own action.
        recipient_uids: list[int] = []
        for uid in (artist_uid, sup_uid):
            if uid is None:
                continue
            uid_i = int(uid)
            if actor_uid is not None and uid_i == int(actor_uid):
                continue
            if uid_i not in recipient_uids:
                recipient_uids.append(uid_i)

        # Choose human-readable title / severity for known transitions.
        label = new_s.replace("_", " ")
        title_map = {
            "approved": (f"Approved: {code}", "info", "info", f"{code} was approved."),
            "review": (f"Review: {code}", "info", "info", f"{code} moved to review."),
            "client_review": (
                f"Client review: {code}",
                "info",
                "info",
                f"{code} moved to client review.",
            ),
            "blocked": (
                f"Blocked: {code}",
                "alert",
                "warning",
                f"{code} is blocked.",
            ),
            "delivered": (
                f"Delivered: {code}",
                "info",
                "info",
                f"{code} was delivered.",
            ),
            "in_progress": (
                f"{code} in progress",
                "info",
                "info",
                f"{code} moved to in progress.",
            ),
            "assigned": (
                f"Shot assigned: {code}",
                "info",
                "info",
                f"{code} moved to assigned.",
            ),
            "pending": (
                f"{code} reset to pending",
                "info",
                "info",
                f"{code} was reset to pending.",
            ),
        }
        title, n_type, severity, msg = title_map.get(
            new_s,
            (
                f"{code}: {label}",
                "info",
                "info",
                f"{code} moved to {label}.",
            ),
        )

        rule = f"vfx_dept_status_{shot.id}_{new_s}"
        et = "vfx_shot"
        dept_href = url_for(
            "vfx_department_workspace", project_id=int(project_id)
        )
        event_key = {
            "approved": "vfx_shot_approved",
            "delivered": "vfx_shot_delivered",
        }.get(new_s, "vfx_shot_status_changed")
        proj = db.session.get(Project, int(project_id))
        managed = send_managed_notification(
            event_key,
            project=proj,
            actor=actor,
            context={
                "project_id": int(project_id),
                "project_name": (proj.name if proj else None) or "Project",
                "entity_type": et,
                "entity_id": eid,
                "shot_id": eid,
                "shot_code": code,
                "shot_status": new_s,
                "vfx_artist_user_id": int(artist_uid) if artist_uid else None,
                "vfx_assigned_user_id": int(artist_uid) if artist_uid else None,
                "department_assigned_user_id": int(sup_uid) if sup_uid else None,
                "notification_title": title,
                "notification_body": msg,
            },
            fallback_title=title,
            fallback_body=msg,
            fallback_url=dept_href,
            fallback_recipient_user_ids=recipient_uids,
        )
        managed_rule_exists = NotificationRule.query.filter_by(event_key=event_key).first() is not None

        if not managed and not managed_rule_exists:
            for uid_i in recipient_uids:
                rk = _notification_alloc_rule_key(rule, et, eid, uid_i)
                if rk is not None:
                    _create_notification(
                        recipient_user_id=uid_i,
                        title=title,
                        message=msg,
                        n_type=n_type,
                        severity=severity,
                        entity_type=et,
                        entity_id=eid,
                        project_id=project_id,
                        rule_key=rk,
                        actor=actor,
                    )
                acc_id = _directory_user_account_id(uid_i)
                if acc_id is not None:
                    emit_notification_to_account(
                        acc_id,
                        {
                            "type": "vfx_shot_status",
                            "title": title,
                            "message": msg,
                            "project_id": project_id,
                            "shot_id": eid,
                            "mgmt_status": new_s,
                            "href": dept_href,
                        },
                    )

        # Panel-update push: emit to every involved user (including the
        # actor's own tabs) so an open /vfx-department/<pid> page refreshes
        # immediately. Different from the notification above — purely for UI.
        push_uids = set(recipient_uids)
        if actor_uid is not None:
            push_uids.add(int(actor_uid))
        for uid_i in push_uids:
            acc_id = _directory_user_account_id(uid_i)
            if acc_id is None:
                continue
            socketio.emit(
                "vfx_shot_status",
                {
                    "project_id": project_id,
                    "shot_id": eid,
                    "mgmt_status": new_s,
                },
                room=f"user_{acc_id}",
            )
        db.session.flush()

    def _vfx_supervisor_job_title_ids() -> list[int]:
        return [
            int(jt.id)
            for jt in JobTitle.query.order_by(JobTitle.id.asc()).all()
            if job_title_matches_vfx_supervisor(jt.name)
        ]

    def _vfx_directory_supervisor_users() -> list[User]:
        """All directory users with a VFX Supervisor job title."""
        by_id: dict[int, User] = {}
        for u in (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .order_by(User.name.asc(), User.id.asc())
            .all()
        ):
            for jt in u.assigned_job_titles():
                if job_title_matches_vfx_supervisor(jt.name):
                    by_id[int(u.id)] = u
                    break
        return sorted(by_id.values(), key=lambda u: ((u.name or "").lower(), int(u.id)))

    def _vfx_supervisor_users_payload_rows(
        project_id: int, *, extra_user_ids: set[int] | None = None
    ) -> list[dict]:
        """Supervisor dropdown options: directory VFX supervisors + optional extras."""
        by_id: dict[int, dict] = {}
        for u in _vfx_directory_supervisor_users():
            by_id[int(u.id)] = {
                "id": int(u.id),
                "name": (u.name or "").strip() or "User",
                "email": (u.email or "").strip(),
            }
        extra = extra_user_ids or set()
        if extra:
            for u in (
                User.query.options(joinedload(User.job_title))
                .filter(User.id.in_(sorted(extra)))
                .all()
            ):
                if int(u.id) in by_id:
                    continue
                by_id[int(u.id)] = {
                    "id": int(u.id),
                    "name": (u.name or "").strip() or "User",
                    "email": (u.email or "").strip(),
                }
        return sorted(by_id.values(), key=lambda x: (x["name"].lower(), x["id"]))

    def _vfx_supervisor_directory_user_ids() -> set[int]:
        """Directory users whose job title is VFX Supervisor."""
        return {int(u.id) for u in _vfx_directory_supervisor_users()}

