    def _vfx_user_has_directory_vfx_job_title(user_id: int) -> bool:
        u = (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .filter_by(id=int(user_id))
            .first()
        )
        if u is None:
            return False
        for jt in u.assigned_job_titles():
            if job_title_contains_vfx(jt.name):
                return True
        return False

    def _vfx_shot_is_in_department(shot: VfxShot) -> bool:
        return vfx_vendor_is_in_house(shot.vendor) and shot.sent_at is not None

    def _notify_vfx_supervisors_shot_sent_to_department(
        project_id: int,
        shot: VfxShot,
        *,
        sent_by: Account | None = None,
    ) -> None:
        """Alert all VFX Supervisors when a shot enters the in-house department workspace."""
        recipients = _vfx_supervisor_directory_user_ids()
        if not recipients:
            return
        proj = db.session.get(Project, int(project_id))
        proj_name = (proj.name if proj else None) or "Project"
        code = shot.shot_code or f"Shot {shot.id}"
        if sent_by is not None:
            sender = (sent_by.username or "").strip() or sent_by.display_login
        else:
            sender = "Someone"
        eid = int(shot.id)
        rule = f"vfx_sent_dept_{shot.id}"
        et = "vfx_shot"
        title = "Shot sent to VFX"
        message = f"{code} was sent to {proj_name} by {sender}."
        managed = send_managed_notification(
            "vfx_shot_sent_to_department",
            project=proj,
            actor=sent_by,
            context={
                "project_id": int(project_id),
                "project_name": proj_name,
                "entity_type": et,
                "entity_id": eid,
                "shot_id": eid,
                "shot_code": code,
                "notification_title": title,
                "notification_body": message,
            },
            fallback_title=title,
            fallback_body=message,
            fallback_url=url_for("vfx_department_workspace", project_id=int(project_id)),
            fallback_recipient_user_ids=sorted(recipients),
        )
        if managed or NotificationRule.query.filter_by(event_key="vfx_shot_sent_to_department").first() is not None:
            db.session.flush()
            return
        for uid in sorted(recipients):
            rk = _notification_alloc_rule_key(rule, et, eid, int(uid))
            if rk is None:
                continue
            _create_notification(
                recipient_user_id=int(uid),
                title=title,
                message=message,
                n_type="info",
                severity="info",
                entity_type=et,
                entity_id=eid,
                project_id=int(project_id),
                rule_key=rk,
                actor=sent_by,
            )
        db.session.flush()

    def _notification_resolve_project_rule_prefix(project_id: int | None, rule_prefix: str) -> None:
        """Mark unresolved notifications for this project whose rule_key starts with prefix."""
        if project_id is None or not (rule_prefix or "").strip():
            return
        pref = rule_prefix.strip()
        rows = (
            Notification.query.filter(
                Notification.project_id == int(project_id),
                Notification.rule_key.startswith(pref),
                _notification_unresolved_filter(),
            )
            .all()
        )
        for row in rows:
            row.is_resolved = True
            row.is_read = True

    def evaluate_hdd_notifications(hdd_id: int, *, actor: Account | None = None) -> None:
        hd = db.session.get(HardDisk, hdd_id)
        if hd is None:
            return
        used = (
            db.session.query(
                db.func.coalesce(
                    db.func.sum(HardDiskUsage.video_size_tb + HardDiskUsage.audio_size_tb),
                    0.0,
                )
            )
            .filter(HardDiskUsage.hard_disk_id == hd.id)
            .scalar()
        )
        used_tb = float(used or 0.0)
        cap_tb = float(hd.capacity_tb or 0.0)
        free_tb = cap_tb - used_tb

        rk_over_prefix = f"hdd_over_capacity:hdd:{hd.id}:"
        if used_tb > cap_tb + 1e-9:
            _notification_emit_to_project(
                project_id=hd.project_id,
                rule="hdd_over_capacity",
                n_type="alert",
                severity="critical",
                title=f"{(hd.name or 'HDD').strip()} over capacity",
                message=f"Used {used_tb:.2f}TB / {cap_tb:.2f}TB.",
                entity_type="hdd",
                entity_id=hd.id,
                actor=actor,
            )
        else:
            _notification_resolve_project_rule_prefix(hd.project_id, rk_over_prefix)

        rk_low_prefix = f"hdd_low_free:hdd:{hd.id}:"
        is_low_free = cap_tb > 0 and free_tb / cap_tb < 0.1
        if is_low_free:
            _notification_emit_to_project(
                project_id=hd.project_id,
                rule="hdd_low_free",
                n_type="alert",
                severity="warning",
                title=f"{(hd.name or 'HDD').strip()} low free space",
                message=f"Free {free_tb:.2f}TB ({(100.0 * free_tb / cap_tb):.1f}%).",
                entity_type="hdd",
                entity_id=hd.id,
                actor=actor,
            )
        else:
            _notification_resolve_project_rule_prefix(hd.project_id, rk_low_prefix)

