    def emit_shooting_day_critical_created(
        note: ShootingDayCriticalNote, day: ShootingDay, *, actor: Account | None = None
    ) -> None:
        """Notify all project team members; appears on Criticals + dashboard critical count."""
        proj = db.session.get(Project, day.project_id)
        pname = (proj.name or "").strip() if proj is not None else "Project"
        day_label = f"Unit {int(day.unit_number or 1)} · {(day.day_name or '').strip() or '—'}"
        date_s = day.shooting_date.isoformat() if day.shooting_date else ""
        snippet = (note.body or "").strip().replace("\n", " ")
        if len(snippet) > 220:
            snippet = snippet[:217] + "..."
        msg = f"{day_label} ({date_s}): {snippet}" if date_s else f"{day_label}: {snippet}"
        _notification_emit_to_project(
            project_id=int(day.project_id),
            rule="shooting_day_critical",
            n_type="alert",
            severity="critical",
            title=f"{pname} · Day critical added",
            message=msg,
            entity_type="shooting_day_critical",
            entity_id=int(note.id),
            actor=actor,
        )
        _sync_shooting_day_critical_notifications(note, day, actor=actor)

    def _shooting_day_critical_notification_text(
        note: ShootingDayCriticalNote, day: ShootingDay
    ) -> tuple[str, str]:
        proj = db.session.get(Project, day.project_id)
        pname = (proj.name or "").strip() if proj is not None else "Project"
        day_label = f"Unit {int(day.unit_number or 1)} · {(day.day_name or '').strip() or '—'}"
        date_s = day.shooting_date.isoformat() if day.shooting_date else ""
        snippet = (note.body or "").strip().replace("\n", " ")
        if len(snippet) > 220:
            snippet = snippet[:217] + "..."
        msg = f"{day_label} ({date_s}): {snippet}" if date_s else f"{day_label}: {snippet}"
        return f"{pname} · Day critical added", msg

    def _sync_shooting_day_critical_notifications(
        note: ShootingDayCriticalNote, day: ShootingDay, *, actor: Account | None = None
    ) -> None:
        """Ensure every project team member has an open critical alert for this day note."""
        title, message = _shooting_day_critical_notification_text(note, day)
        project_id = int(day.project_id)
        note_id = int(note.id)
        entity_type = "shooting_day_critical"

        open_rows = (
            Notification.query.filter(
                Notification.entity_type == entity_type,
                Notification.entity_id == note_id,
            )
            .filter(_notification_unresolved_filter())
            .all()
        )
        for row in open_rows:
            if (row.severity or "").strip().lower() == "error":
                row.severity = "critical"

        notified_uids = {
            int(row.user_id)
            for row in open_rows
            if row.user_id is not None
        }
        for uid in _project_team_user_ids(project_id):
            if uid in notified_uids:
                continue
            _create_notification(
                recipient_user_id=uid,
                title=title,
                message=message,
                n_type="alert",
                severity="critical",
                entity_type=entity_type,
                entity_id=note_id,
                project_id=project_id,
                rule="shooting_day_critical",
                actor=actor,
            )

    def _resolve_shooting_day_critical_notifications(note_id: int) -> None:
        """Resolve every open critical alert for this day note, regardless of rule_key.

        Resolving by entity (not rule_key prefix) is robust to keys that carry a
        de-dupe suffix (e.g. ``shooting_day_critical#<ts>:...``) which a prefix match
        would miss, leaving the critical open and still counted on the dashboard.
        """
        rows = (
            Notification.query.filter(
                Notification.entity_type == "shooting_day_critical",
                Notification.entity_id == int(note_id),
            )
            .filter(_notification_unresolved_filter())
            .all()
        )
        for row in rows:
            row.is_resolved = True
            row.is_read = True

