    def _notification_relative_time(ts: datetime | None) -> str:
        if ts is None:
            return ""
        ts_cairo = _ensure_cairo_aware(ts)
        if ts_cairo is None:
            return ""
        delta = _cairo_now_aware() - ts_cairo
        sec = max(0, int(delta.total_seconds()))
        if sec < 60:
            return f"{sec}s ago"
        mins = sec // 60
        if mins < 60:
            return f"{mins}m ago"
        hrs = mins // 60
        if hrs < 24:
            return f"{hrs}h ago"
        days = hrs // 24
        return f"{days}d ago"

    def _notification_shooting_day_ids_for_critical_notes(rows: Iterable[Notification]) -> dict[int, int]:
        ids = sorted(
            {
                int(n.entity_id)
                for n in rows
                if (n.entity_type or "").strip().lower() == "shooting_day_critical" and int(n.entity_id or 0) > 0
            }
        )
        if not ids:
            return {}
        out: dict[int, int] = {}
        for row in ShootingDayCriticalNote.query.filter(ShootingDayCriticalNote.id.in_(ids)).all():
            out[int(row.id)] = int(row.shooting_day_id)
        return out

    def _notification_critical_creator_labels(rows: Iterable[Notification]) -> dict[int, str]:
        """Map notification id → creator / audit label for critical note alerts."""
        rows_list = list(rows)
        if not rows_list:
            return {}
        note_ids = sorted(
            {
                int(n.entity_id)
                for n in rows_list
                if (n.entity_type or "").strip().lower() == "shooting_day_critical"
                and int(n.entity_id or 0) > 0
            }
        )
        note_audit: dict[int, str] = {}
        note_creator: dict[int, str] = {}
        if note_ids:
            for note in ShootingDayCriticalNote.query.filter(
                ShootingDayCriticalNote.id.in_(note_ids)
            ).all():
                audit = _critical_note_audit_label(note)
                if audit:
                    note_audit[int(note.id)] = audit
                uid = note.created_by_user_id
                if uid is not None:
                    label = (_directory_user_display_name(int(uid)) or "").strip()
                    if label and label.lower() != "system" and label != "—":
                        note_creator[int(note.id)] = label

        missing_note_ids = [nid for nid in note_ids if nid not in note_creator and nid not in note_audit]
        if missing_note_ids:
            for entry in (
                NotificationLog.query.filter(
                    NotificationLog.entity_type == "shooting_day_critical",
                    NotificationLog.entity_id.in_(missing_note_ids),
                )
                .order_by(NotificationLog.id.asc())
                .all()
            ):
                eid = int(entry.entity_id or 0)
                if eid in note_creator:
                    continue
                label = (entry.sender_name or "").strip()
                if label and label.lower() != "system":
                    note_creator[eid] = label

        out: dict[int, str] = {}
        need_log_ids: list[int] = []
        for n in rows_list:
            nid = int(n.id)
            et = (n.entity_type or "").strip().lower()
            if et == "shooting_day_critical":
                eid = int(n.entity_id or 0)
                if eid in note_audit:
                    out[nid] = note_audit[eid]
                    continue
                if eid in note_creator:
                    out[nid] = f"By {note_creator[eid]}"
                    continue
            need_log_ids.append(nid)

        if need_log_ids:
            for entry in (
                NotificationLog.query.filter(NotificationLog.notification_id.in_(need_log_ids))
                .order_by(NotificationLog.id.asc())
                .all()
            ):
                nid = int(entry.notification_id or 0)
                if nid in out:
                    continue
                label = (entry.sender_name or "").strip()
                if label and label.lower() != "system":
                    out[nid] = f"By {label}"
        return out

    def account_may_resolve_criticals(acc: Account | None) -> bool:
        """Producer and Machine Room (plus elevated) may resolve critical alerts."""
        if acc is None:
            return False
        if account_is_elevated(acc):
            return True
        role = _normalized_account_role_key(acc.role)
        return role in (ROLE_PRODUCER, ROLE_MACHINE_ROOM)

    def account_may_solve_critical_note_for(acc: Account | None, project_id: int | None) -> bool:
        """Who may solve a shooting-day critical note for a given project.

        Producer / Machine Room / elevated globally, plus anyone who can edit
        production on the project, plus Post-production Team members on that
        project (global policy: the Post-production Team can solve critical notes).
        """
        if acc is None:
            return False
        if account_may_resolve_criticals(acc):
            return True
        if project_id is None:
            return False
        pid = int(project_id)
        return account_may_edit_production_for(acc, pid) or account_is_production_team_on_project(
            acc, pid
        )

    def task_notification_href(project_id: int | None, task_id: int | None = None) -> str:
        """Deep link to a task on the global tasks page when possible."""
        tid = int(task_id or 0)
        if tid:
            return url_for("tasks_list") + f"#task-{tid}"
        pid = int(project_id) if project_id is not None else None
        if pid is not None:
            return url_for("project_detail", project_id=pid) + "#project-tasks-panel"
        return url_for("tasks_list")

    def _approval_center_notification_href(n: Notification) -> str | None:
        """Open Approval Center for registration / role / workflow queue alerts."""
        et = (n.entity_type or "").strip().lower()
        rk = (n.rule_key or "").strip().lower()
        eid = int(n.entity_id or 0)
        approval_entity_types = {
            "approval_request",
            "user_approval_request",
            "role_change_request",
            "reactivation_request",
            "permission_change_request",
            "user_registered",
            "account_reactivation_request",
            "workflow_request_created",
            "workflow_request_approved",
            "workflow_request_rejected",
            "workflow_request_completed",
        }
        approval_rule_prefixes = (
            "managed:user_registered:",
            "managed:role_change_request:",
            "managed:account_reactivation_request:",
            "managed:permission_change_request:",
            "managed:workflow_request_",
        )
        if et not in approval_entity_types and not rk.startswith(approval_rule_prefixes):
            return None
        if et == "approval_request" and eid > 0:
            return url_for("admin_approval_request_detail", request_id=eid)
        return url_for("admin_approvals")

    def notification_href(n: Notification, *, note_day_map: dict[int, int] | None = None) -> str:
        """In-app link when the user opens a notification."""
        et = (n.entity_type or "").strip().lower()
        eid = int(n.entity_id or 0)
        pid = n.project_id
        approval_href = _approval_center_notification_href(n)
        if approval_href:
            return approval_href
        if et == "booking":
            return url_for("booking.booking_home")
        if et == "task" and pid is None:
            return task_notification_href(None, eid if eid else None)
        if pid is None:
            return url_for("index")
        pid_i = int(pid)
        if et == "shooting_day_critical":
            if note_day_map:
                cday = note_day_map.get(eid)
                if cday is not None:
                    return url_for(
                        "project_production_day",
                        project_id=pid_i,
                        day_id=int(cday),
                    )
            return url_for("project_production", project_id=pid_i)
        if et == "shooting_day":
            base = url_for("project_production", project_id=pid_i)
            return base + (f"#day-{eid}" if eid else "")
        if et == "hdd":
            return url_for("machine_project", project_id=pid_i)
        if et == "booking":
            return url_for("booking.booking_home")
        if et == "vfx_shot":
            return url_for("vfx_department_workspace", project_id=pid_i)
        if et == "vfx":
            return url_for("project_vfx", project_id=pid_i)
        if et == "editing_item" and eid:
            return url_for("project_color_item_workspace", project_id=pid_i, item_id=eid)
        if et in ("color_episode", "episode_version") and eid:
            pe = ProductionEpisode.query.get(int(eid))
            if pe is not None and int(pe.project_id) == pid_i:
                return url_for("episode_color_editor_mode", episode_id=int(pe.id))
        if et == "episode_edit_missing" and eid:
            ev = EpisodeVersion.query.get(int(eid))
            if ev is not None and int(ev.project_id) == pid_i:
                pe = ProductionEpisode.query.filter_by(
                    project_id=pid_i, episode_number=int(ev.episode_number)
                ).first()
                if pe is not None:
                    return url_for("episode_color_editor_mode", episode_id=int(pe.id))
        if et == "task":
            return task_notification_href(pid_i, eid if eid else None)
        if et == "project":
            return url_for("project_detail", project_id=pid_i)
        return url_for("index")

    def _notification_editing_item_id(n: Notification) -> int | None:
        et = (n.entity_type or "").strip().lower()
        eid = int(n.entity_id or 0)
        if et == "editing_item" and eid > 0:
            return eid
        if et == "color_episode" and eid > 0:
            ce_row = ColorEpisode.query.get(eid)
            if ce_row is not None and ce_row.editing_item_id:
                return int(ce_row.editing_item_id)
        rk = (n.rule_key or "").strip()
        m = re.search(r"color_sent_item_(\d+)_", rk)
        if m:
            return int(m.group(1))
        if rk.startswith("managed:editing_item_sent_to_color:"):
            parts = rk.split(":")
            if len(parts) > 4:
                try:
                    cand = int(parts[4])
                    if cand > 0:
                        return cand
                except ValueError:
                    pass
        return None

    def serialize_notification(
        n: Notification,
        *,
        note_day_map: dict[int, int] | None = None,
        project_names: dict[int, str] | None = None,
    ) -> dict:
        """JSON-safe payload for the notification panel (all keys always present)."""
        created_iso = isoformat_stored_instant(n.created_at if isinstance(n.created_at, datetime) else None)
        crit_day: int | None = None
        if note_day_map and (n.entity_type or "").strip().lower() == "shooting_day_critical":
            raw = note_day_map.get(int(n.entity_id or 0))
            if raw is not None:
                crit_day = int(raw)
        base_message, action_label, action_href = cg.split_notification_message_action(n.message or "")
        base_message = scrub_notification_template_tags(base_message)
        action_href = cg.resolve_color_conform_action_href(
            n.project_id, action_label, action_href, url_for=url_for
        )
        editing_item_id = _notification_editing_item_id(n)
        action_label, action_href = cg.resolve_editing_item_notification_action(
            n.project_id,
            n.entity_type,
            n.entity_id,
            action_label,
            action_href,
            editing_item_id=editing_item_id,
            url_for=url_for,
        )
        href = action_href or notification_href(n, note_day_map=note_day_map)
        project_name = ""
        if n.project_id is not None:
            pid_i = int(n.project_id)
            if project_names is not None:
                project_name = project_names.get(pid_i, "")
            if not project_name:
                proj = db.session.get(Project, pid_i)
                project_name = (proj.name if proj else "") or f"Project {pid_i}"
        copy_task_payload = None
        if int(n.entity_id or 0) > 0 and (n.entity_type or "").strip().lower() == "task":
            task_row = db.session.get(Task, int(n.entity_id))
            if (
                task_row is not None
                and (task_row.title or "").strip() in MR_TIMED_STREAM_TITLES
                and task_row.copy_estimated_minutes is not None
                and not bool(task_row.archived)
            ):
                start_dt = task_row.copy_started_at or task_row.created_at
                start_ms = (
                    int(_epoch_ms_from_stored_naive(start_dt))
                    if isinstance(start_dt, datetime)
                    else 0
                )
                copy_task_payload = {
                    "id": int(task_row.id),
                    "status": (task_row.status or "open").strip(),
                    "title": (task_row.title or "").strip(),
                    "copy_day_name": (task_row.copy_day_name or "").strip() or "—",
                    "copy_unit_number": (
                        int(task_row.copy_unit_number)
                        if task_row.copy_unit_number is not None
                        else None
                    ),
                    "copy_estimated_minutes": int(task_row.copy_estimated_minutes),
                    "copy_started_at": format_datetime_cairo(start_dt)
                    if isinstance(start_dt, datetime)
                    else "",
                    "started_ms": start_ms,
                }
        return {
            "id": int(n.id or 0),
            "title": (n.title or "") if n.title is not None else "",
            "message": base_message,
            "action_label": action_label or "",
            "action_href": action_href or "",
            "severity": ((n.severity or "info") or "info").strip().lower(),
            "type": ((n.type or "activity") or "activity").strip().lower(),
            "entity_type": (n.entity_type or "") if n.entity_type is not None else "",
            "entity_id": int(n.entity_id or 0),
            "project_id": int(n.project_id) if n.project_id is not None else None,
            "project_name": project_name,
            "user_id": int(n.user_id) if n.user_id is not None else None,
            "is_read": bool(n.is_read),
            "is_acknowledged": bool(n.is_acknowledged),
            "is_resolved": bool(n.is_resolved) if n.is_resolved is not None else False,
            "rule_key": (n.rule_key or "") if n.rule_key is not None else "",
            "created_at": created_iso,
            "created_ago": _notification_relative_time(
                n.created_at if isinstance(n.created_at, datetime) else None
            ),
            "critical_shooting_day_id": crit_day,
            "href": href,
            "copy_task": copy_task_payload,
        }

    def shooting_day_scene_duration_seconds(link: ShootingDayScene) -> int:
        ds = int(getattr(link, "duration_seconds", 0) or 0)
        if ds > 0:
            return ds
        return max(0, int(link.duration or 0)) * 60

    def shooting_day_total_seconds(day: ShootingDay) -> int:
        """Legacy scene rows (seconds) + pipeline rows (duration_seconds or legacy minutes)."""
        legacy_sec = sum(int(r.duration_seconds or 0) for r in day.scene_rows)
        pipeline_sec = sum(shooting_day_scene_duration_seconds(link) for link in day.pipeline_scenes)
        return legacy_sec + pipeline_sec

    def shooting_day_sync_edit_percentages(day: ShootingDay) -> dict[str, int]:
        """Percent of rows with sync and first edit done (pipeline rows + legacy scene rows)."""
        pipeline = [
            ln
            for ln in (getattr(day, "pipeline_scenes", ()) or ())
            if shooting_items_mod.counts_toward_shooting_day_sync_edit(ln)
        ]
        legacy = list(getattr(day, "scene_rows", ()) or [])
        total = len(pipeline) + len(legacy)
        if not total:
            return {"sync": 0, "edit": 0}
        sync_n = sum(1 for ln in pipeline if ln.sync_done) + sum(1 for r in legacy if r.sync)
        edit_n = sum(1 for ln in pipeline if ln.first_edit_done) + sum(
            1 for r in legacy if r.first_edit
        )
        return {
            "sync": int(round(100.0 * sync_n / total)),
            "edit": int(round(100.0 * edit_n / total)),
        }

    def _parse_episode_number_from_text(raw_episode: str | None) -> int:
        raw = (raw_episode or "").strip()
        if not raw:
            return 0
        m = re.search(r"\d+", raw)
        if m:
            try:
                return max(0, int(m.group(0)))
            except (TypeError, ValueError):
                pass
        return 0

    def shooting_day_search_index(day: ShootingDay) -> dict[str, list[int]]:
        """Episode and scene numbers on a shooting day (pipeline + legacy rows)."""
        episodes: set[int] = set()
        scene_numbers: set[int] = set()
        for link in day.pipeline_scenes or []:
            ep = int(link.episode_number or 0)
            if ep > 0:
                episodes.add(ep)
            sn = int(link.scene_number or 0)
            if sn > 0:
                scene_numbers.add(sn)
            label = (link.scene_label or "").strip()
            if label:
                parsed = _parse_scene_number_from_label(label, sn or 1)
                if parsed > 0:
                    scene_numbers.add(parsed)
        for row in day.scene_rows or []:
            ep = _parse_episode_number_from_text(row.episode)
            if ep > 0:
                episodes.add(ep)
            sc_text = (row.scene or "").strip()
            if sc_text:
                sn = _parse_scene_number_from_label(sc_text, 0)
                if sn > 0:
                    scene_numbers.add(sn)
        return {
            "episodes": sorted(episodes),
            "scene_numbers": sorted(scene_numbers),
        }

    def _parse_scene_number_from_label(raw_scene_label: str | None, fallback: int = 1) -> int:
        raw = (raw_scene_label or "").strip()
        m = re.search(r"\d+", raw)
        if m:
            try:
                return max(1, int(m.group(0)))
            except (TypeError, ValueError):
                pass
        return max(1, int(fallback or 1))

    def _scene_title_from_label(
        raw_scene_label: str | None, *, fallback_number: int = 1
    ) -> str:
        """Human title for UI — preserves alphanumeric labels (e.g. Scene 3A)."""
        raw = (raw_scene_label or "").strip()
        if raw:
            return f"Scene {raw}"
        return f"Scene {max(1, int(fallback_number or 1))}"

    def _next_vfx_shot_number(scene_id: int) -> int:
        mx = (
            db.session.query(func.max(VfxShot.shot_number))
            .filter(VfxShot.scene_id == int(scene_id))
            .scalar()
        )
        return max(0, int(mx or 0)) + 1

    def _build_vfx_shot_code(episode_number: int, scene_number: int, shot_number: int) -> str:
        return (
            f"Eps{int(episode_number or 0):02d}_"
            f"Scene{int(scene_number or 0):02d}_"
            f"Shot{int(shot_number or 0):02d}"
        )

    def _flag_scene_needs_vfx(scene: ShootingDayScene | None) -> None:
        """Mark a production scene as needing VFX once shots or markers are created in the editor."""
        if scene is not None and not scene.needs_vfx:
            scene.needs_vfx = True

    def _allocate_vfx_shot_identity(
        project_id: int,
        scene: ShootingDayScene,
        *,
        preferred_shot_number: int | None = None,
    ) -> tuple[int, str]:
        """Return a per-scene shot number and a globally unique shot code."""
        ep_num = max(1, int(scene.episode_number or 1))
        scene_num = _parse_scene_number_from_label(scene.scene_label, fallback=scene.scene_number or 1)
        shot_num = (
            max(1, int(preferred_shot_number))
            if preferred_shot_number is not None
            else _next_vfx_shot_number(scene.id)
        )
        for _ in range(200):
            code = _build_vfx_shot_code(ep_num, scene_num, shot_num)
            code_clash = VfxShot.query.filter_by(shot_code=code).first()
            num_clash = VfxShot.query.filter_by(scene_id=scene.id, shot_number=shot_num).first()
            if code_clash is None and num_clash is None:
                return shot_num, code
            shot_num += 1
        raise ValueError("shot_code_exhausted")

    def format_duration_mmss(seconds: int) -> str:
        sec = max(0, int(seconds or 0))
        m, s = divmod(sec, 60)
        return f"{m:02d}:{s:02d}"

    def format_duration_day_total(seconds: int) -> str:
        sec = max(0, int(seconds or 0))
        m, s = divmod(sec, 60)
        return f"{m}:{s:02d}"

    def parse_duration_input(raw: str | None) -> int | None:
        s = (raw or "").strip()
        if not s:
            return None
        if s.isdigit():
            return max(0, int(s))
        parts = [p.strip() for p in s.split(":") if p.strip() != ""]
        try:
            if len(parts) == 2:
                return max(0, int(parts[0]) * 60 + int(parts[1]))
            if len(parts) == 3:
                return max(0, int(parts[0]) * 3600 + int(parts[1]) * 60 + int(parts[2]))
        except ValueError:
            return None
        return None

    def parse_shooting_day_duration_seconds(raw: str | None) -> int | None:
        """mm:ss (``::`` folded to ``:``), H:MM:SS, or digits-only.

        Digits-only: 1–3 characters = whole minutes (e.g. ``120`` = 120 min).
        Four or more digits = compact ``MMSS``…: last two are seconds (0–59),
        preceding digits are minutes (e.g. ``0315`` → 3 min 15 sec).
        Empty = 0.
        """
        s = (raw or "").strip()
        if not s:
            return 0
        while "::" in s:
            s = s.replace("::", ":")
        if ":" in s:
            return parse_duration_input(s)
        if s.isdigit():
            if len(s) <= 3:
                return max(0, int(s)) * 60
            sec = max(0, min(59, int(s[-2:])))
            mins = max(0, int(s[:-2]))
            return mins * 60 + sec
        return parse_duration_input(s)

