    def persist_shooting_scene_thumbnail_frame(
        row: ShootingDayScene, file_part
    ) -> str | None:
        """Save uploaded thumbnail on a shooting row. Returns error message or None."""
        if file_part is None or not (getattr(file_part, "filename", None) or "").strip():
            return None
        orig = secure_filename(file_part.filename) or "thumb"
        ext = os.path.splitext(orig)[1].lower()
        if ext not in SHOOTING_SCENE_THUMBNAIL_ALLOWED_EXT:
            return "Thumbnail must be PNG, JPG, GIF, or WebP."
        raw = file_part.read()
        if len(raw) > SHOOTING_SCENE_THUMBNAIL_MAX_BYTES:
            return "Thumbnail image is too large (max 5 MB)."
        fname = f"st{int(row.id)}-{uuid.uuid4().hex}{ext}"
        dest = os.path.join(shooting_scene_thumbnail_upload_root, fname)
        try:
            with open(dest, "wb") as out:
                out.write(raw)
        except OSError:
            return "Could not save the thumbnail image."
        old = (row.scene_thumbnail_frame or "").strip()
        if old:
            remove_shooting_scene_thumbnail_file(old)
        row.scene_thumbnail_frame = fname
        return None

