    def apply_script_analysis_to_document(doc: ScriptDocument, analysis) -> None:
        doc.page_count = int(analysis.page_count or 0)
        doc.scene_count = int(analysis.scene_count or 0)
        doc.language = (analysis.language or "unknown")[:20]
        doc.extraction_status = (analysis.extraction_status or "failed")[:32]
        doc.extraction_error = (analysis.extraction_error or "")[:5000]
        ScriptScene.query.filter_by(script_id=doc.id).delete(synchronize_session=False)
        for s in analysis.scenes or []:
            db.session.add(
                ScriptScene(
                    script_id=doc.id,
                    scene_number=int(s.scene_number),
                    scene_heading=(s.scene_heading or "")[:500],
                    page_number=int(s.page_number or 1),
                    raw_text=(s.raw_text or s.scene_heading or "")[:2000],
                    location_type=(s.location_type or None),
                    time_of_day=(s.time_of_day or None),
                )
            )

    def run_script_analysis_for_document(doc: ScriptDocument) -> None:
        path = script_document_disk_path(doc)
        if not os.path.isfile(path):
            doc.extraction_status = "failed"
            doc.extraction_error = "Script file is missing on disk."
            return
        analysis = analyze_script_pdf(path)
        apply_script_analysis_to_document(doc, analysis)

    def episode_script_disk_path(pe: ProductionEpisode) -> str:
        return os.path.join(episode_script_upload_root, (pe.script_file or "").strip())

    def apply_script_analysis_to_episode(pe: ProductionEpisode, analysis) -> None:
        pe.script_page_count = int(analysis.page_count or 0)
        pe.script_scene_count = int(analysis.scene_count or 0)
        pe.script_analysis_status = (analysis.extraction_status or "failed")[:32]
        pe.script_analysis_error = (analysis.extraction_error or "")[:5000]

    def run_script_analysis_for_episode(pe: ProductionEpisode) -> None:
        path = episode_script_disk_path(pe)
        if not os.path.isfile(path):
            pe.script_analysis_status = "failed"
            pe.script_analysis_error = "Script file is missing on disk."
            pe.script_page_count = 0
            pe.script_scene_count = 0
            return
        analysis = analyze_script_pdf(path)
        apply_script_analysis_to_episode(pe, analysis)

    def latest_script_document_for_project(project_id: int) -> ScriptDocument | None:
        return (
            ScriptDocument.query.filter_by(project_id=project_id)
            .order_by(ScriptDocument.created_at.desc(), ScriptDocument.id.desc())
            .first()
        )

    def ensure_production_episode_rows(project: Project) -> dict[int, ProductionEpisode]:
        """Ensure pipeline_episodes rows exist for episodes 1..number_of_episodes."""
        count = max(0, int(project.number_of_episodes or 0))
        rows = ProductionEpisode.query.filter_by(project_id=project.id).all()
        by_num = {int(e.episode_number): e for e in rows}
        added = False
        for ep_num in range(1, count + 1):
            if ep_num not in by_num:
                row = ProductionEpisode(project_id=project.id, episode_number=ep_num)
                db.session.add(row)
                by_num[ep_num] = row
                added = True
        if added:
            db.session.commit()
            _auto_sync_editing_items_for_episodes(project)
        return by_num

    def _auto_sync_editing_items_for_episodes(project: Project) -> None:
        """Silently create/link episode EditingItems when production episodes exist."""
        if not _project_type_is_tv_series(getattr(project, "project_type", None)):
            return
        if max(0, int(project.number_of_episodes or 0)) <= 0:
            return
        sync_fn = app.extensions.get("editing_items_sync_episodes")
        if not sync_fn:
            return
        try:
            sync_fn(project)
        except Exception:
            db.session.rollback()
            app.logger.exception(
                "editing items episode auto-sync failed for project %s", project.id
            )

