    def _video_media_records_for(entity_type: str, entity_ids: list[int]) -> dict[int, VideoMediaRecord]:
        if not entity_ids:
            return {}
        rows = VideoMediaRecord.query.filter(
            VideoMediaRecord.entity_type == entity_type,
            VideoMediaRecord.entity_id.in_([int(x) for x in entity_ids]),
        ).all()
        return {int(r.entity_id): r for r in rows}

    def _delete_video_media_record(entity_type: str, entity_id: int) -> None:
        rec = VideoMediaRecord.query.filter_by(
            entity_type=entity_type, entity_id=int(entity_id)
        ).first()
        if rec is None:
            return
        vp.remove_preview_files(_video_upload_roots_map(), rec)
        db.session.delete(rec)

