    def _vfx_version_media_fields(
        project_id: int,
        ver: VfxVersion,
        rec: VideoMediaRecord | None,
    ) -> dict:
        orig = (ver.image or "").strip()
        is_video = _vfx_is_video_media(orig)
        orig_url = _vfx_version_preview_url(project_id, orig) if orig else ""
        if not is_video or _vfx_media_is_remote(orig):
            return {
                "previewUrl": orig_url,
                "playbackUrl": orig_url,
                "originalMediaUrl": orig_url,
                "videoPreview": None,
                "previewBadge": "Original",
                "isVideo": is_video,
            }
        play_base = vp.playback_basename(rec, orig)
        play_url = _vfx_version_preview_url(project_id, play_base) if play_base else ""
        preview_json = vp.video_media_json(rec, playback_url=play_url, original_url=orig_url)
        return {
            "previewUrl": play_url or orig_url,
            "playbackUrl": play_url or orig_url,
            "originalMediaUrl": orig_url,
            "videoPreview": preview_json,
            "previewBadge": preview_json.get("previewBadge") or "Original",
            "isVideo": True,
        }

    def _scene_reference_media_fields(
        project_id: int,
        ref: SceneReference,
        rec: VideoMediaRecord | None,
    ) -> dict:
        orig = (ref.video_url or "").strip()
        is_video = _vfx_is_video_media(orig)
        orig_url = _scene_ref_preview_url(project_id, orig) if orig else ""
        if not is_video or _vfx_media_is_remote(orig):
            return {
                "previewUrl": orig_url,
                "playbackUrl": orig_url,
                "originalMediaUrl": orig_url,
                "videoPreview": None,
                "previewBadge": "Original",
                "isVideo": is_video,
            }
        play_base = vp.playback_basename(rec, orig)
        play_url = _scene_ref_preview_url(project_id, play_base) if play_base else ""
        preview_json = vp.video_media_json(rec, playback_url=play_url, original_url=orig_url)
        return {
            "previewUrl": play_url or orig_url,
            "playbackUrl": play_url or orig_url,
            "originalMediaUrl": orig_url,
            "videoPreview": preview_json,
            "previewBadge": preview_json.get("previewBadge") or "Original",
            "isVideo": True,
        }

    def _video_preview_status_json(
        project_id: int,
        entity_type: str,
        entity_id: int,
    ) -> dict | None:
        rec = VideoMediaRecord.query.filter_by(
            entity_type=entity_type, entity_id=int(entity_id)
        ).first()
        if rec is None:
            return None
        if entity_type == "vfx_version":
            ver = VfxVersion.query.join(VfxShot, VfxVersion.shot_id == VfxShot.id).filter(
                VfxShot.project_id == project_id, VfxVersion.id == int(entity_id)
            ).first()
            if ver is None:
                return None
            fields = _vfx_version_media_fields(project_id, ver, rec)
            return {
                "entityType": entity_type,
                "entityId": int(entity_id),
                **fields["videoPreview"],
                "previewUrl": fields["playbackUrl"],
            }
        if entity_type == "scene_reference":
            ref = (
                SceneReference.query.join(
                    ShootingDayScene, SceneReference.scene_id == ShootingDayScene.id
                )
                .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
                .filter(
                    ShootingDay.project_id == project_id,
                    SceneReference.id == int(entity_id),
                )
                .first()
            )
            if ref is None:
                return None
            fields = _scene_reference_media_fields(project_id, ref, rec)
            return {
                "entityType": entity_type,
                "entityId": int(entity_id),
                **fields["videoPreview"],
                "previewUrl": fields["playbackUrl"],
            }
        return None

    def _resolve_vfx_version_disk_filename(project_id: int, filename: str) -> str | None:
        """Validate filename belongs to project (original or preview) and return basename to serve."""
        fn = (filename or "").strip()
        if not fn or "/" in fn or "\\" in fn or fn.startswith("."):
            return None
        ver = (
            VfxVersion.query.join(VfxShot, VfxVersion.shot_id == VfxShot.id)
            .filter(VfxShot.project_id == project_id, VfxVersion.image == fn)
            .first()
        )
        if ver is not None:
            return fn
        rec = VideoMediaRecord.query.filter_by(
            entity_type="vfx_version",
            upload_root="vfx_versions",
            preview_file_path=fn,
        ).first()
        if rec is not None:
            ver2 = (
                VfxVersion.query.join(VfxShot, VfxVersion.shot_id == VfxShot.id)
                .filter(VfxShot.project_id == project_id, VfxVersion.id == rec.entity_id)
                .first()
            )
            if ver2 is not None:
                return fn
        return None

    def _resolve_scene_reference_disk_filename(project_id: int, filename: str) -> str | None:
        fn = (filename or "").strip()
        if not fn or "/" in fn or "\\" in fn or fn.startswith("."):
            return None
        ref = (
            SceneReference.query.join(ShootingDayScene, SceneReference.scene_id == ShootingDayScene.id)
            .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
            .filter(ShootingDay.project_id == project_id, SceneReference.video_url == fn)
            .first()
        )
        if ref is not None:
            return fn
        rec = VideoMediaRecord.query.filter_by(
            entity_type="scene_reference",
            upload_root="scene_refs",
            preview_file_path=fn,
        ).first()
        if rec is not None:
            ref2 = (
                SceneReference.query.join(
                    ShootingDayScene, SceneReference.scene_id == ShootingDayScene.id
                )
                .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
                .filter(
                    ShootingDay.project_id == project_id,
                    SceneReference.id == rec.entity_id,
                )
                .first()
            )
            if ref2 is not None:
                return fn
        return None

    def avatar_href_for_user(u: User | None) -> str:
        if u is None:
            return url_for("static", filename="avatars/preset-01.svg")
        kind = (u.avatar_kind or "preset").lower()
        if kind == "upload" and (u.avatar_upload or "").strip():
            return url_for("user_avatar_file", user_id=u.id)
        return url_for("static", filename=preset_avatar_static_path(u.avatar_preset))

    def chat_avatar_url_for_user(u: User | None) -> str | None:
        """Chat-safe avatar URL: uploaded profile photo only (initials otherwise)."""
        if u is None:
            return None
        kind = (u.avatar_kind or "preset").lower()
        if kind == "upload" and (u.avatar_upload or "").strip():
            return url_for("user_avatar_file", user_id=u.id)
        return None

    def avatar_mimetype_for_filename(filename: str) -> str:
        ext = os.path.splitext(filename)[1].lower()
        return {
            ".jpg": "image/jpeg",
            ".jpeg": "image/jpeg",
            ".png": "image/png",
            ".gif": "image/gif",
            ".webp": "image/webp",
        }.get(ext, "application/octet-stream")

    def avatar_preset_href_for_user(u: User | None) -> str:
        return url_for("static", filename=preset_avatar_static_path(u.avatar_preset if u else None))

