    def ensure_guest_test_users() -> None:
        """Optional dev/test accounts — set BOOTSTRAP_GUEST_USERS=1 to create."""
        if os.environ.get("BOOTSTRAP_GUEST_USERS", "").strip().lower() not in ("1", "true", "yes"):
            return
        specs = (
            ("guest_viewer_user", "guest_viewer@local.test", GUEST_ACCESS_VIEWER),
            ("guest_reviewer_user", "guest_reviewer@local.test", GUEST_ACCESS_REVIEWER),
            ("guest_approver_user", "guest_approver@local.test", GUEST_ACCESS_APPROVER),
        )
        pwd = os.environ.get("BOOTSTRAP_GUEST_PASSWORD") or (
            "" if security_support_mod.is_production_env() else "guest"
        )
        if not pwd:
            return
        created_user_ids: list[int] = []
        for username, email, level in specs:
            acc = Account.query.filter(
                (Account.username == username) | (Account.email == email)
            ).first()
            if acc is None:
                acc = Account(
                    email=email,
                    username=username,
                    password_hash=generate_password_hash(pwd, method="pbkdf2:sha256"),
                    role=ROLE_GUEST,
                    guest_access_level=level,
                )
                db.session.add(acc)
                db.session.flush()
            else:
                acc.role = ROLE_GUEST
                acc.guest_access_level = level
            u = User.query.filter_by(account_id=acc.id).first()
            if u is None:
                u = User(
                    name=username.replace("_", " ").title(),
                    email=email,
                    account_id=acc.id,
                )
                db.session.add(u)
                db.session.flush()
            created_user_ids.append(int(u.id))
        try:
            test_project_id = int(os.environ.get("BOOTSTRAP_GUEST_PROJECT_ID", "4") or "4")
        except (TypeError, ValueError):
            test_project_id = 4
        if db.session.get(Project, test_project_id) is not None:
            for uid in created_user_ids:
                exists = ProjectMember.query.filter_by(
                    project_id=test_project_id, user_id=uid
                ).first()
                if exists is None:
                    db.session.add(ProjectMember(project_id=test_project_id, user_id=uid))
        db.session.commit()

    def ensure_bootstrap_admin_account() -> None:
        if not bootstrap_admin_email:
            return
        if not bootstrap_admin_password:
            return
        acc = Account.query.filter_by(email=bootstrap_admin_email).first()
        if acc:
            changed = False
            if acc.role != ROLE_ADMIN:
                acc.role = ROLE_ADMIN
                changed = True
            if getattr(acc, "status", None) != account_approval_support_mod.STATUS_ACTIVE:
                acc.status = account_approval_support_mod.STATUS_ACTIVE
                changed = True
            if not getattr(acc, "is_active", True):
                acc.is_active = True
                changed = True
            if bootstrap_admin_username:
                taken = Account.query.filter(
                    Account.id != acc.id,
                    Account.username == bootstrap_admin_username,
                ).first()
                if not taken and acc.username != bootstrap_admin_username:
                    acc.username = bootstrap_admin_username
                    changed = True
            if changed:
                db.session.commit()
            return
        uname = bootstrap_admin_username
        if uname and Account.query.filter_by(username=uname).first():
            uname = None
        db.session.add(
            Account(
                email=bootstrap_admin_email,
                username=uname,
                password_hash=generate_password_hash(bootstrap_admin_password, method="pbkdf2:sha256"),
                role=ROLE_ADMIN,
                status=account_approval_support_mod.STATUS_ACTIVE,
                is_active=True,
            )
        )
        db.session.commit()

