    def ensure_sqlite_user_job_titles_table() -> None:
        if db.engine.dialect.name != "sqlite":
            db.create_all()
        else:
            insp = inspect(db.engine)
            if "user_job_titles" not in insp.get_table_names():
                with db.engine.begin() as conn:
                    conn.execute(
                        text(
                            """
                            CREATE TABLE user_job_titles (
                                id INTEGER PRIMARY KEY AUTOINCREMENT,
                                user_id INTEGER NOT NULL,
                                job_title_id INTEGER NOT NULL,
                                sort_order INTEGER NOT NULL DEFAULT 0,
                                FOREIGN KEY(user_id) REFERENCES users(id),
                                FOREIGN KEY(job_title_id) REFERENCES job_titles(id),
                                UNIQUE(user_id, job_title_id)
                            )
                            """
                        )
                    )
        existing_pairs = {
            (int(row.user_id), int(row.job_title_id))
            for row in db.session.query(UserJobTitle.user_id, UserJobTitle.job_title_id).all()
        }
        for u in User.query.filter(User.job_title_id.isnot(None)).all():
            pair = (int(u.id), int(u.job_title_id))
            if pair in existing_pairs:
                continue
            db.session.add(
                UserJobTitle(user_id=u.id, job_title_id=u.job_title_id, sort_order=0)
            )
            existing_pairs.add(pair)
        db.session.commit()

    def resync_primary_job_title_id(u: User) -> None:
        first = (
            UserJobTitle.query.filter_by(user_id=u.id)
            .order_by(UserJobTitle.sort_order.asc(), UserJobTitle.id.asc())
            .first()
        )
        u.job_title_id = int(first.job_title_id) if first is not None else None

    def set_user_job_titles(u: User, title_ids: list) -> None:
        seen: set[int] = set()
        ordered: list[int] = []
        for raw in title_ids:
            try:
                tid = int(raw)
            except (TypeError, ValueError):
                continue
            if tid <= 0 or tid in seen:
                continue
            if JobTitle.query.get(tid) is None:
                continue
            seen.add(tid)
            ordered.append(tid)
        UserJobTitle.query.filter_by(user_id=u.id).delete()
        for idx, tid in enumerate(ordered):
            db.session.add(
                UserJobTitle(user_id=u.id, job_title_id=tid, sort_order=idx)
            )
        u.job_title_id = ordered[0] if ordered else None

