    def backfill_job_title_user_types() -> None:
        from user_role_mapping import infer_job_title_audience

        dirty = False
        for jt in JobTitle.query.all():
            inferred = infer_job_title_audience(
                jt.name,
                jt.category.name if jt.category else None,
            )
            current = (getattr(jt, "user_type", None) or "employee").strip().lower()
            if current != inferred:
                jt.user_type = inferred
                dirty = True
        if dirty:
            db.session.commit()

    def ensure_role_mapping_guest_titles() -> None:
        """Ensure client/guest job titles from the role mapping exist (idempotent)."""
        from user_role_mapping import CLIENT_TITLE_ROLE_MAP

        client_cat = (
            JobCategory.query.filter(
                JobCategory.name.ilike("%client%")
                | JobCategory.name.ilike("%creative%")
            )
            .order_by(JobCategory.sort_order.asc())
            .first()
        )
        if client_cat is None:
            client_cat = JobCategory.query.filter_by(is_system=False).first()
        if client_cat is None:
            return
        existing = {jt.name.strip().lower(): jt for jt in JobTitle.query.all()}
        dirty = False
        for title_name in CLIENT_TITLE_ROLE_MAP:
            key = title_name.strip().lower()
            if key in existing:
                jt = existing[key]
                if (getattr(jt, "user_type", None) or "employee") != "client":
                    jt.user_type = "client"
                    dirty = True
                continue
            jt = JobTitle(
                name=title_name,
                category_id=client_cat.id,
                user_type="client",
            )
            db.session.add(jt)
            dirty = True
        if dirty:
            db.session.commit()
            backfill_job_title_user_types()

