    def unclassified_job_category() -> JobCategory:
        row = JobCategory.query.filter_by(is_system=True).first()
        if row is None:
            row = JobCategory.query.filter(
                JobCategory.name.ilike(UNCLASSIFIED_JOB_CATEGORY_NAME)
            ).first()
        if row is None:
            row = JobCategory(
                name=UNCLASSIFIED_JOB_CATEGORY_NAME,
                description="Job titles not yet assigned to a category.",
                sort_order=9999,
                is_system=True,
                is_active=False,
            )
            db.session.add(row)
            db.session.commit()
        elif not row.is_system:
            row.is_system = True
            db.session.commit()
        if row.is_active:
            row.is_active = False
            db.session.commit()
        return row

