    def ensure_sqlite_projects_unique_name_index() -> None:
        """Case-insensitive unique project names (blocks duplicate creates under race)."""
        if db.engine.dialect.name != "sqlite":
            return
        insp = inspect(db.engine)
        if "projects" not in insp.get_table_names():
            return
        with db.engine.begin() as conn:
            dup_count = conn.execute(
                text(
                    """
                    SELECT COUNT(*) FROM (
                      SELECT 1
                      FROM projects
                      WHERE name IS NOT NULL AND trim(name) != ''
                      GROUP BY lower(trim(name))
                      HAVING COUNT(*) > 1
                    )
                    """
                )
            ).scalar()
            if int(dup_count or 0) > 0:
                app.logger.warning(
                    "Skipping uq_projects_name_lower — %s duplicate project name group(s) still exist",
                    dup_count,
                )
                return
            conn.execute(
                text(
                    "CREATE UNIQUE INDEX IF NOT EXISTS uq_projects_name_lower "
                    "ON projects (lower(trim(name)))"
                )
            )

