    def ensure_shooting_day_critical_stale_resolved_once() -> None:
        """Resolve orphaned day-critical alerts for notes that are solved or no longer critical.

        Historically, solved/cleared notes resolved their alerts by rule_key prefix,
        which missed de-duped keys (``shooting_day_critical#<ts>:...``). Those alerts
        stayed open and kept counting. This one-time pass clears them by entity.
        """
        mark = os.path.join(app.instance_path, ".done_shooting_day_critical_stale_resolve_v2")
        if os.path.isfile(mark):
            return
        insp = inspect(db.engine)
        if "notification" not in insp.get_table_names():
            return
        if "shooting_day_critical_notes" not in insp.get_table_names():
            return
        stale_notes = ShootingDayCriticalNote.query.filter(
            db.or_(
                ShootingDayCriticalNote.solved_at.isnot(None),
                ShootingDayCriticalNote.is_critical.is_(False),
            )
        ).all()
        for note in stale_notes:
            _resolve_shooting_day_critical_notifications(int(note.id))
        db.session.commit()
        try:
            with open(mark, "w", encoding="utf-8") as f:
                f.write("ok\n")
        except OSError:
            pass

