    def load_post_scope_task_context() -> tuple[
        list[tuple[str, str, str]], dict[str, TaskGroup], dict[int, list[TaskGroupTitle]]
    ]:
        from project_settings import POST_SCOPE_FIELDS

        groups_by_scope = {
            g.post_scope_key: g
            for g in TaskGroup.query.filter(TaskGroup.post_scope_key.isnot(None)).all()
            if g.post_scope_key
        }
        titles_by_group: dict[int, list[TaskGroupTitle]] = defaultdict(list)
        for pt in TaskGroupTitle.query.order_by(
            TaskGroupTitle.sort_order, TaskGroupTitle.id
        ).all():
            titles_by_group[pt.group_id].append(pt)
        return POST_SCOPE_FIELDS, groups_by_scope, dict(titles_by_group)

