    def ensure_sqlite_chat_messages_nullable_project_id() -> None:
        """Allow direct/group/department messages without a project_id (SQLite rebuild)."""
        if db.engine.dialect.name != "sqlite":
            return
        insp = inspect(db.engine)
        if "chat_messages" not in insp.get_table_names():
            return
        project_col = next(
            (c for c in insp.get_columns("chat_messages") if c["name"] == "project_id"),
            None,
        )
        if project_col is None or project_col.get("nullable"):
            return
        with db.engine.begin() as conn:
            conn.execute(text("PRAGMA foreign_keys=OFF"))
            conn.execute(
                text(
                    """
                    CREATE TABLE chat_messages__nullable_project (
                        id INTEGER NOT NULL,
                        thread_id INTEGER,
                        project_id INTEGER,
                        user_id INTEGER NOT NULL,
                        account_id INTEGER,
                        message TEXT,
                        image_path VARCHAR(255),
                        audio_path VARCHAR(255),
                        created_at DATETIME,
                        is_deleted BOOLEAN NOT NULL DEFAULT 0,
                        deleted_at DATETIME,
                        deleted_by_account_id INTEGER,
                        deleted_reason TEXT,
                        reply_to_message_id INTEGER,
                        PRIMARY KEY (id),
                        FOREIGN KEY(thread_id) REFERENCES chat_threads (id),
                        FOREIGN KEY(project_id) REFERENCES projects (id),
                        FOREIGN KEY(user_id) REFERENCES users (id),
                        FOREIGN KEY(account_id) REFERENCES accounts (id),
                        FOREIGN KEY(reply_to_message_id) REFERENCES chat_messages (id)
                    )
                    """
                )
            )
            conn.execute(
                text(
                    """
                    INSERT INTO chat_messages__nullable_project (
                        id, thread_id, project_id, user_id, account_id, message,
                        image_path, audio_path, created_at, is_deleted, deleted_at,
                        deleted_by_account_id, deleted_reason, reply_to_message_id
                    )
                    SELECT
                        id, thread_id, project_id, user_id, account_id, message,
                        image_path, audio_path, created_at, is_deleted, deleted_at,
                        deleted_by_account_id, deleted_reason, reply_to_message_id
                    FROM chat_messages
                    """
                )
            )
            conn.execute(text("DROP TABLE chat_messages"))
            conn.execute(
                text("ALTER TABLE chat_messages__nullable_project RENAME TO chat_messages")
            )
            conn.execute(
                text("CREATE INDEX IF NOT EXISTS ix_chat_messages_project_id ON chat_messages (project_id)")
            )
            conn.execute(
                text("CREATE INDEX IF NOT EXISTS ix_chat_messages_thread_id ON chat_messages (thread_id)")
            )
            conn.execute(
                text("CREATE INDEX IF NOT EXISTS ix_chat_messages_account_id ON chat_messages (account_id)")
            )
            conn.execute(text("PRAGMA foreign_keys=ON"))

