    def migrate_chat_threads_from_legacy() -> None:
        """One-time backfill: project threads, thread_id on messages, participant read state."""
        mark = os.path.join(app.instance_path, ".chat_threads_migrated")
        if os.path.isfile(mark):
            return
        ensure_chat_thread_tables()
        ensure_sqlite_chat_messages_thread_columns()
        try:
            project_ids_with_msgs = {
                int(r[0])
                for r in db.session.query(ChatMessage.project_id)
                .filter(ChatMessage.project_id.isnot(None))
                .distinct()
                .all()
                if r[0] is not None
            }
            eligible = set(eligible_chat_project_ids_for_migration())
            for pid in sorted(project_ids_with_msgs | eligible):
                thread = ChatThread.query.filter_by(
                    thread_type=chat_thr.THREAD_TYPE_PROJECT, project_id=pid
                ).first()
                if thread is None:
                    proj = Project.query.get(pid)
                    thread = ChatThread(
                        thread_type=chat_thr.THREAD_TYPE_PROJECT,
                        project_id=pid,
                        title=(proj.name if proj else None) or f"Project {pid}",
                    )
                    db.session.add(thread)
                    db.session.flush()
                members = ProjectMember.query.filter_by(project_id=pid).all()
                for pm in members:
                    u = User.query.get(pm.user_id)
                    if u is None or u.account_id is None:
                        continue
                    part = ChatThreadParticipant.query.filter_by(
                        thread_id=thread.id, account_id=u.account_id
                    ).first()
                    if part is None:
                        db.session.add(
                            ChatThreadParticipant(
                                thread_id=thread.id,
                                account_id=u.account_id,
                                directory_user_id=u.id,
                            )
                        )
                read_states = ProjectChatReadState.query.filter_by(project_id=pid).all()
                for rs in read_states:
                    part = ChatThreadParticipant.query.filter_by(
                        thread_id=thread.id, account_id=rs.account_id
                    ).first()
                    if part is None:
                        acc_row = db.session.get(Account, rs.account_id)
                        uid = None
                        if acc_row is not None:
                            u_for_acc = User.query.filter_by(account_id=acc_row.id).first()
                            uid = u_for_acc.id if u_for_acc else None
                        part = ChatThreadParticipant(
                            thread_id=thread.id,
                            account_id=rs.account_id,
                            directory_user_id=uid,
                        )
                        db.session.add(part)
                        db.session.flush()
                    if rs.last_read_message_id > part.last_read_message_id:
                        part.last_read_message_id = rs.last_read_message_id
                db.session.query(ChatMessage).filter(
                    ChatMessage.project_id == pid,
                    ChatMessage.thread_id.is_(None),
                ).update({ChatMessage.thread_id: thread.id}, synchronize_session=False)
            db.session.commit()
            with open(mark, "w", encoding="utf-8") as f:
                f.write("ok\n")
        except Exception:
            db.session.rollback()
            app.logger.exception("migrate_chat_threads_from_legacy")

    def eligible_chat_project_ids_for_migration() -> list[int]:
        rows = db.session.query(ProjectMember.project_id).distinct().all()
        return [int(r[0]) for r in rows if r[0] is not None]

