    def migrate_shooting_day_scene_runtime_selected_defaults() -> None:
        """One runtime take per episode+scene: earliest row wins (original first)."""
        rows = (
            ShootingDayScene.query.join(ShootingDay)
            .filter(ShootingDay.project_id.isnot(None))
            .order_by(ShootingDay.project_id, ShootingDayScene.id.asc())
            .all()
        )
        groups: dict[tuple[int, str, str], list[ShootingDayScene]] = defaultdict(list)
        for row in rows:
            key = shooting_items_mod.scene_runtime_identity_key(row)
            if key is None:
                row.runtime_selected = False
                continue
            bucket, label = key
            pid = int(row.shooting_day.project_id)
            groups[(pid, bucket, label)].append(row)
        for group_rows in groups.values():
            group_rows.sort(key=lambda r: int(r.id))
            pick_id = int(group_rows[0].id)
            for row in group_rows:
                row.runtime_selected = int(row.id) == pick_id
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()

