    def ensure_sqlite_color_grading_tables() -> None:
        """Color grading department tables (SQLite additive)."""
        if db.engine.dialect.name != "sqlite":
            return
        insp = inspect(db.engine)
        names = set(insp.get_table_names())
        for model in (
            ColorEpisode,
            ColorVersion,
            ColorReviewNote,
            ColorDelivery,
            ColorActivity,
            ColorEpisodeGalleryBatch,
            ColorEpisodeGalleryFrame,
            ColorEpisodeGalleryShare,
        ):
            if model.__tablename__ not in names:
                model.__table__.create(bind=db.engine, checkfirst=True)
        refreshed_names = set(inspect(db.engine).get_table_names())
        if "color_episode_gallery_frame" in refreshed_names:
            frame_cols = {
                c["name"] for c in inspect(db.engine).get_columns("color_episode_gallery_frame")
            }
            if "batch_id" not in frame_cols:
                with db.engine.begin() as conn:
                    conn.execute(
                        text(
                            "ALTER TABLE color_episode_gallery_frame ADD COLUMN batch_id INTEGER "
                            "REFERENCES color_episode_gallery_batch(id)"
                        )
                    )
        if (
            "color_episode_gallery_batch" in refreshed_names
            and "color_episode_gallery_frame" in refreshed_names
        ):
            orphan_rows = db.session.execute(
                text(
                    "SELECT DISTINCT color_episode_id FROM color_episode_gallery_frame "
                    "WHERE batch_id IS NULL"
                )
            ).fetchall()
            for row in orphan_rows:
                ce_id = int(row[0])
                batch = ColorEpisodeGalleryBatch(
                    color_episode_id=ce_id,
                    name="Batch 1",
                    sort_order=1,
                    created_at=now_local(),
                )
                db.session.add(batch)
                db.session.flush()
                db.session.execute(
                    text(
                        "UPDATE color_episode_gallery_frame SET batch_id = :bid "
                        "WHERE color_episode_id = :ceid AND batch_id IS NULL"
                    ),
                    {"bid": int(batch.id), "ceid": ce_id},
                )
            db.session.commit()
        if "color_episode" in inspect(db.engine).get_table_names():
            cols = {c["name"] for c in inspect(db.engine).get_columns("color_episode")}
            with db.engine.begin() as conn:
                if "sent_to_color_at" not in cols:
                    conn.execute(text("ALTER TABLE color_episode ADD COLUMN sent_to_color_at DATETIME"))
                if "sent_by_user_id" not in cols:
                    conn.execute(
                        text(
                            "ALTER TABLE color_episode ADD COLUMN sent_by_user_id INTEGER "
                            "REFERENCES users(id)"
                        )
                    )
                refreshed = {c["name"] for c in inspect(db.engine).get_columns("color_episode")}
                if "sent_to_department_at" in refreshed and "sent_to_color_at" in refreshed:
                    conn.execute(
                        text(
                            "UPDATE color_episode SET sent_to_color_at = sent_to_department_at "
                            "WHERE sent_to_color_at IS NULL AND sent_to_department_at IS NOT NULL"
                        )
                    )
                refreshed = {c["name"] for c in inspect(db.engine).get_columns("color_episode")}
                if "status_before_block" not in refreshed:
                    conn.execute(
                        text("ALTER TABLE color_episode ADD COLUMN status_before_block VARCHAR(32)")
                    )
                refreshed = {c["name"] for c in inspect(db.engine).get_columns("color_episode")}
                if "editing_item_id" not in refreshed:
                    conn.execute(
                        text(
                            "ALTER TABLE color_episode ADD COLUMN editing_item_id INTEGER "
                            "REFERENCES editing_item(id)"
                        )
                    )

