    def migrate_legacy_action_items_once() -> None:
        """One-time import from todo_items / sticky_notes into action_items."""
        if ActionItem.query.count() > 0:
            return
        todo_map: dict[int, int] = {}
        for t in TodoItem.query.order_by(TodoItem.id.asc()).all():
            row = ActionItem(
                item_type="todo",
                title=t.title,
                body=t.description or "",
                status=t.status or "open",
                priority=t.priority or "normal",
                due_date=t.due_date,
                due_time=t.due_time,
                color="yellow",
                is_pinned=False,
                project_id=t.project_id,
                episode_id=t.episode_id,
                scene_id=t.scene_id,
                shooting_day_id=t.shooting_day_id,
                vfx_shot_id=t.vfx_shot_id,
                assigned_to_user_id=t.assigned_to_user_id,
                created_by_user_id=t.created_by_user_id,
                completed_by_user_id=t.completed_by_user_id,
                is_archived=bool(t.is_archived),
                completed_at=t.completed_at,
                created_at=t.created_at,
                updated_at=t.updated_at or t.created_at,
            )
            db.session.add(row)
            db.session.flush()
            todo_map[int(t.id)] = int(row.id)
        merged_todos: set[int] = set()
        for s in StickyNote.query.order_by(StickyNote.id.asc()).all():
            if s.linked_todo_id and int(s.linked_todo_id) in todo_map:
                row = db.session.get(ActionItem, todo_map[int(s.linked_todo_id)])
                if row is not None:
                    row.item_type = "hybrid"
                    row.title = s.title or row.title
                    if s.body:
                        row.body = s.body
                    row.color = s.color or "yellow"
                    row.is_pinned = bool(s.is_pinned)
                    row.position_x = s.position_x
                    row.position_y = s.position_y
                    row.width = s.width
                    row.height = s.height
                    merged_todos.add(int(s.linked_todo_id))
                continue
            db.session.add(
                ActionItem(
                    item_type="note",
                    title=s.title,
                    body=s.body or "",
                    status="open",
                    priority="normal",
                    color=s.color or "yellow",
                    is_pinned=bool(s.is_pinned),
                    position_x=s.position_x,
                    position_y=s.position_y,
                    width=s.width,
                    height=s.height,
                    project_id=s.project_id,
                    episode_id=s.episode_id,
                    scene_id=s.scene_id,
                    shooting_day_id=s.shooting_day_id,
                    vfx_shot_id=s.vfx_shot_id,
                    assigned_to_user_id=s.assigned_to_user_id,
                    created_by_user_id=s.created_by_user_id,
                    is_archived=bool(s.is_archived),
                    created_at=s.created_at,
                    updated_at=s.updated_at or s.created_at,
                )
            )
        db.session.commit()

    def purge_non_note_action_items() -> None:
        """Action Board now supports Notes only; remove any legacy TO DO / Hybrid rows."""
        try:
            removed = (
                ActionItem.query.filter(ActionItem.item_type != "note").delete(synchronize_session=False)
            )
        except Exception:
            db.session.rollback()
            return
        if removed:
            db.session.commit()
        else:
            db.session.rollback()

    def ensure_offline_and_production_color_view_permissions() -> None:
        """Allow editorial and production-team job-title scopes to view color overview/editor mode."""
        from project_settings import (
            PRODUCTION_TEAM_SCOPE_KEY,
            parse_linked_post_scope_keys,
        )

        JobTitlePermission = perm_models.JobTitlePermission
        scopes = {"needs_offline_editing", PRODUCTION_TEAM_SCOPE_KEY}
        titles = (
            JobTitle.query.options(joinedload(JobTitle.category))
            .order_by(JobTitle.id.asc())
            .all()
        )
        for jt in titles:
            cat = getattr(jt, "category", None)
            linked = parse_linked_post_scope_keys(
                getattr(cat, "linked_post_scope_keys", None) if cat is not None else None
            )
            if not scopes.intersection(linked):
                continue
            for page_key in ("color_overview", "color_department"):
                for action_key in ("view",):
                    exists_perm = JobTitlePermission.query.filter_by(
                        job_title_id=int(jt.id),
                        page_key=page_key,
                        action_key=action_key,
                    ).first()
                    if exists_perm is None:
                        db.session.add(
                            JobTitlePermission(
                                job_title_id=int(jt.id),
                                page_key=page_key,
                                action_key=action_key,
                                is_allowed=True,
                            )
                        )
            if "needs_offline_editing" in linked:
                exists_send = JobTitlePermission.query.filter_by(
                    job_title_id=int(jt.id),
                    page_key="color_overview",
                    action_key="send_to_color_department",
                ).first()
                if exists_send is None:
                    db.session.add(
                        JobTitlePermission(
                            job_title_id=int(jt.id),
                            page_key="color_overview",
                            action_key="send_to_color_department",
                            is_allowed=True,
                        )
                    )
        db.session.commit()

