        if "notification_rule_audit_log" not in names:
            NotificationRuleAuditLog.__table__.create(bind=db.engine, checkfirst=True)

        def _add_missing(table_name: str, columns: dict[str, str]) -> None:
            cols = {c["name"] for c in inspect(db.engine).get_columns(table_name)}
            with db.engine.begin() as conn:
                for col_name, ddl in columns.items():
                    if col_name not in cols:
                        conn.execute(text(f"ALTER TABLE {table_name} ADD COLUMN {col_name} {ddl}"))

        _add_missing(
            "notification_rule",
            {
                "description": "TEXT NOT NULL DEFAULT ''",
                "category": "VARCHAR(32) NOT NULL DEFAULT 'general'",
                "is_enabled": "BOOLEAN NOT NULL DEFAULT 1",
                "priority": "VARCHAR(16) NOT NULL DEFAULT 'normal'",
                "cta_label_template": "VARCHAR(120)",
                "cta_url_template": "VARCHAR(255)",
                "recipient_mode": "VARCHAR(32) NOT NULL DEFAULT 'project_members'",
                "recipient_config_json": "TEXT NOT NULL DEFAULT '{}'",
                "condition_config_json": "TEXT NOT NULL DEFAULT '{}'",
                "exclude_actor": "BOOLEAN NOT NULL DEFAULT 1",
                "dedupe_enabled": "BOOLEAN NOT NULL DEFAULT 1",
                "dedupe_window_minutes": "INTEGER NOT NULL DEFAULT 30",
                "source": "VARCHAR(255)",
                "registered_event": "BOOLEAN NOT NULL DEFAULT 0",
                "available_variables_json": "TEXT NOT NULL DEFAULT '[]'",
                "default_config_json": "TEXT NOT NULL DEFAULT '{}'",
                "is_deprecated": "BOOLEAN NOT NULL DEFAULT 0",
                "created_at": "DATETIME",
                "updated_at": "DATETIME",
                "updated_by_id": "INTEGER REFERENCES users(id)",
            },
        )
        _add_missing(
            "notification_rule_audit_log",
            {
                "rule_id": "INTEGER REFERENCES notification_rule(id)",
                "event_key": "VARCHAR(120) NOT NULL DEFAULT ''",
                "project_id": "INTEGER REFERENCES projects(id)",
                "actor_id": "INTEGER REFERENCES users(id)",
                "resolved_recipient_ids": "TEXT NOT NULL DEFAULT '[]'",
                "title_rendered": "VARCHAR(255)",
                "body_rendered": "TEXT",
                "cta_url": "VARCHAR(255)",
                "status": "VARCHAR(32) NOT NULL DEFAULT 'sent'",
                "error": "TEXT NOT NULL DEFAULT ''",
                "created_at": "DATETIME",
            },
        )
        with db.engine.begin() as conn:
            conn.execute(text("CREATE UNIQUE INDEX IF NOT EXISTS ix_notification_rule_event_key_unique ON notification_rule(event_key)"))
            conn.execute(text("CREATE INDEX IF NOT EXISTS ix_notification_rule_category ON notification_rule(category)"))
            conn.execute(text("CREATE INDEX IF NOT EXISTS ix_notification_rule_registered_event ON notification_rule(registered_event)"))
            conn.execute(text("CREATE INDEX IF NOT EXISTS ix_notification_rule_is_deprecated ON notification_rule(is_deprecated)"))
            conn.execute(text("CREATE INDEX IF NOT EXISTS ix_notification_rule_audit_event_key ON notification_rule_audit_log(event_key)"))
