    def _upgrade_machine_room_notification_recipient_presets() -> None:
        """One-time style upgrade: MR stream events should notify all project members."""
        project_team_cfg = json.dumps(notif_events._expand_recipients({"preset": "project_team"}))
        for event_key in _MR_NOTIFICATION_EVENT_KEYS:
            row = NotificationRule.query.filter_by(event_key=event_key).first()
            if row is None:
                continue
            cfg = _notification_json(row.recipient_config_json, {})
            if cfg.get("all_project_members"):
                continue
            post_scopes = set(cfg.get("post_scopes") or [])
            if (
                post_scopes == {"needs_production_team"}
                and not cfg.get("job_titles")
                and not cfg.get("user_ids")
                and not cfg.get("dynamic")
            ):
                row.recipient_config_json = project_team_cfg
                row.updated_at = now_local()

    def _upgrade_critical_note_notification_rule() -> None:
        """Day criticals should notify all project team members (not production_team preset only)."""
        project_team_cfg = json.dumps(notif_events._expand_recipients({"preset": "project_team"}))
        row = NotificationRule.query.filter_by(event_key="critical_note_added").first()
        if row is None:
            return
        cfg = _notification_json(row.recipient_config_json, {})
        if cfg.get("all_project_members"):
            return
        post_scopes = set(cfg.get("post_scopes") or [])
        if (
            post_scopes == {"needs_production_team"}
            and not cfg.get("job_titles")
            and not cfg.get("user_ids")
            and not cfg.get("dynamic")
        ):
            row.recipient_config_json = project_team_cfg
            row.updated_at = now_local()

    def _upgrade_editing_item_sent_to_color_notification_rule() -> None:
        row = NotificationRule.query.filter_by(event_key="editing_item_sent_to_color").first()
        if row is None:
            return
        changed = False
        item_cta = "/projects/{{ project_id }}/color/items/{{ editing_item_id }}"
        if (row.cta_url_template or "").strip() in ("", "/projects/{{ project_id }}/color"):
            row.cta_url_template = item_cta
            changed = True
        if (row.cta_label_template or "").strip() in ("", "Open Color"):
            row.cta_label_template = "Open Color Item"
            changed = True
        old_title = "{{ project_name }} · Episode sent to Color: {{ editing_item_code }}"
        new_title = "{{ project_name }} · Editing item sent to Color: {{ editing_item_code }}"
        if (row.title_template or "").strip() == old_title:
            row.title_template = new_title
            changed = True
        if changed:
            row.updated_at = now_local()

    def _upgrade_conform_requested_notification_rule() -> None:
        row = NotificationRule.query.filter_by(event_key="conform_requested").first()
        if row is None:
            return
        changed = False
        item_cta = "/projects/{{ project_id }}/color/items/{{ editing_item_id }}"
        if (row.cta_url_template or "").strip() in ("", "/tasks#task-{{ task_id }}"):
            row.cta_url_template = item_cta
            changed = True
        if (row.cta_label_template or "").strip() in ("", "Open Conform Task"):
            row.cta_label_template = "Open Color Item"
            changed = True
        expected_title = "Conform requested: {{ editing_item_code }}"
        if (row.title_template or "").strip() in ("", "Conform requested"):
            row.title_template = expected_title
            changed = True
        if changed:
            row.updated_at = now_local()

    def _upgrade_handoff_file_uploaded_notification_rule() -> None:
        row = NotificationRule.query.filter_by(event_key="handoff_file_uploaded").first()
        if row is None:
            return
        changed = False
        new_title = "Color handoff uploaded"
        old_title = "Color handoff uploaded: {{ editing_item_code }}"
        if (row.title_template or "").strip() in (old_title, "Color handoff uploaded:"):
            row.title_template = new_title
            changed = True
        new_body = (
            "{{ actor_name }} uploaded for {{ project_name }} · {{ editing_item_title }}.\n\n"
            "Handoff file: {{ handoff_file_name }}\n"
            "Guide video: {{ guide_video_label }}"
        )
        old_body = (
            "{{ actor_name }} uploaded {{ handoff_file_type }} for {{ editing_item_code }} · {{ editing_item_title }}.\n\n"
            "Handoff file: {{ handoff_file_name }}\n"
            "Guide video: {{ guide_video_label }}"
        )
        if (row.body_template or "").strip() == old_body:
            row.body_template = new_body
            changed = True
        if changed:
            row.updated_at = now_local()

    def _upgrade_jinja_control_notification_rule_bodies() -> None:
        """Replace stored rule bodies that still use {% if %} (renderer historically ignored them)."""
        for event_key, event in get_registered_notification_events().items():
            row = NotificationRule.query.filter_by(event_key=event_key).first()
            if row is None:
                continue
            body = row.body_template or ""
            if "{%" not in body:
                continue
            new_body = (event.get("default_body") or "").strip()
            if not new_body or new_body == body.strip():
                continue
            row.body_template = new_body
            row.updated_at = now_local()

    def _scrub_stored_notification_messages_with_jinja_tags() -> None:
        """One-time cleanup of already-delivered notification messages that leaked Jinja tags."""
        rows = (
            Notification.query.filter(Notification.message.contains("{%"))
            .limit(500)
            .all()
        )
        for n in rows:
            cleaned = scrub_notification_template_tags(n.message or "")
            if cleaned != (n.message or "").strip():
                n.message = cleaned

    def sync_registered_notification_events_to_rules(*, restore: bool = False) -> None:
        registered = get_registered_notification_events()
        for event_key, event in registered.items():
            spec = _registry_rule_spec(event_key, event)
            row = NotificationRule.query.filter_by(event_key=event_key).first()
            if row is None:
                db.session.add(NotificationRule(**spec, created_at=now_local()))
                continue
            metadata_keys = (
                "label",
                "description",
                "category",
                "source",
                "registered_event",
                "available_variables_json",
                "default_config_json",
                "is_deprecated",
            )
            editable_keys = (
                "is_enabled",
                "priority",
                "title_template",
                "body_template",
                "cta_label_template",
                "cta_url_template",
                "recipient_mode",
                "recipient_config_json",
                "condition_config_json",
                "exclude_actor",
                "dedupe_enabled",
                "dedupe_window_minutes",
            )
            for key in metadata_keys:
                if restore or getattr(row, key, None) in (None, "", "[]", "{}") or key in ("registered_event", "is_deprecated"):
                    setattr(row, key, spec[key])
            if restore:
                for key in editable_keys:
                    setattr(row, key, spec[key])
                row.updated_at = now_local()

        registered_keys = set(registered.keys())
        for row in NotificationRule.query.filter(NotificationRule.registered_event.is_(True)).all():
            if row.event_key not in registered_keys and not row.is_deprecated:
                row.is_deprecated = True
                row.updated_at = now_local()
        _upgrade_machine_room_notification_recipient_presets()
        _upgrade_critical_note_notification_rule()
        _upgrade_editing_item_sent_to_color_notification_rule()
        _upgrade_conform_requested_notification_rule()
        _upgrade_handoff_file_uploaded_notification_rule()
        _upgrade_jinja_control_notification_rule_bodies()
        _scrub_stored_notification_messages_with_jinja_tags()
        db.session.commit()

    DEFAULT_NOTIFICATION_RULES = tuple(
        _registry_rule_spec(event_key, event)
        for event_key, event in get_registered_notification_events().items()
        if event.get("is_active", True)
    )

