    def account_can_move_project_audio_folders_for(
        acc: Account | None, project_id: int
    ) -> bool:
        if account_can_manage_project_team_for(acc, project_id):
            return True
        return bool(
            acc is not None
            and account_can_access_project(acc, project_id)
            and account_is_editing_team(acc)
        )

    def resolve_project_id_from_request_path(path: str) -> int | None:
        import re

        p = (path or "").split("?", 1)[0].rstrip("/") or "/"
        for pat in (
            r"^/projects/(\d+)",
            r"^/project/(\d+)",
            r"^/color-department/(\d+)",
            r"^/machine/project/(\d+)",
        ):
            m = re.match(pat, p)
            if m:
                return int(m.group(1))
        m = re.match(r"^/editing-items/(\d+)", p)
        if m:
            item = db.session.get(EditingItem, int(m.group(1)))
            return int(item.project_id) if item and item.project_id else None
        m = re.match(r"^/episodes/(\d+)", p)
        if m:
            episode = db.session.get(ProductionEpisode, int(m.group(1)))
            return int(episode.project_id) if episode and episode.project_id else None
        m = re.match(r"^/editing-item-versions/(\d+)", p)
        if m:
            version = db.session.get(EditingItemVersion, int(m.group(1)))
            if version is None:
                return None
            item = db.session.get(EditingItem, int(version.editing_item_id))
            return int(item.project_id) if item and item.project_id else None
        m = re.match(r"^/api/tasks/(\d+)", p)
        if m:
            task = db.session.get(Task, int(m.group(1)))
            return int(task.project_id) if task and task.project_id else None
        m = re.match(r"^/tasks/(\d+)", p)
        if m:
            task = db.session.get(Task, int(m.group(1)))
            return int(task.project_id) if task and task.project_id else None
        return None

    def account_has_vfx_job_title(acc: Account | None) -> bool:
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return False
        u = (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .filter_by(id=uid)
            .first()
        )
        if u is None:
            return False
        for jt in u.assigned_job_titles():
            if job_title_contains_vfx(jt.name):
                return True
        return False

    def account_has_color_job_title(acc: Account | None) -> bool:
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return False
        u = (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .filter_by(id=uid)
            .first()
        )
        if u is None:
            return False
        for jt in u.assigned_job_titles():
            if cg.job_title_contains_color(jt.name):
                return True
        return False

    def account_is_color_supervisor_effective(acc: Account | None) -> bool:
        if acc is None:
            return False
        if getattr(acc, "is_admin", False):
            return True
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return False
        u = (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .filter_by(id=uid)
            .first()
        )
        if u is None:
            return False
        for jt in u.assigned_job_titles():
            if cg.job_title_matches_color_supervisor(jt.name):
                return True
            if cg.job_title_matches_post_producer(jt.name):
                return True
            if cg.job_title_matches_producer_role(jt.name):
                return True
        return False

    def project_ids_with_vfx_department_shots() -> set[int]:
        """Projects that have at least one in-house VFX shot."""
        out: set[int] = set()
        rows = (
            db.session.query(VfxShot.project_id, VfxShot.vendor).distinct().all()
        )
        for pid, vendor in rows:
            if pid is not None and vfx_vendor_is_in_house(vendor):
                out.add(int(pid))
        return out

    def visible_project_ids_for_vfx_department(acc: Account | None) -> set[int] | None:
        """Hub listing: team projects, or all projects with in-house department shots for VFX job titles."""
        vis = visible_project_ids_for_account(acc)
        if vis is None:
            return None
        if not account_has_vfx_job_title(acc):
            return vis
        return vis | project_ids_with_vfx_department_shots()

    def account_can_access_vfx_department_project(acc: Account | None, project_id: int) -> bool:
        if account_can_access_project(acc, project_id):
            return True
        if not account_has_vfx_job_title(acc):
            return False
        return project_id in project_ids_with_vfx_department_shots()

