    @app.before_request
    def enforce_access_permissions():
        if request.endpoint in PUBLIC_ENDPOINTS or request.endpoint is None:
            return
        acc = account_from_session()
        if acc is None:
            return
        if not account_approval_support_mod.account_may_use_app(acc):
            ep = request.endpoint or ""
            if ep in account_approval_support_mod.PENDING_USER_ENDPOINTS:
                return
        decision = perm_svc.check_request(acc)
        if decision is None or decision.allowed:
            return
        return permission_denied_response(
            json_error=(
                request.path.startswith("/admin/api/")
                or request.path.endswith("/data")
                or "/api/" in request.path
            )
        )

    @app.context_processor
    def inject_permission_helpers():
        def template_can(page_key: str, action_key: str = "view", **kwargs):
            acc = account_from_session()
            owner_user_id = kwargs.get("owner_user_id")
            project_id = kwargs.get("project_id")
            return perm_svc.can(
                acc,
                page_key,
                action_key,
                owner_user_id=owner_user_id,
                project_id=project_id,
            )

        return {"can": template_can, "perm_can": template_can}

