    def _perm_catalog_payload() -> dict:
        pages = PermissionPage.query.order_by(PermissionPage.module.asc(), PermissionPage.name.asc()).all()
        actions = PermissionAction.query.order_by(PermissionAction.key.asc()).all()
        role_perms = RolePermission.query.all()
        jt_perms = JobTitlePermission.query.all()
        overrides = UserPermissionOverride.query.order_by(UserPermissionOverride.id.desc()).all()
        job_titles = JobTitle.query.order_by(JobTitle.name.asc()).all()
        users = User.query.order_by(User.name.asc()).all()
        return {
            "pages": [
                {
                    "id": p.id,
                    "key": p.key,
                    "name": p.name,
                    "description": p.description or "",
                    "route_pattern": p.route_pattern,
                    "module": p.module,
                    "is_active": bool(p.is_active),
                }
                for p in pages
            ],
            "actions": [
                {"id": a.id, "key": a.key, "name": a.name, "description": a.description or ""}
                for a in actions
            ],
            "role_permissions": [
                {
                    "role_name": r.role_name,
                    "page_key": r.page_key,
                    "action_key": r.action_key,
                    "is_allowed": bool(r.is_allowed),
                }
                for r in role_perms
            ],
            "job_title_permissions": [
                {
                    "job_title_id": j.job_title_id,
                    "page_key": j.page_key,
                    "action_key": j.action_key,
                    "is_allowed": bool(j.is_allowed),
                }
                for j in jt_perms
            ],
            "user_overrides": [
                {
                    "id": o.id,
                    "user_id": o.user_id,
                    "page_key": o.page_key,
                    "action_key": o.action_key,
                    "is_allowed": bool(o.is_allowed),
                    "note": o.note or "",
                }
                for o in overrides
            ],
            "job_titles": [{"id": j.id, "name": j.name} for j in job_titles],
            "users": [{"id": u.id, "name": u.name} for u in users],
        }

