    def account_may_use_project_chat(acc: Account | None, project_id: int) -> bool:
        """Only directory users listed on the project team may use chat (same scope as task assignees)."""
        if not account_can_access_project(acc, project_id):
            return False
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return False
        return ProjectMember.query.filter_by(project_id=project_id, user_id=uid).first() is not None

    def ensure_project_chat_read_initialized(acc: Account | None, project_id: int) -> None:
        if acc is None or not account_may_use_project_chat(acc, project_id):
            return
        exists = ProjectChatReadState.query.filter_by(
            account_id=acc.id, project_id=project_id
        ).first()
        if exists is not None:
            return
        mx = (
            db.session.query(db.func.max(ChatMessage.id))
            .filter(ChatMessage.project_id == project_id)
            .scalar()
        )
        mid = int(mx) if mx is not None else 0
        db.session.add(
            ProjectChatReadState(
                account_id=acc.id,
                project_id=project_id,
                last_read_message_id=mid,
            )
        )
        db.session.commit()

    def chat_unread_count_for_account(acc: Account | None, project_id: int) -> int:
        if acc is None or not account_may_use_project_chat(acc, project_id):
            return 0
        ensure_project_chat_read_initialized(acc, project_id)
        state = ProjectChatReadState.query.filter_by(
            account_id=acc.id, project_id=project_id
        ).first()
        last_id = state.last_read_message_id if state else 0
        uid = directory_user_id_for_account(acc)
        q = ChatMessage.query.filter(
            ChatMessage.project_id == project_id,
            ChatMessage.id > last_id,
        )
        if uid is not None:
            q = q.filter(ChatMessage.user_id != uid)
        return q.count()

    def chat_mark_project_read(acc: Account | None, project_id: int) -> None:
        if acc is None or not account_may_use_project_chat(acc, project_id):
            return
        ensure_project_chat_read_initialized(acc, project_id)
        mx = (
            db.session.query(db.func.max(ChatMessage.id))
            .filter(ChatMessage.project_id == project_id)
            .scalar()
        )
        mid = int(mx) if mx is not None else 0
        state = ProjectChatReadState.query.filter_by(
            account_id=acc.id, project_id=project_id
        ).first()
        if state is None:
            return
        if mid > state.last_read_message_id:
            state.last_read_message_id = mid
            db.session.commit()

    def eligible_chat_project_ids(acc: Account | None) -> list[int]:
        """Projects where the account has team chat (directory user on project team)."""
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return []
        return [
            pm.project_id
            for pm in ProjectMember.query.filter_by(user_id=uid)
            .order_by(ProjectMember.project_id.asc())
            .all()
        ]

    def get_or_create_project_thread(project_id: int) -> ChatThread | None:
        thread = ChatThread.query.filter_by(
            thread_type=chat_thr.THREAD_TYPE_PROJECT, project_id=project_id
        ).first()
        if thread is not None:
            return thread
        proj = Project.query.get(project_id)
        thread = ChatThread(
            thread_type=chat_thr.THREAD_TYPE_PROJECT,
            project_id=project_id,
            title=(proj.name if proj else None) or f"Project {project_id}",
        )
        db.session.add(thread)
        db.session.flush()
        for pm in ProjectMember.query.filter_by(project_id=project_id).all():
            u = User.query.get(pm.user_id)
            if u is None or u.account_id is None:
                continue
            db.session.add(
                ChatThreadParticipant(
                    thread_id=thread.id,
                    account_id=u.account_id,
                    directory_user_id=u.id,
                )
            )
        db.session.commit()
        return thread

    def thread_participant_row(
        acc: Account | None,
        thread_id: int,
        *,
        active_only: bool = False,
    ) -> ChatThreadParticipant | None:
        if acc is None:
            return None
        q = ChatThreadParticipant.query.filter_by(thread_id=thread_id, account_id=acc.id)
        if active_only:
            q = q.filter(ChatThreadParticipant.is_active.is_(True))
        return q.first()

    def active_participant_count(thread_id: int) -> int:
        return ChatThreadParticipant.query.filter_by(
            thread_id=thread_id, is_active=True
        ).count()

    def account_has_active_participation(acc: Account | None, thread_id: int) -> bool:
        return thread_participant_row(acc, thread_id, active_only=True) is not None

    def account_may_use_direct_chat(acc: Account | None, thread_id: int) -> bool:
        if acc is None:
            return False
        thread = ChatThread.query.get(thread_id)
        if thread is None or thread.thread_type != chat_thr.THREAD_TYPE_DIRECT:
            return False
        if not thread.is_active:
            return False
        return account_has_active_participation(acc, thread_id)

    def account_may_use_group_chat(acc: Account | None, thread_id: int) -> bool:
        if acc is None:
            return False
        thread = ChatThread.query.get(thread_id)
        if thread is None or thread.thread_type != chat_thr.THREAD_TYPE_GROUP:
            return False
        if not thread.is_active:
            return False
        return account_has_active_participation(acc, thread_id)

    def account_may_use_department_chat(acc: Account | None, thread_id: int) -> bool:
        if acc is None:
            return False
        thread = ChatThread.query.get(thread_id)
        if thread is None or thread.thread_type != chat_thr.THREAD_TYPE_DEPARTMENT:
            return False
        if not thread.is_active:
            return False
        return account_has_active_participation(acc, thread_id)

    def account_may_use_chat_thread(acc: Account | None, thread_id: int) -> bool:
        thread = ChatThread.query.get(thread_id)
        return account_may_use_thread(acc, thread)

    def account_may_use_thread(acc: Account | None, thread: ChatThread | None) -> bool:
        if acc is None or thread is None or not thread.is_active:
            return False
        if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT:
            return account_may_use_project_chat(acc, int(thread.project_id or 0))
        if thread.thread_type == chat_thr.THREAD_TYPE_DIRECT:
            return account_may_use_direct_chat(acc, thread.id)
        if thread.thread_type == chat_thr.THREAD_TYPE_GROUP:
            return account_may_use_group_chat(acc, thread.id)
        if thread.thread_type == chat_thr.THREAD_TYPE_DEPARTMENT:
            return account_may_use_department_chat(acc, thread.id)
        return False

    def group_participant_is_admin(part: ChatThreadParticipant | None) -> bool:
        if part is None:
            return False
        return part.role in (
            chat_thr.PARTICIPANT_ROLE_OWNER,
            chat_thr.PARTICIPANT_ROLE_ADMIN,
        )

    def eligible_account_ids_for_job_category(category_id: int) -> set[int]:
        title_ids = [
            int(r[0])
            for r in db.session.query(JobTitle.id)
            .filter(JobTitle.category_id == category_id)
            .all()
            if r[0] is not None
        ]
        if not title_ids:
            return set()
        account_ids: set[int] = set()
        m2m_user_ids = {
            int(r[0])
            for r in db.session.query(UserJobTitle.user_id)
            .filter(UserJobTitle.job_title_id.in_(title_ids))
            .distinct()
            .all()
            if r[0] is not None
        }
        legacy_users = User.query.filter(
            User.job_title_id.in_(title_ids),
            User.account_id.isnot(None),
        ).all()
        for uid in m2m_user_ids:
            u = User.query.get(uid)
            if u is not None and u.account_id is not None:
                account_ids.add(int(u.account_id))
        for u in legacy_users:
            if u.account_id is not None:
                account_ids.add(int(u.account_id))
        return account_ids

    def get_or_create_department_thread(category: JobCategory) -> ChatThread:
        thread = ChatThread.query.filter_by(
            thread_type=chat_thr.THREAD_TYPE_DEPARTMENT,
            department_id=category.id,
        ).first()
        cname = (category.name or "Department").strip()
        if thread is None:
            thread = ChatThread(
                thread_type=chat_thr.THREAD_TYPE_DEPARTMENT,
                department_id=category.id,
                title=f"{cname} Chat",
                avatar_label=chat_thr.avatar_initial_from_name(cname),
                is_active=True,
            )
            db.session.add(thread)
            db.session.flush()
        elif not thread.title:
            thread.title = f"{cname} Chat"
        return thread

    def ensure_group_participant(
        thread_id: int,
        account_id: int,
        *,
        role: str = chat_thr.PARTICIPANT_ROLE_MEMBER,
    ) -> ChatThreadParticipant:
        part = ChatThreadParticipant.query.filter_by(
            thread_id=thread_id, account_id=account_id
        ).first()
        u = User.query.filter_by(account_id=account_id).first()
        if part is None:
            part = ChatThreadParticipant(
                thread_id=thread_id,
                account_id=account_id,
                directory_user_id=u.id if u else None,
                role=role,
                is_active=True,
            )
            db.session.add(part)
            return part
        part.is_active = True
        part.left_at = None
        if u is not None:
            part.directory_user_id = u.id
        if role == chat_thr.PARTICIPANT_ROLE_OWNER:
            part.role = role
        return part

    def sync_department_chat_participants() -> dict:
        """Materialize department chat membership from job categories."""
        stats = {"categories": 0, "threads": 0, "added": 0, "deactivated": 0}
        now = now_local()
        for category in JobCategory.query.order_by(JobCategory.sort_order.asc(), JobCategory.name.asc()).all():
            stats["categories"] += 1
            thread = get_or_create_department_thread(category)
            stats["threads"] += 1
            eligible = eligible_account_ids_for_job_category(category.id)
            for aid in eligible:
                part = ChatThreadParticipant.query.filter_by(
                    thread_id=thread.id, account_id=aid
                ).first()
                if part is None:
                    ensure_group_participant(thread.id, aid)
                    stats["added"] += 1
                elif not part.is_active:
                    part.is_active = True
                    part.left_at = None
                    stats["added"] += 1
            for part in ChatThreadParticipant.query.filter_by(thread_id=thread.id).all():
                if part.account_id not in eligible and part.is_active:
                    part.is_active = False
                    part.left_at = now
                    stats["deactivated"] += 1
        db.session.commit()
        return stats

    def serialize_thread_member_row(part: ChatThreadParticipant) -> dict:
        u = part.directory_user
        if u is None and part.account_id is not None:
            u = User.query.filter_by(account_id=part.account_id).first()
        name = (u.name if u else None) or ""
        if not name.strip() and part.account_id is not None:
            acc_row = db.session.get(Account, part.account_id)
            name = (acc_row.display_name if acc_row else "") or "User"
        jt_label = ""
        if u is not None:
            titles = u.assigned_job_titles()
            if titles:
                jt_label = (titles[0].name or "").strip()
        return {
            "account_id": part.account_id,
            "user_id": u.id if u else part.directory_user_id,
            "name": name.strip() or "User",
            "job_title": jt_label or None,
            "role": part.role or chat_thr.PARTICIPANT_ROLE_MEMBER,
            "avatar_initial": chat_thr.avatar_initial_from_name(name),
            "avatar_url": chat_avatar_url_for_user(u),
            "is_active": bool(part.is_active),
        }

    def thread_members_for_api(thread: ChatThread) -> list[dict]:
        rows = (
            ChatThreadParticipant.query.filter_by(thread_id=thread.id, is_active=True)
            .order_by(ChatThreadParticipant.role.asc(), ChatThreadParticipant.joined_at.asc())
            .all()
        )
        return [serialize_thread_member_row(p) for p in rows]

    def conference_participant_row(
        acc: Account | None, conference_id: int
    ) -> ChatConferenceParticipant | None:
        if acc is None:
            return None
        return ChatConferenceParticipant.query.filter_by(
            conference_id=conference_id, account_id=acc.id
        ).first()

    def account_may_use_conference(acc: Account | None, conference: ChatConference | None) -> bool:
        if acc is None or conference is None:
            return False
        if conference.thread_id is not None:
            thread = ChatThread.query.get(conference.thread_id)
            if thread is None or not account_may_use_thread(acc, thread):
                return False
        elif conference.project_id is not None:
            if not account_may_use_project_chat(acc, int(conference.project_id)):
                return False
        else:
            return False
        if conference.created_by_account_id == acc.id:
            return True
        part = conference_participant_row(acc, conference.id)
        if part is None:
            if conference.thread_id is not None:
                thread = ChatThread.query.get(conference.thread_id)
                if thread and thread.thread_type == chat_thr.THREAD_TYPE_PROJECT:
                    return True
            return False
        return part.invite_status != chat_conf.INVITE_DECLINED

    def conference_can_manage(acc: Account | None, conference: ChatConference) -> bool:
        if acc is None:
            return False
        if acc.is_admin:
            return True
        if conference.created_by_account_id == acc.id:
            return True
        part = conference_participant_row(acc, conference.id)
        return part is not None and part.role == chat_conf.ROLE_HOST

    def conference_can_join(acc: Account | None, conference: ChatConference) -> bool:
        if not account_may_use_conference(acc, conference):
            return False
        if conference.status not in (chat_conf.STATUS_LIVE, chat_conf.STATUS_SCHEDULED):
            return False
        if conference.created_by_account_id == acc.id:
            return True
        part = conference_participant_row(acc, conference.id)
        if part is None:
            thread = ChatThread.query.get(conference.thread_id) if conference.thread_id else None
            return bool(thread and thread.thread_type == chat_thr.THREAD_TYPE_PROJECT)
        return part.invite_status in (
            chat_conf.INVITE_INVITED,
            chat_conf.INVITE_ACCEPTED,
            chat_conf.INVITE_JOINED,
        )

    def default_participant_account_ids_for_thread(
        thread: ChatThread, acc: Account, selected: list[int] | None = None
    ) -> list[int]:
        if selected:
            ids = sorted({int(x) for x in selected if int(x) != acc.id})
            return ids
        ids: set[int] = set()
        if thread.thread_type == chat_thr.THREAD_TYPE_DIRECT:
            other = chat_thr.other_direct_participant_account_id(thread.participants, acc.id)
            if other is not None:
                ids.add(int(other))
        else:
            for part in ChatThreadParticipant.query.filter_by(
                thread_id=thread.id, is_active=True
            ).all():
                if part.account_id != acc.id:
                    ids.add(int(part.account_id))
        return sorted(ids)

    def default_conference_title_for_thread(thread: ChatThread, acc: Account) -> str:
        if thread.thread_type == chat_thr.THREAD_TYPE_DIRECT:
            other = chat_thr.other_direct_participant_account_id(thread.participants, acc.id)
            if other is not None:
                u = User.query.filter_by(account_id=other).first()
                name = (u.name if u else None) or "User"
                return f"Call with {name.strip()}"
            return "Direct call"
        if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT and thread.project_id:
            proj = Project.query.get(thread.project_id)
            pname = (proj.name if proj else None) or "Project"
            return f"{pname.strip()} Conference"
        if thread.thread_type == chat_thr.THREAD_TYPE_DEPARTMENT:
            return f"{(thread.title or 'Department').strip()} Department Call"
        if thread.thread_type == chat_thr.THREAD_TYPE_GROUP:
            return f"{(thread.title or 'Group').strip()} Call"
        return (thread.title or "Conference").strip()

    def emit_conference_event(
        conference: ChatConference,
        *,
        kind: str,
        extra: dict | None = None,
    ) -> None:
        payload: dict = {
            "conference_id": conference.id,
            "thread_id": conference.thread_id,
            "project_id": conference.project_id,
            "status": conference.status,
            "provider": chat_conf.effective_provider(conference.provider),
            "kind": kind,
        }
        if extra:
            payload.update(extra)
        specific_event = {
            "joined": "conference_joined",
            "left": "conference_left",
            "ended": "conference_ended",
            "cancelled": "conference_ended",
        }.get(kind)
        if conference.thread_id is not None:
            room = f"chat_thread_{conference.thread_id}"
            socketio.emit("conference_updated", payload, room=room)
            if specific_event:
                socketio.emit(specific_event, payload, room=room)
        for part in ChatConferenceParticipant.query.filter_by(conference_id=conference.id).all():
            socketio.emit("conference_invite", payload, room=f"user_{part.account_id}")
            if specific_event:
                socketio.emit(specific_event, payload, room=f"user_{part.account_id}")

    def serialize_conference_json(
        conference: ChatConference,
        acc: Account | None,
        *,
        include_meeting_url: bool = False,
    ) -> dict:
        part = conference_participant_row(acc, conference.id) if acc else None
        eff_provider = chat_conf.effective_provider(conference.provider)
        row: dict = {
            "id": conference.id,
            "thread_id": conference.thread_id,
            "project_id": conference.project_id,
            "title": conference.title,
            "description": conference.description,
            "conference_type": conference.conference_type,
            "provider": eff_provider,
            "status": conference.status,
            "starts_at": isoformat_stored_instant(conference.starts_at)
            if conference.starts_at
            else None,
            "ended_at": isoformat_stored_instant(conference.ended_at)
            if conference.ended_at
            else None,
            "created_by_account_id": conference.created_by_account_id,
            "join_url": url_for("chat_conference_join", conference_id=conference.id),
            "room_url": url_for("chat_conference_room", conference_id=conference.id),
            "can_join": conference_can_join(acc, conference) if acc else False,
            "can_end": conference_can_manage(acc, conference) if acc else False,
            "can_cancel": conference_can_manage(acc, conference)
            if acc and conference.status == chat_conf.STATUS_SCHEDULED
            else False,
            "invite_status": part.invite_status if part else None,
        }
        if include_meeting_url and acc and conference_can_join(acc, conference):
            if eff_provider == chat_conf.PROVIDER_EXTERNAL_LINK:
                row["meeting_url"] = conference.meeting_url
            elif eff_provider == chat_conf.PROVIDER_EMBEDDED_JITSI and conference.meeting_url:
                row["open_external_url"] = conference.meeting_url
        return row

    def ensure_conference_participant(
        conference: ChatConference,
        account_id: int,
        *,
        role: str = chat_conf.ROLE_PARTICIPANT,
        invite_status: str = chat_conf.INVITE_INVITED,
    ) -> ChatConferenceParticipant:
        part = ChatConferenceParticipant.query.filter_by(
            conference_id=conference.id, account_id=account_id
        ).first()
        u = User.query.filter_by(account_id=account_id).first()
        if part is None:
            part = ChatConferenceParticipant(
                conference_id=conference.id,
                account_id=account_id,
                user_id=u.id if u else None,
                role=role,
                invite_status=invite_status,
            )
            db.session.add(part)
            return part
        part.user_id = u.id if u else part.user_id
        if role == chat_conf.ROLE_HOST:
            part.role = role
        if part.invite_status == chat_conf.INVITE_DECLINED and invite_status != chat_conf.INVITE_DECLINED:
            part.invite_status = invite_status
            part.responded_at = None
        return part

    def apply_conference_meeting_url(conference: ChatConference, provider: str, meeting_url: str | None) -> None:
        provider = chat_conf.normalize_provider(provider, meeting_url)
        conference.provider = provider
        eff = chat_conf.effective_provider(provider)
        if eff == chat_conf.PROVIDER_EMBEDDED_JITSI:
            conference.room_name = chat_conf.build_secure_room_name(
                conference_id=conference.id,
            )
            conference.meeting_url = chat_conf.build_jitsi_meeting_url(
                conference.room_name,
                app.config.get("CHAT_CONFERENCE_JITSI_BASE_URL", "https://meet.jit.si"),
            )
        elif eff == chat_conf.PROVIDER_INTERNAL_WEBRTC_FUTURE:
            # TODO: WebRTC signaling, ICE candidates, SDP offer/answer, TURN server, screen sharing
            conference.room_name = chat_conf.build_secure_room_name(
                conference_id=conference.id,
            )
            conference.meeting_url = None
        else:
            conference.meeting_url = (meeting_url or "").strip() or None
            conference.room_name = None

    def end_live_conferences_on_thread(thread_id: int, *, except_id: int | None = None) -> None:
        now = now_local()
        for conf in ChatConference.query.filter_by(
            thread_id=thread_id, status=chat_conf.STATUS_LIVE
        ).all():
            if except_id is not None and conf.id == except_id:
                continue
            conf.status = chat_conf.STATUS_ENDED
            conf.ended_at = now

    def create_conference_system_message(
        conference: ChatConference,
        acc: Account,
        *,
        viewer_uid: int | None,
    ) -> ChatMessage:
        uid = viewer_uid or directory_user_id_for_account(acc)
        if uid is None:
            raise ValueError("no_profile")
        summary = chat_conf.conference_summary_message(
            title=conference.title,
            status=conference.status,
            conference_type=conference.conference_type,
            starts_at_iso=isoformat_stored_instant(conference.starts_at)
            if conference.starts_at
            else None,
        )
        cm = ChatMessage(
            thread_id=conference.thread_id,
            project_id=conference.project_id,
            user_id=uid,
            account_id=acc.id,
            message=summary,
            message_type=chat_conf.MESSAGE_TYPE_CONFERENCE,
            conference_id=conference.id,
        )
        db.session.add(cm)
        if conference.thread_id:
            thread = ChatThread.query.get(conference.thread_id)
            if thread:
                thread.updated_at = now_local()
        return cm

    def serialize_conference_participant_json(part: ChatConferenceParticipant) -> dict:
        u = User.query.filter_by(account_id=part.account_id).first()
        name = (u.name if u else None) or "User"
        return {
            "account_id": part.account_id,
            "name": name.strip(),
            "role": part.role,
            "invite_status": part.invite_status,
            "joined_at": isoformat_stored_instant(part.joined_at) if part.joined_at else None,
            "left_at": isoformat_stored_instant(part.left_at) if part.left_at else None,
        }

    def conference_back_to_chat_url(conf: ChatConference) -> str:
        if conf.thread_id:
            return url_for(
                "chat_page",
                thread_id=conf.thread_id,
                conference_id=conf.id,
            )
        if conf.project_id:
            return url_for(
                "chat_page",
                project_id=conf.project_id,
                conference_id=conf.id,
            )
        return url_for("chat_page")

    def notify_conference_invite(
        conference: ChatConference,
        inviter: Account,
        invitee_account_id: int,
    ) -> None:
        host_u = User.query.filter_by(account_id=inviter.id).first()
        host_name = (host_u.name if host_u else None) or inviter.email or "Someone"
        href = url_for(
            "chat_page",
            thread_id=conference.thread_id,
            conference_id=conference.id,
        )
        invitee_user = User.query.filter_by(account_id=int(invitee_account_id)).first()
        sent = []
        if invitee_user is not None:
            sent = send_managed_notification(
                "conference_invite",
                project=db.session.get(Project, int(conference.project_id)) if conference.project_id else None,
                actor=inviter,
                context={
                    "project_id": int(conference.project_id) if conference.project_id else "",
                    "project_name": (db.session.get(Project, int(conference.project_id)).name if conference.project_id and db.session.get(Project, int(conference.project_id)) else ""),
                    "entity_type": "chat_conference",
                    "entity_id": int(conference.id),
                    "assigned_user_id": int(invitee_user.id),
                    "user_name": invitee_user.name or "",
                    "notification_title": "Conference invite",
                    "notification_body": f"{host_name} invited you to {conference.title}",
                },
                fallback_title="Conference invite",
                fallback_body=f"{host_name} invited you to {conference.title}",
                fallback_url=href,
                fallback_recipient_user_ids=[int(invitee_user.id)],
            )
        if sent or NotificationRule.query.filter_by(event_key="conference_invite").first() is not None:
            return
        emit_notification_to_account(
            invitee_account_id,
            {
                "type": "conference_invite",
                "message": f"{host_name} invited you to {conference.title}",
                "href": href,
                "thread_id": conference.thread_id,
                "conference_id": conference.id,
            },
        )

    def live_conference_for_thread(thread_id: int) -> ChatConference | None:
        return (
            ChatConference.query.filter_by(thread_id=thread_id, status=chat_conf.STATUS_LIVE)
            .order_by(ChatConference.id.desc())
            .first()
        )

    def get_or_create_direct_thread(account_a_id: int, account_b_id: int) -> ChatThread | None:
        if account_a_id == account_b_id:
            return None
        a_acc = db.session.get(Account, account_a_id)
        b_acc = db.session.get(Account, account_b_id)
        if a_acc is None or b_acc is None:
            return None
        pair = chat_thr.direct_pair_key(account_a_id, account_b_id)
        existing = ChatThread.query.filter_by(
            thread_type=chat_thr.THREAD_TYPE_DIRECT, direct_pair_key=pair
        ).first()
        if existing is not None:
            return existing
        ua = User.query.filter_by(account_id=account_a_id).first()
        ub = User.query.filter_by(account_id=account_b_id).first()
        if ua is None or ub is None:
            return None
        title = (ub.name or b_acc.email or "User").strip()
        thread = ChatThread(
            thread_type=chat_thr.THREAD_TYPE_DIRECT,
            project_id=None,
            title=title,
            direct_pair_key=pair,
        )
        db.session.add(thread)
        db.session.flush()
        db.session.add(
            ChatThreadParticipant(
                thread_id=thread.id,
                account_id=account_a_id,
                directory_user_id=ua.id,
            )
        )
        db.session.add(
            ChatThreadParticipant(
                thread_id=thread.id,
                account_id=account_b_id,
                directory_user_id=ub.id,
            )
        )
        db.session.commit()
        return thread

    def ensure_thread_participant_initialized(acc: Account | None, thread: ChatThread) -> ChatThreadParticipant | None:
        if acc is None:
            return None
        part = thread_participant_row(acc, thread.id)
        if part is not None:
            return part
        if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT:
            if not account_may_use_project_chat(acc, int(thread.project_id or 0)):
                return None
            uid = directory_user_id_for_account(acc)
            part = ChatThreadParticipant(
                thread_id=thread.id,
                account_id=acc.id,
                directory_user_id=uid,
            )
            db.session.add(part)
            db.session.commit()
            return part
        return None

    def chat_unread_count_for_thread(acc: Account | None, thread: ChatThread) -> int:
        if acc is None or not account_may_use_thread(acc, thread):
            return 0
        part = ensure_thread_participant_initialized(acc, thread) or thread_participant_row(acc, thread.id)
        last_id = part.last_read_message_id if part else 0
        uid = directory_user_id_for_account(acc)
        q = ChatMessage.query.filter(ChatMessage.thread_id == thread.id, ChatMessage.id > last_id)
        if uid is not None:
            q = q.filter(ChatMessage.user_id != uid)
        return q.count()

    def chat_mark_thread_read(acc: Account | None, thread: ChatThread) -> None:
        if acc is None or not account_may_use_thread(acc, thread):
            return
        part = ensure_thread_participant_initialized(acc, thread) or thread_participant_row(acc, thread.id)
        if part is None:
            return
        mx = (
            db.session.query(db.func.max(ChatMessage.id))
            .filter(ChatMessage.thread_id == thread.id)
            .scalar()
        )
        mid = int(mx) if mx is not None else 0
        if mid > part.last_read_message_id:
            part.last_read_message_id = mid
            db.session.commit()

    def fetch_paginated_thread_messages(
        thread_id: int,
        *,
        limit: int = chat_sup.DEFAULT_CHAT_MSG_LIMIT,
        before_id: int | None = None,
        after_id: int | None = None,
        direction: str = "latest",
    ) -> tuple[list[ChatMessage], bool, bool]:
        limit = chat_sup.clamp_chat_limit(limit)
        base = ChatMessage.query.filter(ChatMessage.thread_id == thread_id)
        if direction == "newer" or after_id is not None:
            anchor = after_id if after_id is not None else 0
            rows = (
                base.filter(ChatMessage.id > anchor)
                .order_by(ChatMessage.id.asc())
                .limit(limit + 1)
                .all()
            )
            has_newer = len(rows) > limit
            if has_newer:
                rows = rows[:limit]
            oldest_id = rows[0].id if rows else None
            has_older = False
            if oldest_id is not None:
                has_older = base.filter(ChatMessage.id < oldest_id).limit(1).first() is not None
            return rows, has_older, has_newer
        if before_id is not None or direction == "older":
            anchor = before_id
            q = base
            if anchor is not None:
                q = q.filter(ChatMessage.id < anchor)
            rows = q.order_by(ChatMessage.id.desc()).limit(limit + 1).all()
            has_older = len(rows) > limit
            if has_older:
                rows = rows[:limit]
            rows.reverse()
            newest_id = rows[-1].id if rows else None
            has_newer = False
            if newest_id is not None:
                has_newer = base.filter(ChatMessage.id > newest_id).limit(1).first() is not None
            return rows, has_older, has_newer
        rows = base.order_by(ChatMessage.id.desc()).limit(limit + 1).all()
        has_older = len(rows) > limit
        if has_older:
            rows = rows[:limit]
        rows.reverse()
        newest_id = rows[-1].id if rows else None
        has_newer = False
        if newest_id is not None:
            has_newer = base.filter(ChatMessage.id > newest_id).limit(1).first() is not None
        return rows, has_older, has_newer

    def _thread_last_message(thread_id: int) -> ChatMessage | None:
        mid = (
            db.session.query(db.func.max(ChatMessage.id))
            .filter(ChatMessage.thread_id == thread_id)
            .scalar()
        )
        if mid is None:
            return None
        return ChatMessage.query.get(int(mid))

    def build_chat_threads_for_dashboard(acc: Account | None) -> list[dict]:
        """Project + direct chat threads for sidebar and floating launcher."""
        from project_settings import project_type_display_label

        if acc is None:
            return []
        enriched: list[tuple[float, dict]] = []

        pids = eligible_chat_project_ids(acc)
        if pids:
            projects = Project.query.filter(Project.id.in_(pids)).all()
            pmap = {p.id: p for p in projects}
            member_count_rows = (
                db.session.query(
                    ProjectMember.project_id,
                    db.func.count(ProjectMember.id),
                )
                .filter(ProjectMember.project_id.in_(pids))
                .group_by(ProjectMember.project_id)
                .all()
            )
            member_count_by_pid = {int(r[0]): int(r[1]) for r in member_count_rows}
            for pid in pids:
                p = pmap.get(pid)
                if p is None:
                    continue
                thread = get_or_create_project_thread(pid)
                if thread is None:
                    continue
                m = _thread_last_message(thread.id)
                preview = chat_thr.message_preview_text(
                    m.message if m else None,
                    has_image=bool(m and m.image_path),
                    has_audio=bool(m and m.audio_path),
                )
                last_at_iso: str | None = None
                last_sort = 0.0
                if m is not None and m.created_at:
                    last_at_iso = isoformat_stored_instant(m.created_at)
                    last_sort = _epoch_ms_from_stored_naive(m.created_at)
                unread = chat_unread_count_for_thread(acc, thread)
                pname = (p.name or "").strip() or "Project"
                last_author_avatar = None
                if m is not None and getattr(m, "account_id", None):
                    last_author = User.query.filter_by(account_id=m.account_id).first()
                    last_author_avatar = chat_avatar_url_for_user(last_author)
                row = chat_thr.serialize_thread_list_item(
                    thread_id=thread.id,
                    thread_type=chat_thr.THREAD_TYPE_PROJECT,
                    project_id=pid,
                    title=pname,
                    subtitle="Project chat",
                    avatar_initial=chat_thr.avatar_initial_from_name(pname),
                    avatar_url=last_author_avatar,
                    unread_count=unread,
                    last_preview=preview,
                    last_at=last_at_iso,
                    messages_url=url_for("chat_thread_messages", thread_id=thread.id),
                    mark_read_url=url_for("chat_thread_mark_read", thread_id=thread.id),
                    unread_url=url_for("chat_thread_unread_count", thread_id=thread.id),
                    detail_url=url_for("project_detail", project_id=pid),
                    team_count=member_count_by_pid.get(pid, 0),
                    project_type=(p.project_type or "").strip(),
                    project_type_label=project_type_display_label(p.project_type),
                    director=(p.director or "").strip(),
                    production_house=(p.production_house or "").strip(),
                )
                row["name"] = pname
                live = live_conference_for_thread(thread.id)
                if live:
                    row["live_conference_id"] = live.id
                enriched.append((last_sort, row))

        direct_threads = (
            ChatThread.query.join(
                ChatThreadParticipant,
                ChatThreadParticipant.thread_id == ChatThread.id,
            )
            .filter(
                ChatThread.thread_type == chat_thr.THREAD_TYPE_DIRECT,
                ChatThreadParticipant.account_id == acc.id,
                ChatThreadParticipant.is_archived.is_(False),
            )
            .order_by(ChatThread.updated_at.desc(), ChatThread.id.desc())
            .all()
        )
        for thread in direct_threads:
            part = thread_participant_row(acc, thread.id)
            other_aid = chat_thr.other_direct_participant_account_id(thread.participants, acc.id)
            other_user = None
            other_acc = None
            if other_aid is not None:
                other_acc = db.session.get(Account, other_aid)
                other_user = User.query.filter_by(account_id=other_aid).first()
            display = (other_user.name if other_user else None) or (
                other_acc.email if other_acc else None
            ) or (thread.title or "Direct message")
            display = display.strip()
            m = _thread_last_message(thread.id)
            preview = chat_thr.message_preview_text(
                m.message if m else None,
                has_image=bool(m and m.image_path),
                has_audio=bool(m and m.audio_path),
            )
            last_at_iso: str | None = None
            last_sort = 0.0
            if m is not None and m.created_at:
                last_at_iso = isoformat_stored_instant(m.created_at)
                last_sort = _epoch_ms_from_stored_naive(m.created_at)
            elif thread.updated_at:
                last_sort = _epoch_ms_from_stored_naive(thread.updated_at)
            unread = chat_unread_count_for_thread(acc, thread)
            jt = ""
            if other_user and other_user.job_title_id:
                jt_row = JobTitle.query.get(other_user.job_title_id)
                if jt_row:
                    jt = (jt_row.name or "").strip()
            row = chat_thr.serialize_thread_list_item(
                thread_id=thread.id,
                thread_type=chat_thr.THREAD_TYPE_DIRECT,
                project_id=None,
                title=display,
                subtitle=jt or (other_acc.email if other_acc else "Direct message"),
                avatar_initial=chat_thr.avatar_initial_from_name(display),
                avatar_url=chat_avatar_url_for_user(other_user),
                unread_count=unread,
                last_preview=preview,
                last_at=last_at_iso,
                is_muted=bool(part and part.muted_forever),
                is_archived=bool(part and part.is_archived),
                messages_url=url_for("chat_thread_messages", thread_id=thread.id),
                mark_read_url=url_for("chat_thread_mark_read", thread_id=thread.id),
                unread_url=url_for("chat_thread_unread_count", thread_id=thread.id),
                other_account_id=other_aid,
                other_user_id=other_user.id if other_user else None,
                job_title=jt or None,
                email=other_acc.email if other_acc else None,
            )
            row["name"] = display
            live = live_conference_for_thread(thread.id)
            if live:
                row["live_conference_id"] = live.id
            enriched.append((last_sort, row))

        participant_threads = (
            ChatThread.query.join(
                ChatThreadParticipant,
                ChatThreadParticipant.thread_id == ChatThread.id,
            )
            .filter(
                ChatThread.thread_type.in_(
                    (chat_thr.THREAD_TYPE_GROUP, chat_thr.THREAD_TYPE_DEPARTMENT)
                ),
                ChatThread.is_active.is_(True),
                ChatThreadParticipant.account_id == acc.id,
                ChatThreadParticipant.is_active.is_(True),
            )
            .order_by(ChatThread.updated_at.desc(), ChatThread.id.desc())
            .all()
        )
        for thread in participant_threads:
            part = thread_participant_row(acc, thread.id, active_only=True)
            mcount = active_participant_count(thread.id)
            m = _thread_last_message(thread.id)
            preview = chat_thr.message_preview_text(
                m.message if m else None,
                has_image=bool(m and m.image_path),
                has_audio=bool(m and m.audio_path),
            )
            last_at_iso: str | None = None
            last_sort = 0.0
            if m is not None and m.created_at:
                last_at_iso = isoformat_stored_instant(m.created_at)
                last_sort = _epoch_ms_from_stored_naive(m.created_at)
            elif thread.updated_at:
                last_sort = _epoch_ms_from_stored_naive(thread.updated_at)
            unread = chat_unread_count_for_thread(acc, thread)
            title = (thread.title or "Chat").strip()
            if thread.thread_type == chat_thr.THREAD_TYPE_GROUP:
                subtitle = f"Group · {mcount} member" + ("s" if mcount != 1 else "")
            else:
                subtitle = f"Department · {mcount} member" + ("s" if mcount != 1 else "")
            last_author_avatar = None
            if m is not None and getattr(m, "account_id", None):
                last_author = User.query.filter_by(account_id=m.account_id).first()
                last_author_avatar = chat_avatar_url_for_user(last_author)
            row = chat_thr.serialize_thread_list_item(
                thread_id=thread.id,
                thread_type=thread.thread_type,
                project_id=None,
                department_id=thread.department_id,
                title=title,
                subtitle=subtitle,
                avatar_initial=thread.avatar_label or chat_thr.avatar_initial_from_name(title),
                avatar_url=last_author_avatar,
                unread_count=unread,
                last_preview=preview,
                last_at=last_at_iso,
                is_muted=bool(part and part.muted_forever),
                is_archived=bool(part and part.is_archived),
                messages_url=url_for("chat_thread_messages", thread_id=thread.id),
                mark_read_url=url_for("chat_thread_mark_read", thread_id=thread.id),
                unread_url=url_for("chat_thread_unread_count", thread_id=thread.id),
                member_count=mcount,
            )
            row["name"] = title
            live = live_conference_for_thread(thread.id)
            if live:
                row["live_conference_id"] = live.id
            enriched.append((last_sort, row))

        enriched.sort(key=lambda t: (-t[0], t[1].get("title", "").lower()))
        return [t[1] for t in enriched]

    def find_project_mentions_for_text(project_id: int, text: str | None) -> list[User]:
        """Resolve @DisplayName tokens against project members (longest name first)."""
        if not text:
            return []
        members = (
            User.query.join(ProjectMember, ProjectMember.user_id == User.id)
            .filter(ProjectMember.project_id == project_id)
            .all()
        )
        named: list[tuple[User, str]] = []
        for u in members:
            name = (u.name or "").strip()
            if name:
                named.append((u, name))
        named.sort(key=lambda t: len(t[1]), reverse=True)
        found: dict[int, User] = {}
        pos = 0
        n = len(text)
        while pos < n:
            at = text.find("@", pos)
            if at < 0:
                break
            rest = text[at + 1 :]
            hit: User | None = None
            hit_len = 0
            for u, name in named:
                if rest.startswith(name):
                    boundary = rest[len(name) : len(name) + 1]
                    if boundary and boundary[0].isalnum():
                        continue
                    hit = u
                    hit_len = len(name)
                    break
            if hit is not None:
                found[hit.id] = hit
                pos = at + 1 + hit_len
            else:
                pos = at + 1
        return list(found.values())

    def summarize_chat_reactions(
        reaction_rows: Sequence[ChatMessageReaction],
        viewer_dir_user_id: int | None,
    ) -> list[dict]:
        counts: dict[str, int] = defaultdict(int)
        viewer_emoji: str | None = None
        for r in reaction_rows:
            counts[r.emoji] += 1
            if viewer_dir_user_id is not None and r.user_id == viewer_dir_user_id:
                viewer_emoji = r.emoji
        out: list[dict] = []
        seen: set[str] = set()
        for em in CHAT_REACTION_EMOJIS:
            if em in counts:
                out.append(
                    {
                        "emoji": em,
                        "count": counts[em],
                        "me": viewer_emoji == em,
                    }
                )
                seen.add(em)
        for em in sorted(counts.keys()):
            if em not in seen:
                out.append(
                    {
                        "emoji": em,
                        "count": counts[em],
                        "me": viewer_emoji == em,
                    }
                )
        return out

    def emit_chat_updated(
        project_id: int | None,
        message_id: int,
        user_id: int | None = None,
        *,
        kind: str = "message",
        thread_id: int | None = None,
        thread_type: str | None = None,
    ) -> None:
        payload: dict = {
            "message_id": message_id,
            "kind": kind,
        }
        if project_id is not None:
            payload["project_id"] = project_id
        if thread_id is not None:
            payload["thread_id"] = thread_id
        if thread_type:
            payload["thread_type"] = thread_type
        if user_id is not None:
            payload["user_id"] = user_id
        if thread_id is not None:
            socketio.emit("chat_updated", payload, room=f"chat_thread_{thread_id}")
        if project_id is not None:
            socketio.emit("chat_updated", payload, room=f"project_{project_id}")

    def batch_load_chat_reactions(
        message_ids: Sequence[int],
    ) -> dict[int, list[ChatMessageReaction]]:
        react_by_mid: dict[int, list[ChatMessageReaction]] = defaultdict(list)
        if not message_ids:
            return react_by_mid
        for r in ChatMessageReaction.query.filter(
            ChatMessageReaction.message_id.in_(list(message_ids))
        ).all():
            react_by_mid[r.message_id].append(r)
        return react_by_mid

    def batch_load_pinned_message_ids(project_id: int, message_ids: Sequence[int]) -> set[int]:
        if not message_ids:
            return set()
        rows = ChatPinnedMessage.query.filter(
            ChatPinnedMessage.project_id == project_id,
            ChatPinnedMessage.message_id.in_(list(message_ids)),
            ChatPinnedMessage.is_active.is_(True),
        ).all()
        return {r.message_id for r in rows}

    def batch_load_message_links(message_ids: Sequence[int]) -> dict[int, list[dict]]:
        out: dict[int, list[dict]] = defaultdict(list)
        if not message_ids:
            return out
        for link in ChatMessageLink.query.filter(
            ChatMessageLink.message_id.in_(list(message_ids))
        ).order_by(ChatMessageLink.id.asc()).all():
            out[link.message_id].append(
                {
                    "id": link.id,
                    "entity_type": link.entity_type,
                    "entity_id": link.entity_id,
                    "label": chat_entity_link_label(link.entity_type, link.entity_id, link.project_id),
                }
            )
        return out

    def chat_entity_link_label(entity_type: str, entity_id: int, project_id: int) -> str:
        et = (entity_type or "").strip().lower()
        if et == "scene":
            sc = ProductionScene.query.get(entity_id)
            if sc is not None:
                num = sc.scene_number if sc.scene_number is not None else entity_id
                return f"Scene {num}"
        elif et == "vfx_shot":
            shot = VfxShot.query.get(entity_id)
            if shot is not None:
                return (shot.shot_code or f"VFX Shot {entity_id}").strip()
        elif et == "episode":
            ep = ProductionEpisode.query.get(entity_id)
            if ep is not None:
                return f"Episode {ep.episode_number or entity_id}"
        elif et == "shooting_day":
            day = ShootingDay.query.get(entity_id)
            if day is not None:
                return (day.day_name or f"Shooting day {entity_id}").strip()
        elif et == "action_item":
            return f"Action item #{entity_id}"
        elif et == "task":
            return f"Task #{entity_id}"
        return f"{et.replace('_', ' ').title()} #{entity_id}"

    def chat_read_metadata_for_account(
        acc: Account | None,
        project_id: int,
        viewer_uid: int | None,
    ) -> tuple[int, int | None]:
        if acc is None:
            return 0, None
        ensure_project_chat_read_initialized(acc, project_id)
        state = ProjectChatReadState.query.filter_by(
            account_id=acc.id, project_id=project_id
        ).first()
        last_read = int(state.last_read_message_id) if state else 0
        q = ChatMessage.query.filter(
            ChatMessage.project_id == project_id,
            ChatMessage.id > last_read,
        )
        if viewer_uid is not None:
            q = q.filter(ChatMessage.user_id != viewer_uid)
        first_unread = q.order_by(ChatMessage.id.asc()).first()
        return last_read, (first_unread.id if first_unread else None)

    def fetch_paginated_chat_messages(
        project_id: int,
        *,
        limit: int = chat_sup.DEFAULT_CHAT_MSG_LIMIT,
        before_id: int | None = None,
        after_id: int | None = None,
        direction: str = "latest",
    ) -> tuple[list[ChatMessage], bool, bool]:
        limit = chat_sup.clamp_chat_limit(limit)
        base = ChatMessage.query.filter_by(project_id=project_id)
        if direction == "newer" or after_id is not None:
            anchor = after_id if after_id is not None else 0
            rows = (
                base.filter(ChatMessage.id > anchor)
                .order_by(ChatMessage.id.asc())
                .limit(limit + 1)
                .all()
            )
            has_newer = len(rows) > limit
            if has_newer:
                rows = rows[:limit]
            oldest_id = rows[0].id if rows else None
            has_older = False
            if oldest_id is not None:
                has_older = (
                    base.filter(ChatMessage.id < oldest_id).limit(1).first() is not None
                )
            return rows, has_older, has_newer
        if before_id is not None or direction == "older":
            anchor = before_id
            q = base
            if anchor is not None:
                q = q.filter(ChatMessage.id < anchor)
            rows = q.order_by(ChatMessage.id.desc()).limit(limit + 1).all()
            has_older = len(rows) > limit
            if has_older:
                rows = rows[:limit]
            rows.reverse()
            newest_id = rows[-1].id if rows else None
            has_newer = False
            if newest_id is not None:
                has_newer = (
                    base.filter(ChatMessage.id > newest_id).limit(1).first() is not None
                )
            return rows, has_older, has_newer
        rows = base.order_by(ChatMessage.id.desc()).limit(limit + 1).all()
        has_older = len(rows) > limit
        if has_older:
            rows = rows[:limit]
        rows.reverse()
        newest_id = rows[-1].id if rows else None
        has_newer = False
        if newest_id is not None:
            has_newer = (
                base.filter(ChatMessage.id > newest_id).limit(1).first() is not None
            )
        return rows, has_older, has_newer

    def fetch_chat_messages_around(
        project_id: int,
        message_id: int,
        *,
        limit: int = chat_sup.DEFAULT_CHAT_MSG_LIMIT,
    ) -> tuple[list[ChatMessage], bool, bool]:
        limit = chat_sup.clamp_chat_limit(limit)
        anchor = ChatMessage.query.filter_by(id=message_id, project_id=project_id).first()
        if anchor is None:
            return [], False, False
        half = max(1, limit // 2)
        older = (
            ChatMessage.query.filter(
                ChatMessage.project_id == project_id,
                ChatMessage.id < message_id,
            )
            .order_by(ChatMessage.id.desc())
            .limit(half)
            .all()
        )
        older.reverse()
        newer = (
            ChatMessage.query.filter(
                ChatMessage.project_id == project_id,
                ChatMessage.id >= message_id,
            )
            .order_by(ChatMessage.id.asc())
            .limit(half + 1)
            .all()
        )
        rows = older + newer
        if not rows:
            return [], False, False
        oldest_id = rows[0].id
        newest_id = rows[-1].id
        base = ChatMessage.query.filter_by(project_id=project_id)
        has_older = base.filter(ChatMessage.id < oldest_id).limit(1).first() is not None
        has_newer = base.filter(ChatMessage.id > newest_id).limit(1).first() is not None
        return rows, has_older, has_newer

    def build_chat_messages_response(
        project_id: int,
        rows: Sequence[ChatMessage],
        viewer_uid: int | None,
        acc: Account | None,
        *,
        has_older: bool,
        has_newer: bool,
    ) -> dict:
        ids = [m.id for m in rows]
        react_by_mid = batch_load_chat_reactions(ids)
        pinned_ids = batch_load_pinned_message_ids(project_id, ids)
        links_by_mid = batch_load_message_links(ids)
        reply_ids = [m.reply_to_message_id for m in rows if m.reply_to_message_id]
        reply_by_id = batch_load_reply_messages(reply_ids)
        last_read, first_unread = chat_read_metadata_for_account(acc, project_id, viewer_uid)
        messages = []
        for m in rows:
            reply_preview = None
            if m.reply_to_message_id:
                reply_preview = chat_reply_preview_dict(
                    reply_by_id.get(m.reply_to_message_id)
                )
            delivery = None
            if viewer_uid is not None and m.user_id == viewer_uid and not m.is_deleted:
                delivery = chat_message_delivery_state(project_id, m.id, viewer_uid)
            messages.append(
                chat_message_json(
                    m,
                    viewer_uid,
                    reactions=react_by_mid.get(m.id, []),
                    is_pinned=m.id in pinned_ids,
                    entity_links=links_by_mid.get(m.id, []),
                    reply_preview=reply_preview,
                    delivery_state=delivery,
                    acc=acc,
                )
            )
        return {
            "ok": True,
            "messages": messages,
            "has_older": has_older,
            "has_newer": has_newer,
            "oldest_id": rows[0].id if rows else None,
            "newest_id": rows[-1].id if rows else None,
            "project_id": project_id,
            "last_read_message_id": last_read,
            "first_unread_message_id": first_unread,
        }

    def chat_read_metadata_for_thread(
        acc: Account | None,
        thread: ChatThread,
        viewer_uid: int | None,
    ) -> tuple[int, int | None]:
        if acc is None:
            return 0, None
        part = ensure_thread_participant_initialized(acc, thread) or thread_participant_row(acc, thread.id)
        last_read = int(part.last_read_message_id) if part else 0
        q = ChatMessage.query.filter(
            ChatMessage.thread_id == thread.id,
            ChatMessage.id > last_read,
        )
        if viewer_uid is not None:
            q = q.filter(ChatMessage.user_id != viewer_uid)
        first_unread = q.order_by(ChatMessage.id.asc()).first()
        return last_read, (first_unread.id if first_unread else None)

    def build_thread_messages_response(
        thread: ChatThread,
        rows: Sequence[ChatMessage],
        viewer_uid: int | None,
        acc: Account | None,
        *,
        has_older: bool,
        has_newer: bool,
    ) -> dict:
        if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT and thread.project_id:
            body = build_chat_messages_response(
                int(thread.project_id),
                rows,
                viewer_uid,
                acc,
                has_older=has_older,
                has_newer=has_newer,
            )
            body["thread_id"] = thread.id
            body["thread_type"] = thread.thread_type
            return body
        ids = [m.id for m in rows]
        react_by_mid = batch_load_chat_reactions(ids)
        reply_ids = [m.reply_to_message_id for m in rows if m.reply_to_message_id]
        reply_by_id = batch_load_reply_messages(reply_ids)
        last_read, first_unread = chat_read_metadata_for_thread(acc, thread, viewer_uid)
        messages = []
        for m in rows:
            reply_preview = None
            if m.reply_to_message_id:
                reply_preview = chat_reply_preview_dict(reply_by_id.get(m.reply_to_message_id))
            messages.append(
                chat_message_json(
                    m,
                    viewer_uid,
                    reactions=react_by_mid.get(m.id, []),
                    is_pinned=False,
                    entity_links=[],
                    reply_preview=reply_preview,
                    delivery_state=None,
                    acc=acc,
                )
            )
        return {
            "ok": True,
            "messages": messages,
            "has_older": has_older,
            "has_newer": has_newer,
            "oldest_id": rows[0].id if rows else None,
            "newest_id": rows[-1].id if rows else None,
            "thread_id": thread.id,
            "thread_type": thread.thread_type,
            "project_id": thread.project_id,
            "last_read_message_id": last_read,
            "first_unread_message_id": first_unread,
        }

    def persist_chat_mentions_for_message(
        project_id: int,
        message_id: int,
        msg_text: str | None,
        sender_uid: int,
        sender_acc_id: int,
    ) -> None:
        if not msg_text:
            return
        for mentioned in find_project_mentions_for_text(project_id, msg_text):
            if mentioned.id == sender_uid:
                continue
            if mentioned.account_id is None:
                continue
            exists = ChatMention.query.filter_by(
                message_id=message_id,
                mentioned_account_id=mentioned.account_id,
            ).first()
            if exists is not None:
                continue
            db.session.add(
                ChatMention(
                    project_id=project_id,
                    message_id=message_id,
                    mentioned_account_id=mentioned.account_id,
                    mentioned_user_id=mentioned.id,
                    created_by_account_id=sender_acc_id,
                )
            )
        db.session.commit()

    def chat_reply_preview_dict(m: ChatMessage | None) -> dict | None:
        if m is None:
            return None
        u = m.user
        username = (u.name or "Unknown").strip() if u else "Unknown"
        if m.is_deleted:
            return {
                "id": m.id,
                "username": username,
                "message": "Original message was deleted.",
                "has_image": False,
                "has_audio": False,
                "is_deleted": True,
            }
        preview = (m.message or "").strip()
        if not preview:
            if (m.image_path or "").strip():
                preview = "Photo"
            elif (m.audio_path or "").strip():
                preview = "Voice message"
        if len(preview) > 120:
            preview = preview[:120] + "…"
        return {
            "id": m.id,
            "username": username,
            "message": preview,
            "has_image": bool((m.image_path or "").strip()),
            "has_audio": bool((m.audio_path or "").strip()),
            "is_deleted": False,
        }

    def batch_load_reply_messages(
        reply_ids: Sequence[int],
    ) -> dict[int, ChatMessage]:
        if not reply_ids:
            return {}
        rows = ChatMessage.query.filter(ChatMessage.id.in_(list(reply_ids))).all()
        return {m.id: m for m in rows}

    def chat_message_delivery_state(
        project_id: int, message_id: int, sender_uid: int
    ) -> str:
        """sent or read — read if any other team member account has caught up."""
        member_uids = [
            pm.user_id
            for pm in ProjectMember.query.filter_by(project_id=project_id).all()
            if pm.user_id != sender_uid
        ]
        if not member_uids:
            return "sent"
        users = User.query.filter(User.id.in_(member_uids)).all()
        account_ids = [u.account_id for u in users if u.account_id is not None]
        if not account_ids:
            return "sent"
        for aid in account_ids:
            state = ProjectChatReadState.query.filter_by(
                account_id=aid, project_id=project_id
            ).first()
            if state is not None and int(state.last_read_message_id) >= int(message_id):
                return "read"
        return "sent"

    def chat_read_receipts_for_message(
        project_id: int, message_id: int, sender_uid: int
    ) -> list[dict]:
        out: list[dict] = []
        member_uids = [
            pm.user_id
            for pm in ProjectMember.query.filter_by(project_id=project_id).all()
            if pm.user_id != sender_uid
        ]
        if not member_uids:
            return out
        users = User.query.filter(User.id.in_(member_uids)).all()
        for u in users:
            if u.account_id is None:
                continue
            state = ProjectChatReadState.query.filter_by(
                account_id=u.account_id, project_id=project_id
            ).first()
            if state is None or int(state.last_read_message_id) < int(message_id):
                continue
            out.append(
                {
                    "account_id": u.account_id,
                    "name": (u.name or "").strip() or "Team member",
                    "read_at": None,
                }
            )
        return out

    def chat_message_json(
        m: ChatMessage,
        viewer_dir_user_id: int | None,
        *,
        reactions: Sequence[ChatMessageReaction] | None = None,
        is_pinned: bool = False,
        entity_links: Sequence[dict] | None = None,
        reply_preview: dict | None = None,
        delivery_state: str | None = None,
        acc: Account | None = None,
    ) -> dict:
        u = m.user
        username = u.name if u is not None else "Unknown"
        avatar_initial = "?"
        for ch in username.strip():
            if ch.isalnum():
                avatar_initial = ch.upper()
                break
        base_me = viewer_dir_user_id is not None and m.user_id == viewer_dir_user_id
        created_iso = isoformat_stored_instant(m.created_at)
        if m.is_deleted:
            return {
                "id": m.id,
                "username": username,
                "message": "",
                "image_url": None,
                "audio_url": None,
                "avatar_initial": avatar_initial,
                "avatar_url": chat_avatar_url_for_user(u),
                "created_at": created_iso,
                "is_me": base_me,
                "is_deleted": True,
                "reactions": [],
                "is_pinned": is_pinned,
                "entity_links": list(entity_links or []),
                "reply_to": reply_preview,
            }
        image_url = None
        if (m.image_path or "").strip():
            if m.thread_id is not None:
                image_url = url_for(
                    "chat_thread_attachment",
                    thread_id=m.thread_id,
                    filename=m.image_path.strip(),
                )
            elif m.project_id is not None:
                image_url = url_for(
                    "project_chat_attachment",
                    project_id=m.project_id,
                    filename=m.image_path.strip(),
                )
        audio_url = None
        if (m.audio_path or "").strip():
            if m.thread_id is not None:
                audio_url = url_for(
                    "chat_thread_attachment",
                    thread_id=m.thread_id,
                    filename=m.audio_path.strip(),
                )
            elif m.project_id is not None:
                audio_url = url_for(
                    "project_chat_attachment",
                    project_id=m.project_id,
                    filename=m.audio_path.strip(),
                )
        react_seq = reactions if reactions is not None else []
        payload: dict = {
            "id": m.id,
            "username": username,
            "message": (m.message or "").strip(),
            "image_url": image_url,
            "audio_url": audio_url,
            "avatar_initial": avatar_initial,
            "avatar_url": chat_avatar_url_for_user(u),
            "created_at": created_iso,
            "is_me": base_me,
            "is_deleted": False,
            "reactions": summarize_chat_reactions(react_seq, viewer_dir_user_id),
            "is_pinned": is_pinned,
            "entity_links": list(entity_links or []),
            "reply_to": reply_preview,
        }
        if base_me and delivery_state:
            payload["delivery_state"] = delivery_state
            if delivery_state == "read":
                payload["read_by_count"] = len(
                    chat_read_receipts_for_message(m.project_id, m.id, m.user_id)
                )
        msg_type = getattr(m, "message_type", None) or chat_conf.MESSAGE_TYPE_TEXT
        payload["message_type"] = msg_type
        if msg_type == chat_conf.MESSAGE_TYPE_CONFERENCE and m.conference_id:
            conf = ChatConference.query.get(m.conference_id)
            if conf is not None:
                payload["conference"] = serialize_conference_json(conf, acc)
        return payload

