    def shooting_day_location_suggestions(project_id: int) -> list[str]:
        """Distinct non-empty locations used on shooting days in this project."""
        rows = (
            db.session.query(ShootingDay.location)
            .filter(
                ShootingDay.project_id == int(project_id),
                ShootingDay.location.isnot(None),
                ShootingDay.location != "",
            )
            .distinct()
            .order_by(ShootingDay.location.asc())
            .all()
        )
        seen: set[str] = set()
        out: list[str] = []
        for row in rows:
            loc = (row[0] or "").strip()
            if not loc:
                continue
            key = loc.casefold()
            if key in seen:
                continue
            seen.add(key)
            out.append(loc)
        return out

