    def _assign_scene_wants_json() -> bool:
        if (request.form.get("_ajax") or "").strip() == "1":
            return True
        if (request.headers.get("X-Requested-With") or "").strip().lower() == "xmlhttprequest":
            return True
        accept = (request.headers.get("Accept") or "").lower()
        return "application/json" in accept

    def shooting_day_scene_runtime_siblings(
        project_id: int,
        row: ShootingDayScene,
        *,
        exclude_link_id: int | None = None,
    ) -> list[ShootingDayScene]:
        identity = shooting_items_mod.scene_runtime_identity_key(row)
        if identity is None:
            return []
        bucket, label = identity
        q = (
            ShootingDayScene.query.join(ShootingDay)
            .filter(ShootingDay.project_id == int(project_id))
            .order_by(ShootingDayScene.id.asc())
        )
        if bucket == "x":
            q = q.filter(ShootingDayScene.is_episode_unassigned.is_(True))
        elif bucket == "establishing":
            q = q.filter(ShootingDayScene.is_establishing_shots_pool.is_(True))
        else:
            ep = int(bucket.split(":", 1)[1])
            q = q.filter(
                ShootingDayScene.is_episode_unassigned.is_(False),
                ShootingDayScene.is_establishing_shots_pool.is_(False),
                ShootingDayScene.episode_number == ep,
            )
        out: list[ShootingDayScene] = []
        for candidate in q.all():
            if exclude_link_id is not None and int(candidate.id) == int(exclude_link_id):
                continue
            if shooting_items_mod.scene_runtime_identity_key(candidate) == identity:
                out.append(candidate)
        return out

    def find_episode_scene_label_duplicate(
        project_id: int,
        episode_number: int,
        scene_label: str,
        *,
        is_episode_unassigned: bool = False,
        is_establishing_shots_pool: bool = False,
        exclude_link_id: int | None = None,
    ) -> ShootingDayScene | None:
        key = shooting_items_mod.normalize_scene_label_key(scene_label)
        if not key:
            return None
        q = (
            ShootingDayScene.query.join(ShootingDay)
            .options(joinedload(ShootingDayScene.shooting_day))
            .filter(ShootingDay.project_id == int(project_id))
        )
        if is_episode_unassigned:
            q = q.filter(ShootingDayScene.is_episode_unassigned.is_(True))
        elif is_establishing_shots_pool:
            q = q.filter(ShootingDayScene.is_establishing_shots_pool.is_(True))
        else:
            q = q.filter(
                ShootingDayScene.is_episode_unassigned.is_(False),
                ShootingDayScene.is_establishing_shots_pool.is_(False),
                ShootingDayScene.episode_number == int(episode_number),
            )
        rows = q.all()
        for row in rows:
            if exclude_link_id is not None and int(row.id) == int(exclude_link_id):
                continue
            if shooting_items_mod.normalize_scene_label_key(row.scene_label) == key:
                return row
        return None

    def _shooting_scene_conflict_payload(
        project_id: int,
        episode_number: int,
        scene_label: str,
        existing: ShootingDayScene,
        *,
        is_episode_unassigned: bool = False,
        is_establishing_shots_pool: bool = False,
    ) -> dict[str, object]:
        day = existing.shooting_day
        day_label = ""
        day_url = ""
        if day is not None:
            day_url = url_for(
                "project_production_day",
                project_id=project_id,
                day_id=day.id,
            )
            day_label = (
                f"Unit {day.unit_number} · {day.day_name or 'Day'} · "
                f"{day.shooting_date.strftime('%Y-%m-%d')}"
            )
        return {
            "ok": False,
            "conflict": True,
            "episode_number": int(episode_number),
            "is_episode_unassigned": bool(is_episode_unassigned),
            "is_establishing_shots_pool": bool(is_establishing_shots_pool),
            "scene_label": scene_label,
            "existing": {
                "id": int(existing.id),
                "day_id": int(existing.shooting_day_id),
                "item_type": shooting_items_mod.normalize_shooting_item_type(
                    existing.shooting_item_type
                ),
                "day_label": day_label,
                "day_url": day_url,
            },
        }

    def next_legacy_scene_id_for_day(day_id: int) -> int:
        """Compatibility allocator for legacy UNIQUE(shooting_day_id, scene_id)."""
        mx = (
            db.session.query(db.func.max(ShootingDayScene.scene_id))
            .filter(ShootingDayScene.shooting_day_id == day_id)
            .scalar()
        )
        try:
            return max(1, int(mx or 0) + 1)
        except (TypeError, ValueError):
            return 1

    @app.route("/projects/<int:project_id>/shooting-days", methods=["POST"])
    def shooting_day_create(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        require_production_edit(acc, project_id)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))

        raw_unit = (request.form.get("unit_number") or "").strip()
        try:
            unit_number = int(raw_unit)
        except ValueError:
            flash("Select a valid unit number.", "error")
            return _production_redirect(project_id)
        if unit_number < 1:
            flash("Unit number must be at least 1.", "error")
            return _production_redirect(project_id)

        day_name = (request.form.get("day_name") or "").strip()
        if not day_name:
            flash("Enter a day name.", "error")
            return _production_redirect(project_id)
        if len(day_name) > 50:
            flash("Day name must be 50 characters or fewer.", "error")
            return _production_redirect(project_id)

        raw_date = (request.form.get("shooting_date") or "").strip()
        try:
            sd = datetime.strptime(raw_date, "%Y-%m-%d").date()
        except ValueError:
            flash("Use a valid shooting date.", "error")
            return _production_redirect(project_id)

        day = ShootingDay(
            project_id=p.id,
            unit_number=unit_number,
            day_name=day_name,
            shooting_date=sd,
        )
        p.lifecycle_status = "post_production"
        db.session.add(day)
        db.session.flush()
        emit_shooting_day_created_activity(day, "production")
        import project_activity_hooks as pah

        pah.log_shooting_day_created(day, source="production")
        db.session.commit()
        flash("Shooting day added.", "success")
        return redirect(
            url_for("project_production_day", project_id=project_id, day_id=day.id, new=1)
        )

    @app.route("/projects/<int:project_id>/production/days/<int:day_id>/delete", methods=["POST"])
    def production_day_delete(project_id: int, day_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        require_production_edit(acc, project_id)
        d = shooting_day_in_project(day_id, project_id)
