    @app.route("/login", methods=["GET", "POST"])
    def login():
        if session.get("account_id"):
            return redirect(_safe_next_url(request.args.get("next")))

        if request.method == "POST":
            login_id = (request.form.get("login") or request.form.get("email") or "").strip()
            password = request.form.get("password") or ""
            next_url = _safe_next_url(request.form.get("next") or request.args.get("next"))

            if not login_id or not password:
                flash("Email or username and password are required.", "error")
                return render_template("login.html", next_url=next_url)

            login_lower = login_id.lower()
            if "@" in login_id:
                acc = Account.query.filter_by(email=login_lower).first()
            else:
                acc = Account.query.filter(
                    db.func.lower(Account.username) == login_lower,
                ).first()
            if acc is None or not check_password_hash(acc.password_hash, password):
                log_security_event(
                    "login_failure",
                    details={"login": login_lower[:120]},
                )
                flash("Invalid sign-in or password.", "error")
                return render_template("login.html", next_url=next_url)

            if not account_approval_support_mod.account_may_use_app(acc):
                status = account_approval_support_mod.normalized_account_status(
                    getattr(acc, "status", None)
                )
                if status == account_approval_support_mod.STATUS_PENDING_APPROVAL:
                    flash("Your account is awaiting administrator approval.", "error")
                elif status == account_approval_support_mod.STATUS_REJECTED:
                    msg = "Your registration request has not been approved."
                    if getattr(acc, "status_notes", None):
                        msg += f" {acc.status_notes}"
                    flash(msg, "error")
                elif status == account_approval_support_mod.STATUS_SUSPENDED:
                    flash("Your account has been suspended.", "error")
                else:
                    flash("Your account is not active.", "error")
                session.clear()
                session["account_id"] = acc.id
                log_security_event(
                    "login_success",
                    account_id=acc.id,
                    details={"restricted": True, "status": status},
                )
                return redirect(url_for("account_pending"))

            session.clear()
            session["account_id"] = acc.id
            log_security_event("login_success", account_id=acc.id)
            return redirect(next_url)

        return render_template("login.html", next_url=_safe_next_url(request.args.get("next")))

    PASSWORD_RESET_SALT = "password-reset"
    PASSWORD_RESET_MAX_AGE_SEC = 60 * 60

    def _account_by_login_id(login_id: str):
        ident = (login_id or "").strip()
        if not ident:
            return None
        ident_lower = ident.lower()
        if "@" in ident:
            return Account.query.filter_by(email=ident_lower).first()
        return Account.query.filter(
            db.func.lower(Account.username) == ident_lower,
        ).first()

    def _password_reset_serializer():
        return URLSafeTimedSerializer(app.config["SECRET_KEY"], salt=PASSWORD_RESET_SALT)

    def _password_reset_stamp(acc: Account) -> str:
        raw = (acc.password_hash or "").encode("utf-8")
        return hashlib.sha256(raw).hexdigest()[:24]

    def _password_reset_token(acc: Account) -> str:
        return _password_reset_serializer().dumps(
            {"id": int(acc.id), "ph": _password_reset_stamp(acc)}
        )

    def _account_from_password_reset_token(token: str):
        try:
            data = _password_reset_serializer().loads(
                token or "", max_age=PASSWORD_RESET_MAX_AGE_SEC
            )
        except (BadSignature, SignatureExpired, TypeError, ValueError):
            return None
        if not isinstance(data, dict):
            return None
        try:
            acc_id = int(data.get("id") or 0)
        except (TypeError, ValueError):
            return None
        acc = db.session.get(Account, acc_id)
        if acc is None:
            return None
        if _password_reset_stamp(acc) != str(data.get("ph") or ""):
            return None
        if not account_approval_support_mod.account_may_use_app(acc):
            return None
        return acc

    def _notify_admins_password_reset(acc: Account, reset_url: str) -> None:
        try:
            admin_ids = account_approval_support_mod.admin_directory_user_ids(
                db, Account, User, ROLE_ADMIN, ROLE_SUPER_USER
            )
            login_label = acc.display_login
            account_approval_support_mod.notify_users(
                db,
                User,
                create_notification=_create_notification,
                emit_to_account=emit_notification_to_account,
                recipient_user_ids=admin_ids,
                title="Password reset requested",
                message=(
                    f"{login_label} requested a password reset. "
                    f"Send them this link (expires in 1 hour): {reset_url}"
                ),
                entity_type="account",
                entity_id=int(acc.id),
                actor=acc,
                severity="warning",
                n_type="security",
            )
        except Exception:
            app.logger.exception("Could not notify administrators of a password reset request")

    @app.route("/forgot-password", methods=["GET", "POST"])
    def forgot_password():
        if session.get("account_id"):
            return redirect(url_for("index"))
        if request.method == "POST":
            login_id = (request.form.get("login") or "").strip()
            acc = _account_by_login_id(login_id)
            if acc is not None and account_approval_support_mod.account_may_use_app(acc):
                token = _password_reset_token(acc)
                reset_url = url_for("reset_password", token=token, _external=True)
                log_security_event(
                    "password_reset_requested",
                    account_id=int(acc.id),
                    details={"login": (acc.display_login or "")[:120]},
                )
                app.logger.info("Password reset link for account %s: %s", acc.id, reset_url)
                _notify_admins_password_reset(acc, reset_url)
            else:
                log_security_event(
                    "password_reset_requested",
                    details={"login": login_id.lower()[:120], "unknown": True},
                )
            flash(
                "If an account matches, a reset link was sent to an administrator. "
                "Check with them, then use the link within one hour.",
                "success",
            )
            return redirect(url_for("login"))
        return render_template("forgot_password.html")

    @app.route("/reset-password/<token>", methods=["GET", "POST"])
    def reset_password(token: str):
        if session.get("account_id"):
            return redirect(url_for("index"))
        acc = _account_from_password_reset_token(token)
        if acc is None:
            flash("That reset link is invalid or has expired. Request a new one.", "error")
            return redirect(url_for("forgot_password"))
        if request.method == "POST":
            new_pw = request.form.get("password") or ""
            confirm_pw = request.form.get("confirm") or ""
            if len(new_pw) < MIN_PASSWORD_LENGTH:
                flash(
                    f"Password must be at least {MIN_PASSWORD_LENGTH} characters.",
                    "error",
                )
                return render_template("reset_password.html", token=token)
            if new_pw != confirm_pw:
                flash("Passwords do not match.", "error")
                return render_template("reset_password.html", token=token)
            acc.password_hash = generate_password_hash(new_pw, method="pbkdf2:sha256")
            db.session.commit()
            log_security_event("password_reset_completed", account_id=int(acc.id))
            flash("Your password was updated. Sign in with the new password.", "success")
            return redirect(url_for("login"))
        return render_template("reset_password.html", token=token)


    @app.route("/register", methods=["GET", "POST"])
    def register():
        if not app.config.get("ALLOW_PUBLIC_REGISTER"):
            flash("Public registration is disabled. Ask an administrator for an account.", "error")
            return redirect(url_for("login"))
        if session.get("account_id"):
            return redirect(url_for("index"))

        if request.method == "POST":
            name = (request.form.get("name") or "").strip()
            email = (request.form.get("email") or "").strip().lower()
            password = request.form.get("password") or ""
            confirm = request.form.get("confirm") or ""
            company = (request.form.get("company") or "").strip()[:160] or None
            department_code = (request.form.get("department_code") or "").strip()[:40] or None
            jt_raw = (request.form.get("requested_job_title_id") or "").strip()
            requested_job_title_id = int(jt_raw) if jt_raw.isdigit() else None

            if not email or not password:
                flash("Email and password are required.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            if not name:
                flash("Name is required.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            if len(password) < MIN_PASSWORD_LENGTH:
                flash(f"Password must be at least {MIN_PASSWORD_LENGTH} characters.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            if password != confirm:
                flash("Passwords do not match.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            acc = Account(
                email=email,
                password_hash=generate_password_hash(password, method="pbkdf2:sha256"),
                role=ROLE_USER,
                status=account_approval_support_mod.STATUS_PENDING_APPROVAL,
                is_active=False,
            )
            db.session.add(acc)
            try:
                db.session.commit()
            except sa_exc.IntegrityError:
                db.session.rollback()
                flash("An account with that email already exists.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            try:
                link_account_to_directory_user(acc, display_name=name)
                du = User.query.filter_by(account_id=acc.id).first()
                if du is not None:
                    if company:
                        du.company = company
                    if department_code:
                        du.department_code = department_code
                    if requested_job_title_id:
                        set_user_job_titles(du, [str(requested_job_title_id)])
                legacy_req = UserApprovalRequest(
                    account_id=acc.id,
                    user_id=du.id if du else 0,
                    status=account_approval_support_mod.REQUEST_PENDING,
                    full_name=name,
                    email=email,
                    company=company,
                    department_code=department_code,
                    requested_job_title_id=requested_job_title_id,
                )
                db.session.add(legacy_req)
                db.session.flush()
                workflow_engine.create_request(
                    request_type=workflow_types_mod.REQUEST_TYPE_USER_REGISTRATION,
                    created_by=acc,
                    target_user_id=du.id if du else None,
                    title=f"Registration: {name}",
                    description="New user registration awaiting approval.",
                    payload={
                        "account_id": int(acc.id),
                        "user_id": int(du.id) if du else None,
                        "full_name": name,
                        "email": email,
                        "company": company,
                        "department_code": department_code,
                        "requested_job_title_id": requested_job_title_id,
                    },
                    priority=workflow_types_mod.PRIORITY_HIGH,
                    legacy_request_type="user_approval_request",
                    legacy_request_id=int(legacy_req.id),
                    request=request,
                )
                account_approval_support_mod.write_approval_audit(
                    db,
                    AccountApprovalAuditLog,
                    action="registration",
                    actor_account_id=acc.id,
                    target_account_id=acc.id,
                    target_user_id=du.id if du else None,
                    entity_type="user_approval_request",
                    request=request,
                )
                db.session.commit()
            except sa_exc.IntegrityError:
                db.session.rollback()
                stale = db.session.get(Account, acc.id)
                if stale is not None:
                    db.session.delete(stale)
                    db.session.commit()
                flash("Could not create directory profile for that email.", "error")
                return render_template("register.html", job_titles=_registration_job_titles())

            profile_url = url_for("admin_approvals", tab="pending_users", _external=True)
            req_row = UserApprovalRequest.query.filter_by(account_id=acc.id).first()
            body = account_approval_support_mod.format_registration_admin_message(
                req_row, profile_url
            ) if req_row else f"New user {name} ({email}) registered."
            log_security_event(
                "register_success",
                account_id=acc.id,
                details={"email": email, "pending_approval": True},
            )
            flash(
                "Registration received. Your account is awaiting administrator approval.",
                "success",
            )
            return redirect(url_for("login"))

        return render_template("register.html", job_titles=_registration_job_titles())

    def _registration_job_titles():
        return (
            JobTitle.query.filter_by(is_active=True)
            .order_by(JobTitle.name.asc())
            .all()
        )

    @app.route("/logout", methods=["POST"])
    def logout():
        aid = session.get("account_id")
        if aid:
            log_security_event("logout", account_id=int(aid))
        session.clear()
        return redirect(url_for("login"))

    @app.route("/profile", methods=["GET", "POST"])
    def profile():
        aid = session.get("account_id")
        if not aid:
            return redirect(url_for("login"))
        acc = db.session.get(Account, aid)
        if acc is None:
            session.clear()
            return redirect(url_for("login"))
        du = (
            User.query.options(
                joinedload(User.job_title),
                joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
            )
            .filter_by(account_id=acc.id)
            .first()
        )

        if request.method == "POST":
            action = (request.form.get("action") or "profile").strip().lower()
            if action == "password":
                current_pw = request.form.get("current_password") or ""
                new_pw = request.form.get("new_password") or ""
                confirm_pw = request.form.get("confirm_password") or ""
                if not current_pw or not new_pw:
                    flash("Current password and new password are required.", "error")
                    return redirect(url_for("profile"))
                if len(new_pw) < MIN_PASSWORD_LENGTH:
                    flash(f"New password must be at least {MIN_PASSWORD_LENGTH} characters.", "error")
                    return redirect(url_for("profile"))
                if new_pw != confirm_pw:
                    flash("New passwords do not match.", "error")
                    return redirect(url_for("profile"))
                if not check_password_hash(acc.password_hash, current_pw):
                    flash("Current password is incorrect.", "error")
                    return redirect(url_for("profile"))
                acc.password_hash = generate_password_hash(new_pw, method="pbkdf2:sha256")
                db.session.commit()
                flash("Password updated.", "success")
                return redirect(url_for("profile"))

            if action == "avatar_upload":
                if du is None:
                    flash("Could not load your directory profile.", "error")
                    return redirect(url_for("profile"))
                upload_part = request.files.get("avatar_file")
                if (
                    not upload_part
                    or not upload_part.filename
                    or not str(upload_part.filename).strip()
                ):
                    flash("Choose an image to upload.", "error")
                    return redirect(url_for("profile"))
                orig = secure_filename(upload_part.filename) or "photo"
                ext = os.path.splitext(orig)[1].lower()
                if ext not in AVATAR_ALLOWED_EXT:
                    flash("Use PNG, JPG, GIF, or WebP for your photo.", "error")
                    return redirect(url_for("profile"))
                raw = upload_part.read()
                if len(raw) > AVATAR_UPLOAD_MAX_BYTES:
                    flash("Profile image is too large (max 2 MB).", "error")
                    return redirect(url_for("profile"))
                remove_profile_avatar_file(du.avatar_upload)
                new_upload_base = f"u{du.id}-{uuid.uuid4().hex}{ext}"
                dest = os.path.join(upload_root, new_upload_base)
                try:
                    with open(dest, "wb") as out:
                        out.write(raw)
                except OSError:
                    flash("Could not save your photo.", "error")
                    return redirect(url_for("profile"))
                du.avatar_kind = "upload"
                du.avatar_upload = new_upload_base
                try:
                    db.session.commit()
                    flash("Photo updated.", "success")
                except Exception:
                    db.session.rollback()
                    remove_profile_avatar_file(new_upload_base)
                    flash("Could not save your photo.", "error")
                return redirect(url_for("profile"))

            name = (request.form.get("name") or "").strip()
            email = (request.form.get("email") or "").strip().lower()
            if not name or not email:
                flash("Full name and email are required.", "error")
                return redirect(url_for("profile"))
            if du is None:
                link_account_to_directory_user(acc, display_name=name)
                db.session.commit()
                du = User.query.filter_by(account_id=acc.id).first()
            if du is None:
                flash("Could not load your directory profile.", "error")
                return redirect(url_for("profile"))
            if acc.email != email:
                taken = (
                    Account.query.filter(Account.email == email, Account.id != acc.id).first()
                    or User.query.filter(User.email == email, User.id != du.id).first()
                )
                if taken:
                    flash("That email is already in use.", "error")
                    return redirect(url_for("profile"))

            du.name = name
            phone_raw = (request.form.get("phone") or "").strip()[:40]
            du.phone = phone_raw or None

            jt_raw = request.form.get("job_title_id")
            title_ids = request.form.getlist("job_title_ids")
            if not title_ids and jt_raw:
                title_ids = [jt_raw]
            company_raw = (request.form.get("company") or "").strip()[:160] or None
            dept_raw = (request.form.get("department_code") or "").strip()[:40] or None
            emp_raw = (request.form.get("employment_type_code") or "").strip()[:40] or None

            if not account_approval_support_mod.account_may_use_app(acc):
                pass
            else:
                from user_role_mapping import role_for_job_title, USER_TYPE_EMPLOYEE, role_label

                form_snapshot = {
                    "job_title_ids": title_ids,
                    "job_title_id": title_ids[0] if title_ids else None,
                    "department_code": dept_raw,
                    "company": company_raw,
                    "employment_type_code": emp_raw,
                }
                sensitive = account_approval_support_mod.sensitive_profile_changes(
                    du, acc, form_snapshot
                )
                if sensitive:
                    primary_jt = None
                    if sensitive.get("job_title_id"):
                        primary_jt = db.session.get(JobTitle, int(sensitive["job_title_id"]))
                    jt_name = primary_jt.name if primary_jt else ""
                    suggested = role_for_job_title(
                        USER_TYPE_EMPLOYEE,
                        jt_name,
                        job_title=primary_jt,
                    )
                    row = account_approval_support_mod.create_role_change_request(
                        db,
                        RoleChangeRequest,
                        user=du,
                        acc=acc,
                        requested=sensitive,
                        suggested_access_role=suggested,
                    )
                    # Mark the account as awaiting administrator review for sensitive changes.
                    acc.status = account_approval_support_mod.STATUS_PENDING_ROLE_APPROVAL
                    acc.is_active = True
                    acc.status_notes = None
                    account_approval_support_mod.write_approval_audit(
                        db,
                        AccountApprovalAuditLog,
                        action="role_change_requested",
                        actor_account_id=acc.id,
                        target_account_id=acc.id,
                        target_user_id=du.id,
                        entity_type="role_change_request",
                        entity_id=row.id,
                        old_values=account_approval_support_mod.profile_snapshot(du, acc),
                        new_values=sensitive,
                        request=request,
                    )
                    body = account_approval_support_mod.format_role_change_admin_message(
                        row, role_label
                    )
                    workflow_engine.create_request(
                        request_type=workflow_types_mod.REQUEST_TYPE_ROLE_CHANGE,
                        created_by=acc,
                        target_user_id=int(du.id),
                        title=f"Role change: {du.name}",
                        description="Security-sensitive profile changes awaiting approval.",
                        payload={
                            "account_id": int(acc.id),
                            "user_id": int(du.id),
                            "current": account_approval_support_mod.profile_snapshot(du, acc),
                            "requested": {
                                **sensitive,
                                "suggested_access_role": suggested,
                                "requested_access_role": suggested,
                            },
                            "role_change_request_body": body,
                        },
                        priority=workflow_types_mod.PRIORITY_HIGH,
                        legacy_request_type="role_change_request",
                        legacy_request_id=int(row.id),
                        request=request,
                        replace_existing_pending=True,
                    )
                    flash(
                        "Security-sensitive profile changes were submitted for administrator approval.",
                        "success",
                    )
                else:
                    set_user_job_titles(du, title_ids)
                    if company_raw is not None:
                        du.company = company_raw
                    if dept_raw is not None:
                        du.department_code = dept_raw
                    if emp_raw is not None:
                        du.employment_type_code = emp_raw

            acc.email = email
            du.email = email
            try:
                db.session.commit()
                flash("Profile updated.", "success")
            except sa_exc.IntegrityError:
                db.session.rollback()
                flash("Could not save profile (email may be taken).", "error")
            return redirect(url_for("profile"))

        categories = (
            JobCategory.query.options(joinedload(JobCategory.job_titles))
            .order_by(JobCategory.sort_order.asc(), JobCategory.name.asc())
            .all()
        )
        job_title_groups = job_title_picker_groups(categories)
        orphan_titles = [
            jt
            for jt in JobTitle.query.filter(JobTitle.category_id.is_(None))
            .order_by(JobTitle.name.asc())
            .all()
            if getattr(jt, "is_active", True)
        ]
        if orphan_titles:
            job_title_groups.append((UNCLASSIFIED_JOB_CATEGORY_NAME, orphan_titles))

        import employment_structure_support as esup
        import job_titles_master_support as jtms

        job_title_meta = jtms.job_title_metadata_for_picker(
            db, JobTitle, JobTitleEmploymentTypeLink, JobTitlePostScopeLink, SystemMasterEntry
        )

        employment_policy = (
            esup.user_employment_policy_summary(
                db, SystemMasterEntry, EmploymentScopeLink, du, acc
            )
            if du
            else None
        )
        job_title_scope_chips = (
            jtms.job_title_eligible_scope_chips(du, SystemMasterEntry) if du else []
        )
        pending_role_request = None
        if du and acc:
            pending_role_request = RoleChangeRequest.query.filter_by(
                user_id=du.id, status=account_approval_support_mod.ROLE_REQUEST_PENDING
            ).first()

        return render_template(
            "profile.html",
            account=acc,
            directory_user=du,
            job_title_groups=job_title_groups,
            job_title_picker_data=job_title_picker_json(job_title_groups, categories, job_title_meta),
            employment_policy=employment_policy,
            job_title_scope_chips=job_title_scope_chips,
            account_restricted=not account_approval_support_mod.account_may_use_app(acc),
            pending_role_request=pending_role_request,
            account_status_label=account_approval_support_mod.status_label(getattr(acc, "status", None)),
            account_status_badge_class=account_approval_support_mod.status_badge_class(
                getattr(acc, "status", None)
            ),
        )

    @app.route("/profile/avatar-file/<path:filename>")
    def profile_avatar_file(filename: str):
        if not session.get("account_id"):
            abort(404)
        if "/" in filename or "\\" in filename or ".." in filename or filename.startswith("."):
            abort(404)
        u = User.query.filter_by(account_id=session["account_id"]).first()
        if u is None or (u.avatar_kind or "").lower() != "upload":
            abort(404)
        if (u.avatar_upload or "") != filename:
            abort(404)
        return send_from_directory(upload_root, filename)

    _music_tag_palette = ("red", "orange", "yellow", "green", "blue", "purple")

    def _music_parse_color_tags(raw: str | None) -> list[str]:
        if not raw:
            return []
        parts = [p.strip().lower() for p in str(raw).split(",")]
        out: list[str] = []
        for p in parts:
            if p in _music_tag_palette and p not in out:
                out.append(p)
        return out

    def _music_color_tags_to_db(tags: list[str]) -> str | None:
        clean: list[str] = []
        for t in tags:
            v = (t or "").strip().lower()
            if v in _music_tag_palette and v not in clean:
                clean.append(v)
        return ",".join(clean) if clean else None

    def _music_mount_base_real(mount: MusicMount) -> str:
        return os.path.realpath(os.path.abspath(mount.base_path))

    def _music_file_under_mount(file_path: str, mount: MusicMount) -> str | None:
        """Resolved file path if it exists as a file and stays under mount.base_path."""
        try:
            real_f = os.path.realpath(os.path.abspath(file_path))
            base = _music_mount_base_real(mount)
        except OSError:
            return None
        prefix = base + os.sep
        if real_f != base and not real_f.startswith(prefix):
            return None
        if not os.path.isfile(real_f):
            return None
        return real_f

    def ensure_project_main_audio_library(project_id: int) -> ProjectAudioLibrary:
        row = (
            ProjectAudioLibrary.query.filter_by(project_id=project_id, parent_id=None)
            .order_by(ProjectAudioLibrary.id.asc())
            .first()
        )
        if row is not None:
            if (row.name or "").strip().lower() != "main":
                row.name = "Main"
                db.session.commit()
            return row
        row = ProjectAudioLibrary(project_id=project_id, name="Main", parent_id=None)
        db.session.add(row)
        db.session.commit()
        return row

    def _music_get_or_create_for_mount_rel(
        mount: MusicMount, rel_path: str
    ) -> MusicFile | None:
        """Return indexed row for mount+relative path; create a row if file exists."""
        rel = (rel_path or "").strip().replace("\\", "/")
        parts = [p for p in rel.split("/") if p and p != "."]
        if any(p == ".." for p in parts):
            return None
        if not parts:
            return None
        name = parts[-1]
        if not ml.music_is_supported_filename(name):
            return None
        try:
            base = _music_mount_base_real(mount)
        except OSError:
            return None
        target = os.path.realpath(os.path.join(base, *parts))
        prefix = base + os.sep
        if target != base and not target.startswith(prefix):
            return None
        if not os.path.isfile(target):
            return None
        row = MusicFile.query.filter_by(file_path=target).first()
        if row is not None:
            if row.mount_id is None:
                row.mount_id = mount.id
            return row
        rel_fold = "/".join(parts[:-1])
        row = MusicFile(
            mount_id=mount.id,
            file_path=target,
            name=name,
            folder=rel_fold,
            duration=0.0,
            type=ml.music_file_type_from_name(name),
        )
        db.session.add(row)
        return row

    def _music_count_audio_in_tree(scan_root: str) -> int:
        if not os.path.isdir(scan_root):
            return 0
        count = 0
        for _root, _dirs, files in os.walk(scan_root, followlinks=True):
            for fname in files:
                if ml.music_is_supported_filename(fname):
                    count += 1
        return count

    def _music_indexed_in_folder_scope(mount_id: int, folder_path: str) -> list[MusicFile]:
        folder_path = ml.normalize_music_folder_path(folder_path)
        q = MusicFile.query.filter(MusicFile.mount_id == int(mount_id))
        if not folder_path:
            return q.all()
        return q.filter(
            or_(
                MusicFile.folder == folder_path,
                MusicFile.folder.like(folder_path + "/%"),
            )
        ).all()

    def _music_resolve_scan_root(mount: MusicMount, folder_path: str | None) -> tuple[str, str | None]:
        """Return (scan_root, normalized folder_path). folder_path None means full mount."""
        base_path = _music_mount_base_real(mount)
        if not os.path.isdir(base_path):
            raise FileNotFoundError(base_path)
        if folder_path is None:
            return base_path, None
        norm_folder = ml.normalize_music_folder_path(folder_path)
        scan_root = base_path if not norm_folder else os.path.join(base_path, norm_folder)
        try:
            scan_root = os.path.realpath(scan_root)
        except OSError as exc:
            raise FileNotFoundError("Folder no longer exists on disk.") from exc
        if not os.path.isdir(scan_root):
            raise FileNotFoundError("Folder no longer exists on disk.")
        prefix = base_path + os.sep
        if scan_root != base_path and not scan_root.startswith(prefix):
            raise FileNotFoundError("Folder no longer exists on disk.")
        return scan_root, norm_folder

    def _music_read_file_disk_meta(resolved: str, fname: str, folder_display: str) -> dict[str, object]:
        """Disk-derived index fields only; user metadata is never read from disk."""
        from mutagen import File as MutagenFile

        duration = 0.0
        read_error = False
        try:
            audio = MutagenFile(resolved)
            if audio is not None and getattr(audio, "info", None) is not None:
                duration = float(getattr(audio.info, "length", 0) or 0)
        except Exception:
            read_error = True
            duration = 0.0
        mtime = None
        size_bytes = None
        try:
            mtime = float(os.path.getmtime(resolved))
            size_bytes = int(os.path.getsize(resolved))
        except OSError:
            read_error = True
        return {
            "name": fname,
            "folder": folder_display,
            "type": ml.music_file_type_from_name(fname),
            "duration": duration,
            "mtime": mtime,
            "size_bytes": size_bytes,
            "read_error": read_error,
        }

    def _music_sync_existing_file_row(
        existing: MusicFile, meta: dict[str, object], mount_id: int
    ) -> bool:
        """Refresh disk-derived fields; preserve tags, favorites, and other user metadata."""
        changed = False
        if int(existing.mount_id or 0) != int(mount_id):
            existing.mount_id = int(mount_id)
            changed = True
        if (existing.name or "") != str(meta.get("name") or ""):
            existing.name = str(meta.get("name") or "")
            changed = True
        if (existing.folder or "") != str(meta.get("folder") or ""):
            existing.folder = str(meta.get("folder") or "")
            changed = True
        if (existing.type or "") != str(meta.get("type") or ""):
            existing.type = str(meta.get("type") or "")
            changed = True
        new_dur = float(meta.get("duration") or 0)
        if abs(float(existing.duration or 0) - new_dur) > 0.01:
            existing.duration = new_dur
            changed = True
        new_mtime = meta.get("mtime")
        if new_mtime is not None and float(existing.modified_at or 0) != float(new_mtime):
            existing.modified_at = float(new_mtime)
            changed = True
        new_size = meta.get("size_bytes")
        if new_size is not None and int(existing.size_bytes or 0) != int(new_size):
            existing.size_bytes = int(new_size)
            changed = True
        if bool(existing.missing):
            existing.missing = False
            changed = True
        return changed

    def _music_mount_library_type(mount: MusicMount) -> str:
        lib_type = str(getattr(mount, "library_type", None) or "music").strip().lower()
        return lib_type if lib_type in ml.MUSIC_LIBRARY_TYPES else "music"

    def _music_mount_index_counts(mount_id: int) -> tuple[int, int]:
        file_count = int(
            MusicFile.query.filter(
                MusicFile.mount_id == int(mount_id),
                MusicFile.missing.is_(False),
            ).count()
        )
        folder_count = int(MusicFolder.query.filter_by(mount_id=int(mount_id)).count())
        if not folder_count:
            folder_count = int(
                db.session.query(func.count(func.distinct(MusicFile.folder)))
                .filter(
                    MusicFile.mount_id == int(mount_id),
                    MusicFile.folder != "",
                    MusicFile.missing.is_(False),
                )
                .scalar()
                or 0
            )
        return file_count, folder_count

    def _music_update_mount_index_stats(mount_id: int, *, scan_status: str = "idle") -> None:
        row = db.session.get(MusicMount, int(mount_id))
        if row is None:
            return
        file_count, folder_count = _music_mount_index_counts(int(mount_id))
        row.indexed_file_count = int(file_count)
        row.indexed_folder_count = int(folder_count)
        row.scan_status = str(scan_status or "idle")
        if scan_status == "idle":
            row.last_scanned_at = now_local()
        row.updated_at = now_local()

    def _music_sync_folder_index_for_mount(
        mount: MusicMount,
        *,
        disk_folder_paths: set[str] | None = None,
    ) -> None:
        """Rebuild persisted folder rows for a mount from indexed files and scan walk."""
        mount_id = int(mount.id)
        lib_type = _music_mount_library_type(mount)
        file_rows = (
            db.session.query(MusicFile.folder, func.count(MusicFile.id))
            .filter(
                MusicFile.mount_id == mount_id,
                MusicFile.missing.is_(False),
            )
            .group_by(MusicFile.folder)
            .all()
        )
        direct_counts: dict[str, int] = {}
        all_paths: set[str] = set()
        for fold_raw, cnt in file_rows:
            fold = ml.normalize_music_folder_path(fold_raw)
            if fold:
                direct_counts[fold] = int(cnt or 0)
                parts = [p for p in fold.split("/") if p]
                for i in range(len(parts)):
                    all_paths.add("/".join(parts[: i + 1]))
        if disk_folder_paths:
            for path in disk_folder_paths:
                norm = ml.normalize_music_folder_path(path)
                if norm:
                    all_paths.add(norm)
                    parts = [p for p in norm.split("/") if p]
                    for i in range(len(parts) - 1):
                        all_paths.add("/".join(parts[: i + 1]))
        MusicFolder.query.filter_by(mount_id=mount_id).delete()
        child_counts: dict[str, int] = defaultdict(int)
        for path in all_paths:
            parts = [p for p in path.split("/") if p]
            if len(parts) > 1:
                parent = "/".join(parts[:-1])
                child_counts[parent] += 1
        now_ts = now_local()
        for path in sorted(all_paths, key=lambda s: (s.count("/"), s.lower())):
            parts = [p for p in path.split("/") if p]
            if not parts:
                continue
            parent = "/".join(parts[:-1]) if len(parts) > 1 else ""
            db.session.add(
                MusicFolder(
                    mount_id=mount_id,
                    library_type=lib_type,
                    relative_path=path,
                    name=parts[-1],
                    parent_path=parent,
                    depth=len(parts),
                    file_count=int(direct_counts.get(path, 0)),
                    child_folder_count=int(child_counts.get(path, 0)),
                    updated_at=now_ts,
                )
            )

    def _music_ensure_folder_index(mount_id: int) -> None:
        """Backfill folder index from file rows when missing (legacy mounts)."""
        if MusicFolder.query.filter_by(mount_id=int(mount_id)).limit(1).first() is not None:
            return
        mount = db.session.get(MusicMount, int(mount_id))
        if mount is None:
            return
        _music_sync_folder_index_for_mount(mount)
        db.session.commit()

    def scan_mount(
        mount: MusicMount,
        *,
        folder_path: str | None = None,
        rescan_folder: bool = False,
        progress_cb=None,
        total_files: int | None = None,
    ) -> dict[str, int]:
        """Walk mount or folder; index audio files. Never modifies files on disk."""
        base_path = _music_mount_base_real(mount)
        scan_root, norm_folder = _music_resolve_scan_root(mount, folder_path)
        if total_files is None:
            total_files = _music_count_audio_in_tree(scan_root)

        added = 0
        updated = 0
        removed = 0
        errors = 0
        files_scanned = 0
        folders_scanned = 0
        disk_paths: set[str] = set()
        disk_folder_paths: set[str] = set()
        pending = 0
        mount_id = int(mount.id)
        db.session.query(MusicMount).filter_by(id=mount_id).update({"scan_status": "running"})
        db.session.commit()

        def _report(current_path: str = "", message: str | None = None) -> None:
            if not progress_cb:
                return
            pct = 0
            if total_files and total_files > 0:
                pct = min(99, int(files_scanned * 100 / total_files))
            progress_cb(
                files_scanned=files_scanned,
                folders_scanned=folders_scanned,
                current_path=current_path,
                percent=pct,
                message=message or "",
                added=added,
                updated=updated,
                removed=removed,
                errors=errors,
            )

        for root, _dirs, files in os.walk(scan_root, followlinks=True):
            folders_scanned += 1
            rel_fold = os.path.relpath(root, base_path)
            folder_display = "" if rel_fold in (".", "") else rel_fold.replace("\\", "/")
            if folder_display:
                disk_folder_paths.add(folder_display)
            display_path = folder_display or mount.name or "Root"
            _report(display_path, f"Scanning folder: {display_path}")

            for fname in files:
                if not ml.music_is_supported_filename(fname):
                    continue
                full_path = os.path.join(root, fname)
                try:
                    resolved = os.path.realpath(full_path)
                except OSError:
                    errors += 1
                    continue
                prefix = base_path + os.sep
                if resolved != base_path and not resolved.startswith(prefix):
                    continue
                if not os.path.isfile(resolved):
                    continue

                files_scanned += 1
                disk_paths.add(resolved)
                meta = _music_read_file_disk_meta(resolved, fname, folder_display)
                if meta.get("read_error"):
                    errors += 1

                existing = MusicFile.query.filter_by(file_path=resolved).first()
                if existing is not None:
                    if rescan_folder:
                        if _music_sync_existing_file_row(existing, meta, int(mount.id)):
                            updated += 1
                            pending += 1
                            if pending >= 256:
                                db.session.commit()
                                pending = 0
                    elif bool(existing.missing):
                        if _music_sync_existing_file_row(existing, meta, int(mount.id)):
                            updated += 1
                            pending += 1
                            if pending >= 256:
                                db.session.commit()
                                pending = 0
                    continue

                db.session.add(
                    MusicFile(
                        mount_id=mount.id,
                        file_path=resolved,
                        name=str(meta.get("name") or fname),
                        folder=str(meta.get("folder") or folder_display),
                        duration=float(meta.get("duration") or 0),
                        type=str(meta.get("type") or ml.music_file_type_from_name(fname)),
                        size_bytes=int(meta.get("size_bytes") or 0) or None,
                        modified_at=float(meta.get("mtime")) if meta.get("mtime") is not None else None,
                        missing=False,
                    )
                )
                added += 1
                pending += 1
                if pending >= 256:
                    db.session.commit()
                    pending = 0
                if files_scanned % 16 == 0:
                    _report(resolved)

        if rescan_folder:
            scope_folder = norm_folder if norm_folder is not None else ""
            for row in _music_indexed_in_folder_scope(mount.id, scope_folder):
                if row.file_path in disk_paths:
                    continue
                try:
                    still_exists = os.path.isfile(row.file_path)
                except OSError:
                    still_exists = False
                if not still_exists:
                    if not bool(row.missing):
                        row.missing = True
                        removed += 1
                        pending += 1
                        if pending >= 256:
                            db.session.commit()
                            pending = 0

        if pending:
            db.session.commit()
        _music_sync_folder_index_for_mount(mount, disk_folder_paths=disk_folder_paths)
        _music_update_mount_index_stats(mount_id, scan_status="idle")
        db.session.commit()
        _report("", f"{files_scanned} files scanned")
        return {
            "added": added,
            "updated": updated,
            "removed": removed,
            "errors": errors,
            "files_scanned": files_scanned,
            "folders_scanned": folders_scanned,
        }

    def _enqueue_music_scan(mount_id: int, folder_path: str | None, *, rescan_folder: bool) -> str:
        scan_id = ml.create_music_scan_job(mount_id, folder_path or "")

        def _job() -> None:
            with app.app_context():
                try:
                    m = db.session.get(MusicMount, int(mount_id))
                    if m is None:
                        ml.update_music_scan_job(
                            scan_id,
                            status="failed",
                            message="Mount not found.",
                            finished_at=time.time(),
                        )
                        return
                    norm_label = ml.normalize_music_folder_path(folder_path) if rescan_folder else ""
                    is_folder_scope = rescan_folder and bool(norm_label)
                    if is_folder_scope:
                        start_msg = "Rescanning folder: " + (norm_label or "Root")
                    elif rescan_folder:
                        start_msg = f"Rescanning audio source “{m.name}”…"
                    else:
                        start_msg = f"Scanning audio source “{m.name}”…"
                    ml.update_music_scan_job(
                        scan_id,
                        status="running",
                        message=start_msg,
                        percent=0,
                    )

                    scan_root, _norm = _music_resolve_scan_root(m, folder_path if rescan_folder else None)
                    total_files = _music_count_audio_in_tree(scan_root)

                    def _progress(**fields) -> None:
                        ml.update_music_scan_job(scan_id, **fields)

                    result = scan_mount(
                        m,
                        folder_path=folder_path if rescan_folder else None,
                        rescan_folder=rescan_folder,
                        progress_cb=_progress,
                        total_files=total_files,
                    )
                    file_count, folder_count = _music_mount_index_counts(int(m.id))
                    msg = ml.music_scan_summary_message(result, rescan=rescan_folder)
                    ml.update_music_scan_job(
                        scan_id,
                        status="done",
                        percent=100,
                        message=msg,
                        added=int(result.get("added") or 0),
                        updated=int(result.get("updated") or 0),
                        removed=int(result.get("removed") or 0),
                        errors=int(result.get("errors") or 0),
                        files_scanned=int(result.get("files_scanned") or 0),
                        folders_scanned=int(result.get("folders_scanned") or 0),
                        mount_file_count=file_count,
                        mount_folder_count=folder_count,
                        finished_at=time.time(),
                    )
                except FileNotFoundError as exc:
                    err = str(exc) or "Folder no longer exists on disk."
                    if "no longer exists" not in err.lower():
                        err = f"Mount path is not available: {err}"
                    m_fail = db.session.get(MusicMount, int(mount_id))
                    if m_fail is not None:
                        m_fail.scan_status = "failed"
                        db.session.commit()
                    ml.update_music_scan_job(
                        scan_id,
                        status="failed",
                        message=err,
                        finished_at=time.time(),
                    )
                except Exception as exc:
                    app.logger.exception("music_scan_job %s", scan_id)
                    m_fail = db.session.get(MusicMount, int(mount_id))
                    if m_fail is not None:
                        m_fail.scan_status = "failed"
                        db.session.commit()
                    ml.update_music_scan_job(
                        scan_id,
                        status="failed",
                        message=f"Scan failed: {exc}",
                        finished_at=time.time(),
                    )

        thread = threading.Thread(
            target=_job,
            name=f"music-scan-{scan_id[:8]}",
            daemon=True,
        )
        thread.start()
        return scan_id

    def _music_usage_counts_for_files(file_ids: list[int]) -> dict[int, int]:
        if not file_ids:
            return {}
        out: dict[int, int] = {}
        for fid, cnt in (
            db.session.query(AudioUsage.file_id, func.count(AudioUsage.id))
            .filter(
                AudioUsage.file_id.in_(file_ids),
                AudioUsage.action.in_(tuple(ml.MUSIC_USAGE_MOST_USED_ACTIONS)),
            )
            .group_by(AudioUsage.file_id)
            .all()
        ):
            out[int(fid)] = int(cnt or 0)
        return out

    def _music_serialize_file_row(
        row: MusicFile,
        usage_count: int = 0,
        *,
        include_metadata: bool = False,
    ) -> dict[str, object]:
        return ml.serialize_music_file_row(
            row,
            usage_count=usage_count,
            color_tags=_music_parse_color_tags(row.color_tag),
            include_metadata=include_metadata,
        )

    def _music_record_usage(
        *,
        file_id: int,
        action: str,
        actor: Account | None,
        project_id: int | None = None,
        episode_id: int | None = None,
        scene_id: int | None = None,
        notes: str = "",
    ) -> None:
        act = str(action or "").strip().lower()
        if act not in ml.MUSIC_USAGE_ACTIONS:
            return
        row = db.session.get(MusicFile, int(file_id))
        if row is None:
            return
        uid = int(actor.id) if actor is not None else None
        db.session.add(
            AudioUsage(
                file_id=int(row.id),
                project_id=project_id,
                episode_id=episode_id,
                scene_id=scene_id,
                user_id=uid,
                action=act,
                notes=(notes or "").strip(),
            )
        )
        db.session.commit()

    def _music_child_folder_names_at(
        all_folders: list[str], parent_folder: str
    ) -> set[str]:
        """Immediate child folder names under parent_folder (subfolders only)."""
        parent_folder = ml.normalize_music_folder_path(parent_folder)
        prefix = parent_folder + "/" if parent_folder else ""
        names: set[str] = set()
        for fold_raw in all_folders:
            fold = ml.normalize_music_folder_path(fold_raw)
            if parent_folder:
                if fold != parent_folder and not fold.startswith(prefix):
                    continue
                rel = fold[len(prefix) :] if fold.startswith(prefix) else ""
            else:
                rel = fold
            if not rel:
                continue
            parts = [p for p in rel.split("/") if p]
            if parts:
                names.add(parts[0])
        return names

    def _music_folder_child_nodes(mount_id: int, folder: str) -> list[dict[str, object]]:
        """Immediate child folders from persisted index only (no disk scan)."""
        _music_ensure_folder_index(int(mount_id))
        folder = ml.normalize_music_folder_path(folder)
        mount = db.session.get(MusicMount, int(mount_id))
        source_name = (mount.name if mount else "") or ""
        lib_type = _music_mount_library_type(mount) if mount else "music"
        rows = (
            MusicFolder.query.filter_by(mount_id=int(mount_id), parent_path=folder)
            .order_by(MusicFolder.name.asc())
            .all()
        )
        nodes: list[dict[str, object]] = []
        for row in rows:
            nodes.append(
                {
                    "name": row.name,
                    "path": row.relative_path,
                    "has_children": int(row.child_folder_count or 0) > 0,
                    "child_folder_count": int(row.child_folder_count or 0),
                    "file_count": int(row.file_count or 0),
                    "subtree_count": int(row.file_count or 0),
                    "mount_id": int(mount_id),
                    "library_type": lib_type,
                    "source_name": source_name,
                }
            )
        return nodes

    def _build_folder_mounts() -> list[dict[str, object]]:
        """Lightweight mount summaries for page bootstrap — children load via /folders."""
        folder_mounts: list[dict[str, object]] = []
        for m in MusicMount.query.order_by(MusicMount.created_at.asc()).all():
            mid = int(m.id)
            lib_type = _music_mount_library_type(m)
            file_count = int(getattr(m, "indexed_file_count", 0) or 0)
            folder_count = int(getattr(m, "indexed_folder_count", 0) or 0)
            if not file_count and not folder_count:
                file_count, folder_count = _music_mount_index_counts(mid)
            root_children = int(
                MusicFolder.query.filter_by(mount_id=mid, parent_path="").count()
            )
            folder_mounts.append(
                {
                    "mount_id": mid,
                    "mount": (m.name or "").strip() or f"Source {mid}",
                    "library_type": lib_type,
                    "indexed_file_count": file_count,
                    "indexed_folder_count": folder_count,
                    "scan_status": str(getattr(m, "scan_status", None) or "idle"),
                    "root_child_folder_count": root_children,
                    "children": [],
                }
            )
        return folder_mounts

    def _find_mount_by_resolved_path(resolved: str) -> MusicMount | None:
        try:
            target = os.path.realpath(resolved)
        except OSError:
            return None
        for m in MusicMount.query.all():
            try:
                if _music_mount_base_real(m) == target:
                    return m
            except OSError:
                continue
        return None

    @app.route("/music-library/")
    @app.route("/music-library")
    def music_library():
        q = (request.args.get("q") or "").strip()
        folder_mounts = _build_folder_mounts()
        all_mounts = MusicMount.query.order_by(MusicMount.created_at.asc()).all()

        usage_top: list[dict[str, object]] = []
        usage_recent: list[dict[str, object]] = []
        try:
            meaningful = tuple(ml.MUSIC_USAGE_MOST_USED_ACTIONS)
            top_q = (
                db.session.query(AudioUsage.file_id, func.count(AudioUsage.id).label("cnt"))
                .filter(AudioUsage.action.in_(meaningful))
                .group_by(AudioUsage.file_id)
                .order_by(func.count(AudioUsage.id).desc())
                .limit(10)
                .all()
            )
            for file_id, cnt in top_q:
                mf = db.session.get(MusicFile, int(file_id))
                usage_top.append(
                    {
                        "id": int(file_id),
                        "name": mf.name if mf else "Unknown",
                        "count": int(cnt),
                    }
                )
            recent_rows = (
                AudioUsage.query.filter(AudioUsage.action.in_(meaningful))
                .order_by(AudioUsage.created_at.desc())
                .limit(12)
                .all()
            )
            for row in recent_rows:
                mf = row.file
                act = str(row.action or "")
                usage_recent.append(
                    {
                        "file_id": int(row.file_id),
                        "name": mf.name if mf else "Unknown",
                        "action": act,
                        "action_label": ml.MUSIC_USAGE_ACTION_LABELS.get(act, act.replace("_", " ").title()),
                        "at": row.created_at.isoformat() if row.created_at else "",
                    }
                )
        except Exception:
            usage_top = []
            usage_recent = []

        actor = account_from_session()
        visible = visible_project_ids_for_account(actor)
        project_query = Project.query.order_by(Project.name.asc())
        if visible is not None:
            if not visible:
                project_rows = []
            else:
                project_rows = project_query.filter(Project.id.in_(list(visible))).all()
        else:
            project_rows = project_query.all()
        project_audio_targets: dict[int, list[dict[str, object]]] = {}
        if project_rows:
            pids = [int(p.id) for p in project_rows]
            libs = (
                ProjectAudioLibrary.query.filter(ProjectAudioLibrary.project_id.in_(pids))
                .order_by(ProjectAudioLibrary.parent_id.asc(), ProjectAudioLibrary.name.asc())
                .all()
            )
            by_pid: dict[int, list[ProjectAudioLibrary]] = defaultdict(list)
            for l in libs:
                by_pid[int(l.project_id)].append(l)
            for p in project_rows:
                ensure_project_main_audio_library(int(p.id))
                libs_for_project = by_pid.get(int(p.id), [])
                if not libs_for_project:
                    libs_for_project = (
                        ProjectAudioLibrary.query.filter_by(project_id=int(p.id))
                        .order_by(ProjectAudioLibrary.parent_id.asc(), ProjectAudioLibrary.name.asc())
                        .all()
                    )
                project_audio_targets[int(p.id)] = [
                    {"id": int(l.id), "name": l.name, "parent_id": (int(l.parent_id) if l.parent_id else None)}
                    for l in libs_for_project
                ]

        mounts = all_mounts
        mount_link_counts: dict[int, int] = {}
        mount_file_counts: dict[int, int] = {}
        mount_folder_counts: dict[int, int] = {}
        if mounts:
            mids = [int(m.id) for m in mounts]
            for mid, cnt in (
                db.session.query(ProjectAudioFolder.mount_id, func.count(ProjectAudioFolder.id))
                .filter(ProjectAudioFolder.mount_id.in_(mids))
                .group_by(ProjectAudioFolder.mount_id)
                .all()
            ):
                mount_link_counts[int(mid)] = int(cnt or 0)
            for m in mounts:
                mid = int(m.id)
                fc = int(getattr(m, "indexed_file_count", 0) or 0)
                fdc = int(getattr(m, "indexed_folder_count", 0) or 0)
                if fc or fdc:
                    mount_file_counts[mid] = fc
                    mount_folder_counts[mid] = fdc
                else:
                    mount_file_counts[mid], mount_folder_counts[mid] = _music_mount_index_counts(mid)

        music_total_files = int(
            MusicFile.query.filter(MusicFile.missing.is_(False)).count()
        )
        music_total_folders = int(MusicFolder.query.count())
        if not music_total_folders:
            music_total_folders = int(
                db.session.query(func.count(func.distinct(MusicFile.folder)))
                .filter(MusicFile.folder != "", MusicFile.missing.is_(False))
                .scalar()
                or 0
            )
        music_recent_preview = (
            MusicFile.query.options(joinedload(MusicFile.mount))
            .filter(MusicFile.missing.is_(False))
            .order_by(MusicFile.created_at.desc())
            .limit(8)
            .all()
        )

        return render_template(
            "music_library.html",
            search_files=[],
            folder_mounts=folder_mounts,
            mounts=mounts,
            mount_link_counts=mount_link_counts,
            mount_file_counts=mount_file_counts,
            mount_folder_counts=mount_folder_counts,
            projects_for_audio=project_rows,
            project_audio_targets=project_audio_targets,
            query=q,
            usage_top=usage_top,
            usage_recent=usage_recent,
            music_total_files=music_total_files,
            music_total_folders=music_total_folders,
            music_recent_preview=music_recent_preview,
            file_usage_counts={},
        )

    app.add_url_rule("/audio-library/", "audio_library", music_library, methods=["GET"])
    app.add_url_rule("/audio-library", "audio_library", music_library, methods=["GET"])

    @app.route("/music-library/files")
    def music_library_files():
        folder = ml.normalize_music_folder_path(request.args.get("folder"))
        mount_id = request.args.get("mount_id", type=int)
        name_q = (request.args.get("q") or "").strip()
        library_type = (request.args.get("library_type") or "").strip().lower()
        page = max(1, int(request.args.get("page", 1) or 1))
        per_page = min(500, max(1, int(request.args.get("per_page", 100) or 100)))
        legacy_array = request.args.get("legacy") == "1"
        include_metadata = request.args.get("include_metadata", "0").strip().lower() in {
            "1",
            "true",
            "yes",
        }
        include_missing = request.args.get("include_missing", "0").strip().lower() in {
            "1",
            "true",
            "yes",
        }
        search_mode = bool(name_q) and mount_id is None and not folder

        query = MusicFile.query.filter(MusicFile.missing.is_(False))
        if not include_missing:
            pass
        if mount_id is not None:
            query = query.filter(MusicFile.mount_id == int(mount_id))
        if library_type in ml.MUSIC_LIBRARY_TYPES:
            query = query.join(MusicMount, MusicMount.id == MusicFile.mount_id).filter(
                MusicMount.library_type == library_type
            )
        if search_mode:
            like = f"%{name_q}%"
            search_filters = [
                MusicFile.name.ilike(like),
                MusicFile.folder.ilike(like),
                MusicFile.type.ilike(like),
                MusicFile.tags.ilike(like),
            ]
            type_q = ml.music_search_type_from_query(name_q)
            if type_q:
                search_filters.append(MusicFile.type == type_q)
            query = query.filter(or_(*search_filters))
        elif name_q:
            like = f"%{name_q}%"
            query = query.filter(MusicFile.name.ilike(like))
        elif folder:
            query = query.filter(
                or_(
                    MusicFile.folder == folder,
                    MusicFile.folder.like(folder + "/%"),
                )
            )
        elif mount_id is not None:
            query = query.filter(MusicFile.folder == "")
        query = query.order_by(MusicFile.name.asc())
        total = int(query.count())
        files = (
            query.options(joinedload(MusicFile.mount))
            .offset((page - 1) * per_page)
            .limit(per_page)
            .all()
        )
        usage_by_id = _music_usage_counts_for_files([int(f.id) for f in files])
        items = [
            _music_serialize_file_row(
                f,
                usage_by_id.get(int(f.id), 0),
                include_metadata=include_metadata,
            )
            for f in files
        ]

        if legacy_array:
            return jsonify(items)

        return jsonify(
            ml.music_json_ok(
                data={
                    "items": items,
                    "page": page,
                    "per_page": per_page,
                    "total": total,
                    "has_next": page * per_page < total,
                    "has_prev": page > 1,
                }
            )
        )

    @app.route("/music-library/file/<int:file_id>/metadata", methods=["GET"])
    def music_library_file_metadata_get(file_id: int):
        actor = account_from_session()
        if actor is None:
            return jsonify(ml.music_json_err("Sign in required.", error="forbidden")), 403
        row = db.session.get(MusicFile, int(file_id))
        if row is None or bool(row.missing):
            return jsonify(ml.music_json_err("File not found.", error="not_found")), 404
        usage = _music_usage_counts_for_files([int(row.id)]).get(int(row.id), 0)
        return jsonify(
            ml.music_json_ok(
                data=_music_serialize_file_row(row, usage, include_metadata=True),
            )
        )

    @app.route("/music-library/folders")
    def music_library_folders():
        mount_id = request.args.get("mount_id", type=int)
        folder = ml.normalize_music_folder_path(request.args.get("folder"))
        if mount_id is None:
            return jsonify(ml.music_json_err("mount_id is required.", error="invalid_input")), 400
        mount = db.session.get(MusicMount, int(mount_id))
        if mount is None:
            return jsonify(ml.music_json_err("Mount not found.", error="not_found")), 404
        children = _music_folder_child_nodes(int(mount_id), folder)
        items = [
            {
                "name": c.get("name"),
                "mount_id": int(mount_id),
                "library_type": c.get("library_type") or _music_mount_library_type(mount),
                "folder": c.get("path") or "",
                "has_children": bool(c.get("has_children")),
                "file_count": int(c.get("file_count") or 0),
                "source_name": c.get("source_name") or (mount.name or ""),
                "child_folder_count": int(c.get("child_folder_count") or 0),
            }
            for c in children
        ]
        return jsonify(
            ml.music_json_ok(
                data={
                    "mount_id": int(mount_id),
                    "folder": folder,
                    "children": children,
                    "items": items,
                }
            )
        )

    @app.route("/music-library/folder-links")
    def music_library_folder_links():
        actor = account_from_session()
        if actor is None:
            return jsonify(ml.music_json_err("Sign in required.", error="forbidden")), 403
        mount_id = request.args.get("mount_id", type=int)
        folder = ml.normalize_music_folder_path(request.args.get("folder"))
        if mount_id is None:
            return jsonify(ml.music_json_err("mount_id is required.", error="invalid_input")), 400
        links = (
            ProjectAudioFolder.query.options(joinedload(ProjectAudioFolder.library))
            .filter_by(mount_id=int(mount_id), folder_path=folder)
            .all()
        )
        project_ids = {int(l.project_id) for l in links if l.project_id}
        projects = (
            {int(p.id): p for p in Project.query.filter(Project.id.in_(project_ids)).all()}
            if project_ids
            else {}
        )
        out = []
        for link in links:
            p = projects.get(int(link.project_id or 0))
            if p is None:
                continue
            out.append(
                {
                    "link_id": int(link.id),
                    "project_id": int(p.id),
                    "project_name": p.name or f"Project {int(p.id)}",
                    "library_id": int(link.library_id or 0),
                    "library_name": (link.library.name if link.library else "") or "",
                    "usage_type": link.usage_type or "",
                    "can_open": bool(account_can_access_project(actor, p.id)),
                }
            )
        out.sort(key=lambda x: str(x.get("project_name") or "").lower())
        return jsonify(ml.music_json_ok(data={"links": out}))

    @app.route("/music-library/mount/validate", methods=["POST"])
    def music_library_mount_validate():
        actor = account_from_session()
        if not account_can_manage_music_mounts(actor):
            return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403
        payload = request.get_json(silent=True) or {}
        raw = (payload.get("base_path") or request.form.get("base_path") or "").strip()
        lib_raw = payload.get("library_type") or request.form.get("library_type")
        library_type, lt_err = ml.normalize_library_type(lib_raw or "music")
        if lt_err:
            return jsonify(ml.music_json_err(lt_err, error="invalid_input")), 400
        existing = {str(m.base_path) for m in MusicMount.query.all()}
        bases = [(int(m.id), str(m.base_path)) for m in MusicMount.query.all()]
        result = ml.validate_mount_path(raw, existing_mount_paths=existing, all_mount_bases=bases)
        if result.get("duplicate"):
            dup_mount = MusicMount.query.filter_by(base_path=result.get("normalized_path") or raw).first()
            if dup_mount is None and result.get("normalized_path"):
                for m in MusicMount.query.all():
                    try:
                        if os.path.realpath(str(m.base_path)) == os.path.realpath(str(result.get("normalized_path"))):
                            dup_mount = m
                            break
                    except OSError:
                        continue
            if dup_mount is not None:
                label = ml.library_type_label(getattr(dup_mount, "library_type", "music"))
                result["message"] = f"This path is already mounted as {label}."
                result["library_type"] = str(getattr(dup_mount, "library_type", "music") or "music")
        status = 200 if result.get("ok") else 400
        if result.get("duplicate"):
            status = 409
        elif result.get("ok") and library_type:
            result["library_type"] = library_type
            result["message"] = (
                f"Path is valid and will be mounted under {ml.library_type_label(library_type)}."
            )
        return jsonify(result), status

    @app.route("/music-library/mount/add/", methods=["POST"])
    @app.route("/music-library/mount/add", methods=["POST"])
    def music_library_mount_add():
        actor = account_from_session()
        wants_json = (
            request.is_json
            or "application/json" in (request.headers.get("Accept") or "").lower()
            or request.headers.get("X-Requested-With") == "XMLHttpRequest"
        )
        if not account_can_manage_music_mounts(actor):
            msg = "Only administrators and super users can manage audio sources."
            if wants_json:
                return jsonify(ml.music_json_err(msg, error="forbidden")), 403
            flash(msg, "error")
            return redirect(url_for("music_library"))
        raw = (request.form.get("base_path") or "").strip()
        lib_raw = request.form.get("library_type")
        if request.is_json:
            payload = request.get_json(silent=True) or {}
            raw = (payload.get("base_path") or raw).strip()
            lib_raw = payload.get("library_type") or lib_raw
        library_type, lt_err = ml.normalize_library_type(lib_raw, required=True)
        if lt_err:
            msg = lt_err
            if wants_json:
                return jsonify(ml.music_json_err(msg, error="invalid_input")), 400
            flash(msg, "error")
            return redirect(url_for("music_library"))
        existing = {str(m.base_path) for m in MusicMount.query.all()}
        bases = [(int(m.id), str(m.base_path)) for m in MusicMount.query.all()]
        validated = ml.validate_mount_path(raw, existing_mount_paths=existing, all_mount_bases=bases)
        if not validated.get("ok"):
            msg = str(validated.get("message") or "Invalid audio source path.")
            if validated.get("duplicate"):
                dup_mount = MusicMount.query.filter_by(base_path=validated.get("normalized_path") or raw).first()
                if dup_mount is None and validated.get("normalized_path"):
                    for m in MusicMount.query.all():
                        try:
                            if os.path.realpath(str(m.base_path)) == os.path.realpath(
                                str(validated.get("normalized_path"))
                            ):
                                dup_mount = m
                                break
                        except OSError:
                            continue
                if dup_mount is not None:
                    label = ml.library_type_label(getattr(dup_mount, "library_type", "music"))
                    msg = f"This path is already mounted as {label}."
            if wants_json:
                code = 409 if validated.get("duplicate") else 400
                return jsonify({**validated, "message": msg}), code
            flash(msg, "error" if not validated.get("duplicate") else "warning")
            return redirect(url_for("music_library"))
        resolved = str(validated.get("normalized_path") or "")
        label = os.path.basename(resolved.rstrip(os.sep)) or resolved
        new_mount = MusicMount(
            name=label,
            base_path=resolved,
            library_type=library_type,
            scan_status="queued",
        )
        db.session.add(new_mount)
        db.session.commit()
        log_security_event(
            "audio_mount_add",
            account_id=actor.id if actor else None,
            entity_type="music_mount",
            entity_id=int(new_mount.id),
            details={"base_path": resolved, "library_type": library_type},
        )
        scan_id = _enqueue_music_scan(int(new_mount.id), None, rescan_folder=False)
        msg = f"Audio source added under {ml.library_type_label(library_type)}. Indexing started."
        if wants_json:
            return jsonify(
                ml.music_json_ok(
                    msg,
                    data={
                        "library_type": library_type,
                        "mount_id": int(new_mount.id),
                        "scan_id": scan_id,
                    },
                )
            )
        flash(msg, "success")
        return redirect(url_for("music_library"))

