    @app.route("/music-library/mount/<int:mount_id>/remove/", methods=["POST"])
    @app.route("/music-library/mount/<int:mount_id>/remove", methods=["POST"])
    def music_library_mount_remove(mount_id: int):
        """Unmount library path and remove its indexed files from DB only."""
        actor = account_from_session()
        if not account_can_manage_music_mounts(actor):
            return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403
        m = db.session.get(MusicMount, mount_id)
        if m is None:
            return jsonify(ml.music_json_err("Mount not found.", error="not_found")), 404
        link_count = int(ProjectAudioFolder.query.filter_by(mount_id=mount_id).count())
        if link_count > 0:
            ProjectAudioFolder.query.filter_by(mount_id=mount_id).delete(synchronize_session=False)
        file_ids = [
            int(fid)
            for (fid,) in db.session.query(MusicFile.id)
            .filter_by(mount_id=mount_id)
            .all()
        ]
        removed_files = len(file_ids)
        if file_ids:
            AudioUsage.query.filter(AudioUsage.file_id.in_(file_ids)).delete(
                synchronize_session=False
            )
            MusicFile.query.filter(MusicFile.id.in_(file_ids)).delete(synchronize_session=False)
        MusicFolder.query.filter_by(mount_id=mount_id).delete(synchronize_session=False)
        mount_path = str(getattr(m, "base_path", "") or "")
        db.session.delete(m)
        db.session.commit()
        log_security_event(
            "audio_mount_remove",
            account_id=actor.id if actor else None,
            entity_type="music_mount",
            entity_id=mount_id,
            details={"base_path": mount_path, "removed_files": removed_files},
        )
        msg = "Mount removed from library index. Original files were not deleted."
        if link_count:
            msg += f" {link_count} project library link(s) were removed."
        return jsonify(
            ml.music_json_ok(
                msg,
                data={
                    "removed_files": removed_files,
                    "unlinked_projects": link_count,
                },
            )
        )

    @app.route("/audio/<int:file_id>")
    def stream_audio(file_id: int):
        mf = db.session.get(MusicFile, file_id)
        if mf is None:
            abort(404)
        if not os.path.exists(mf.file_path):
            abort(404)
        if mf.mount_id is not None:
            mount = db.session.get(MusicMount, mf.mount_id)
            if mount is None:
                abort(403)
            real_f = _music_file_under_mount(mf.file_path, mount)
            if real_f is None:
                abort(403)
        else:
            try:
                real_f = os.path.realpath(os.path.abspath(mf.file_path))
            except OSError:
                abort(404)
            if not os.path.isfile(real_f):
                abort(404)
            allowed = False
            for m in MusicMount.query.all():
                base = _music_mount_base_real(m)
                pref = base + os.sep
                if real_f == base or real_f.startswith(pref):
                    allowed = True
                    break
            if not allowed:
                abort(403)
        mt, _enc = mimetypes.guess_type(real_f)
        return send_file(
            real_f, conditional=True, mimetype=mt or "application/octet-stream"
        )

    @app.route("/audio/track", methods=["POST"])
    def track_audio():
        """Legacy usage tracking endpoint (kept for compatibility)."""
        return music_library_usage_track()

    @app.route("/music-library/usage/track", methods=["POST"])
    def music_library_usage_track():
        actor = account_from_session()
        if actor is None:
            return jsonify(ml.music_json_err("Please sign in.", error="forbidden")), 403
        payload = request.get_json(silent=True) or {}
        try:
            file_id = int(payload.get("file_id"))
        except (TypeError, ValueError):
            return jsonify(ml.music_json_err("Invalid file id.", error="invalid_input")), 400
        action = str(payload.get("action") or "").strip().lower()
        if action not in ml.MUSIC_USAGE_ACTIONS:
            return jsonify(ml.music_json_err("Invalid action.", error="invalid_input")), 400
        row = db.session.get(MusicFile, file_id)
        if row is None:
            return jsonify(ml.music_json_err("File not found.", error="not_found")), 404

        project_id: int | None = None
        episode_id: int | None = None
        scene_id: int | None = None
        raw_project_id = payload.get("project_id")
        if raw_project_id not in (None, ""):
            try:
                pid = int(raw_project_id)
                if account_can_access_project(actor, pid):
                    project_id = pid
            except (TypeError, ValueError):
                pass
        raw_episode_id = payload.get("episode_id")
        if raw_episode_id not in (None, ""):
            try:
                episode_id = int(raw_episode_id)
            except (TypeError, ValueError):
                episode_id = None
        raw_scene_id = payload.get("scene_id")
        if raw_scene_id not in (None, ""):
            try:
                scene_id = int(raw_scene_id)
            except (TypeError, ValueError):
                scene_id = None

        try:
            _music_record_usage(
                file_id=int(row.id),
                action=action,
                actor=actor,
                project_id=project_id,
                episode_id=episode_id,
                scene_id=scene_id,
                notes=str(payload.get("notes") or ""),
            )
        except Exception:
            app.logger.exception("music_library_usage_track")
            return jsonify(ml.music_json_err("Could not record usage.", error="server_error")), 500
        return jsonify(ml.music_json_ok())

    @app.route("/music-library/file/<int:file_id>/metadata", methods=["POST"])
    def music_library_file_metadata(file_id: int):
        actor = account_from_session()
        if actor is None or not perm_svc.can(actor, "music_library", "view"):
            return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403
        row = db.session.get(MusicFile, file_id)
        if row is None:
            return jsonify(ml.music_json_err("File not found.", error="not_found")), 404
        payload = request.get_json(silent=True) or {}
        if "tags" in payload:
            row.tags = str(payload.get("tags") or "").strip()[:512]
        if "is_favorite" in payload:
            row.is_favorite = bool(payload.get("is_favorite"))
        if "bpm" in payload:
            row.bpm = ml.parse_music_bpm(payload.get("bpm"))
        for field in (
            "musical_key",
            "mood",
            "genre",
            "instrument",
            "composer",
            "source",
            "license_status",
        ):
            if field in payload:
                setattr(row, field, str(payload.get(field) or "").strip())
        if "usage_notes" in payload:
            row.usage_notes = str(payload.get("usage_notes") or "").strip()
        if "approved_status" in payload:
            row.approved_status = ml.parse_approved_status(payload.get("approved_status"))
        if "comments" in payload:
            row.comments = str(payload.get("comments") or "").strip()
        db.session.commit()
        try:
            _music_record_usage(
                file_id=int(row.id),
                action="metadata_update",
                actor=actor,
                notes="metadata save",
            )
        except Exception:
            app.logger.exception("music metadata usage track")
        return jsonify(
            ml.music_json_ok(
                "Metadata saved.",
                data={"file": _music_serialize_file_row(row)},
            )
        )

    @app.route("/music-library/show/<int:file_id>")
    def music_library_show_in_finder(file_id: int):
        """macOS only: reveal indexed file in Finder (DB/index only; no file mutation)."""
        mf = db.session.get(MusicFile, file_id)
        if mf is None:
            return jsonify(ml.music_json_err("File not found.", error="not_found")), 404
        if os.name != "posix":
            return jsonify(ml.music_json_err("Show in Finder is only available on macOS.", error="unsupported_platform")), 400

        real_f: str | None = None
        if mf.mount_id is not None:
            mount = db.session.get(MusicMount, mf.mount_id)
            if mount is None:
                return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403
            real_f = _music_file_under_mount(mf.file_path, mount)
            if real_f is None:
                return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403
        else:
            # Legacy rows without mount_id: allow only if path stays under any registered mount.
            try:
                candidate = os.path.realpath(os.path.abspath(mf.file_path))
            except OSError:
                candidate = ""
            if not candidate or not os.path.isfile(candidate):
                return jsonify(ml.music_json_err("File not found on disk.", error="not_found")), 404
            for m in MusicMount.query.all():
                base = _music_mount_base_real(m)
                pref = base + os.sep
                if candidate == base or candidate.startswith(pref):
                    real_f = candidate
                    break
            if real_f is None:
                return jsonify(ml.music_json_err("Permission denied.", error="forbidden")), 403

        if not os.path.exists(real_f):
            return jsonify(ml.music_json_err("File not found on disk.", error="not_found")), 404
        try:
            subprocess.run(["open", "-R", real_f], check=False)
        except Exception:
            return jsonify(ml.music_json_err("Could not open Finder.", error="open_failed")), 500
        actor = account_from_session()
        try:
            _music_record_usage(file_id=int(mf.id), action="show_in_finder", actor=actor)
        except Exception:
            app.logger.exception("music show_in_finder usage")
        return jsonify(ml.music_json_ok("Revealed in Finder."))

    @app.route("/music-library/delete/<int:file_id>/", methods=["POST"])
    @app.route("/music-library/delete/<int:file_id>", methods=["POST"])
    def delete_music_file(file_id: int):
        """Remove index row only; never deletes audio from disk."""
        mf = db.session.get(MusicFile, file_id)
