    @app.route("/actions/<int:item_id>/update", methods=["POST"])
    def actions_update(item_id: int):
        acc = account_from_session()
        if acc is None:
            return jsonify(ab.ab_json_err("Sign in required.", error="auth")), 401
        item = ActionItem.query.get_or_404(item_id)
        if not _ab_can_view(item, acc):
            return jsonify(ab.ab_json_err("Not found.", error="forbidden")), 403
        if not ab.can_edit(item, acc, directory_user_id_for_account=directory_user_id_for_account):
            return jsonify(ab.ab_json_err("You cannot edit this item.", error="forbidden")), 403
        payload = request.json if request.is_json else request.form.to_dict()
        if "title" in payload:
            item.title = (payload.get("title") or "").strip()[:300] or None
        if "body" in payload:
            body = (payload.get("body") or "").strip()
            if body:
                item.body = ab.normalize_action_board_body(body)
        if payload.get("item_type") or payload.get("itemType"):
            ab.apply_type_defaults(item, ab.normalize_item_type(payload.get("item_type") or payload.get("itemType")))
        if payload.get("color"):
            item.color = ab.normalize_color(payload.get("color"))
        if payload.get("priority"):
            item.priority = ab.normalize_priority(payload.get("priority"))
        if "due_date" in payload or "dueDate" in payload:
            item.due_date = ab.parse_due_date(payload.get("due_date") or payload.get("dueDate"))
        if "is_pinned" in payload or "isPinned" in payload:
            pin = payload.get("is_pinned", payload.get("isPinned"))
            item.is_pinned = str(pin).lower() not in ("0", "false", "no")
        if payload.get("assigned_to_user_id") is not None or payload.get("assignedToUserId") is not None:
            item.assigned_to_user_id = _ab_parse_int(payload, "assigned_to_user_id", "assignedToUserId")
        link_data = {
            "project_id": _ab_parse_int(payload, "project_id", "projectId"),
            "episode_id": _ab_parse_int(payload, "episode_id", "episodeId"),
            "scene_id": _ab_parse_int(payload, "scene_id", "sceneId"),
            "shooting_day_id": _ab_parse_int(payload, "shooting_day_id", "shootingDayId"),
            "vfx_shot_id": _ab_parse_int(payload, "vfx_shot_id", "vfxShotId"),
            "audio_library_id": _ab_parse_int(payload, "audio_library_id", "audioLibraryId"),
        }
        if any(v is not None for v in link_data.values()):
            err = _ab_apply_links(item, link_data, acc)
            if err:
                return jsonify(ab.ab_json_err(err)), 403
        if "width" in payload:
            try:
                w = int(payload.get("width"))
                item.width = max(140, min(760, w))
            except (TypeError, ValueError):
                pass
        if "height" in payload:
            try:
                h = int(payload.get("height"))
                item.height = max(120, min(480, h))
            except (TypeError, ValueError):
                pass
        item.updated_at = now_local()
        db.session.commit()
        return jsonify(ab.ab_json_ok("Saved.", data={"item": _ab_serialize(item, acc)}))

    @app.route("/actions/<int:item_id>/status", methods=["POST"])
    def actions_status(item_id: int):
        acc = account_from_session()
        if acc is None:
            return jsonify(ab.ab_json_err("Sign in required.", error="auth")), 401
        item = ActionItem.query.get_or_404(item_id)
        if not _ab_can_view(item, acc):
            return jsonify(ab.ab_json_err("Not found.", error="forbidden")), 403
        if not ab.can_update_status(item, acc, directory_user_id_for_account=directory_user_id_for_account):
            return jsonify(ab.ab_json_err("Cannot update status.", error="forbidden")), 403
        if item.item_type == "note":
            return jsonify(ab.ab_json_err("Notes do not have status.", error="conflict")), 409
        payload = request.json if request.is_json else request.form.to_dict()
        status = ab.normalize_status(payload.get("status"))
        if str(payload.get("done")).lower() in ("1", "true", "yes"):
            status = "done"
        if str(payload.get("reopen")).lower() in ("1", "true", "yes"):
            status = "open"
        uid = directory_user_id_for_account(acc)
        ab.apply_status_change(item, status, uid=uid, now_local=now_local)
        item.updated_at = now_local()
        db.session.commit()
        return jsonify(ab.ab_json_ok("Status updated.", data={"item": _ab_serialize(item, acc)}))

