    def _ignored_missing_info_keys() -> set[str]:
        return {r.issue_key for r in IgnoredMissingInfo.query.with_entities(IgnoredMissingInfo.issue_key).all()}

    def _monitor_issue_url(item: dict, *, current_uid: int | None = None) -> str:
        et = (item.get("entity_type") or "").strip().lower()
        eid = int(item.get("entity_id") or 0)
        project_id = item.get("project_id")
        shooting_day_id = item.get("shooting_day_id")
        issue_key = (item.get("issue_key") or "").lower()
        pid = int(project_id) if project_id is not None else None

        if et == "scene" and pid and shooting_day_id:
            return url_for(
                "project_production_day",
                project_id=pid,
                day_id=int(shooting_day_id),
                new=eid if eid else None,
            )
        if et == "shooting_day" and pid and eid:
            return url_for("project_production_day", project_id=pid, day_id=eid)
        if et == "critical":
            return url_for("criticals_list")
        if et == "action_item":
            return url_for("actions_page")
        if et == "vfx_shot" and pid:
            return url_for("vfx_department_workspace", project_id=pid)
        if et == "booking":
            return url_for("booking.booking_home")
        if et == "task":
            if pid:
                return task_notification_href(pid, eid if eid else None)
            return url_for("tasks_list")
        if et == "project" and (pid or eid):
            settings_keys = (
                "missing_director",
                "missing_production_house",
                "missing_project_type",
                "missing_episode_count",
                "missing_shooting_days",
            )
            if any(k in issue_key for k in settings_keys):
                return url_for("project_edit", project_id=int(pid or eid))
            return url_for("project_detail", project_id=int(pid or eid))
        if et == "audio_source":
            return url_for("music_library")
        if et == "hdd" and pid:
            return url_for("machine_project", project_id=pid)
        if et == "user":
            if current_uid is not None and eid == int(current_uid):
                return url_for("profile")
            return url_for("users_list")
        if et == "account":
            return url_for("users_list")
        return url_for("index")

    def _monitor_projects_for_filter(acc: Account | None) -> list[Project]:
        vis = visible_project_ids_for_account(acc)
        q = Project.query.order_by(Project.name.asc())
        if vis is not None:
            if not vis:
                return []
            q = q.filter(Project.id.in_(vis))
        return q.all()

    def _attach_monitor_urls(items: list[dict], acc: Account | None = None) -> None:
        current_uid = directory_user_id_for_account(acc) if acc is not None else None
        for item in items:
            item["url"] = _monitor_issue_url(item, current_uid=current_uid)

    def _dashboard_task_mine_filter(uid: int):
        # "Involved" on the dashboard means you are either the assignee or the creator.
        return or_(Task.user_id == int(uid), Task.requested_by_id == int(uid))

    def count_dashboard_my_open_tasks(project_ids: set[int] | list[int], uid: int) -> int:
        if not project_ids:
            return 0
        return (
            Task.query.filter(
                Task.project_id.in_(project_ids),
                Task.archived.is_(False),
                Task.status == "open",
                _dashboard_task_mine_filter(uid),
            ).count()
        )

    def count_dashboard_team_open_tasks(project_ids: set[int] | list[int], uid: int) -> int:
        if not project_ids:
            return 0
        return (
            Task.query.filter(
                Task.project_id.in_(project_ids),
                Task.archived.is_(False),
                Task.status == "open",
                ~_dashboard_task_mine_filter(uid),
            ).count()
        )

    @app.route("/")
    def index():
        acc = db.session.get(Account, session.get("account_id"))
        vis = visible_project_ids_for_account(acc)
        user_count = User.query.count()
        if vis is None:
            # Administrator: all projects, original dashboard semantics
            task_count = Task.query.filter_by(archived=False).count()
            open_tasks = Task.query.filter_by(status="open", archived=False).count()
        elif not vis:
            task_count = 0
            open_tasks = 0
        else:
            uid = directory_user_id_for_account(acc)
            if uid is None:
                task_count = 0
                open_tasks = 0
            else:
                open_tasks = count_dashboard_my_open_tasks(vis, int(uid))
                task_count = count_dashboard_team_open_tasks(vis, int(uid))

        if acc is not None and account_has_vfx_job_title(acc):
            open_tasks = count_my_open_vfx_shots_for_account(acc)

        if acc is not None and account_is_directory_vfx_supervisor(acc):
            task_count = count_team_open_vfx_shots_for_supervisor(acc)

        # Dashboard "Number of projects": VFX job titles = in-house department projects;
        # administrators = all rows; everyone else = team membership only
        if acc is not None and account_has_vfx_job_title(acc):
            project_count = len(project_ids_with_vfx_department_shots())
        elif acc is not None and acc.is_admin:
            project_count = Project.query.count()
        elif vis is None:
            # Machine Room role: same project list as /machine-room
            project_count = Project.query.count()
        elif not vis:
            project_count = 0
        else:
            project_count = len(vis)

        booking_today_card = None
        if acc is not None:
            uid_bt = directory_user_id_for_account(acc)
            if uid_bt is not None:
                bt = (
                    Booking.query.options(
                        joinedload(Booking.edit_suite),
                        joinedload(Booking.project),
                        joinedload(Booking.booked_for_user),
                    )
                    .filter(
                        Booking.booked_for_id == uid_bt,
                        Booking.booking_date == today_cairo(),
                        Booking.is_active.is_(True),
                    )
                    .order_by(Booking.start_time.asc())
                    .first()
                )
                if bt is not None:
                    sn = bt.edit_suite.name if bt.edit_suite is not None else "Room"
                    pn = bt.project.name if bt.project is not None else ""
                    bf = bt.booked_for_user
                    bf_name = (bf.name or bf.email or "").strip() if bf is not None else ""
                    booking_today_card = {
                        "suite_name": sn,
                        "project_name": pn,
                        "time_label": f"{bt.start_time.strftime('%H:%M')}–{bt.end_time.strftime('%H:%M')}",
                        "booked_for_name": bf_name,
                        "is_full_day": bool(bt.is_full_day),
                    }

        machine_room_tasks = fetch_dashboard_machine_room_tasks(acc)
        critical_count = 0
        if acc is not None:
            uid_crit = directory_user_id_for_account(acc)
            vis_crit = _notification_visible_filter(uid=uid_crit, visible=vis)
            if vis_crit is not None:
                critical_count = (
                    Notification.query.filter(_notification_unresolved_filter())
                    .filter(vis_crit)
                    .filter(_notification_critical_dashboard_filter())
                    .count()
                )

