    @app.route("/criticals")
    def criticals_list():
        acc = db.session.get(Account, session.get("account_id"))
        if acc is None:
            return redirect(url_for("login", next=request.path))
        uid = directory_user_id_for_account(acc)
        visible = visible_project_ids_for_account(acc)
        vis = _notification_visible_filter(uid=uid, visible=visible)
        notifications: list[Notification] = []
        resolved_notifications: list[Notification] = []
        if vis is not None:
            notifications = (
                Notification.query.options(joinedload(Notification.project))
                .filter(_notification_unresolved_filter())
                .filter(vis)
                .filter(_notification_critical_dashboard_filter())
                .order_by(Notification.created_at.desc(), Notification.id.desc())
                .all()
            )
            resolved_notifications = (
                Notification.query.options(joinedload(Notification.project))
                .filter(Notification.is_resolved.is_(True))
                .filter(vis)
                .filter(_notification_critical_dashboard_filter())
                .order_by(Notification.created_at.desc(), Notification.id.desc())
                .limit(75)
                .all()
            )
        all_for_meta = list(notifications) + list(resolved_notifications)
        critical_note_day_ids = _notification_shooting_day_ids_for_critical_notes(all_for_meta)
        creator_labels = _notification_critical_creator_labels(all_for_meta)
        can_resolve = account_may_resolve_criticals(acc)
        # Production editors can resolve shooting-day criticals (same as the day
        # panel's "Solved" button), even if they aren't Producer / Machine Room.
        production_resolvable_ids: set[int] = set()
        if not can_resolve:
            for row in notifications:
                if (row.entity_type or "").strip().lower() != "shooting_day_critical":
                    continue
                if row.project_id is not None and account_may_solve_critical_note_for(
                    acc, int(row.project_id)
                ):
                    production_resolvable_ids.add(int(row.id))
        return render_template(
            "criticals.html",
            notifications=notifications,
            resolved_notifications=resolved_notifications,
            critical_note_day_ids=critical_note_day_ids,
            creator_labels=creator_labels,
            can_resolve_criticals=can_resolve,
            production_resolvable_ids=production_resolvable_ids,
        )

    @app.post("/criticals/notifications/<int:notification_id>/ack")
    def criticals_notification_ack(notification_id: int):
        err = _notification_mutate_field_result(notification_id, "is_acknowledged")
        if err is not None:
            flash("Could not acknowledge that alert.", "error")
        else:
            flash("Critical acknowledged.", "success")
        return redirect(url_for("criticals_list"))

    @app.post("/criticals/notifications/<int:notification_id>/resolve")
    def criticals_notification_resolve(notification_id: int):
        actor = account_from_session()
        if actor is None:
            return redirect(url_for("login", next=url_for("criticals_list")))
        n = db.session.get(Notification, notification_id)
        if n is None:
            flash("Could not resolve that alert.", "error")
            return redirect(url_for("criticals_list"))

        # Shooting-day critical notes behave exactly like the day panel's "Solved"
        # button: mark the underlying note solved, which resolves everyone's alerts
        # and drops it from the criticals list + count. Allowed for anyone who can
        # edit production on the project (matching the Solved button's permission),
        # in addition to Producer / Machine Room.
        et = (n.entity_type or "").strip().lower()
        if et == "shooting_day_critical" and int(n.entity_id or 0) > 0:
            note = db.session.get(ShootingDayCriticalNote, int(n.entity_id))
            if note is not None:
                may_solve = account_may_solve_critical_note_for(actor, n.project_id)
                if not may_solve:
                    flash("You do not have permission to resolve that critical.", "error")
                    return redirect(url_for("criticals_list"))
                if note.solved_at is None:
                    note.solved_at = now_local()
                    note.solved_by_user_id = directory_user_id_for_account(actor)
                    day_for_note = db.session.get(ShootingDay, int(note.shooting_day_id))
                    if day_for_note is not None:
                        emit_shooting_day_critical_solved(note, day_for_note, actor=actor)
                    db.session.commit()
                flash("Critical resolved.", "success")
                return redirect(url_for("criticals_list"))

        if not account_may_resolve_criticals(actor):
            flash("Only Producer or Machine Room can resolve criticals.", "error")
            return redirect(url_for("criticals_list"))
        if not _notification_row_may_mutate(actor, n, field_name="is_resolved"):
            # Still allow Producer/MR to resolve project-scoped criticals they can access.
            if n.project_id is None or not account_can_access_project(actor, int(n.project_id)):
                flash("Could not resolve that alert.", "error")
                return redirect(url_for("criticals_list"))

        err = _notification_mutate_field_result(notification_id, "is_resolved")
        if err is not None:
            # Producer/MR may resolve another teammate's critical row for this project.
            if n.project_id is not None and account_can_access_project(actor, int(n.project_id)):
                n.is_resolved = True
                n.is_read = True
                db.session.commit()
                flash("Critical resolved.", "success")
            else:
                flash("Could not resolve that alert.", "error")
        else:
            flash("Critical resolved.", "success")
        return redirect(url_for("criticals_list"))

    @app.post("/criticals/notifications/<int:notification_id>/read")
    def criticals_notification_read(notification_id: int):
        err = _notification_mutate_field_result(notification_id, "is_read")
        if err is not None:
            flash("Could not mark that alert as read.", "error")
        return redirect(url_for("criticals_list"))

