    def _chat_users_payload(acc: Account, q: str) -> list[dict]:
        rows = chat_thr.eligible_chat_accounts_query(Account, User, acc.id).all()
        users_out: list[dict] = []
        qq = (q or "").strip().lower()
        for row in rows:
            u = User.query.filter_by(account_id=row.id).first()
            if u is None:
                continue
            name = (u.name or row.email or "").strip()
            titles = u.assigned_job_titles()
            jt = (titles[0].name or "").strip() if titles else ""
            if not jt and u.job_title_id:
                jt_row = JobTitle.query.get(u.job_title_id)
                if jt_row:
                    jt = (jt_row.name or "").strip()
            if qq and qq not in name.lower() and qq not in (row.email or "").lower() and qq not in jt.lower():
                continue
            users_out.append(
                {
                    "account_id": row.id,
                    "user_id": u.id,
                    "name": name,
                    "email": row.email,
                    "job_title": jt,
                    "avatar_initial": chat_thr.avatar_initial_from_name(name),
                    "avatar_url": chat_avatar_url_for_user(u),
                    "is_online": False,
                }
            )
        return users_out

