    @app.route("/chat/direct/start", methods=["POST"])
    def chat_direct_start():
        acc = account_from_session()
        if acc is None:
            return jsonify({"ok": False, "error": "auth"}), 401
        payload = request.get_json(silent=True) or {}
        other_id = payload.get("account_id")
        try:
            other_id = int(other_id)
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "bad_account"}), 400
        if other_id == acc.id:
            return jsonify({"ok": False, "error": "self"}), 400
        thread = get_or_create_direct_thread(acc.id, other_id)
        if thread is None:
            return jsonify({"ok": False, "error": "unavailable"}), 400
        threads = build_chat_threads_for_dashboard(acc)
        row = next((t for t in threads if t.get("thread_id") == thread.id), None)
        return jsonify({"ok": True, "thread": row})

    @app.route("/chat/groups", methods=["POST"])
    def chat_groups_create():
        acc = account_from_session()
        if acc is None:
            return jsonify({"ok": False, "error": "auth"}), 401
        payload = request.get_json(silent=True) or {}
        title = (payload.get("title") or "").strip()
        description = (payload.get("description") or "").strip() or None
        raw_ids = payload.get("participant_account_ids") or []
        if not title:
            return jsonify({"ok": False, "error": "title_required"}), 400
        try:
            other_ids = sorted({int(x) for x in raw_ids if int(x) != acc.id})
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "bad_participants"}), 400
        if len(other_ids) < 2:
            return jsonify({"ok": False, "error": "min_participants"}), 400
        eligible = {
            int(r.id)
            for r in chat_thr.eligible_chat_accounts_query(Account, User, acc.id).all()
        }
        if not all(aid in eligible for aid in other_ids):
            return jsonify({"ok": False, "error": "invalid_participant"}), 400
        thread = ChatThread(
            thread_type=chat_thr.THREAD_TYPE_GROUP,
            title=title,
            description=description,
            avatar_label=chat_thr.avatar_initial_from_name(title),
            created_by_account_id=acc.id,
            is_active=True,
        )
        db.session.add(thread)
        db.session.flush()
        ensure_group_participant(thread.id, acc.id, role=chat_thr.PARTICIPANT_ROLE_OWNER)
        for aid in other_ids:
            ensure_group_participant(thread.id, aid)
        db.session.commit()
        threads = build_chat_threads_for_dashboard(acc)
        row = next((t for t in threads if t.get("thread_id") == thread.id), None)
        return jsonify({"ok": True, "thread": row})

