    def _group_thread_or_404(thread_id: int) -> ChatThread | None:
        thread = ChatThread.query.get(thread_id)
        if thread is None or thread.thread_type != chat_thr.THREAD_TYPE_GROUP:
            return None
        return thread

    def _group_admin_part(acc: Account, thread: ChatThread) -> ChatThreadParticipant | None:
        part = thread_participant_row(acc, thread.id, active_only=True)
        if not group_participant_is_admin(part):
            return None
        return part

    @app.route("/chat/groups/<int:thread_id>/members/add", methods=["POST"])
    def chat_group_members_add(thread_id: int):
        acc = account_from_session()
        thread = _group_thread_or_404(thread_id)
        if thread is None or not account_may_use_thread(acc, thread):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if _group_admin_part(acc, thread) is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        payload = request.get_json(silent=True) or {}
        try:
            aid = int(payload.get("account_id"))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "bad_account"}), 400
        eligible = {
            int(r.id)
            for r in chat_thr.eligible_chat_accounts_query(Account, User, acc.id).all()
        }
        if aid not in eligible and aid != acc.id:
            return jsonify({"ok": False, "error": "invalid_participant"}), 400
        ensure_group_participant(thread.id, aid)
        db.session.commit()
        return jsonify({"ok": True, "members": thread_members_for_api(thread)})

    @app.route("/chat/groups/<int:thread_id>/members/remove", methods=["POST"])
    def chat_group_members_remove(thread_id: int):
        acc = account_from_session()
        thread = _group_thread_or_404(thread_id)
        if thread is None or not account_may_use_thread(acc, thread):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if _group_admin_part(acc, thread) is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        payload = request.get_json(silent=True) or {}
        try:
            aid = int(payload.get("account_id"))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "bad_account"}), 400
        if aid == acc.id:
            return jsonify({"ok": False, "error": "use_leave"}), 400
        part = ChatThreadParticipant.query.filter_by(thread_id=thread.id, account_id=aid).first()
        if part is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        if part.role == chat_thr.PARTICIPANT_ROLE_OWNER:
            owners = ChatThreadParticipant.query.filter_by(
                thread_id=thread.id,
                role=chat_thr.PARTICIPANT_ROLE_OWNER,
                is_active=True,
            ).count()
            if owners <= 1:
                return jsonify({"ok": False, "error": "last_owner"}), 400
        part.is_active = False
        part.left_at = now_local()
        db.session.commit()
        return jsonify({"ok": True, "members": thread_members_for_api(thread)})

