    @app.route("/chat/groups/<int:thread_id>/leave", methods=["POST"])
    def chat_group_leave(thread_id: int):
        acc = account_from_session()
        thread = _group_thread_or_404(thread_id)
        if thread is None or not account_may_use_thread(acc, thread):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        part = thread_participant_row(acc, thread.id, active_only=True)
        if part is None:
            return jsonify({"ok": False, "error": "not_member"}), 400
        if part.role == chat_thr.PARTICIPANT_ROLE_OWNER:
            other_admin = ChatThreadParticipant.query.filter(
                ChatThreadParticipant.thread_id == thread.id,
                ChatThreadParticipant.is_active.is_(True),
                ChatThreadParticipant.account_id != acc.id,
                ChatThreadParticipant.role.in_(
                    (chat_thr.PARTICIPANT_ROLE_OWNER, chat_thr.PARTICIPANT_ROLE_ADMIN)
                ),
            ).first()
            if other_admin is None:
                return jsonify({"ok": False, "error": "transfer_owner"}), 400
        part.is_active = False
        part.left_at = now_local()
        db.session.commit()
        return jsonify({"ok": True})

