    @app.route("/admin/chat/management")
    def admin_chat_management():
        acc = account_from_session()
        if acc is None or not acc.is_admin:
            flash("Administrator access required.", "error")
            return redirect(url_for("index"))
        dept_rows = []
        for cat in JobCategory.query.order_by(JobCategory.sort_order.asc(), JobCategory.name.asc()).all():
            thread = ChatThread.query.filter_by(
                thread_type=chat_thr.THREAD_TYPE_DEPARTMENT, department_id=cat.id
            ).first()
            mcount = active_participant_count(thread.id) if thread else 0
            dept_rows.append(
                {
                    "category": cat,
                    "thread": thread,
                    "member_count": mcount,
                }
            )
        group_threads = (
            ChatThread.query.filter_by(thread_type=chat_thr.THREAD_TYPE_GROUP)
            .order_by(ChatThread.created_at.desc())
            .all()
        )
        group_rows = []
        for gt in group_threads:
            owner_part = ChatThreadParticipant.query.filter_by(
                thread_id=gt.id, role=chat_thr.PARTICIPANT_ROLE_OWNER, is_active=True
            ).first()
            owner_name = ""
            if owner_part is not None:
                owner_acc = db.session.get(Account, owner_part.account_id)
                owner_name = owner_acc.display_name if owner_acc else ""
            group_rows.append(
                {
                    "thread": gt,
                    "owner_name": owner_name,
                    "member_count": active_participant_count(gt.id),
                }
            )
        return render_template(
            "admin_chat_management.html",
            dept_rows=dept_rows,
            group_rows=group_rows,
        )

    @app.route("/chat/threads/<int:thread_id>/messages", methods=["GET", "POST"])
    def chat_thread_messages(thread_id: int):
        acc = account_from_session()
        thread = ChatThread.query.get_or_404(thread_id)
        if not account_may_use_thread(acc, thread):
            return jsonify({"error": "forbidden"}), 403
        viewer_uid = directory_user_id_for_account(acc)

        if request.method == "GET":
            limit = chat_sup.clamp_chat_limit(request.args.get("limit"))
            before_id = request.args.get("before_id", type=int)
            after_id = request.args.get("after_id", type=int)
            direction = chat_sup.parse_chat_direction(request.args.get("direction"))
            rows, has_older, has_newer = fetch_paginated_thread_messages(
                thread_id,
                limit=limit,
                before_id=before_id,
                after_id=after_id,
                direction=direction,
            )
            return jsonify(
                build_thread_messages_response(
                    thread,
                    rows,
                    viewer_uid,
                    acc,
                    has_older=has_older,
                    has_newer=has_newer,
                )
            )

        temp_id = (request.form.get("temp_id") or "").strip() or None
        text_raw = (request.form.get("message") or request.form.get("text") or "").strip()
        audio_part = request.files.get("audio")
        image_part = request.files.get("image") or request.files.get("file")
        audio_raw: bytes | None = None
        if audio_part is not None:
            try:
                blob = audio_part.read()
            except Exception:
                blob = b""
            if len(blob) > 0:
                audio_raw = blob
        has_audio = audio_raw is not None
        has_image = bool(image_part and image_part.filename and image_part.filename.strip())
        if has_audio and has_image:
            return jsonify({"error": "one_attachment", "detail": "Send either a photo or a voice note per message, not both."}), 400
        if not text_raw and not has_audio and not has_image:
            return jsonify({"error": "empty", "detail": "Add text, a photo, or a voice note."}), 400
        uid = directory_user_id_for_account(acc)
        if uid is None or acc is None:
            return jsonify({"error": "no_profile"}), 403

        reply_to_id = request.form.get("reply_to_message_id", type=int)
        if reply_to_id is not None:
            ref = ChatMessage.query.filter_by(id=reply_to_id, thread_id=thread_id).first()
            if ref is None:
                return jsonify({"error": "bad_reply", "detail": "Reply target not found in this thread."}), 400

        image_name: str | None = None
        audio_name: str | None = None
        if has_audio:
            assert audio_raw is not None
            if len(audio_raw) > CHAT_AUDIO_MAX_BYTES:
                return jsonify({"error": "too_large", "detail": "Voice note must be 15 MB or smaller."}), 400
            ext = _ext_for_chat_audio(
                getattr(audio_part, "mimetype", None),
                getattr(audio_part, "filename", None),
                audio_raw,
            )
            if ext not in CHAT_AUDIO_EXT:
                ext = ".webm"
            if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT and thread.project_id:
                audio_name = chat_thr.project_attachment_basename(
                    int(thread.project_id), uid, uuid.uuid4().hex, ext, audio=True
                )
            else:
                audio_name = chat_thr.thread_attachment_basename(
                    thread_id, acc.id, uuid.uuid4().hex, ext
                )
            with open(os.path.join(chat_upload_root, audio_name), "wb") as out:
                out.write(audio_raw)
        elif has_image:
            up = image_part
            raw = up.read() if up else b""
            if len(raw) > CHAT_UPLOAD_MAX_BYTES:
                return jsonify({"error": "too_large", "detail": "Image must be 5 MB or smaller."}), 400
            orig = secure_filename(up.filename or "") or "image"
            ext = os.path.splitext(orig)[1].lower()
            if ext not in CHAT_ALLOWED_EXT:
                return jsonify({"error": "bad_type", "detail": "Allowed image types: JPG, PNG, JPEG, WebP."}), 400
            if thread.thread_type == chat_thr.THREAD_TYPE_PROJECT and thread.project_id:
                image_name = chat_thr.project_attachment_basename(
                    int(thread.project_id), uid, uuid.uuid4().hex, ext
                )
            else:
                image_name = chat_thr.thread_attachment_basename(
                    thread_id, acc.id, uuid.uuid4().hex, ext
                )
            with open(os.path.join(chat_upload_root, image_name), "wb") as out:
                out.write(raw)

        msg_text = text_raw if text_raw else None
        cm = ChatMessage(
            thread_id=thread_id,
            project_id=thread.project_id,
            user_id=uid,
            account_id=acc.id,
            message=msg_text,
            image_path=image_name,
            audio_path=audio_name,
            reply_to_message_id=reply_to_id,
        )
        db.session.add(cm)
        thread.updated_at = now_local()
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
            if image_name:
                remove_chat_upload_file(image_name)
            if audio_name:
                remove_chat_upload_file(audio_name)
            app.logger.exception("chat_thread_messages post")
            return jsonify({"error": "save"}), 500

        emit_chat_updated(
            thread.project_id,
            cm.id,
            uid,
            kind="message",
            thread_id=thread.id,
            thread_type=thread.thread_type,
        )

        if msg_text and thread.thread_type == chat_thr.THREAD_TYPE_PROJECT and thread.project_id:
            proj = Project.query.get(thread.project_id)
            pname = (proj.name or "Project").strip() if proj else "Project"
            sender_u = User.query.get(uid)
            sender_label = (sender_u.name or "Someone").strip() if sender_u else "Someone"
            chat_href = url_for("chat_page", project_id=thread.project_id, message_id=cm.id)
            for mentioned in find_project_mentions_for_text(int(thread.project_id), msg_text):
                if mentioned.id == uid or mentioned.account_id is None:
                    continue
                emit_notification_to_account(
                    mentioned.account_id,
                    {
                        "type": "mention",
                        "message": f"{sender_label} mentioned you in {pname}",
                        "href": chat_href,
                        "project_id": thread.project_id,
                        "message_id": cm.id,
                    },
                )
            persist_chat_mentions_for_message(int(thread.project_id), cm.id, msg_text, uid, acc.id)

        body = {
            "ok": True,
            "message": chat_message_json(
                cm,
                viewer_uid,
                reactions=[],
                reply_preview=chat_reply_preview_dict(
                    db.session.get(ChatMessage, reply_to_id) if reply_to_id else None
                ),
                delivery_state="sent",
            ),
        }
        if temp_id:
            body["temp_id"] = temp_id
        return jsonify(body), 201

