    @app.route("/chat/conferences", methods=["GET"])
    def chat_conferences_mine():
        acc = account_from_session()
        if acc is None:
            return jsonify({"ok": False, "error": "auth"}), 401
        part_rows = ChatConferenceParticipant.query.filter_by(account_id=acc.id).all()
        conf_ids = {p.conference_id for p in part_rows}
        created = ChatConference.query.filter_by(created_by_account_id=acc.id).all()
        for c in created:
            conf_ids.add(c.id)
        conferences = (
            ChatConference.query.filter(ChatConference.id.in_(list(conf_ids)))
            .order_by(ChatConference.created_at.desc())
            .limit(100)
            .all()
            if conf_ids
            else []
        )
        out = [
            serialize_conference_json(c, acc)
            for c in conferences
            if account_may_use_conference(acc, c)
        ]
        return jsonify({"ok": True, "conferences": out})

    @app.route("/chat/conferences/<int:conference_id>/join", methods=["POST"])
    def chat_conference_join(conference_id: int):
        acc = account_from_session()
        conf = ChatConference.query.get_or_404(conference_id)
        if not conference_can_join(acc, conf):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        part = conference_participant_row(acc, conference_id)
        now = now_local()
        if part is None and conf.thread_id:
            thread = ChatThread.query.get(conf.thread_id)
            if thread and thread.thread_type == chat_thr.THREAD_TYPE_PROJECT:
                part = ensure_conference_participant(
                    conf, acc.id, invite_status=chat_conf.INVITE_JOINED
                )
        if part is None:
            return jsonify({"ok": False, "error": "not_invited"}), 403
        if conf.status == chat_conf.STATUS_SCHEDULED:
            conf.status = chat_conf.STATUS_LIVE
        part.invite_status = chat_conf.INVITE_JOINED
        part.joined_at = now
        if part.responded_at is None:
            part.responded_at = now
        conf.updated_at = now
        db.session.commit()
        emit_conference_event(conf, kind="joined")
        eff = chat_conf.effective_provider(conf.provider)
        resp: dict = {
            "ok": True,
            "conference": serialize_conference_json(conf, acc, include_meeting_url=True),
            "provider": eff,
        }
        if eff == chat_conf.PROVIDER_EMBEDDED_JITSI:
            resp["room_url"] = url_for("chat_conference_room", conference_id=conf.id)
        elif eff == chat_conf.PROVIDER_EXTERNAL_LINK:
            resp["meeting_url"] = conf.meeting_url
        elif eff == chat_conf.PROVIDER_INTERNAL_WEBRTC_FUTURE:
            resp["room_url"] = url_for("chat_conference_room", conference_id=conf.id)
        return jsonify(resp)

