        acc = account_from_session()
        conf = ChatConference.query.get_or_404(conference_id)
        if not conference_can_manage(acc, conf):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        conf.status = chat_conf.STATUS_ENDED
        conf.ended_at = now_local()
        viewer_uid = directory_user_id_for_account(acc)
        end_cm: ChatMessage | None = None
        if viewer_uid is not None and conf.thread_id:
            end_cm = ChatMessage(
                thread_id=conf.thread_id,
                project_id=conf.project_id,
                user_id=viewer_uid,
                account_id=acc.id,
                message="Conference ended.",
                message_type=chat_conf.MESSAGE_TYPE_SYSTEM,
                conference_id=conf.id,
            )
            db.session.add(end_cm)
            thread = ChatThread.query.get(conf.thread_id)
            if thread:
                thread.updated_at = now_local()
        db.session.commit()
        if end_cm is not None:
            thread = ChatThread.query.get(conf.thread_id)
            emit_chat_updated(
                conf.project_id,
                end_cm.id,
                viewer_uid,
                kind="message",
                thread_id=conf.thread_id,
                thread_type=thread.thread_type if thread else None,
            )
        emit_conference_event(conf, kind="ended")
        return jsonify({"ok": True, "conference": serialize_conference_json(conf, acc)})

