    @app.route("/chat/conferences/<int:conference_id>/invite", methods=["POST"])
    def chat_conference_invite(conference_id: int):
        acc = account_from_session()
        conf = ChatConference.query.get_or_404(conference_id)
        if not conference_can_manage(acc, conf):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        payload = request.get_json(silent=True) or {}
        raw_ids = payload.get("participant_account_ids") or []
        try:
            ids = sorted({int(x) for x in raw_ids if int(x) != acc.id})
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "bad_participants"}), 400
        for aid in ids:
            ensure_conference_participant(conf, aid, invite_status=chat_conf.INVITE_INVITED)
            notify_conference_invite(conf, acc, aid)
        db.session.commit()
        emit_conference_event(conf, kind="invited")
        return jsonify({"ok": True})

    @app.route("/chat/conferences/<int:conference_id>/room")
    def chat_conference_room(conference_id: int):
        acc = account_from_session()
        if acc is None:
            flash("Sign in to join the call.", "error")
            return redirect(url_for("login"))
        conf = ChatConference.query.get_or_404(conference_id)
        if not account_may_use_conference(acc, conf):
            abort(403)
        back_url = conference_back_to_chat_url(conf)
        thread = ChatThread.query.get(conf.thread_id) if conf.thread_id else None
        project = Project.query.get(conf.project_id) if conf.project_id else None
        thread_title = (thread.title if thread else None) or None
        project_name = (project.name if project else None) or None
        if conf.status == chat_conf.STATUS_CANCELLED:
            return render_template(
                "chat_conference_room.html",
                state="cancelled",
                conference=conf,
                back_url=back_url,
                thread_title=thread_title,
                project_name=project_name,
            )
        if conf.status == chat_conf.STATUS_ENDED:
            return render_template(
                "chat_conference_room.html",
                state="ended",
                conference=conf,
                back_url=back_url,
                thread_title=thread_title,
                project_name=project_name,
            )
        eff = chat_conf.effective_provider(conf.provider)
        uid = directory_user_id_for_account(acc)
        u = User.query.get(uid) if uid else None
        display_name = ((u.name if u else None) or acc.email or "User").strip()
        jitsi_base = app.config.get("CHAT_CONFERENCE_JITSI_BASE_URL", "https://meet.jit.si")
        jitsi_domain = chat_conf.jitsi_domain_from_base_url(jitsi_base)
        return render_template(
            "chat_conference_room.html",
            state="active",
            conference=conf,
            provider=eff,
            room_name=conf.room_name if eff == chat_conf.PROVIDER_EMBEDDED_JITSI else None,
            jitsi_domain=jitsi_domain,
            display_name=display_name,
            can_end=conference_can_manage(acc, conf),
            back_url=back_url,
            thread_title=thread_title,
            project_name=project_name,
            conference_id=conf.id,
            thread_id=conf.thread_id,
        )

