    @app.route("/tour/help/<slug>")
    def app_tour_help(slug: str):
        """Illustrated help page for one Take a Tour area."""
        from pathlib import Path

        from app_tour_help_catalog import TOUR_HELP_SLUGS, build_tour_help_catalog

        key = (slug or "").strip().lower()
        if key not in TOUR_HELP_SLUGS:
            abort(404)
        catalog = build_tour_help_catalog(_)
        help_page = catalog.get(key)
        if help_page is None:
            abort(404)
        redirect_ep = help_page.get("redirect_to")
        if redirect_ep:
            return redirect(url_for(redirect_ep))

        open_url = None
        open_ep = help_page.get("open_endpoint")
        if open_ep:
            # Machine Room roles use a different Tasks entry point.
            if key == "tasks" and account_is_machine_room_role(account_from_session()):
                open_url = url_for("machine_room_tasks_tab", tab_slug="progress")
            else:
                try:
                    open_url = url_for(open_ep, **(help_page.get("open_kwargs") or {}))
                except Exception:
                    open_url = None

        static_root = Path(app.static_folder or "static")
        for sec in help_page.get("sections") or []:
            for shot in sec.get("shots") or []:
                rel = str(shot.get("src") or "")
                shot["exists"] = bool(rel) and (static_root / rel).is_file()

        related_machine_room_help = key in ("storage", "machine-room")
        related_access_control_help = key == "access-control"
        return render_template(
            "app_tour_help.html",
            help=help_page,
            open_url=open_url,
            related_machine_room_help=related_machine_room_help,
            related_access_control_help=related_access_control_help,
            tour_slug=key,
        )

    @app.route("/chat/mentions")
    def chat_mentions_page():
        acc = account_from_session()
        if acc is None:
            flash("Sign in to view mentions.", "error")
            return redirect(url_for("login"))
        status = (request.args.get("status") or "open").strip().lower()
        q = ChatMention.query.filter_by(mentioned_account_id=acc.id)
        if status == "open":
            q = q.filter(ChatMention.is_resolved.is_(False))
        elif status == "resolved":
            q = q.filter(ChatMention.is_resolved.is_(True))
        rows = q.order_by(ChatMention.created_at.desc()).limit(200).all()
        mentions = []
        for row in rows:
            m = db.session.get(ChatMessage, row.message_id)
            proj = Project.query.get(row.project_id)
            sender_acc = db.session.get(Account, row.created_by_account_id)
            sender_name = "Someone"
            if sender_acc:
                suid = directory_user_id_for_account(sender_acc)
                if suid:
                    su = User.query.get(suid)
                    if su:
                        sender_name = (su.name or sender_name).strip()
            excerpt = ""
            if m and not m.is_deleted:
                excerpt = chat_sup.message_search_excerpt(m.message, "")
            mentions.append(
                {
                    "id": row.id,
                    "project_name": (proj.name or "Project").strip() if proj else "Project",
                    "sender_name": sender_name,
                    "message_excerpt": excerpt,
                    "created_at": isoformat_stored_instant(row.created_at),
                    "is_resolved": bool(row.is_resolved),
                    "url": chat_sup.chat_message_deep_link(row.project_id, row.message_id),
                }
            )
        return render_template(
            "chat_mentions.html",
            mentions=mentions,
            status_filter=status if status in ("open", "resolved", "all") else "open",
        )

