    def _notification_resolve_superseded_copy_estimate_updates() -> None:
        """Hide open 'Copy/Convert time left updated' cards; progress lives on the started card."""
        estimate_rows = (
            Notification.query.filter(
                _notification_unresolved_filter(),
                Notification.entity_type == "task",
                Notification.rule_key.like("mr_stream_estimate|%"),
            )
            .limit(500)
            .all()
        )
        if not estimate_rows:
            return
        for row in estimate_rows:
            row.is_resolved = True
            row.is_read = True
        db.session.commit()

    def query_notifications_for_account(
        acc: Account | None,
        *,
        limit: int = 50,
        kind: str = "all",
    ) -> list[Notification]:
        """Unresolved notifications visible to this account (team projects + personal rows)."""
        _notification_resolve_superseded_copy_estimate_updates()
        uid = directory_user_id_for_account(acc)
        visible = visible_project_ids_for_account(acc)
        vis = _notification_visible_filter(uid=uid, visible=visible)
        if vis is None:
            return []
        q = (
            Notification.query.filter(_notification_unresolved_filter())
            .filter(vis)
            .order_by(Notification.created_at.desc(), Notification.id.desc())
        )
        if kind in ("alert", "activity"):
            q = q.filter(db.func.lower(db.func.coalesce(Notification.type, "")) == kind)
        return q.limit(max(1, min(200, int(limit)))).all()

    def serialize_notifications_batch(
        rows: list[Notification], *, note_day_map: dict[int, int] | None = None
    ) -> list[dict]:
        pids = {int(n.project_id) for n in rows if n.project_id is not None}
        project_names: dict[int, str] = {}
        if pids:
            for proj in Project.query.filter(Project.id.in_(pids)).all():
                project_names[int(proj.id)] = (proj.name or "").strip() or f"Project {proj.id}"
        if note_day_map is None:
            note_day_map = _notification_shooting_day_ids_for_critical_notes(rows)
        return [
            serialize_notification(n, note_day_map=note_day_map, project_names=project_names)
            for n in rows
        ]

    @app.route("/notifications", methods=["GET"])
    def notifications_list():
        actor = account_from_session()
        if actor is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        raw_limit = (request.args.get("limit") or "50").strip()
        try:
            limit = max(1, min(200, int(raw_limit)))
        except (TypeError, ValueError):
            limit = 50
        kind = (request.args.get("type") or "all").strip().lower()
        rows = query_notifications_for_account(actor, limit=limit, kind=kind)
        return jsonify(
            {
                "ok": True,
                "notifications": serialize_notifications_batch(rows),
            }
        )

    @app.route("/notifications/read-all", methods=["POST"])
    def notifications_mark_all_read():
        actor = account_from_session()
        if actor is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        uid = directory_user_id_for_account(actor)
        visible = visible_project_ids_for_account(actor)
        vis = _notification_visible_filter(uid=uid, visible=visible)
        if vis is None:
            return jsonify({"ok": True})
        for r in Notification.query.filter(vis, Notification.is_read.is_(False)).all():
            r.is_read = True
        db.session.commit()
        return jsonify({"ok": True})

    def _notification_mutate_field_result(
        notification_id: int, field_name: str
    ) -> tuple[Response, int] | None:
        """Apply read/ack/resolve mutation. Returns ``None`` on success, else ``(jsonify, status)``."""
        actor = account_from_session()
        if actor is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        n = db.session.get(Notification, notification_id)
        if n is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        if not _notification_row_may_mutate(actor, n, field_name=field_name):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if field_name == "is_acknowledged":
            n.is_acknowledged = True
            n.is_read = True
            if (n.type or "").strip().lower() == "activity":
                n.is_resolved = True
        elif field_name == "is_resolved":
            n.is_resolved = True
            n.is_read = True
        elif field_name == "is_read":
            n.is_read = True
        else:
            return jsonify({"ok": False, "error": "invalid"}), 400
        db.session.commit()
        return None

    def _notification_mark_field(notification_id: int, field_name: str):
        err = _notification_mutate_field_result(notification_id, field_name)
        if err is not None:
            return err
        return jsonify({"ok": True})

    @app.route("/notifications/read/<int:notification_id>", methods=["POST"])
    def notifications_mark_read(notification_id: int):
        return _notification_mark_field(notification_id, "is_read")

    @app.route("/notifications/ack/<int:notification_id>", methods=["POST"])
    def notifications_ack(notification_id: int):
        return _notification_mark_field(notification_id, "is_acknowledged")

    @app.route("/notifications/resolve/<int:notification_id>", methods=["POST"])
    def notifications_resolve(notification_id: int):
        return _notification_mark_field(notification_id, "is_resolved")

