    @app.route("/machine/project/<int:project_id>/hdd/add-shooting-day", methods=["POST"])
    def machine_hdd_add_shooting_day(project_id: int):
        """Create a shooting day (same model as production) and link it to a project HDD in one step."""
        actor = account_from_session()
        if actor is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if not account_may_use_machine_project_view(actor):
            return jsonify({"ok": False, "error": "forbidden"}), 403

        data = request.get_json(silent=True) or {}
        action = (data.get("action") or "create_link").strip().lower()
        if action not in ("create_link", "start_copy"):
            action = "create_link"
        start_copy = action == "start_copy"
        copy_mins: int | None = None
        if start_copy:
            try:
                copy_mins = int(data.get("copy_time_minutes"))
            except (TypeError, ValueError):
                copy_mins = None
            if copy_mins is None or copy_mins < 1:
                return jsonify({"ok": False, "error": "invalid_copy_time"}), 400
            assign_uid = directory_user_id_for_account(actor)
            if assign_uid is None:
                return jsonify({"ok": False, "error": "no_directory_user"}), 400

        try:
            volume_id = int(data.get("volume_id") or 0)
        except (TypeError, ValueError):
            volume_id = 0
        try:
            disk_id = int(data.get("disk_id") or 0)
        except (TypeError, ValueError):
            disk_id = 0

        vol = None
        hd = None
        storage_label = ""
        if volume_id > 0:
            vol = db.session.get(StorageVolume, volume_id)
            if vol is None:
                return jsonify({"ok": False, "error": "volume_not_found"}), 404
            link = StorageVolumeProjectLink.query.filter_by(
                volume_id=int(vol.id), project_id=int(p.id)
            ).first()
            if link is None:
                return jsonify({"ok": False, "error": "volume_not_linked"}), 404
            storage_label = (vol.display_name or vol.name or "volume").strip()
        elif disk_id > 0:
            hd = db.session.get(HardDisk, disk_id)
            if hd is None or hd.project_id != p.id:
                return jsonify({"ok": False, "error": "disk_not_found"}), 404
            storage_label = (hd.name or "disk").strip()
        else:
            return jsonify({"ok": False, "error": "invalid_disk"}), 400

        try:
            unit_number = int(data.get("unit_number"))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid_unit"}), 400
        if unit_number < 1:
            return jsonify({"ok": False, "error": "invalid_unit"}), 400

        day_name = (data.get("day_name") or "").strip()
        if not day_name:
            return jsonify({"ok": False, "error": "day_name_required"}), 400
        if len(day_name) > 50:
            return jsonify({"ok": False, "error": "day_name_too_long"}), 400

        raw_date = (data.get("shooting_date") or "").strip()
        try:
            sd = datetime.strptime(raw_date, "%Y-%m-%d").date()
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid_date"}), 400

        try:
            video_tb = float(data.get("video_size_tb") or 0)
            audio_gb = float(data.get("audio_size_gb") or 0)
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid_sizes"}), 400
        if video_tb < 0 or audio_gb < 0:
            return jsonify({"ok": False, "error": "invalid_sizes"}), 400
        audio_tb = audio_gb / HDD_STORAGE_GB_PER_TB
        notes = (data.get("notes") or "").strip()
        destination_path = (data.get("destination_path") or "").strip()[:512]
        checksum_method = (data.get("checksum_method") or "").strip()[:32]
        checksum_status = (data.get("checksum_status") or "").strip()[:32]
        make_critical = bool(data.get("make_critical"))
        if make_critical and not notes:
            return jsonify({"ok": False, "error": "critical_note_required"}), 400
        if make_critical and len(notes) > 20_000:
            return jsonify({"ok": False, "error": "critical_note_too_long"}), 400

        if not start_copy:
            meta_lines: list[str] = []
            if destination_path:
                meta_lines.append(f"Destination: {destination_path}")
            if checksum_method:
                meta_lines.append(f"Checksum method: {checksum_method}")
            if checksum_status:
                meta_lines.append(f"Checksum status: {checksum_status}")
            if meta_lines:
                suffix = "\n".join(meta_lines)
                notes = f"{notes}\n\n{suffix}".strip() if notes else suffix

        existing_used = 0.0
        cap = 0.0
        if vol is not None:
            existing_used = sum(
                float(u.video_size_tb or 0) + float(u.audio_size_tb or 0)
                for u in StorageVolumeShootingDayUsage.query.filter_by(volume_id=int(vol.id)).all()
            )
            cap = float(vol.capacity_tb or 0)
        else:
            existing_used = sum(
                float(u.video_size_tb or 0) + float(u.audio_size_tb or 0)
                for u in HardDiskUsage.query.filter_by(hard_disk_id=hd.id).all()
            )
            cap = float(hd.capacity_tb or 0)
        if cap > 0 and existing_used + video_tb + audio_tb > cap + 1e-9:
            return jsonify({"ok": False, "error": "over_capacity"}), 400

        day = ShootingDay(
            project_id=p.id,
            unit_number=unit_number,
            day_name=day_name[:50],
            shooting_date=sd,
        )
        p.lifecycle_status = "post_production"
        db.session.add(day)
        db.session.flush()
        if vol is not None:
            usage = StorageVolumeShootingDayUsage(
                volume_id=int(vol.id),
                shooting_day_id=day.id,
                video_size_tb=video_tb,
                audio_size_tb=audio_tb,
                notes=notes,
            )
        else:
            usage = HardDiskUsage(
                hard_disk_id=hd.id,
                shooting_day_id=day.id,
                video_size_tb=video_tb,
                audio_size_tb=audio_tb,
                notes=notes,
            )
        db.session.add(usage)
        db.session.flush()
        if make_critical:
            crit = ShootingDayCriticalNote(
                shooting_day_id=day.id,
                body=notes,
                created_by_user_id=directory_user_id_for_account(actor),
            )
            db.session.add(crit)
            db.session.flush()
            emit_shooting_day_critical_created(crit, day, actor=actor)
        copy_task_id: int | None = None
        pname = (p.name or "").strip() or "Project"
        if start_copy:
            if ProjectMember.query.filter_by(project_id=p.id, user_id=assign_uid).first() is None:
                db.session.add(ProjectMember(project_id=p.id, user_id=assign_uid))
            dm_gid = task_group_id_for_post_scope("needs_mastering_delivery")
            starter = db.session.get(User, assign_uid)
            starter_label = (starter.name or "").strip() if starter is not None else actor.display_name
            copy_task = Task(
                title="Copy Material",
                description="",
                user_id=int(assign_uid),
                group_id=dm_gid,
                project_id=p.id,
                status="open",
                priority="high",
                copy_started_at=_utc_now(),
                copy_estimated_minutes=int(copy_mins),
                copy_day_name=day_name[:80],
                copy_unit_number=int(unit_number),
            )
            db.session.add(copy_task)
            db.session.flush()
            copy_task_id = int(copy_task.id)
            import project_activity_hooks as pah

            pah.log_media_started(
                project_id=p.id,
                kind="copy",
                task_id=copy_task_id,
                day_label=day_name[:80],
                unit_number=int(unit_number),
                started_at=copy_task.copy_started_at,
                metadata={
                    "source_volume": storage_label,
                    "destination_volume": (getattr(vol, "name", None) or "") if vol is not None else "",
                    "destination_path": destination_path,
                    "estimated_minutes": int(copy_mins) if copy_mins else None,
                    "shooting_day_id": int(day.id),
                },
            )
            _notify_machine_project_team(
                project_id=p.id,
                rule=f"copy_task_started|{copy_task_id}",
                title=f"{pname} · Copy task started",
                message=(
                    f"{starter_label} created shooting day {day_name[:80]} (Unit {unit_number}) "
                    f"and started copying from {storage_label}."
                ),
                entity_type="task",
                entity_id=copy_task_id,
                actor=actor,
            )
            est_h, est_m = divmod(max(0, int(copy_mins)), 60)
            batch = MediaIngestBatch(
                project_id=p.id,
                shooting_day_id=day.id,
                shooting_day_label=day_name[:120],
                batch_name=f"Day {day_name[:50]} · Unit {unit_number}"[:160],
                unit_number=unit_number,
                shoot_date=sd,
                destination_volume_id=int(vol.id) if vol is not None else None,
                destination_path=destination_path,
                status="copying",
                checksum_method=checksum_method,
                checksum_status=checksum_status,
                copied_by_account_id=int(actor.id),
                copy_started_at=_utc_now(),
                notes=notes,
                video_size_tb=video_tb if video_tb > 0 else None,
                audio_size_gb=audio_gb if audio_gb > 0 else None,
                estimated_copy_time=f"{est_h:02d}:{est_m:02d}",
                notes_critical=make_critical,
                has_primary_copy=True,
            )
            machine_room_dashboard_support_mod.sync_ingest_batch_backup(batch)
            db.session.add(batch)
        try:
            if not start_copy:
                emit_shooting_day_created_activity(day, "machine", actor=actor)
                import project_activity_hooks as pah

                pah.log_shooting_day_created(day, source="machine")
            db.session.commit()
        except sa_exc.IntegrityError:
            db.session.rollback()
            return jsonify({"ok": False, "error": "conflict"}), 409
        if hd is not None:
            evaluate_hdd_notifications(hd.id, actor=actor)
            db.session.commit()
        else:
            db.session.commit()
        emit_tasks_feed_changed(p.id)
        out: dict = {"ok": True}
        if start_copy:
            out["copy_started"] = True
            out["task_id"] = copy_task_id
        return jsonify(out)

    @app.route("/machine/project/<int:project_id>/hard-disks/<int:disk_id>/usage", methods=["POST"])
    def machine_project_hard_disk_usage_add(project_id: int, disk_id: int):
        actor = account_from_session()
        if actor is None:
            abort(403)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("machine_room"))
        if not account_may_use_machine_project_view(actor):
            abort(403)
        hd = db.session.get(HardDisk, disk_id)
        if hd is None or hd.project_id != p.id:
            flash("Hard disk not found.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        raw_day = (request.form.get("shooting_day_id") or "").strip()
        try:
            shooting_day_id = int(raw_day)
        except (TypeError, ValueError):
            flash("Select a shooting day.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        day = shooting_day_in_project(shooting_day_id, p.id)
        if day is None:
            flash("That shooting day is not on this project.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        try:
            video_tb = float((request.form.get("video_size_tb") or "0").strip() or 0)
            audio_gb = float((request.form.get("audio_size_gb") or "0").strip() or 0)
        except (TypeError, ValueError):
            flash("Video and audio sizes must be numbers.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        if video_tb < 0 or audio_gb < 0:
            flash("Sizes cannot be negative.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        audio_tb = audio_gb / HDD_STORAGE_GB_PER_TB
        notes = (request.form.get("notes") or "").strip()
        existing_used = sum(
            float(u.video_size_tb or 0) + float(u.audio_size_tb or 0)
            for u in HardDiskUsage.query.filter_by(hard_disk_id=hd.id).all()
        )
        cap = float(hd.capacity_tb or 0)
        if existing_used + video_tb + audio_tb > cap + 1e-9:
            flash("Video plus audio would exceed this disk capacity.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        usage = HardDiskUsage(
            hard_disk_id=hd.id,
            shooting_day_id=day.id,
            video_size_tb=video_tb,
            audio_size_tb=audio_tb,
            notes=notes,
        )
        db.session.add(usage)
        try:
            db.session.flush()
        except sa_exc.IntegrityError:
            db.session.rollback()
            flash("That shooting day is already linked to this disk.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        db.session.commit()
        evaluate_hdd_notifications(hd.id, actor=actor)
        db.session.commit()
        flash("Shooting day linked to disk.", "success")
        return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))

    @app.route(
        "/machine/project/<int:project_id>/hard-disks/<int:disk_id>/usage/<int:usage_id>/delete",
        methods=["POST"],
    )
    def machine_project_hard_disk_usage_delete(project_id: int, disk_id: int, usage_id: int):
        actor = account_from_session()
        if actor is None:
            abort(403)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("machine_room"))
        if not account_may_use_machine_project_view(actor):
            abort(403)
        hd = db.session.get(HardDisk, disk_id)
        if hd is None or hd.project_id != p.id:
            flash("Hard disk not found.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        row = db.session.get(HardDiskUsage, usage_id)
        if row is None or row.hard_disk_id != hd.id:
            flash("That link was not found.", "error")
            return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))
        db.session.delete(row)
        db.session.commit()
        evaluate_hdd_notifications(hd.id, actor=actor)
        db.session.commit()
        flash("Shooting day unlinked from disk.", "success")
        return redirect(url_for("project_machine_room_hdd_media", project_id=project_id))

    @app.route(
        "/machine/project/<int:project_id>/hard-disks/<int:disk_id>/usage/<int:usage_id>/update",
        methods=["POST"],
    )
    def machine_project_hard_disk_usage_update(
        project_id: int, disk_id: int, usage_id: int
    ):
        """Update video/audio sizes for a linked shooting day on a disk."""
        actor = account_from_session()
        if actor is None:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if not account_may_use_machine_project_view(actor):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        hd = db.session.get(HardDisk, disk_id)
        if hd is None or hd.project_id != p.id:
            return jsonify({"ok": False, "error": "disk_not_found"}), 404
        row = db.session.get(HardDiskUsage, usage_id)
        if row is None or row.hard_disk_id != hd.id:
            return jsonify({"ok": False, "error": "usage_not_found"}), 404

        data = request.get_json(silent=True) or {}
        if not data and request.form:
            data = {
                "video_size_tb": request.form.get("video_size_tb"),
                "audio_size_gb": request.form.get("audio_size_gb"),
            }
        try:
            video_tb = float((data.get("video_size_tb") if data.get("video_size_tb") is not None else "0"))
            audio_gb = float((data.get("audio_size_gb") if data.get("audio_size_gb") is not None else "0"))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid_sizes"}), 400
        if video_tb < 0 or audio_gb < 0:
            return jsonify({"ok": False, "error": "negative_sizes"}), 400
        audio_tb = audio_gb / HDD_STORAGE_GB_PER_TB
        other_used = sum(
            float(u.video_size_tb or 0) + float(u.audio_size_tb or 0)
            for u in HardDiskUsage.query.filter_by(hard_disk_id=hd.id).all()
            if int(u.id) != int(row.id)
        )
        cap = float(hd.capacity_tb or 0)
        if other_used + video_tb + audio_tb > cap + 1e-9:
            return jsonify({"ok": False, "error": "capacity_exceeded"}), 400
        row.video_size_tb = video_tb
        row.audio_size_tb = audio_tb
        db.session.commit()
        evaluate_hdd_notifications(hd.id, actor=actor)
        db.session.commit()
        return jsonify(
            {
                "ok": True,
                "video_tb": video_tb,
                "audio_gb": audio_gb,
            }
        )

    @app.route("/machine/project/<int:project_id>/volumes/<int:volume_id>/usage", methods=["POST"])
    def machine_project_volume_usage_add(project_id: int, volume_id: int):
        actor = account_from_session()
        wants_json = (
            request.headers.get("X-Requested-With") == "XMLHttpRequest"
            or request.accept_mimetypes.best == "application/json"
        )

        def _fail(error: str, status: int = 400):
            if wants_json:
                return jsonify({"ok": False, "error": error}), status
            flash(error.replace("_", " ").capitalize() + ".", "error")
            return redirect(
                url_for("project_machine_room", project_id=project_id, tab="volumes")
            )

        if actor is None:
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden"}), 403
            abort(403)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden"}), 403
            flash("You do not have access to that project.", "error")
            return redirect(url_for("machine_room"))
        if not account_may_use_machine_project_view(actor):
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden"}), 403
            abort(403)
        vol = db.session.get(StorageVolume, volume_id)
        if vol is None:
            return _fail("volume_not_found", 404)
        if StorageVolumeProjectLink.query.filter_by(volume_id=int(vol.id), project_id=int(p.id)).first() is None:
            return _fail("volume_not_linked", 404)
        raw_day = (request.form.get("shooting_day_id") or "").strip()
        try:
            shooting_day_id = int(raw_day)
        except (TypeError, ValueError):
            return _fail("shooting_day_required")
        day = shooting_day_in_project(shooting_day_id, p.id)
        if day is None:
            return _fail("shooting_day_not_found")
        try:
            video_tb = float((request.form.get("video_size_tb") or "0").strip() or 0)
            audio_gb = float((request.form.get("audio_size_gb") or "0").strip() or 0)
        except (TypeError, ValueError):
            return _fail("invalid_sizes")
        if video_tb < 0 or audio_gb < 0:
            return _fail("negative_sizes")
        audio_tb = audio_gb / HDD_STORAGE_GB_PER_TB
        notes = (request.form.get("notes") or "").strip()
        existing_used = sum(
            float(u.video_size_tb or 0) + float(u.audio_size_tb or 0)
            for u in StorageVolumeShootingDayUsage.query.filter_by(volume_id=int(vol.id)).all()
        )
        cap = float(vol.capacity_tb or 0)
        if cap > 0 and existing_used + video_tb + audio_tb > cap + 1e-9:
            return _fail("capacity_exceeded")
        usage = StorageVolumeShootingDayUsage(
            volume_id=int(vol.id),
            shooting_day_id=day.id,
            video_size_tb=video_tb,
            audio_size_tb=audio_tb,
            notes=notes,
        )
        db.session.add(usage)
        try:
            db.session.flush()
        except sa_exc.IntegrityError:
            db.session.rollback()
            return _fail("already_linked", 409)
        db.session.commit()
        if wants_json:
            return jsonify({"ok": True})
        flash("Shooting day linked to volume.", "success")
        return redirect(url_for("project_machine_room", project_id=project_id, tab="volumes"))

