    @app.route("/projects/new", methods=["POST"])
    def projects_create():
        from project_settings import (
            POST_SCOPE_REQUIRED_MSG,
            any_post_scope_selected,
            post_scope_from_form,
        )

        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_create_projects(actor):
            flash("Only administrators, super users, and producers can create projects.", "error")
            return redirect(url_for("projects_list"))
        post_scope = post_scope_from_form(request.form)
        if not any_post_scope_selected(post_scope):
            flash(POST_SCOPE_REQUIRED_MSG, "error")
            return redirect(url_for("projects_list"))
        name = (request.form.get("name") or "").strip()
        project_type = (request.form.get("project_type") or "").strip()
        production_house = (request.form.get("production_house") or "").strip()
        director = (request.form.get("director") or "").strip()
        if not name or not project_type or not production_house or not director:
            flash("All fields are required.", "error")
            return redirect(url_for("projects_list"))

        create_token = (request.form.get("create_token") or "").strip()
        used_tokens = session.get("project_create_used_tokens") or {}
        if not isinstance(used_tokens, dict):
            used_tokens = {}
        if create_token and create_token in used_tokens:
            existing_id = used_tokens.get(create_token)
            flash("That project was already created.", "info")
            if existing_id:
                return redirect(url_for("project_settings", project_id=int(existing_id)))
            return redirect(url_for("projects_list"))
        expected_token = (session.get("project_create_form_token") or "").strip()
        if not create_token or not expected_token or create_token != expected_token:
            # Stale/double navigation — prefer existing same-name project if present.
            existing_same_name = (
                Project.query.filter(db.func.lower(Project.name) == name.lower())
                .order_by(Project.id.asc())
                .first()
            )
            if existing_same_name is not None:
                flash(
                    f'A project named “{existing_same_name.name}” already exists.',
                    "info",
                )
                return redirect(url_for("project_detail", project_id=existing_same_name.id))
            flash("Please create the project again from the New project dialog.", "error")
            return redirect(url_for("projects_list"))

        existing_same_name = (
            Project.query.filter(db.func.lower(Project.name) == name.lower())
            .order_by(Project.id.asc())
            .first()
        )
        if existing_same_name is not None:
            flash(
                f'A project named “{existing_same_name.name}” already exists. Open it instead of creating another.',
                "error",
            )
            return redirect(url_for("project_detail", project_id=existing_same_name.id))

        # Reserve this form token immediately so a second POST of the same form
        # cannot create another project while the first request is still committing.
        used_tokens[create_token] = None
        session["project_create_used_tokens"] = used_tokens
        session.modified = True

        try:
            number_of_episodes = max(0, int((request.form.get("number_of_episodes") or "0").strip() or 0))
        except (TypeError, ValueError):
            number_of_episodes = 0
        if not _project_type_is_tv_series(project_type):
            number_of_episodes = 0
        try:
            estimated_shooting_days = max(
                0, int((request.form.get("estimated_shooting_days") or "0").strip() or 0)
            )
        except (TypeError, ValueError):
            estimated_shooting_days = 0
        try:
            estimated_episode_duration_minutes = max(
                0,
                int(
                    (request.form.get("estimated_episode_duration_minutes") or "0").strip() or 0
                ),
            )
        except (TypeError, ValueError):
            estimated_episode_duration_minutes = 0
        project_status = normalize_project_status(request.form.get("project_status"))
        mx = db.session.query(db.func.max(Project.sort_order)).scalar()
        next_ord = (mx if mx is not None else -1) + 1
        p = Project(
            name=name,
            project_type=project_type,
            production_house=production_house,
            director=director,
            sort_order=next_ord,
            number_of_episodes=number_of_episodes,
            estimated_shooting_days=estimated_shooting_days,
            estimated_episode_duration_minutes=estimated_episode_duration_minutes,
            project_status=project_status,
            **post_scope,
        )
        db.session.add(p)
        try:
            db.session.commit()
        except sa_exc.IntegrityError:
            db.session.rollback()
            used_tokens.pop(create_token, None)
            session["project_create_used_tokens"] = used_tokens
            existing_same_name = (
                Project.query.filter(db.func.lower(Project.name) == name.lower())
                .order_by(Project.id.asc())
                .first()
            )
            if existing_same_name is not None:
                flash(
                    f'A project named “{existing_same_name.name}” already exists. Open it instead of creating another.',
                    "error",
                )
                return redirect(url_for("project_detail", project_id=existing_same_name.id))
            flash("Could not create the project. Please try again.", "error")
            return redirect(url_for("projects_list"))

        used_tokens[create_token] = int(p.id)
        # Keep a short history so repeat POSTs of the same form cannot create again.
        if len(used_tokens) > 40:
            for old_key in list(used_tokens.keys())[:-20]:
                used_tokens.pop(old_key, None)
        session["project_create_used_tokens"] = used_tokens
        session.pop("project_create_form_token", None)

        ensure_project_main_audio_library(p.id)
        creator_uid = directory_user_id_for_account(actor)
        if creator_uid is not None:
            if ProjectMember.query.filter_by(project_id=p.id, user_id=creator_uid).first() is None:
                db.session.add(ProjectMember(project_id=p.id, user_id=creator_uid))
                db.session.commit()
        if _project_type_is_tv_series(p.project_type) and number_of_episodes > 0:
            ensure_production_episode_rows(p)
        flash("Project created.", "success")
        return redirect(url_for("project_settings", project_id=p.id))

    @app.route("/projects/reorder", methods=["POST"])
    def projects_reorder():
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not actor.is_admin:
            return jsonify({"ok": False, "error": "forbidden"}), 403
        data = request.get_json(silent=True) or {}
        raw_ids = data.get("project_ids")
        if not isinstance(raw_ids, list) or not raw_ids:
            return jsonify({"ok": False, "error": "invalid"}), 400
        try:
            id_list = [int(x) for x in raw_ids]
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid"}), 400
        all_ids = {p.id for p in Project.query.all()}
        if set(id_list) != all_ids or len(id_list) != len(all_ids):
            return jsonify({"ok": False, "error": "mismatch"}), 400
        for order, pid in enumerate(id_list):
            p = db.session.get(Project, pid)
            if p is not None:
                p.sort_order = order
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
            app.logger.exception("projects_reorder")
            return jsonify({"ok": False, "error": "save"}), 500
        return jsonify({"ok": True})

    def _exclude_user_from_team_picker(u: User) -> bool:
        """Omit admin accounts, Machine Room role, and literal Admin from add-member picker."""
        if (u.name or "").strip().lower() == "admin":
            return True
        if _directory_user_is_machine_room_role(int(u.id)):
            return True
        u_acc = u.account
        if u_acc is None:
            return False
        if u_acc.is_admin:
            return True
        if (u_acc.username or "").strip().lower() == "admin":
            return True
        return False

    def _load_project_team_page_data(p: Project, acc: Account | None = None) -> dict:
        from project_settings import (
            build_project_team_admin_warnings,
            collect_user_post_scope_keys,
            count_project_team_members_for_scope,
            group_project_team_by_post_scope,
            project_enabled_post_scope_fields,
        )
        import job_titles_master_support as jtms_team

        member_ids = {m.user_id for m in p.memberships}
        if member_ids:
            member_users = (
                User.query.options(
                    joinedload(User.job_title).joinedload(JobTitle.category),
                    joinedload(User.user_job_title_links)
                    .joinedload(UserJobTitle.job_title)
                    .joinedload(JobTitle.category),
                    joinedload(User.user_job_title_links)
                    .joinedload(UserJobTitle.job_title)
                    .joinedload(JobTitle.post_scope_links)
                    .joinedload(JobTitlePostScopeLink.post_scope_entry),
                    joinedload(User.user_job_title_links)
                    .joinedload(UserJobTitle.job_title)
                    .joinedload(JobTitle.category)
                    .joinedload(JobCategory.post_scope_links)
                    .joinedload(JobCategoryPostScopeLink.post_scope_entry),
                )
                .filter(User.id.in_(member_ids))
                .all()
            )
            member_users.sort(key=lambda u: u.name.lower())
        else:
            member_users = []
        member_team_scope_groups, member_post_coverage = group_project_team_by_post_scope(
            p, member_users
        )
        member_user_scope_keys = {
            int(u.id): sorted(collect_user_post_scope_keys(u)) for u in member_users
        }
        member_job_title_scope_chips = {
            int(u.id): jtms_team.job_title_eligible_scope_chips(u, SystemMasterEntry)
            for u in member_users
        }
        all_users = (
            User.query.options(
                joinedload(User.job_title).joinedload(JobTitle.category),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.category),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.post_scope_links)
                .joinedload(JobTitlePostScopeLink.post_scope_entry),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.category)
                .joinedload(JobCategory.post_scope_links)
                .joinedload(JobCategoryPostScopeLink.post_scope_entry),
                joinedload(User.account),
            )
            .order_by(User.name)
            .all()
        )
        # Disabled / suspended accounts must not be available for new membership selection.
        available_to_add = [
            u
            for u in all_users
            if u.id not in member_ids
            and not _exclude_user_from_team_picker(u)
            and (
                not getattr(u, "account_id", None)
                or getattr(u, "account", None) is None
                or account_approval_support_mod.account_may_use_app(getattr(u, "account", None))
            )
        ]
        available_user_scope_keys = {
            int(u.id): sorted(collect_user_post_scope_keys(u)) for u in available_to_add
        }
        available_job_title_scope_chips = {
            int(u.id): jtms_team.job_title_eligible_scope_chips(u, SystemMasterEntry)
            for u in available_to_add
        }
        import employment_structure_support as esup

        member_employment_policy = {
            int(u.id): esup.user_employment_policy_summary(
                db, SystemMasterEntry, EmploymentScopeLink, u, getattr(u, "account", None)
            )
            for u in member_users
        }
        available_employment_policy = {
            int(u.id): esup.user_employment_policy_summary(
                db, SystemMasterEntry, EmploymentScopeLink, u, getattr(u, "account", None)
            )
            for u in available_to_add
        }
        project_team_structure = []
        for key, label, _hint in project_enabled_post_scope_fields(p):
            eligible = jtms_team.get_users_eligible_for_post_scope(
                key,
                User=User,
                UserJobTitle=UserJobTitle,
                JobTitle=JobTitle,
                SystemMasterEntry=SystemMasterEntry,
                JobTitlePostScopeLink=JobTitlePostScopeLink,
                JobCategoryPostScopeLink=JobCategoryPostScopeLink,
                project_id=int(p.id),
                active_only=True,
            )
            project_team_structure.append(
                {
                    "scope_key": key,
                    "scope_label": label,
                    "eligible_count": len(eligible),
                    "member_count": count_project_team_members_for_scope(member_users, key),
                }
            )
        team_page_warnings: list[str] = []
        if acc and getattr(acc, "is_admin", False):
            team_page_warnings = build_project_team_admin_warnings(member_users)
        return {
            "member_users": member_users,
            "member_team_scope_groups": member_team_scope_groups,
            "member_post_coverage": member_post_coverage,
            "team_page_warnings": team_page_warnings,
            "member_user_scope_keys": member_user_scope_keys,
            "member_job_title_scope_chips": member_job_title_scope_chips,
            "available_to_add": available_to_add,
            "available_user_scope_keys": available_user_scope_keys,
            "available_job_title_scope_chips": available_job_title_scope_chips,
            "member_employment_policy": member_employment_policy,
            "available_employment_policy": available_employment_policy,
            "project_team_structure": project_team_structure,
        }

    @app.route("/projects/<int:project_id>")
    def project_detail(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        project_tasks_all = (
            Task.query.options(
                joinedload(Task.group), joinedload(Task.assignee), joinedload(Task.project)
            )
            .filter_by(project_id=p.id)
            .order_by(Task.created_at.desc())
            .all()
        )
        active_open = [
            t
            for t in project_tasks_all
            if not t.archived and t.status in ("open", "in_progress")
        ]
        active_tasks, request_tasks = partition_project_open_tasks(active_open)
        ga = app.extensions.get("guest_access") or {}
        if acc and ga.get("is_guest_user", lambda _a: False)(acc):
            active_tasks = []
            request_tasks = []

        member_ids = {m.user_id for m in p.memberships}
        if member_ids:
            member_users = (
                User.query.options(
                    joinedload(User.job_title),
                    joinedload(User.user_job_title_links).joinedload(UserJobTitle.job_title),
                )
                .filter(User.id.in_(member_ids))
                .all()
            )
            member_users.sort(key=lambda u: u.name.lower())
        else:
            member_users = []
        post_scope_fields, scope_groups, titles_by_group = load_post_scope_task_context()
        from project_settings import project_enabled_post_scope_fields

        post_scope_fields = project_enabled_post_scope_fields(p)
        has_title_presets = TaskGroupTitle.query.count() > 0
        user_project_ids: dict[int, list[int]] = defaultdict(list)
        for pm in ProjectMember.query.all():
            user_project_ids[pm.user_id].append(pm.project_id)
        production_episode_count = max(0, int(p.number_of_episodes or 0))
        todo_episodes = (
            ProductionEpisode.query.filter_by(project_id=p.id)
            .order_by(ProductionEpisode.episode_number.asc())
            .all()
        )
        todo_shooting_days = (
            ShootingDay.query.filter_by(project_id=p.id)
            .order_by(ShootingDay.shooting_date.asc(), ShootingDay.id.asc())
            .all()
        )
        todo_vfx_shots = (
            VfxShot.query.filter_by(project_id=p.id)
            .order_by(VfxShot.shot_code.asc())
            .limit(200)
            .all()
        )
        return render_template(
            "project_detail.html",
            project=p,
            active_tasks=active_tasks,
            request_tasks=request_tasks,
            member_users=member_users,
            post_scope_fields=post_scope_fields,
            scope_groups=scope_groups,
            titles_by_group=titles_by_group,
            has_title_presets=has_title_presets,
            user_project_ids=dict(user_project_ids),
            production_episode_count=production_episode_count,
            workflow_active="overview",
            todo_episodes=todo_episodes,
            todo_shooting_days=todo_shooting_days,
            todo_vfx_shots=todo_vfx_shots,
            todo_member_users=member_users,
            todo_mention_members=[
                {"id": int(u.id), "name": (u.name or "").strip()}
                for u in member_users
                if (u.name or "").strip()
            ],
        )

