    def _build_project_audio_tree_bootstrap(
        *,
        main_library_id: int | None,
        audio_libraries: list,
        linked_audio_folders: list,
    ) -> dict[str, object]:
        links_by_lib: dict[int, list[dict[str, object]]] = defaultdict(list)
        for link in linked_audio_folders:
            lib_id = int(link.library_id or 0)
            mount_name = (link.mount.name if link.mount else "Mount") or "Mount"
            links_by_lib[lib_id].append(
                {
                    "link_id": int(link.id),
                    "folder_path": link.folder_path or "",
                    "mount_id": int(link.mount_id or 0),
                    "mount_name": mount_name,
                }
            )
        for lib_id in list(links_by_lib.keys()):
            links_by_lib[lib_id].sort(
                key=lambda x: (
                    str(x.get("mount_name") or "").lower(),
                    str(x.get("folder_path") or "").lower(),
                )
            )
        libraries = [
            {
                "id": int(lib.id),
                "name": lib.name or "",
                "parent_id": int(lib.parent_id) if lib.parent_id else None,
                "links": links_by_lib.get(int(lib.id), []),
            }
            for lib in audio_libraries
        ]
        return {
            "main_library_id": int(main_library_id) if main_library_id else None,
            "libraries": libraries,
        }

    def _serialize_project_audio_files(rows) -> list[dict[str, object]]:
        out: list[dict[str, object]] = []
        for r in rows:
            name = r.name or ""
            ext = (r.type or "").strip().lower()
            if not ext and "." in name:
                ext = name.rsplit(".", 1)[-1].lower()
            mount = getattr(r, "mount", None)
            lib_type = "music"
            if mount is not None:
                lib_type = str(getattr(mount, "library_type", None) or "music").strip().lower() or "music"
            out.append(
                {
                    "id": int(r.id),
                    "name": name,
                    "file_path": r.file_path or "",
                    "folder": r.folder or "",
                    "mount_id": int(r.mount_id or 0),
                    "duration": float(r.duration or 0),
                    "color_tags": _music_parse_color_tags(r.color_tag),
                    "is_favorite": bool(r.is_favorite),
                    "type": ext,
                    "library_type": lib_type,
                }
            )
        return out

