    @app.route("/projects/<int:project_id>/production")
    def project_production(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        shooting_days = (
            ShootingDay.query.filter_by(project_id=p.id)
            .options(
                joinedload(ShootingDay.scene_rows),
                joinedload(ShootingDay.pipeline_scenes),
            )
            .order_by(
                ShootingDay.unit_number.asc(),
                ShootingDay.shooting_date.asc(),
                ShootingDay.id.asc(),
            )
            .all()
        )
        production_day_totals = {
            d.id: shooting_day_total_seconds(d) for d in shooting_days
        }
        production_day_progress = {
            d.id: shooting_day_sync_edit_percentages(d) for d in shooting_days
        }
        units_map: dict[int, list] = {}
        for d in shooting_days:
            units_map.setdefault(d.unit_number, []).append(d)

        def _day_sort_key(day):
            digits = "".join(ch for ch in (day.day_name or "") if ch.isdigit())
            num = int(digits) if digits else 0
            return (num, day.shooting_date, int(day.id or 0))

        production_units = [
            {"unit_number": unit_num, "days": sorted(days, key=_day_sort_key)}
            for unit_num, days in sorted(units_map.items(), key=lambda item: item[0])
        ]
        production_day_search = {
            d.id: shooting_day_search_index(d) for d in shooting_days
        }
        day_ids = [int(d.id) for d in shooting_days]
        production_day_hdd_labels: dict[int, list[str]] = defaultdict(list)
        if day_ids:
            for usage in (
                HardDiskUsage.query.options(joinedload(HardDiskUsage.hard_disk))
                .filter(HardDiskUsage.shooting_day_id.in_(day_ids))
                .order_by(HardDiskUsage.id)
                .all()
            ):
                hd = usage.hard_disk
                label = (hd.name or f"HDD {hd.id}") if hd else "HDD"
                sid = int(usage.shooting_day_id)
                if label not in production_day_hdd_labels[sid]:
                    production_day_hdd_labels[sid].append(label)
        return render_template(
            "project_production.html",
            project=p,
            production_section="days",
            shooting_days=shooting_days,
            production_units=production_units,
            production_day_totals=production_day_totals,
            production_day_progress=production_day_progress,
            production_day_search=production_day_search,
            production_day_hdd_labels=dict(production_day_hdd_labels),
            shooting_location_suggestions=shooting_day_location_suggestions(p.id),
            workflow_active="shooting",
            may_edit_production=(
                (app.extensions.get("guest_access") or {})
                .get("account_may_edit_production", lambda _a, _p: True)(acc, p.id)
                if acc
                else False
            ),
        )

    @app.route("/projects/<int:project_id>/production/day/<int:day_id>")
    def project_production_day(project_id: int, day_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        day = ShootingDay.query.filter_by(id=day_id, project_id=p.id).first()
        if day is None:
            abort(404)
        ordered_ids = (
            db.session.query(ShootingDay.id)
            .filter_by(project_id=p.id)
            .order_by(ShootingDay.shooting_date.asc(), ShootingDay.id.asc())
            .all()
        )
        id_list = [int(r[0]) for r in ordered_ids]
        day_display_index = id_list.index(day_id) + 1
        pipeline_links = ed.sort_shooting_day_pipeline_links_for_display(
            ShootingDayScene.query.filter_by(shooting_day_id=day.id)
            .order_by(ShootingDayScene.id.asc())
            .all()
        )
        shot_duration_seconds = sum(
            shooting_day_scene_duration_seconds(link)
            for link in pipeline_links
            if shooting_items_mod.counts_toward_shooting_day_shot_duration(link)
        )
        runtime_meta_by_id = {
            int(link.id): shooting_items_mod.runtime_row_display_meta(link, pipeline_links)
            for link in pipeline_links
        }
        is_tv_project = _project_type_is_tv_series(p.project_type)
        max_episode_number = max(0, int(p.number_of_episodes or 0)) if is_tv_project else 1
        item_stats = shooting_items_mod.shooting_day_item_stats(pipeline_links)
        progress_rows = [
            ln
            for ln in pipeline_links
            if shooting_items_mod.counts_toward_shooting_day_sync_edit(ln)
        ]
        total_items = len(progress_rows)
        if total_items:
            sync_done_n = sum(1 for ln in progress_rows if ln.sync_done)
            edit_done_n = sum(1 for ln in progress_rows if ln.first_edit_done)
            sync_percentage = int(round(100.0 * sync_done_n / total_items))
            edit_percentage = int(round(100.0 * edit_done_n / total_items))
        else:
            sync_percentage = 0
            edit_percentage = 0
        day_critical_open = (
            ShootingDayCriticalNote.query.filter(
                ShootingDayCriticalNote.shooting_day_id == day.id,
                ShootingDayCriticalNote.solved_at.is_(None),
            )
            .order_by(
                ShootingDayCriticalNote.is_critical.desc(),
                ShootingDayCriticalNote.created_at.desc(),
            )
            .all()
        )
        day_critical_solved = (
            ShootingDayCriticalNote.query.filter(
                ShootingDayCriticalNote.shooting_day_id == day.id,
                ShootingDayCriticalNote.solved_at.isnot(None),
            )
            .order_by(ShootingDayCriticalNote.solved_at.desc())
            .all()
        )
        critical_note_user_ids = {
            int(uid)
            for note in list(day_critical_open) + list(day_critical_solved)
            for uid in (
                note.created_by_user_id,
                note.updated_by_user_id,
                note.solved_by_user_id,
            )
            if uid is not None
        }
        critical_note_user_names = {
            uid: _directory_user_display_name(uid) for uid in critical_note_user_ids
        }
        return render_template(
            "project_production_day.html",
            project=p,
            production_section="days",
            production_day=day,
            day_display_index=day_display_index,
            pipeline_links=pipeline_links,
            shot_duration_seconds=shot_duration_seconds,
            runtime_meta_by_id=runtime_meta_by_id,
            max_episode_number=max_episode_number,
            total_items=total_items,
            scene_row_count=item_stats["scene_rows"],
            vfx_row_count=item_stats["vfx_rows"],
            sound_row_count=item_stats["sound_rows"],
            episode_x_item_count=item_stats["episode_x_items"],
            episode_x_scene_count=item_stats["episode_x_scenes"],
            episode_x_vfx_count=item_stats["episode_x_vfx"],
            episode_x_sound_count=item_stats["episode_x_sound"],
            sync_percentage=sync_percentage,
            edit_percentage=edit_percentage,
            is_tv_project=is_tv_project,
            shooting_item_types=shooting_items_mod.SHOOTING_ITEM_TYPES,
            shooting_sound_item_types=tuple(shooting_items_mod.SOUND_ITEM_TYPES),
            shooting_auto_vfx_item_types=tuple(shooting_items_mod.AUTO_VFX_ITEM_TYPES),
            workflow_active="shooting",
            day_critical_open=day_critical_open,
            day_critical_solved=day_critical_solved,
            critical_note_user_names=critical_note_user_names,
            shooting_location_suggestions=shooting_day_location_suggestions(p.id),
            vfx_item_by_scene_id=_vfx_item_ids_by_scene_id(p.id),
            may_edit_production=(
                (app.extensions.get("guest_access") or {})
                .get("account_may_edit_production", lambda _a, _p: True)(acc, p.id)
                if acc
                else False
            ),
        )

