    @app.route("/vfx-department/<int:project_id>/api/shots/<int:shot_id>", methods=["POST"])
    @app.route("/projects/<int:project_id>/vfx-department/api/shots/<int:shot_id>", methods=["POST"])
    def vfx_department_api_shot(project_id: int, shot_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_vfx_department_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        actor_uid = directory_user_id_for_account(acc)
        shot = VfxShot.query.filter_by(id=shot_id, project_id=project_id).first()
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        if not vfx_vendor_is_in_house(shot.vendor):
            return jsonify({"ok": False, "error": "not_in_department"}), 404
        if not _vfx_dept_viewer_may_edit_shot(acc, shot):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        data = request.get_json(silent=True) or {}
        if account_is_directory_vfx_artist_only(acc):
            for key in (
                "assigned_artist_user_id",
                "assigned_supervisor_user_id",
            ):
                data.pop(key, None)

        def log_act(action: str, detail: dict) -> None:
            db.session.add(
                VfxMgmtActivity(
                    project_id=project_id,
                    shot_id=int(shot.id),
                    user_id=actor_uid,
                    action=action,
                    detail=json.dumps(detail, ensure_ascii=False),
                    created_at=now_local(),
                )
            )

        old_mgmt = (getattr(shot, "mgmt_status", None) or "pending").strip().lower()
        old_artist = getattr(shot, "assigned_artist_user_id", None)

        if "mgmt_status" in data:
            st = str(data.get("mgmt_status") or "").strip().lower()
            if st not in VFX_MGMT_STATUSES:
                return jsonify({"ok": False, "error": "invalid_mgmt_status"}), 400
            force_transition = bool(acc and acc.is_admin)
            if not _vfx_mgmt_transition_allowed(
                old_mgmt, st, force=force_transition
            ):
                return (
                    jsonify(
                        {
                            "ok": False,
                            "error": "invalid_transition",
                            "from": old_mgmt,
                            "to": st,
                        }
                    ),
                    400,
                )
            if st != old_mgmt:
                log_act(
                    "mgmt_status",
                    {
                        "from": old_mgmt,
                        "to": st,
                        "forced": force_transition and st not in VFX_MGMT_TRANSITIONS.get(old_mgmt, frozenset()) and st != old_mgmt,
                    },
                )
            shot.mgmt_status = st
            if st == "blocked":
                shot.status = "blocked"
            elif old_mgmt == "blocked" and st != "blocked" and (shot.status or "").strip().lower() == "blocked":
                shot.status = "pending"
            if st == "delivered" and shot.sent_at is None:
                shot.sent_at = now_local()
        if "priority" in data:
            pr = str(data.get("priority") or "").strip().lower()
            if pr not in VFX_MGMT_PRIORITIES:
                return jsonify({"ok": False, "error": "invalid_priority"}), 400
            shot.priority = pr
            log_act("priority", {"to": pr})
        if "assigned_artist_user_id" in data:
            raw = data.get("assigned_artist_user_id")
            if raw in (None, "", 0, "0"):
                shot.assigned_artist_user_id = None
            else:
                try:
                    nid = int(raw)
                except (TypeError, ValueError):
                    return jsonify({"ok": False, "error": "invalid_artist"}), 400
                if not _vfx_user_can_assign_as_artist(project_id, nid):
                    return jsonify({"ok": False, "error": "artist_not_eligible"}), 400
                shot.assigned_artist_user_id = nid
            log_act(
                "assign_artist",
                {"to": shot.assigned_artist_user_id, "from": old_artist},
            )
        if "assigned_supervisor_user_id" in data:
            raw = data.get("assigned_supervisor_user_id")
            if raw in (None, "", 0, "0"):
                shot.assigned_supervisor_user_id = None
            else:
                try:
                    nid = int(raw)
                except (TypeError, ValueError):
                    return jsonify({"ok": False, "error": "invalid_supervisor"}), 400
                if not _vfx_user_can_assign_as_supervisor(project_id, nid):
                    return jsonify({"ok": False, "error": "supervisor_not_eligible"}), 400
                shot.assigned_supervisor_user_id = nid
            log_act("assign_supervisor", {"to": shot.assigned_supervisor_user_id})
        if "due_date" in data:
            raw = str(data.get("due_date") or "").strip()
            if not raw:
                shot.due_date = None
            else:
                try:
                    shot.due_date = date.fromisoformat(raw[:10])
                except ValueError:
                    return jsonify({"ok": False, "error": "invalid_due_date"}), 400
            log_act("due_date", {"to": raw})
        if "start_date" in data:
            raw = str(data.get("start_date") or "").strip()
            if not raw:
                shot.start_date = None
            else:
                try:
                    shot.start_date = date.fromisoformat(raw[:10])
                except ValueError:
                    return jsonify({"ok": False, "error": "invalid_start_date"}), 400
        if "estimated_days" in data:
            raw = data.get("estimated_days")
            if raw in (None, ""):
                shot.estimated_days = None
            else:
                try:
                    shot.estimated_days = max(0, min(3650, int(raw)))
                except (TypeError, ValueError):
                    return jsonify({"ok": False, "error": "invalid_estimated_days"}), 400
        if "depends_on_shot_id" in data:
            raw = data.get("depends_on_shot_id")
            if raw in (None, "", 0, "0"):
                shot.depends_on_shot_id = None
            else:
                try:
                    did = int(raw)
                except (TypeError, ValueError):
                    return jsonify({"ok": False, "error": "invalid_dependency"}), 400
                if did == int(shot.id):
                    return jsonify({"ok": False, "error": "self_dependency"}), 400
                dep = VfxShot.query.filter_by(id=did, project_id=project_id).first()
                if dep is None:
                    return jsonify({"ok": False, "error": "dependency_not_found"}), 400
                if not vfx_vendor_is_in_house(dep.vendor):
                    return jsonify({"ok": False, "error": "dependency_not_in_house"}), 400
                if _vfx_dependency_creates_cycle(project_id, int(shot.id), did):
                    return (
                        jsonify({"ok": False, "error": "dependency_cycle"}),
                        400,
                    )
                shot.depends_on_shot_id = did
            log_act("dependency", {"depends_on_shot_id": shot.depends_on_shot_id})
        if "delivery_notes" in data:
            notes = str(data.get("delivery_notes") or "").strip()
            if len(notes) > 20_000:
                return jsonify({"ok": False, "error": "notes_too_long"}), 400
            shot.delivery_notes = notes
            log_act("delivery_notes", {"len": len(notes)})

        na = getattr(shot, "assigned_artist_user_id", None)
        if na is not None and (old_artist is None or int(na) != int(old_artist)):
            _notify_vfx_dept_shot_assigned(
                project_id,
                shot,
                int(na),
                old_artist,
                assigned_by=acc,
            )

        new_mgmt = (shot.mgmt_status or "pending").strip().lower()
        if new_mgmt != old_mgmt:
            _notify_vfx_dept_shot_status_change(
                shot, old_mgmt=old_mgmt, new_mgmt=new_mgmt, actor=acc
            )

        db.session.commit()
        color_hooks = app.extensions.get("color_hooks") or {}
        on_vfx = color_hooks.get("on_vfx_shot_updated")
        if callable(on_vfx):
            try:
                on_vfx(shot)
                db.session.commit()
            except Exception:
                db.session.rollback()
        proj = Project.query.get(project_id)
        return jsonify(
            {"ok": True, "payload": build_vfx_department_payload(proj, viewer=acc)}
        )

    def _vfx_client_review_branding(raw: str | None) -> dict:
        try:
            data = json.loads(raw or "{}")
        except (TypeError, json.JSONDecodeError):
            data = {}
        if not isinstance(data, dict):
            data = {}
        accent = str(data.get("accentColor") or data.get("accent_color") or "#c9a227").strip()
        if not re.match(r"^#[0-9A-Fa-f]{6}$", accent):
            accent = "#c9a227"
        return {
            "logoUrl": str(data.get("logoUrl") or data.get("logo_url") or "").strip(),
            "coverUrl": str(data.get("coverUrl") or data.get("cover_url") or "").strip(),
            "accentColor": accent,
        }

    def _vfx_client_review_shot_ids(link: VfxClientReviewLink) -> list[int]:
        try:
            raw = json.loads(link.shot_ids_json or "[]")
        except (TypeError, json.JSONDecodeError):
            return []
        if not isinstance(raw, list):
            return []
        out: list[int] = []
        for x in raw:
            try:
                out.append(int(x))
            except (TypeError, ValueError):
                continue
        return out

    def _vfx_client_review_link_active(link: VfxClientReviewLink | None) -> bool:
        if link is None:
            return False
        if link.revoked_at is not None:
            return False
        if link.expires_at is not None and link.expires_at < now_local():
            return False
        return True

    def _vfx_client_review_link_by_token(token: str) -> VfxClientReviewLink | None:
        t = (token or "").strip()
        if not t or len(t) > 64:
            return None
        return VfxClientReviewLink.query.filter_by(token=t).first()

    def _vfx_client_review_media_url(token: str, image: str) -> str:
        raw = (image or "").strip()
        if not raw:
            return ""
        if _vfx_media_is_remote(raw):
            return raw
        return url_for("client_review_media", token=token, filename=raw)

    def _vfx_client_review_version_dict(
        token: str,
        project_id: int,
        ver: VfxVersion,
        rec: VideoMediaRecord | None,
        *,
        client_status: str,
    ) -> dict:
        orig = (ver.image or "").strip()
        is_video = _vfx_is_video_media(orig)
        if not is_video or _vfx_media_is_remote(orig):
            preview_url = _vfx_client_review_media_url(token, orig) if orig else ""
            return {
                "id": ver.id,
                "versionNumber": int(ver.version_number or 0),
                "versionLabel": f"v{int(ver.version_number or 0):03d}",
                "previewUrl": preview_url,
                "playbackUrl": preview_url,
                "originalMediaUrl": preview_url,
                "isVideo": is_video,
                "videoPreview": None,
                "previewBadge": "Original",
                "note": (ver.comment or "").strip(),
                "uploadedAt": isoformat_stored_instant(
                    ver.created_at if isinstance(ver.created_at, datetime) else None
                ),
                "uploader": "Studio",
                "status": client_status,
            }
        play_base = vp.playback_basename(rec, orig)
        play_url = _vfx_client_review_media_url(token, play_base) if play_base else ""
        orig_url = _vfx_client_review_media_url(token, orig)
        preview_json = vp.video_media_json(rec, playback_url=play_url, original_url=orig_url)
        return {
            "id": ver.id,
            "versionNumber": int(ver.version_number or 0),
            "versionLabel": f"v{int(ver.version_number or 0):03d}",
            "previewUrl": play_url or orig_url,
            "playbackUrl": play_url or orig_url,
            "originalMediaUrl": orig_url,
            "isVideo": True,
            "videoPreview": preview_json,
            "previewBadge": preview_json.get("previewBadge") or "Original",
            "note": (ver.comment or "").strip(),
            "uploadedAt": isoformat_stored_instant(
                ver.created_at if isinstance(ver.created_at, datetime) else None
            ),
            "uploader": "Studio",
            "status": client_status,
        }

    def _vfx_client_review_episode_reel_label(shot: VfxShot, project: Project) -> str:
        is_tv = _project_type_is_tv_series(project.project_type)
        ep = shot.episode_number
        reel = shot.reel_number
        if is_tv and ep is not None:
            return f"Episode {int(ep):02d}"
        if reel is not None:
            meta = _vfx_project_reel_meta(project)
            labels = meta.get("labels", {}) if isinstance(meta, dict) else {}
            lbl = labels.get(str(int(reel))) or labels.get(int(reel))
            if lbl:
                return f"Reel {lbl}"
            return f"Reel {int(reel):02d}"
        if ep is not None:
            return f"Episode {int(ep):02d}"
        return ""

    def _vfx_client_review_status_row(
        link: VfxClientReviewLink, shot_id: int
    ) -> VfxClientReviewShot | None:
        return VfxClientReviewShot.query.filter_by(link_id=link.id, shot_id=shot_id).first()

    def _vfx_client_review_set_status(
        link: VfxClientReviewLink, shot: VfxShot, status: str
    ) -> VfxClientReviewShot:
        st = (status or "").strip().lower()
        if st not in VFX_CLIENT_STATUSES:
            st = "waiting_review"
        row = _vfx_client_review_status_row(link, shot.id)
        if row is None:
            row = VfxClientReviewShot(
                link_id=link.id,
                shot_id=shot.id,
                sort_order=0,
                client_status=st,
            )
            db.session.add(row)
        else:
            row.client_status = st
        return row

    def _vfx_notify_client_review_action(
        *,
        project_id: int,
        shot: VfxShot,
        rule_suffix: str,
        title: str,
        message: str,
        severity: str = "info",
    ) -> None:
        _notification_emit_to_project(
            project_id=project_id,
            rule=f"vfx_client_{rule_suffix}_{shot.id}_{int(now_local().timestamp())}",
            n_type="info",
            severity=severity,
            title=title,
            message=message,
            entity_type="vfx_shot",
            entity_id=int(shot.id),
        )

    def build_client_review_payload(link: VfxClientReviewLink) -> dict:
        p = db.session.get(Project, link.project_id)
        if p is None:
            return {}
        token = link.token
        shot_ids = _vfx_client_review_shot_ids(link)
        if not shot_ids:
            rows = (
                VfxClientReviewShot.query.filter_by(link_id=link.id)
                .order_by(VfxClientReviewShot.sort_order.asc(), VfxClientReviewShot.id.asc())
                .all()
            )
            shot_ids = [int(r.shot_id) for r in rows]
        shots = (
            VfxShot.query.filter(VfxShot.id.in_(shot_ids), VfxShot.project_id == p.id)
            .options(joinedload(VfxShot.versions))
            .all()
        )
        shot_by_id = {int(s.id): s for s in shots}
        ordered: list[VfxShot] = []
        for sid in shot_ids:
            sh = shot_by_id.get(int(sid))
            if sh is not None:
                ordered.append(sh)
        status_rows = {
            int(r.shot_id): r
            for r in VfxClientReviewShot.query.filter_by(link_id=link.id).all()
        }
        comments = (
            VfxClientComment.query.filter_by(link_id=link.id)
            .order_by(VfxClientComment.created_at.asc(), VfxClientComment.id.asc())
            .all()
        )
        comments_by_shot: dict[int, list[dict]] = defaultdict(list)
        for c in comments:
            comments_by_shot[int(c.shot_id)].append(
                {
                    "id": c.id,
                    "shotId": c.shot_id,
                    "versionId": c.version_id,
                    "authorName": c.author_name or "Client",
                    "commentType": (c.comment_type or "general").strip().lower(),
                    "timeSeconds": float(c.time_seconds) if c.time_seconds is not None else None,
                    "timeLabel": _format_vfx_scene_timecode(c.time_seconds or 0)
                    if c.time_seconds is not None
                    else None,
                    "parentId": c.parent_id,
                    "body": c.body or "",
                    "createdAt": isoformat_stored_instant(c.created_at),
                }
            )
        approvals = (
            VfxClientApproval.query.filter_by(link_id=link.id)
            .order_by(VfxClientApproval.created_at.desc(), VfxClientApproval.id.desc())
            .all()
        )
        approvals_by_shot: dict[int, list[dict]] = defaultdict(list)
        for a in approvals:
            approvals_by_shot[int(a.shot_id)].append(
                {
                    "id": a.id,
                    "shotId": a.shot_id,
                    "versionId": a.version_id,
                    "authorName": a.author_name or "Client",
                    "action": (a.action or "approve").strip().lower(),
                    "note": a.note or "",
                    "createdAt": isoformat_stored_instant(a.created_at),
                }
            )
        branding = _vfx_client_review_branding(link.branding_json)
        cr_version_ids = [
            int(v.id) for sh in ordered for v in (sh.versions or [])
        ]
        cr_version_media = _video_media_records_for("vfx_version", cr_version_ids)
        shots_out: list[dict] = []
        for sh in ordered:
            versions = sorted(sh.versions or [], key=lambda v: int(v.version_number or 0))
            cv = max((int(v.version_number or 0) for v in versions), default=0)
            st_row = status_rows.get(int(sh.id))
            client_st = (
                (st_row.client_status if st_row else "waiting_review") or "waiting_review"
            ).strip().lower()
            if client_st not in VFX_CLIENT_STATUSES:
                client_st = "waiting_review"
            shots_out.append(
                {
                    "id": sh.id,
                    "shotCode": sh.shot_code,
                    "episodeReel": _vfx_client_review_episode_reel_label(sh, p),
                    "clientStatus": client_st,
                    "currentVersion": cv,
                    "versions": [
                        _vfx_client_review_version_dict(
                            token,
                            int(link.project_id),
                            v,
                            cr_version_media.get(int(v.id)),
                            client_status=client_st,
                        )
                        for v in versions
                    ],
                    "comments": comments_by_shot.get(int(sh.id), []),
                    "approvals": approvals_by_shot.get(int(sh.id), []),
                }
            )
        return {
            "token": token,
            "title": (link.title or "").strip() or "Review",
            "projectName": p.name or "Project",
            "branding": branding,
            "shots": shots_out,
            "annotationsEnabled": False,
        }

    def _vfx_client_review_shot_in_link(link: VfxClientReviewLink, shot_id: int) -> VfxShot | None:
        ids = set(_vfx_client_review_shot_ids(link))
        if not ids:
            ids = {
                int(r.shot_id)
                for r in VfxClientReviewShot.query.filter_by(link_id=link.id).all()
            }
        if int(shot_id) not in ids:
            return None
        return VfxShot.query.filter_by(id=shot_id, project_id=link.project_id).first()

    @app.route("/review/<token>", methods=["GET"])
    def client_review_page(token: str):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            return render_template("client_review.html", review_invalid=True, review_token=token), 403
        log_security_event(
            "public_token_access",
            entity_type="client_review_link",
            entity_id=int(link.id),
            project_id=int(link.project_id) if link.project_id else None,
            details={"route": "client_review_page"},
        )
        return render_template(
            "client_review.html",
            review_invalid=False,
            review_token=token,
            review_bootstrap=build_client_review_payload(link),
        )

