    @app.route("/review/<token>/media/<path:filename>", methods=["GET"])
    def client_review_media(token: str, filename: str):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            abort(403)
        if "/" in filename or "\\" in filename or ".." in filename or filename.startswith("."):
            abort(404)
        shot_ids = _vfx_client_review_shot_ids(link)
        if not shot_ids:
            shot_ids = [
                int(r.shot_id)
                for r in VfxClientReviewShot.query.filter_by(link_id=link.id).all()
            ]
        ver = (
            VfxVersion.query.join(VfxShot, VfxVersion.shot_id == VfxShot.id)
            .filter(
                VfxShot.project_id == link.project_id,
                VfxShot.id.in_(shot_ids),
                VfxVersion.image == filename,
            )
            .first()
        )
        if ver is not None:
            return send_from_directory(vfx_version_upload_root, filename)
        rec = VideoMediaRecord.query.filter_by(
            entity_type="vfx_version",
            upload_root="vfx_versions",
            preview_file_path=filename,
        ).first()
        if rec is not None:
            ver2 = (
                VfxVersion.query.join(VfxShot, VfxVersion.shot_id == VfxShot.id)
                .filter(
                    VfxShot.project_id == link.project_id,
                    VfxShot.id.in_(shot_ids),
                    VfxVersion.id == rec.entity_id,
                )
                .first()
            )
            if ver2 is not None:
                return send_from_directory(vfx_version_upload_root, filename)
        abort(404)

    @app.route("/review/<token>/api/shots/<int:shot_id>/status", methods=["POST"])
    def client_review_api_shot_status(token: str, shot_id: int):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            return jsonify({"ok": False, "error": "invalid_or_expired"}), 403
        shot = _vfx_client_review_shot_in_link(link, shot_id)
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        st = str(data.get("client_status") or "client_reviewing").strip().lower()
        if st not in VFX_CLIENT_STATUSES:
            st = "client_reviewing"
        row = _vfx_client_review_set_status(link, shot, st)
        if st == "client_reviewing" and (shot.mgmt_status or "").strip().lower() == "client_review":
            pass
        elif st == "client_reviewing":
            shot.mgmt_status = "client_review"
        db.session.commit()
        return jsonify(
            {
                "ok": True,
                "clientStatus": row.client_status,
                "payload": build_client_review_payload(link),
            }
        )

    @app.route("/review/<token>/api/shots/<int:shot_id>/comments", methods=["POST"])
    def client_review_api_comment_add(token: str, shot_id: int):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            return jsonify({"ok": False, "error": "invalid_or_expired"}), 403
        shot = _vfx_client_review_shot_in_link(link, shot_id)
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        body = (data.get("body") or "").strip()
        if not body:
            return jsonify({"ok": False, "error": "empty_body"}), 400
        if len(body) > 20_000:
            return jsonify({"ok": False, "error": "body_too_long"}), 400
        author = (data.get("author_name") or data.get("authorName") or "Client").strip()[:120] or "Client"
        ctype = str(data.get("comment_type") or data.get("commentType") or "general").strip().lower()
        if ctype not in VFX_CLIENT_COMMENT_TYPES:
            ctype = "general"
        time_seconds: float | None = None
        if ctype == "frame":
            raw_t = data.get("time_seconds", data.get("timeSeconds"))
            try:
                time_seconds = max(0.0, float(raw_t))
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "time_required"}), 400
        raw_vid = data.get("version_id", data.get("versionId"))
        version_id: int | None = None
        if raw_vid is not None and str(raw_vid).strip() != "":
            try:
                version_id = int(raw_vid)
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "invalid_version"}), 400
            ver = VfxVersion.query.filter_by(id=version_id, shot_id=shot.id).first()
            if ver is None:
                return jsonify({"ok": False, "error": "invalid_version"}), 400
        parent_id = data.get("parent_id", data.get("parentId"))
        pid: int | None = None
        if parent_id is not None and str(parent_id).strip() != "":
            try:
                pid = int(parent_id)
            except (TypeError, ValueError):
                pid = None
            if pid is not None:
                parent = VfxClientComment.query.filter_by(id=pid, link_id=link.id, shot_id=shot.id).first()
                if parent is None:
                    return jsonify({"ok": False, "error": "invalid_parent"}), 400
        row = VfxClientComment(
            link_id=link.id,
            shot_id=shot.id,
            version_id=version_id,
            author_name=author,
            comment_type=ctype,
            time_seconds=time_seconds,
            parent_id=pid,
            body=body,
            created_at=now_local(),
        )
        db.session.add(row)
        _vfx_client_review_set_status(link, shot, "client_reviewing")
        if (shot.mgmt_status or "").strip().lower() not in ("approved", "delivered"):
            shot.mgmt_status = "client_review"
        db.session.flush()
        _vfx_notify_client_review_action(
            project_id=int(link.project_id),
            shot=shot,
            rule_suffix=f"comment_{row.id}",
            title=f"Client comment: {shot.shot_code}",
            message=f"{author} left a note on {shot.shot_code}.",
        )
        db.session.commit()
        return jsonify(
            {
                "ok": True,
                "comment": {
                    "id": row.id,
                    "shotId": shot.id,
                    "versionId": version_id,
                    "authorName": author,
                    "commentType": ctype,
                    "timeSeconds": time_seconds,
                    "timeLabel": _format_vfx_scene_timecode(time_seconds or 0)
                    if time_seconds is not None
                    else None,
                    "parentId": pid,
                    "body": body,
                    "createdAt": isoformat_stored_instant(row.created_at),
                },
                "payload": build_client_review_payload(link),
            }
        )

    @app.route("/review/<token>/api/shots/<int:shot_id>/approval", methods=["POST"])
    def client_review_api_approval(token: str, shot_id: int):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            return jsonify({"ok": False, "error": "invalid_or_expired"}), 403
        shot = _vfx_client_review_shot_in_link(link, shot_id)
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        action = str(data.get("action") or "").strip().lower()
        if action not in VFX_CLIENT_APPROVAL_ACTIONS:
            return jsonify({"ok": False, "error": "invalid_action"}), 400
        author = (data.get("author_name") or data.get("authorName") or "Client").strip()[:120] or "Client"
        note = (data.get("note") or "").strip()[:5000]
        raw_vid = data.get("version_id", data.get("versionId"))
        version_id: int | None = None
        if raw_vid is not None and str(raw_vid).strip() != "":
            try:
                version_id = int(raw_vid)
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "invalid_version"}), 400
            ver = VfxVersion.query.filter_by(id=version_id, shot_id=shot.id).first()
            if ver is None:
                return jsonify({"ok": False, "error": "invalid_version"}), 400
        row = VfxClientApproval(
            link_id=link.id,
            shot_id=shot.id,
            version_id=version_id,
            author_name=author,
            action=action,
            note=note,
            created_at=now_local(),
        )
        db.session.add(row)
        if action == "approve":
            _vfx_client_review_set_status(link, shot, "approved")
            shot.status = "approved"
            shot.mgmt_status = "approved"
            title = f"Client approved: {shot.shot_code}"
            message = f"{author} approved {shot.shot_code}."
            severity = "info"
        else:
            _vfx_client_review_set_status(link, shot, "changes_requested")
            shot.status = "review"
            shot.mgmt_status = "review"
            title = f"Changes requested: {shot.shot_code}"
            message = f"{author} requested changes on {shot.shot_code}."
            severity = "warning"
        db.session.flush()
        _vfx_notify_client_review_action(
            project_id=int(link.project_id),
            shot=shot,
            rule_suffix=f"approval_{row.id}",
            title=title,
            message=message,
            severity=severity,
        )
        db.session.commit()
        return jsonify({"ok": True, "payload": build_client_review_payload(link)})

    @app.route("/review/<token>/export", methods=["GET"])
    def client_review_export(token: str):
        link = _vfx_client_review_link_by_token(token)
        if not _vfx_client_review_link_active(link):
            return jsonify({"ok": False, "error": "invalid_or_expired"}), 403
        payload = build_client_review_payload(link)
        lines: list[str] = [
            f"# {payload.get('projectName', 'Project')} — {payload.get('title', 'Review')}",
            "",
        ]
        for sh in payload.get("shots") or []:
            lines.append(f"## {sh.get('shotCode', 'Shot')}")
            lines.append(f"Status: {sh.get('clientStatus', '')}")
            if sh.get("episodeReel"):
                lines.append(f"Context: {sh.get('episodeReel')}")
            lines.append("")
            for c in sh.get("comments") or []:
                tl = c.get("timeLabel")
                prefix = f"[{tl}] " if tl else ""
                lines.append(f"- {prefix}{c.get('authorName')}: {c.get('body')}")
            for a in sh.get("approvals") or []:
                act = "Approved" if a.get("action") == "approve" else "Changes requested"
                lines.append(f"- {act} by {a.get('authorName')} at {a.get('createdAt')}")
                if a.get("note"):
                    lines.append(f"  Note: {a.get('note')}")
            lines.append("")
        text = "\n".join(lines).strip() + "\n"
        safe = re.sub(r"[^A-Za-z0-9._-]+", "_", (payload.get("title") or "review")).strip("_") or "review"
        return Response(
            text,
            mimetype="text/plain; charset=utf-8",
            headers={"Content-Disposition": f'attachment; filename="{safe}_notes.txt"'},
        )

