    @app.route("/projects/<int:project_id>/vfx/items/create", methods=["POST"])
    def project_vfx_item_create(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        data = request.get_json(silent=True) or {}
        try:
            episode_number = int(data.get("episode_number", 0))
        except (TypeError, ValueError):
            return jsonify({"ok": False, "error": "invalid_episode"}), 400
        display_name = str(data.get("display_name") or "").strip()
        item_type = str(data.get("item_type") or "scene").strip().lower()
        raw_ids = data.get("included_scene_ids") or []
        if not isinstance(raw_ids, list):
            return jsonify({"ok": False, "error": "invalid_payload"}), 400
        included_ids: list[int] = []
        for raw in raw_ids:
            try:
                included_ids.append(int(raw))
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "invalid_scene_id"}), 400
        if not included_ids:
            return jsonify({"ok": False, "error": "included_scenes_required"}), 400
        user_id = directory_user_id_for_account(acc)
        models = _vfx_bridge_query_models()
        item, err = vfx_bridge_mod.create_vfx_item(
            db,
            models,
            project_id=p.id,
            episode_number=episode_number,
            display_name=display_name,
            item_type=item_type,
            included_scene_ids=included_ids,
            priority=str(data.get("priority") or "normal"),
            vendor=str(data.get("vendor") or "in_house"),
            description=str(data.get("notes") or data.get("description") or ""),
            created_by_id=user_id,
        )
        if err:
            return jsonify({"ok": False, "error": err}), 400
        db.session.commit()
        return jsonify({"ok": True, "itemId": int(item.id), "payload": build_vfx_editor_payload(p)})

