    @app.route("/projects/<int:project_id>/vfx/api/scenes/<int:scene_id>/shots/bulk", methods=["POST"])
    def project_vfx_api_scene_bulk_shots(project_id: int, scene_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        scene = shooting_day_scene_for_project(scene_id, project_id)
        if scene is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        start_n = max(1, int(data.get("start") or 1))
        end_n = max(start_n, int(data.get("end") or 10))
        if end_n > 99:
            return jsonify({"ok": False, "error": "range_too_large"}), 400
        ep_num = max(1, int(scene.episode_number or 1))
        existing_nums = {int(s.shot_number) for s in (scene.vfx_shots or [])}
        cycle = list(VFX_DEPARTMENTS)
        created = 0
        for n in range(start_n, end_n + 1):
            if n in existing_nums:
                continue
            dep = cycle[(n - 1) % len(cycle)]
            try:
                shot_num, shot_code = _allocate_vfx_shot_identity(
                    project_id, scene, preferred_shot_number=n
                )
            except ValueError:
                return jsonify({"ok": False, "error": "shot_code_exhausted"}), 400
            sh = VfxShot(
                project_id=project_id,
                scene_id=scene.id,
                episode_number=ep_num,
                reel_number=None,
                shot_number=shot_num,
                shot_code=shot_code,
                shot_briefing="",
                department=dep,
                status="pending",
                created_at=now_local(),
            )
            _vfx_prepare_new_editor_shot(sh)
            db.session.add(sh)
            created += 1
        if created:
            _flag_scene_needs_vfx(scene)
        try:
            db.session.commit()
        except sa_exc.IntegrityError:
            db.session.rollback()
            return jsonify({"ok": False, "error": "shot_code_conflict"}), 409
        return jsonify(
            {"ok": True, "created": created, "payload": build_vfx_editor_payload(Project.query.get(project_id))}
        )

    @app.route("/projects/<int:project_id>/vfx/api/scenes/<int:scene_id>/markers", methods=["POST"])
    def project_vfx_api_scene_marker_add(project_id: int, scene_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return jsonify({"ok": False, "error": "no_directory_user"}), 403
        scene = shooting_day_scene_for_project(scene_id, project_id)
        if scene is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        n_existing = VfxSceneMarker.query.filter_by(scene_id=scene.id).count()
        if n_existing >= VFX_SCENE_MARKER_MAX_PER_SCENE:
            return jsonify({"ok": False, "error": "too_many_markers"}), 400

        def _decode_data_url_image(data_url: str) -> tuple[bytes, str]:
            m = re.match(r"^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$", data_url, re.DOTALL)
            if not m:
                raise ValueError("invalid_image_data")
            mime = (m.group(1) or "").lower()
            ext_map = {"image/png": ".png", "image/jpeg": ".jpg", "image/jpg": ".jpg", "image/webp": ".webp"}
            ext = ext_map.get(mime, "")
            if not ext or ext not in VFX_VERSION_ALLOWED_EXT:
                raise ValueError("unsupported_format")
            try:
                raw = base64.b64decode(m.group(2), validate=True)
            except Exception as exc:
                raise ValueError("invalid_image_data") from exc
            return raw, ext

        raw_full: bytes = b""
        raw_thumb: bytes = b""
        tsec = 0.0
        comment = ""
        legacy_single_file = False
        legacy_ext = ".jpg"

        ct = (request.content_type or "").lower()
        if "multipart/form-data" in ct:
            try:
                tsec = float((request.form.get("time_seconds") or "0").strip() or 0)
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "invalid_time"}), 400
            comment = (request.form.get("comment") or "").strip()
            fp = request.files.get("image_full")
            tp = request.files.get("image_thumb")
            if not fp or not tp:
                return jsonify({"ok": False, "error": "image_pair_required"}), 400
            raw_full = fp.read() or b""
            raw_thumb = tp.read() or b""
        else:
            data = request.get_json(silent=True) or {}
            try:
                tsec = float(data.get("time_seconds", 0))
            except (TypeError, ValueError):
                return jsonify({"ok": False, "error": "invalid_time"}), 400
            comment = str(data.get("comment") or "").strip()
            thumb_url = str(data.get("image_thumb_data") or "").strip()
            image_data = str(data.get("image_data") or "").strip()
            try:
                if thumb_url and image_data:
                    raw_full, _ = _decode_data_url_image(image_data)
                    raw_thumb, _ = _decode_data_url_image(thumb_url)
                elif image_data:
                    raw_thumb, legacy_ext = _decode_data_url_image(image_data)
                    legacy_single_file = True
                else:
                    return jsonify({"ok": False, "error": "image_required"}), 400
            except ValueError as e:
                err = str(e)
                if err == "unsupported_format":
                    return jsonify({"ok": False, "error": "unsupported_format"}), 400
                return jsonify({"ok": False, "error": "invalid_image_data"}), 400

        if tsec < 0 or tsec > 86400 * 7:
            return jsonify({"ok": False, "error": "invalid_time"}), 400
        if len(comment) > 20_000:
            return jsonify({"ok": False, "error": "comment_too_long"}), 400
        if _vfx_scene_has_marker_at_time(scene.id, tsec):
            return jsonify({"ok": False, "error": "marker_time_exists"}), 409

        if legacy_single_file:
            if len(raw_thumb) > VFX_VERSION_MAX_BYTES:
                return jsonify({"ok": False, "error": "file_too_large"}), 400
            fname = f"smark-{scene.id}-{uuid.uuid4().hex}{legacy_ext}"
            dest = os.path.join(vfx_version_upload_root, fname)
            try:
                with open(dest, "wb") as f:
                    f.write(raw_thumb)
            except OSError:
                return jsonify({"ok": False, "error": "save_failed"}), 500
            row = VfxSceneMarker(
                scene_id=scene.id,
                time_seconds=tsec,
                thumbnail=fname,
                thumbnail_full="",
                comment=comment,
                created_by_user_id=uid,
                created_at=now_local(),
            )
            db.session.add(row)
            db.session.commit()
            return jsonify(
                {
                    "ok": True,
                    "markerId": row.id,
                    "payload": build_vfx_editor_payload(Project.query.get(project_id)),
                }
            )

        if len(raw_full) > VFX_VERSION_MAX_BYTES or len(raw_thumb) > VFX_SCENE_MARKER_THUMB_MAX_BYTES:
            return jsonify({"ok": False, "error": "file_too_large"}), 400

        stem = uuid.uuid4().hex[:16]
        full_fname = f"sc{scene.id}_marker_{stem}_full.jpg"
        thumb_fname = f"sc{scene.id}_marker_{stem}_thumb.jpg"
        try:
            with open(os.path.join(vfx_version_upload_root, full_fname), "wb") as ff:
                ff.write(raw_full)
            with open(os.path.join(vfx_version_upload_root, thumb_fname), "wb") as tf:
                tf.write(raw_thumb)
        except OSError:
            remove_vfx_version_file(full_fname)
            remove_vfx_version_file(thumb_fname)
            return jsonify({"ok": False, "error": "save_failed"}), 500

        row = VfxSceneMarker(
            scene_id=scene.id,
            time_seconds=tsec,
            thumbnail=thumb_fname,
            thumbnail_full=full_fname,
            comment=comment,
            created_by_user_id=uid,
            created_at=now_local(),
        )
        db.session.add(row)
        db.session.commit()
        return jsonify(
            {
                "ok": True,
                "markerId": row.id,
                "payload": build_vfx_editor_payload(Project.query.get(project_id)),
            }
        )

