    @app.route("/projects/<int:project_id>/vfx/api/markers/<int:marker_id>/delete", methods=["POST"])
    def project_vfx_api_scene_marker_delete(project_id: int, marker_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        row = (
            VfxSceneMarker.query.join(ShootingDayScene, VfxSceneMarker.scene_id == ShootingDayScene.id)
            .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
            .filter(VfxSceneMarker.id == marker_id, ShootingDay.project_id == project_id)
            .first()
        )
        if row is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        thumb = (row.thumbnail or "").strip()
        fullp = (getattr(row, "thumbnail_full", None) or "").strip()
        seen: set[str] = set()
        for t in (thumb, fullp):
            if t and not _vfx_media_is_remote(t) and t not in seen:
                seen.add(t)
                remove_vfx_version_file(t)
        db.session.delete(row)
        db.session.commit()
        return jsonify({"ok": True, "payload": build_vfx_editor_payload(Project.query.get(project_id))})

    @app.route("/projects/<int:project_id>/vfx/api/markers/<int:marker_id>/create-shot", methods=["POST"])
    def project_vfx_api_marker_create_shot(project_id: int, marker_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        row = (
            VfxSceneMarker.query.join(ShootingDayScene, VfxSceneMarker.scene_id == ShootingDayScene.id)
            .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
            .filter(VfxSceneMarker.id == marker_id, ShootingDay.project_id == project_id)
            .first()
        )
        if row is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        scene = row.scene
        if scene is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        if getattr(row, "created_shot_id", None):
            return jsonify({"ok": False, "error": "marker_shot_exists"}), 409
        data = request.get_json(silent=True) or {}
        dep = str(data.get("department") or "animation").strip().lower()
        if dep not in VFX_DEPARTMENTS:
            return jsonify({"ok": False, "error": "invalid_department"}), 400
        src_full = (getattr(row, "thumbnail_full", None) or "").strip()
        src_thumb = (row.thumbnail or "").strip()
        src_key = src_full if src_full and not _vfx_media_is_remote(src_full) else src_thumb
        if not src_key or _vfx_media_is_remote(src_key):
            return jsonify({"ok": False, "error": "no_thumbnail"}), 400
        src_path = _vfx_local_media_path(src_key, "version")
        if not src_path:
            return jsonify({"ok": False, "error": "thumbnail_missing"}), 400
        ep_num = max(1, int(scene.episode_number or 1))
        try:
            shot_num, shot_code = _allocate_vfx_shot_identity(project_id, scene)
        except ValueError:
            return jsonify({"ok": False, "error": "shot_code_exhausted"}), 400
        shot = VfxShot(
            project_id=project_id,
            scene_id=scene.id,
            episode_number=ep_num,
            reel_number=None,
            shot_number=shot_num,
            shot_code=shot_code,
            shot_briefing="",
            department=dep,
            status="pending",
            created_at=now_local(),
        )
        _vfx_prepare_new_editor_shot(shot)
        db.session.add(shot)
        _flag_scene_needs_vfx(scene)
        try:
            db.session.flush()
        except sa_exc.IntegrityError:
            db.session.rollback()
            return jsonify({"ok": False, "error": "shot_code_conflict"}), 409
        ext = os.path.splitext(src_key)[1].lower() or ".jpg"
        if ext not in {".jpg", ".jpeg", ".png", ".webp", ".gif"}:
            ext = ".jpg"
        new_fname = f"ref{shot.id}-{uuid.uuid4().hex}{ext}"
        dest = os.path.join(vfx_version_upload_root, new_fname)
        try:
            shutil.copy2(src_path, dest)
        except OSError:
            db.session.rollback()
            return jsonify({"ok": False, "error": "copy_failed"}), 500
        shot.shot_ref_frame = new_fname
        note = (row.comment or "").strip()
        tc = _format_vfx_scene_timecode(float(row.time_seconds or 0))
        if note:
            shot.shot_briefing = note + "\n\n" + f"Scene marker @ {tc}"
        else:
            shot.shot_briefing = f"Scene marker @ {tc}"
        row.created_shot_id = shot.id
        try:
            db.session.commit()
        except sa_exc.IntegrityError:
            db.session.rollback()
            return jsonify({"ok": False, "error": "shot_code_conflict"}), 409
        payload = build_vfx_editor_payload(Project.query.get(project_id))
        return jsonify({"ok": True, "shotId": shot.id, "payload": payload})

    def _vfx_create_shot_version_from_request(
        shot: VfxShot,
    ) -> tuple[VfxVersion | None, str | None, int, int | None]:
        """Parse upload from the current request and stage a new VfxVersion row (no commit)."""
        image = ""
        comment = ""
        preview_record_id: int | None = None
        upload_orig_name = ""
        upload_size = 0
        file_part = request.files.get("image_file") or request.files.get("file")
        if file_part and (file_part.filename or "").strip():
            orig = secure_filename(file_part.filename) or "version"
            ext = os.path.splitext(orig)[1].lower()
            if ext not in VFX_VERSION_ALLOWED_EXT:
                return None, "unsupported_format", 400, None
            raw = file_part.read()
            if len(raw) > VFX_VERSION_MAX_BYTES:
                return None, "file_too_large", 400, None
            fname = f"vfx{shot.id}-{uuid.uuid4().hex}{ext}"
            dest = os.path.join(vfx_version_upload_root, fname)
            try:
                with open(dest, "wb") as f:
                    f.write(raw)
            except OSError:
                return None, "save_failed", 500, None
            image = fname
            upload_orig_name = orig
            upload_size = len(raw)
            comment = (request.form.get("comment") or "").strip()
        if not image and request.is_json:
            body = request.get_json(silent=True) or {}
            image = (body.get("image") or "").strip()
            comment = (body.get("comment") or "").strip()
        elif not image:
            image = (request.form.get("image") or "").strip()
            comment = (request.form.get("comment") or "").strip()
        if not image:
            return None, "image_required", 400, None
        if len(comment) > 20_000:
            return None, "comment_too_long", 400, None
        next_version = (
            db.session.query(func.max(VfxVersion.version_number)).filter(VfxVersion.shot_id == shot.id).scalar()
        )
        ver = VfxVersion(
            shot_id=shot.id,
            version_number=max(0, int(next_version or 0)) + 1,
            image=image,
            comment=comment,
            created_at=now_local(),
        )
        db.session.add(ver)
        db.session.flush()
        if upload_orig_name and _vfx_is_video_media(image):
            preview_record_id = _register_vfx_version_video_preview(
                ver,
                original_filename=upload_orig_name,
                file_size_bytes=upload_size,
            )
        return ver, None, 200, preview_record_id

    @app.route("/projects/<int:project_id>/vfx/api/shots/<int:shot_id>/versions", methods=["POST"])
    def project_vfx_api_add_version(project_id: int, shot_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        shot = VfxShot.query.filter_by(id=shot_id, project_id=project_id).first()
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        # Once a shot is in the department, version uploads must respect the
        # same artist/supervisor scope as /vfx-department/.../versions —
        # otherwise an artist could upload to other artists' shots through
        # the back door.
        if _vfx_shot_is_in_department(shot) and not _vfx_dept_viewer_may_edit_shot(
            acc, shot
        ):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        ver, err, status, preview_rid = _vfx_create_shot_version_from_request(shot)
        if err:
            return jsonify({"ok": False, "error": err}), status
        db.session.commit()
        _enqueue_video_preview(preview_rid)
        resp = {"ok": True, "payload": build_vfx_editor_payload(Project.query.get(project_id))}
        if preview_rid is not None and ver is not None:
            vp_st = _video_preview_status_json(project_id, "vfx_version", int(ver.id))
            if vp_st:
                resp["videoPreview"] = vp_st
                resp["uploadMessage"] = "Video uploaded. Creating web preview…"
        return jsonify(resp)

    @app.route("/vfx-department/<int:project_id>/api/shots/<int:shot_id>/versions", methods=["POST"])
    @app.route("/projects/<int:project_id>/vfx-department/api/shots/<int:shot_id>/versions", methods=["POST"])
    def vfx_department_api_add_version(project_id: int, shot_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_vfx_department_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        actor_uid = directory_user_id_for_account(acc)
        shot = VfxShot.query.filter_by(id=shot_id, project_id=project_id).first()
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        if not vfx_vendor_is_in_house(shot.vendor):
            return jsonify({"ok": False, "error": "not_in_department"}), 404
        if not _vfx_dept_viewer_may_edit_shot(acc, shot):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        ver, err, status, preview_rid = _vfx_create_shot_version_from_request(shot)
        if err:
            return jsonify({"ok": False, "error": err}), status
        if actor_uid is not None:
            db.session.add(
                VfxMgmtActivity(
                    project_id=project_id,
                    shot_id=int(shot.id),
                    user_id=actor_uid,
                    action="version_upload",
                    detail=json.dumps(
                        {"versionNumber": int(ver.version_number or 0)},
                        ensure_ascii=False,
                    ),
                    created_at=now_local(),
                )
            )
        db.session.commit()
        _enqueue_video_preview(preview_rid)
        resp = {
            "ok": True,
            "versionId": int(ver.id),
            "payload": build_vfx_department_payload(
                Project.query.get(project_id), viewer=acc
            ),
        }
        if preview_rid is not None:
            vp_st = _video_preview_status_json(project_id, "vfx_version", int(ver.id))
            if vp_st:
                resp["videoPreview"] = vp_st
                resp["uploadMessage"] = "Video uploaded. Creating web preview…"
        return jsonify(resp)

    @app.route(
        "/projects/<int:project_id>/vfx/api/shots/<int:shot_id>/versions/<int:version_id>/delete",
        methods=["POST"],
    )
    def project_vfx_api_delete_version(project_id: int, shot_id: int, version_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        shot = VfxShot.query.filter_by(id=shot_id, project_id=project_id).first()
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        ver = VfxVersion.query.filter_by(id=version_id, shot_id=shot.id).first()
        if ver is None:
            return jsonify({"ok": False, "error": "version_not_found"}), 404
        top_ids = [
            int(c.id)
            for c in VfxShotComment.query.filter(VfxShotComment.version_id == ver.id).all()
        ]
        if top_ids:
            VfxShotComment.query.filter(VfxShotComment.parent_id.in_(top_ids)).delete(
                synchronize_session=False
            )
            VfxShotComment.query.filter(VfxShotComment.id.in_(top_ids)).delete(
                synchronize_session=False
            )
        img = (ver.image or "").strip()
        _delete_video_media_record("vfx_version", int(ver.id))
        if img and not _vfx_media_is_remote(img):
            remove_vfx_version_file(img)
        db.session.delete(ver)
        db.session.commit()
        return jsonify({"ok": True, "payload": build_vfx_editor_payload(Project.query.get(project_id))})

    @app.route("/projects/<int:project_id>/vfx/api/shots/<int:shot_id>/comments", methods=["POST"])
    def project_vfx_api_shot_comment_add(project_id: int, shot_id: int):
        """Post a message into the shot's flat discussion thread.

        Comments are now a simple shot-level discussion (no per-version
        scoping, no reply threads, no resolve actions). Legacy
        `version_id` and `parent_id` are still accepted for
        backwards-compatibility but no longer required.
        """
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        uid = directory_user_id_for_account(acc)
        if uid is None:
            return jsonify({"ok": False, "error": "no_directory_user"}), 403
        shot = VfxShot.query.filter_by(id=shot_id, project_id=project_id).first()
        if shot is None:
            return jsonify({"ok": False, "error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        body = (data.get("body") or "").strip()
        if not body:
            return jsonify({"ok": False, "error": "empty_body"}), 400
        if len(body) > 20_000:
            return jsonify({"ok": False, "error": "body_too_long"}), 400

        version_id: int | None = None
        raw_vid = data.get("version_id")
        if raw_vid not in (None, "", 0, "0"):
            try:
                version_id = int(raw_vid)
            except (TypeError, ValueError):
                version_id = None
            if version_id is not None:
                ver = VfxVersion.query.filter_by(
                    id=version_id, shot_id=shot.id
                ).first()
                if ver is None:
                    version_id = None  # ignore stale version reference

        row = VfxShotComment(
            shot_id=shot.id,
            version_id=version_id,
            user_id=uid,
            parent_id=None,
            body=body,
            resolved=False,
            created_at=now_local(),
        )
        db.session.add(row)
        db.session.commit()
        u = db.session.get(User, uid)
        comment_out = {
            "id": row.id,
            "versionId": getattr(row, "version_id", None),
            "userId": uid,
            "userName": (u.name if u else "Unknown"),
            "body": row.body,
            "parentId": None,
            "resolved": False,
            "createdAt": isoformat_stored_instant(row.created_at),
        }
        return jsonify({"ok": True, "comment": comment_out})

