    def _episode_pie_css(done_count: int, total: int, done_color: str, pending_color: str) -> str | None:
        if total <= 0:
            return None
        done_deg = max(0, min(360, round(360 * done_count / total)))
        if done_deg <= 0:
            return f"conic-gradient({pending_color} 0deg 360deg)"
        if done_deg >= 360:
            return f"conic-gradient({done_color} 0deg 360deg)"
        return (
            f"conic-gradient({done_color} 0deg {done_deg}deg, "
            f"{pending_color} {done_deg}deg 360deg)"
        )

    def calculate_editorial_episode_scene_set(
        project: Project, episode_number: int, *, production_rows: list | None = None
    ) -> dict:
        """Single source of truth for the EDITORIAL membership of an episode.

        A scene's *effective editorial episode* is decided ONLY by its active
        PRIMARY assignment (SceneEditorialAssignment.is_primary)::

            effective_editorial_episode =
                active_primary_assignment.editorial_episode_number
                if an active primary assignment exists
                else production_episode  (ShootingDayScene.episode_number)

        So episode N's editorial cut = production scenes whose effective episode
        is still N (no primary move, or a primary pointing back to N) PLUS scenes
        from other production episodes whose active primary points to N.

        An assignment merely *existing* is NOT proof the scene moved away — only
        an active PRIMARY pointing to a DIFFERENT episode removes it. Non-primary
        (reuse / flashback / recap) assignments never affect this membership.

        Production data is never modified. Both the Episode List cards and the
        Episode Detail page consume this so their runtime / scene count / VFX /
        progress figures always match. Pass ``production_rows`` (the scenes whose
        production episode == N) to avoid a re-query when the caller has them.
        """
        ep = int(episode_number)
        if production_rows is None:
            production_rows = (
                ShootingDayScene.query.options(
                    joinedload(ShootingDayScene.shooting_day),
                    selectinload(ShootingDayScene.vfx_shots).selectinload(VfxShot.versions),
                    selectinload(ShootingDayScene.vfx_shots).selectinload(
                        VfxShot.assigned_artist
                    ),
                )
                .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
                .filter(
                    ShootingDay.project_id == int(project.id),
                    ShootingDayScene.episode_number == ep,
                    ShootingDayScene.is_episode_unassigned.is_(False),
                    ShootingDayScene.is_establishing_shots_pool.is_(False),
                )
                .all()
            )
        prod_ids = [int(s.id) for s in production_rows]
        # Effective editorial episode for each production scene = its active
        # PRIMARY assignment target (shared resolver — same rule the VFX portal
        # uses via get_effective_editorial_episode).
        primary_target = _active_primary_editorial_targets(prod_ids)
        # A scene leaves this episode ONLY when its active primary points to a
        # different episode. A primary pointing back to N keeps it here.
        reassigned_ids = {sid for sid, tgt in primary_target.items() if tgt != ep}
        used_in_map: dict[int, list[int]] = defaultdict(list)
        for sid, tgt in primary_target.items():
            if tgt != ep:
                used_in_map[sid].append(tgt)
        retained = [s for s in production_rows if int(s.id) not in reassigned_ids]
        # Scenes moved IN from OTHER production episodes (active primary -> ep).
        assigned_in_ids: list[int] = []
        assigned_in_reason: dict[int, str] = {}
        for a in (
            SceneEditorialAssignment.query.filter_by(
                project_id=int(project.id),
                editorial_episode_number=ep,
                is_active=True,
                is_primary=True,
            )
            .order_by(
                SceneEditorialAssignment.added_at.desc(),
                SceneEditorialAssignment.id.desc(),
            )
            .all()
        ):
            sid = int(a.scene_id)
            if sid not in assigned_in_reason:
                assigned_in_ids.append(sid)
                assigned_in_reason[sid] = a.reason or ""
        prod_id_set = set(prod_ids)
        assigned_in = []
        if assigned_in_ids:
            fetched = {
                int(s.id): s
                for s in ShootingDayScene.query.options(
                    joinedload(ShootingDayScene.shooting_day),
                    selectinload(ShootingDayScene.vfx_shots).selectinload(VfxShot.versions),
                    selectinload(ShootingDayScene.vfx_shots).selectinload(
                        VfxShot.assigned_artist
                    ),
                )
                .filter(ShootingDayScene.id.in_(assigned_in_ids))
                .all()
            }
            for sid in assigned_in_ids:
                s = fetched.get(sid)
                if s is None:
                    continue
                # A scene whose production origin is already this episode is a
                # retained original, never an assigned-in — never double count.
                if _scene_production_episode_key(s) == ep or sid in prod_id_set:
                    continue
                assigned_in.append(s)
        rows = ed.sort_shooting_day_scenes_for_display(retained + assigned_in)
        return {
            "rows": rows,
            "retained": retained,
            "assigned_in": assigned_in,
            "assigned_in_ids": {int(s.id) for s in assigned_in},
            "assigned_in_reason": assigned_in_reason,
            "reassigned_ids": reassigned_ids,
            "used_in_map": used_in_map,
        }

    def build_editorial_episode_statistics(
        project: Project,
        episode_number: int,
        *,
        production_rows: list | None = None,
        membership: dict | None = None,
    ) -> dict:
        """SINGLE authoritative editorial statistics for one episode.

        This is the ONE calculation consumed by BOTH the Episode List cards
        (``project_episodes``) and the Episode Detail page
        (``_build_episode_detail_context``) so their scene count, runtime and
        VFX figures are always identical.

        Scene membership comes ONLY from the editorial relationship
        (``calculate_editorial_episode_scene_set`` -> active
        ``SceneEditorialAssignment`` rows). Production origin
        (``ShootingDayScene.episode_number``) is used only to seed the candidate
        set and is never modified. VFX totals are resolved from ACTIVE
        ``VfxSceneItemSource`` links for the current editorial scene ids, never
        from the (possibly stale) ``VfxSceneItem.episode_number``.

        Pass ``membership`` (a prior ``calculate_editorial_episode_scene_set``
        result) or ``production_rows`` to avoid re-querying.
        """
        ep = int(episode_number)
        if membership is None:
            membership = calculate_editorial_episode_scene_set(
                project, ep, production_rows=production_rows
            )
        rows = membership["rows"]
        scene_ids = [int(s.id) for s in rows]
        runtime_seconds = sum(
            shooting_day_scene_duration_seconds(r)
            for r in rows
            if shooting_items_mod.counts_toward_episode_runtime(r)
        )
        scene_count = shooting_items_mod.count_unique_real_scenes(rows)
        # Split the count: originals whose production origin is THIS episode and
        # are still here, versus scenes editorially moved IN from other episodes.
        original_scene_count = shooting_items_mod.count_unique_real_scenes(
            membership.get("retained") or []
        )
        assigned_scene_count = shooting_items_mod.count_unique_real_scenes(
            membership.get("assigned_in") or []
        )
        # VFX is derived ONLY from active source links for the CURRENT editorial
        # scene ids (never VfxSceneItem.episode_number, which may be stale after
        # a scene is editorially reassigned).
        vfx_item_ids: set[int] = set()
        scenes_with_vfx_ids: set[int] = set()
        if scene_ids:
            for sid, item_id in (
                db.session.query(
                    VfxSceneItemSource.shooting_day_scene_id,
                    VfxSceneItemSource.vfx_scene_item_id,
                )
                .filter(
                    VfxSceneItemSource.shooting_day_scene_id.in_(scene_ids),
                    VfxSceneItemSource.is_active.is_(True),
                )
                .all()
            ):
                scenes_with_vfx_ids.add(int(sid))
                if item_id is not None:
                    vfx_item_ids.add(int(item_id))
        vfx_item_count = 0
        if vfx_item_ids:
            vfx_item_count = VfxSceneItem.query.filter(
                VfxSceneItem.id.in_(vfx_item_ids),
                VfxSceneItem.is_active.is_(True),
            ).count()
        all_shots: list = []
        for r in rows:
            shots = r.vfx_shots or []
            if shots:
                all_shots.extend(shots)
                scenes_with_vfx_ids.add(int(r.id))
        vfx_shot_count = len(all_shots)
        pending_vfx_count = sum(1 for sh in all_shots if not ed.vfx_shot_is_terminal(sh))
        completed_vfx_count = vfx_shot_count - pending_vfx_count
        return {
            "scene_ids": scene_ids,
            "scene_count": int(scene_count),
            "original_scene_count": int(original_scene_count),
            "assigned_scene_count": int(assigned_scene_count),
            "runtime_seconds": int(runtime_seconds),
            "runtime_display": format_duration_day_total(runtime_seconds),
            "vfx_item_count": int(vfx_item_count),
            "scenes_with_vfx": len(scenes_with_vfx_ids),
            "vfx_shot_count": int(vfx_shot_count),
            "pending_vfx_count": int(pending_vfx_count),
            "completed_vfx_count": int(completed_vfx_count),
            "membership": membership,
        }

    def _log_editorial_stats_debug(source: str, project, episode_number, stats) -> None:
        """Dev-only parity logging (set EDITORIAL_STATS_DEBUG=1 to enable).

        Prints the scene ids / runtime / origins used by each call site so the
        Episode List and Episode Detail sets can be compared. Disabled by
        default so production logs stay quiet.
        """
        if not os.environ.get("EDITORIAL_STATS_DEBUG"):
            return
        try:
            mem = stats.get("membership") or {}
            mem_rows = mem.get("rows") or []
            app.logger.info(
                "[EDITORIAL-STATS %s] project=%s ep=%s scene_ids=%s runtime_seconds=%s "
                "scene_count=%s origins=%s used_in=%s vfx_items=%s vfx_shots=%s pending_vfx=%s",
                source,
                int(project.id),
                int(episode_number),
                stats.get("scene_ids"),
                stats.get("runtime_seconds"),
                stats.get("scene_count"),
                {int(r.id): _scene_production_episode_key(r) for r in mem_rows},
                {int(k): v for k, v in (mem.get("used_in_map") or {}).items()},
                stats.get("vfx_item_count"),
                stats.get("vfx_shot_count"),
                stats.get("pending_vfx_count"),
            )
        except Exception:  # pragma: no cover - logging must never break a page
            pass

    def _episode_dock_card_from_rows(
        rows: list,
        *,
        episode_number: int | None,
        project: Project,
        pe: ProductionEpisode | None = None,
        is_episode_x: bool = False,
        is_establishing_collection: bool = False,
    ) -> dict:
        _ts = sum(
            shooting_day_scene_duration_seconds(r)
            for r in rows
            if shooting_items_mod.counts_toward_episode_runtime(r)
        )
        episode_runtime_seconds = _ts
        total_duration = (_ts + 59) // 60 if _ts else 0
        reshoot_count = shooting_items_mod.count_reshoot_versions(rows)
        runtime_selection_needed = shooting_items_mod.episode_runtime_selection_needed(rows)
        if is_establishing_collection:
            shooting_n = len(rows)
            real_rows = []
        elif is_episode_x:
            shooting_n = shooting_items_mod.count_unique_real_scenes_on_day(
                rows, include_unassigned=True
            )
            real_rows = [
                r for r in rows if shooting_items_mod.counts_toward_shooting_day_sync_edit(r)
            ]
        else:
            real_rows = shooting_items_mod.real_scene_rows_for_episode_stats(rows)
            shooting_n = shooting_items_mod.count_unique_real_scenes(rows)
        real_row_count = len(real_rows)
        sync_done_n = sum(1 for r in real_rows if bool(r.sync_done))
        first_edit_done_n = sum(1 for r in real_rows if bool(r.first_edit_done))
        vfx_rows = [r for r in rows if bool(r.needs_vfx)]
        vfx_needs_n = len(vfx_rows)
        vfx_done_n = sum(1 for r in vfx_rows if _shooting_scene_vfx_done(r))
        script_file = ""
        script_original_name = ""
        if pe is not None:
            script_file = (pe.script_file or "").strip()
            script_original_name = (pe.script_original_name or "").strip()
            if script_file and not (pe.script_analysis_status or "").strip():
                run_script_analysis_for_episode(pe)
                try:
                    db.session.commit()
                except Exception:
                    db.session.rollback()
        script_n = int(pe.script_scene_count or 0) if pe else 0
        scenes_pie_css = None
        if script_n > 0 and shooting_n + script_n > 0:
            shoot_deg = max(0, min(360, round(360 * shooting_n / (shooting_n + script_n))))
            if shoot_deg <= 0:
                scenes_pie_css = "conic-gradient(rgba(91, 141, 239, 0.85) 0deg 360deg)"
            elif shoot_deg >= 360:
                scenes_pie_css = "conic-gradient(rgba(255, 255, 255, 0.95) 0deg 360deg)"
            else:
                scenes_pie_css = (
                    f"conic-gradient(rgba(255, 255, 255, 0.95) 0deg {shoot_deg}deg, "
                    f"rgba(91, 141, 239, 0.85) {shoot_deg}deg 360deg)"
                )
        sync_pie_css = _episode_pie_css(sync_done_n, real_row_count, "#e89550", "#1a1a1a")
        first_edit_pie_css = _episode_pie_css(
            first_edit_done_n, real_row_count, "#3d9a7a", "#1a1a1a"
        )
        if real_row_count > 0:
            if vfx_needs_n > 0:
                vfx_pie_css = _episode_pie_css(vfx_done_n, vfx_needs_n, "#3d9a7a", "#1a1a1a")
                vfx_done_pct = round(100 * vfx_done_n / vfx_needs_n)
            else:
                vfx_pie_css = "conic-gradient(#1a1a1a 0deg 360deg)"
                vfx_done_pct = 0
        else:
            vfx_pie_css = None
            vfx_done_pct = 0
        sync_done_pct = round(100 * sync_done_n / real_row_count) if real_row_count else 0
        first_edit_done_pct = (
            round(100 * first_edit_done_n / real_row_count) if real_row_count else 0
        )
        scenes_shoot_pct = (
            round(100 * shooting_n / (shooting_n + script_n))
            if script_n > 0 and shooting_n + script_n > 0
            else 0
        )
        combo_slides: list[dict[str, object]] = []
        if not is_establishing_collection:
            if sync_pie_css:
                combo_slides.append({"pct": sync_done_pct, "label": "SYNC", "ring": "sync"})
            if first_edit_pie_css:
                combo_slides.append({"pct": first_edit_done_pct, "label": "1ST", "ring": "edit"})
            if scenes_pie_css:
                combo_slides.append({"pct": scenes_shoot_pct, "label": "SHOOT", "ring": "shoot"})
        x_item_stats = (
            shooting_items_mod.shooting_day_item_stats(rows) if is_episode_x else None
        )
        return {
            "episode_number": episode_number,
            "is_episode_x": is_episode_x,
            "is_establishing_collection": is_establishing_collection,
            "scene_count": shooting_n,
            "original_scene_count": shooting_n,
            "assigned_scene_count": 0,
            "total_duration": total_duration,
            "episode_runtime_seconds": episode_runtime_seconds,
            "runtime_display": format_duration_day_total(episode_runtime_seconds),
            "reshoot_count": reshoot_count,
            "runtime_selection_needed": runtime_selection_needed,
            "sync_done": bool(real_rows) and sync_done_n == real_row_count,
            "sync_done_count": sync_done_n,
            "sync_done_pct": sync_done_pct,
            "sync_pie_css": sync_pie_css,
            "first_edit_done": bool(real_rows) and first_edit_done_n == real_row_count,
            "first_edit_done_count": first_edit_done_n,
            "first_edit_done_pct": first_edit_done_pct,
            "first_edit_pie_css": first_edit_pie_css,
            "vfx_done_count": vfx_done_n,
            "vfx_needs_count": vfx_needs_n,
            "vfx_done_pct": vfx_done_pct,
            "vfx_pie_css": vfx_pie_css,
            "scenes_pie_css": scenes_pie_css,
            "scenes_shoot_pct": scenes_shoot_pct,
            "combo_slides": combo_slides,
            "has_script": bool(script_file),
            "script_page_count": int(pe.script_page_count or 0) if pe else 0,
            "script_scene_count": int(pe.script_scene_count or 0) if pe else 0,
            "script_analysis_status": (pe.script_analysis_status or "") if pe else "",
            "script_analysis_error": (pe.script_analysis_error or "") if pe else "",
            "script_label": script_original_name or "Script.pdf",
            "script_url": (
                url_for(
                    "project_episode_script_file",
                    project_id=project.id,
                    episode_number=episode_number,
                )
                if script_file and episode_number is not None
                else None
            ),
            "item_count": (
                len(rows)
                if is_establishing_collection
                else int(x_item_stats["episode_x_items"])
                if x_item_stats
                else 0
            ),
            "vfx_item_count": int(x_item_stats["episode_x_vfx"]) if x_item_stats else 0,
            "sound_item_count": int(x_item_stats["episode_x_sound"]) if x_item_stats else 0,
        }

    def _editing_item_dock_summary(item: EditingItem, project_id: int) -> dict:
        import editing_item_support as ei

        overall = (item.overall_status or "not_started").strip()
        edit_st = (item.edit_status or "not_started").strip()
        return {
            "id": int(item.id),
            "code": item.code or "",
            "title": item.title or "",
            "item_type": item.item_type or "other",
            "item_type_label": ei.item_type_label(item.item_type),
            "overall_status": overall,
            "overall_status_label": overall.replace("_", " ").title(),
            "edit_status": edit_st,
            "edit_status_label": edit_st.replace("_", " ").title(),
            "episode_number": int(item.number) if item.number else None,
            "linked_episode_id": int(item.linked_episode_id) if item.linked_episode_id else None,
            "url": url_for("project_editing_items", project_id=int(project_id)) + f"#item-{int(item.id)}",
        }

    def _attach_editing_items_to_episode_cards(
        episodes: list[dict],
        *,
        pipeline_by_num: dict[int, ProductionEpisode],
        editing_item_models: list,
        editing_item_summaries: list[dict],
    ) -> None:
        import editing_item_support as ei

        by_pe_id: dict[int, dict] = {}
        summaries_by_id = {int(s["id"]): s for s in editing_item_summaries}

        linked_groups: dict[int, list] = {}
        for model in editing_item_models:
            if (model.item_type or "").lower() != "episode":
                continue
            if not model.is_active or not model.linked_episode_id:
                continue
            linked_groups.setdefault(int(model.linked_episode_id), []).append(model)

        for pe_id, group in linked_groups.items():
            pe = next((p for p in pipeline_by_num.values() if int(p.id) == pe_id), None)
            ep_num = int(pe.episode_number) if pe and pe.episode_number else None
            primary = ei.pick_primary_episode_editing_item(group, episode_number=ep_num)
            if primary:
                by_pe_id[pe_id] = summaries_by_id[int(primary.id)]

        for ep in episodes:
            num = ep.get("episode_number")
            linked = None
            pe = None
            if num is not None:
                pe = pipeline_by_num.get(int(num))
                if pe is not None:
                    linked = by_pe_id.get(int(pe.id))
            ep["linked_editing_item"] = linked
            ep["production_episode_id"] = int(pe.id) if pe is not None else None

    @app.route("/projects/<int:project_id>/episodes", methods=["GET", "POST"])
    def project_episodes(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        episode_count = max(0, int(p.number_of_episodes or 0))
        links = (
            ShootingDayScene.query.options(joinedload(ShootingDayScene.vfx_shots))
            .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
            .filter(ShootingDay.project_id == p.id)
            .all()
        )
        by_episode: dict[int, list[ShootingDayScene]] = defaultdict(list)
        episode_x_rows: list[ShootingDayScene] = []
        establishing_rows: list[ShootingDayScene] = []
        for row in links:
            if shooting_items_mod.is_establishing_shot_row(row):
                establishing_rows.append(row)
            if bool(getattr(row, "is_episode_unassigned", False)):
                episode_x_rows.append(row)
                continue
            if bool(getattr(row, "is_establishing_shots_pool", False)):
                continue
            ep_num = int(row.episode_number or 0)
            if 1 <= ep_num <= episode_count:
                by_episode[ep_num].append(row)
        pipeline_by_num = ensure_production_episode_rows(p)
        episodes = []
        for ep_num in range(1, episode_count + 1):
            # SINGLE source of truth: the same editorial statistics the Episode
            # Detail page uses. The card's scene count / runtime / VFX numbers
            # are populated exclusively from this result (never from production
            # episode_number or stored aggregates), so list == detail always.
            stats = build_editorial_episode_statistics(
                p, ep_num, production_rows=by_episode.get(ep_num, [])
            )
            card = _episode_dock_card_from_rows(
                stats["membership"]["rows"],
                episode_number=ep_num,
                project=p,
                pe=pipeline_by_num.get(ep_num),
            )
            card["scene_count"] = stats["scene_count"]
            card["original_scene_count"] = stats["original_scene_count"]
            card["assigned_scene_count"] = stats["assigned_scene_count"]
            card["episode_runtime_seconds"] = stats["runtime_seconds"]
            card["total_duration"] = (
                (stats["runtime_seconds"] + 59) // 60 if stats["runtime_seconds"] else 0
            )
            card["runtime_display"] = stats["runtime_display"]
            card["vfx_item_count"] = stats["vfx_item_count"]
            card["scenes_with_vfx"] = stats["scenes_with_vfx"]
            card["vfx_shot_count"] = stats["vfx_shot_count"]
            card["pending_vfx_count"] = stats["pending_vfx_count"]
            card["completed_vfx_count"] = stats["completed_vfx_count"]
            _log_editorial_stats_debug("LIST", p, ep_num, stats)
            episodes.append(card)
        episode_x = None
        establishing_shots = None
        if episode_count > 0:
            episode_x = _episode_dock_card_from_rows(
                episode_x_rows,
                episode_number=None,
                project=p,
                is_episode_x=True,
            )
            establishing_shots = _episode_dock_card_from_rows(
                establishing_rows,
                episode_number=None,
                project=p,
                is_establishing_collection=True,
            )
        editing_item_models = (
            EditingItem.query.filter_by(project_id=int(p.id), is_active=True)
            .order_by(EditingItem.sort_order.asc(), EditingItem.code.asc())
            .all()
        )
        editing_items = [
            _editing_item_dock_summary(item, int(p.id)) for item in editing_item_models
        ]
        _attach_editing_items_to_episode_cards(
            episodes,
            pipeline_by_num=pipeline_by_num,
            editing_item_models=editing_item_models,
            editing_item_summaries=editing_items,
        )
        import editing_item_support as ei

        all_editing_items = EditingItem.query.filter_by(project_id=int(p.id)).all()
        production_episodes = list(pipeline_by_num.values())
        episode_conflicts = ei.detect_episode_editing_item_conflicts(
            p, production_episodes, all_editing_items
        )
        other_editing_items = [
            s
            for s in editing_items
            if not (
                (s.get("item_type") or "").lower() == "episode"
                and s.get("linked_episode_id")
            )
        ]
        assigned_editor_ids = {
            item.assigned_editor_id
            for item in editing_item_models
            if item.assigned_editor_id
        }
        editors = ei.load_offline_editing_editors(
            db,
            User,
            p,
            include_user_ids=assigned_editor_ids,
        )
        return render_template(
            "project_episodes.html",
            project=p,
            episodes=episodes,
            episode_x=episode_x,
            establishing_shots=establishing_shots,
            other_editing_items=other_editing_items,
            episode_conflicts=episode_conflicts,
            item_types=ei.create_item_types_for_project(p),
            priorities=ei.PRIORITIES,
            editors=editors,
            allows_episode_sync=ei.project_allows_episode_sync(p),
            workflow_active="episodes",
            is_macos=sys.platform == "darwin",
        )

    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/script/reveal",
        methods=["POST"],
    )
    def project_episode_script_reveal(project_id: int, episode_number: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        pe = ProductionEpisode.query.filter_by(
            project_id=p.id, episode_number=episode_number
        ).first()
        if pe is None or not (pe.script_file or "").strip():
            flash("No script file to show.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        path = os.path.realpath(episode_script_disk_path(pe))
        if not os.path.isfile(path):
            flash("Script file is missing on disk.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        if sys.platform == "darwin":
            subprocess.run(["open", "-R", path], check=False)
            flash("Revealed in Finder.", "success")
        elif sys.platform == "win32":
            subprocess.run(["explorer", "/select,", os.path.normpath(path)], check=False)
            flash("Revealed in File Explorer.", "success")
        else:
            flash(f"Script file: {path}", "info")
        return redirect(url_for("project_episodes", project_id=p.id))

    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/script",
        methods=["POST"],
    )
    def project_episode_script_upload(project_id: int, episode_number: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        episode_count = max(0, int(p.number_of_episodes or 0))
        if episode_number < 1 or episode_number > episode_count:
            flash("Invalid episode.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        upload_part = request.files.get("script_file")
        if (
            not upload_part
            or not upload_part.filename
            or not str(upload_part.filename).strip()
        ):
            flash("Choose a PDF script to upload.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        orig = secure_filename(upload_part.filename) or "script.pdf"
        ext = os.path.splitext(orig)[1].lower()
        if ext not in EPISODE_SCRIPT_ALLOWED_EXT:
            flash("Scripts must be PDF files.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        raw = upload_part.read()
        if len(raw) > EPISODE_SCRIPT_UPLOAD_MAX_BYTES:
            flash("Script file is too large (max 50 MB).", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        if not raw.startswith(b"%PDF"):
            flash("The file does not look like a valid PDF.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        pipeline_by_num = ensure_production_episode_rows(p)
        pe = pipeline_by_num.get(episode_number)
        if pe is None:
            flash("Episode not found.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        remove_episode_script_file(pe.script_file)
        new_upload_base = f"p{p.id}-ep{episode_number}-{uuid.uuid4().hex}{ext}"
        dest = os.path.join(episode_script_upload_root, new_upload_base)
        try:
            with open(dest, "wb") as out:
                out.write(raw)
        except OSError:
            flash("Could not save the script file.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        pe.script_file = new_upload_base
        pe.script_original_name = orig[:255]
        run_script_analysis_for_episode(pe)
        try:
            db.session.commit()
            if pe.script_analysis_status == "completed":
                flash(
                    f"Script uploaded for episode {episode_number} — "
                    f"{pe.script_page_count} pages, {pe.script_scene_count} scenes.",
                    "success",
                )
            elif pe.script_analysis_status == "no_scenes":
                flash(
                    f"Script uploaded — {pe.script_page_count} pages. "
                    f"No scene headings found.",
                    "success",
                )
            elif pe.script_analysis_status == "needs_ocr":
                flash(
                    f"Script uploaded — {pe.script_page_count} pages. "
                    f"This PDF may be scanned; OCR is required.",
                    "error",
                )
            else:
                flash(
                    f"Script uploaded for episode {episode_number}. "
                    f"{pe.script_analysis_error or 'Analysis could not complete.'}",
                    "error" if pe.script_analysis_status == "failed" else "success",
                )
        except Exception:
            db.session.rollback()
            remove_episode_script_file(new_upload_base)
            flash("Could not save the script file.", "error")
        return_to = (request.form.get("return_to") or "").strip()
        if return_to.startswith("/") and not return_to.startswith("//"):
            return redirect(return_to)
        return redirect(url_for("project_episodes", project_id=p.id))

    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/script/remove",
        methods=["POST"],
    )
    def project_episode_script_remove(project_id: int, episode_number: int):
        acc = db.session.get(Account, session.get("account_id"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        episode_count = max(0, int(p.number_of_episodes or 0))
        if episode_number < 1 or episode_number > episode_count:
            flash("Invalid episode.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        pe = ProductionEpisode.query.filter_by(
            project_id=p.id, episode_number=episode_number
        ).first()
        if pe is None or not (pe.script_file or "").strip():
            flash("No script to remove.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        remove_episode_script_file(pe.script_file)
        pe.script_file = None
        pe.script_original_name = None
        pe.script_page_count = 0
        pe.script_scene_count = 0
        pe.script_analysis_status = ""
        pe.script_analysis_error = ""
        try:
            db.session.commit()
            flash(f"Script removed for episode {episode_number}.", "success")
        except Exception:
            db.session.rollback()
            flash("Could not remove the script.", "error")
        return redirect(url_for("project_episodes", project_id=p.id))

    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/script/file",
        methods=["GET"],
    )
    def project_episode_script_file(project_id: int, episode_number: int):
        acc = db.session.get(Account, session.get("account_id"))
        if acc is None:
            abort(404)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id):
            abort(403)
        pe = ProductionEpisode.query.filter_by(
            project_id=p.id, episode_number=episode_number
        ).first()
        if pe is None:
            abort(404)
        basename = (pe.script_file or "").strip()
        if not basename or "/" in basename or "\\" in basename or basename.startswith("."):
            abort(404)
        download_name = (pe.script_original_name or f"episode-{episode_number}-script.pdf").strip()
        if not download_name.lower().endswith(".pdf"):
            download_name = f"{download_name}.pdf"
        return send_from_directory(
            episode_script_upload_root,
            basename,
            mimetype="application/pdf",
            as_attachment=False,
            download_name=download_name,
        )

    def _episode_media_rel(*parts: str) -> str:
        return "/".join(p.strip("/") for p in parts if p)

    def _episode_version_disk_path(rel_path: str) -> str:
        raw = (rel_path or "").strip().lstrip("/")
        if not raw or ".." in raw.split("/"):
            raise ValueError("invalid_path")
        return os.path.join(episode_media_upload_root, raw)

    def _next_episode_version_number(project_id: int, episode_number: int) -> int:
        latest = (
            EpisodeVersion.query.filter_by(project_id=project_id, episode_number=episode_number)
            .order_by(EpisodeVersion.version_number.desc(), EpisodeVersion.id.desc())
            .first()
        )
        return int(latest.version_number) + 1 if latest else 1

    def _next_scene_version_number(project_id: int, episode_number: int, scene_id: int) -> int:
        latest = (
            SceneVersion.query.filter_by(
                project_id=project_id, episode_number=episode_number, scene_id=scene_id
            )
            .order_by(SceneVersion.version_number.desc(), SceneVersion.id.desc())
            .first()
        )
        return int(latest.version_number) + 1 if latest else 1

    def _episode_detail_perm(acc: Account | None, action_key: str) -> bool:
        return perm_svc.can(acc, "episode_detail", action_key)

    def _episode_detail_redirect(
        p: Project, episode_number: int, tab: str, *, default: str = "scene-versions"
    ):
        allowed = {
            "overview",
            "shooting",
            "scenes",
            "vfx",
            "episode-versions",
            "scene-versions",
            "notes",
        }
        t = (tab or default).strip().lower()
        if t not in allowed:
            t = default
        return redirect(
            url_for(
                "project_episode_detail",
                project_id=p.id,
                episode_number=episode_number,
                tab=t,
            )
        )

    def _group_shooting_day_cards_by_unit(cards: list[dict[str, object]]) -> list[dict[str, object]]:
        shooting_units_map: dict[int, list[dict[str, object]]] = defaultdict(list)
        for card in cards:
            day = card.get("day")
            unit_num = int(getattr(day, "unit_number", 0) or 0) if day is not None else 0
            shooting_units_map[unit_num].append(card)
        shooting_units: list[dict[str, object]] = []
        for unit_num in sorted(shooting_units_map.keys()):
            day_cards = shooting_units_map[unit_num]
            hdd_labels: list[str] = []
            for card in day_cards:
                for h in card.get("hdd") or []:
                    label = str(h.get("label") or "")
                    if label and label not in hdd_labels:
                        hdd_labels.append(label)
            shooting_units.append(
                {
                    "unit_number": unit_num,
                    "days": day_cards,
                    "hdd_labels": hdd_labels,
                }
            )
        return shooting_units

    @app.template_filter("group_episode_shooting_units")
    def group_episode_shooting_units(cards: list[dict[str, object]] | None) -> list[dict[str, object]]:
        if not cards:
            return []
        return _group_shooting_day_cards_by_unit(cards)

    def _episode_detail_user_name(user_id: int | None) -> str:
        if user_id is None:
            return "—"
        u = db.session.get(User, int(user_id))
        return (u.name or "").strip() if u else "—"

    def _enqueue_episode_version_preview(version_id: int) -> None:
        def _job() -> None:
            with app.app_context():
                ev = db.session.get(EpisodeVersion, int(version_id))
                if ev is None:
                    return
                rel = (ev.file_path or "").strip()
                if not rel or not vp.is_video_basename(os.path.basename(rel)):
                    if ev.status == "processing":
                        ev.status = "ready"
                        ev.updated_at = now_local()
                        db.session.commit()
                    return
                try:
                    src = _episode_version_disk_path(rel)
                except ValueError:
                    return
                if not os.path.isfile(src):
                    return
                preview_name = f"{uuid.uuid4().hex}_preview.mp4"
                preview_rel = _episode_media_rel(
                    os.path.dirname(rel).split("/")[0],
                    os.path.dirname(rel).split("/")[1] if "/" in rel else "",
                )
                # previews live under episodes/ep_XX/previews/
                parts = rel.split("/")
                if len(parts) >= 4:
                    preview_rel = "/".join(parts[:4]) + "/previews/" + preview_name
                else:
                    preview_rel = f"projects/project_{ev.project_id}/episodes/ep_{ev.episode_number:02d}/previews/{preview_name}"
                try:
                    dest = _episode_version_disk_path(preview_rel)
                except ValueError:
                    return
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                if not vp.ffmpeg_available():
                    ev.status = "uploaded"
                    ev.updated_at = now_local()
                    db.session.commit()
                    return
                try:
                    vp.transcode_web_preview(src, dest)
                    meta = vp.probe_video_metadata(dest)
                    ev.preview_file_path = preview_rel
                    if ev.status in ("uploaded", "processing"):
                        ev.status = "ready"
                    if meta.get("duration_seconds"):
                        ev.duration_seconds = int(meta["duration_seconds"])
                    ev.updated_at = now_local()
                    db.session.commit()
                except Exception:
                    db.session.rollback()
                    ev = db.session.get(EpisodeVersion, int(version_id))
                    if ev is not None:
                        ev.status = "uploaded"
                        ev.updated_at = now_local()
                        db.session.commit()

        thread = threading.Thread(target=_job, name=f"ep-preview-{version_id}", daemon=True)
        thread.start()

    def _enqueue_scene_version_preview(version_id: int) -> None:
        def _job() -> None:
            with app.app_context():
                sv = db.session.get(SceneVersion, int(version_id))
                if sv is None:
                    return
                rel = (sv.file_path or "").strip()
                if not rel or not vp.is_video_basename(os.path.basename(rel)):
                    if sv.status == "processing":
                        sv.status = "ready"
                        sv.updated_at = now_local()
                        db.session.commit()
                    return
                try:
                    src = _episode_version_disk_path(rel)
                except ValueError:
                    return
                if not os.path.isfile(src):
                    return
                preview_name = f"{uuid.uuid4().hex}_preview.mp4"
                parts = rel.split("/")
                if len(parts) >= 4:
                    preview_rel = "/".join(parts[:4]) + "/previews/" + preview_name
                else:
                    preview_rel = (
                        f"projects/project_{sv.project_id}/episodes/ep_{sv.episode_number:02d}"
                        f"/previews/{preview_name}"
                    )
                try:
                    dest = _episode_version_disk_path(preview_rel)
                except ValueError:
                    return
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                if not vp.ffmpeg_available():
                    sv.status = "uploaded"
                    sv.updated_at = now_local()
                    db.session.commit()
                    return
                try:
                    vp.transcode_web_preview(src, dest)
                    meta = vp.probe_video_metadata(dest)
                    sv.preview_file_path = preview_rel
                    if sv.status in ("uploaded", "processing"):
                        sv.status = "ready"
                    if meta.get("duration_seconds"):
                        sv.duration_seconds = int(meta["duration_seconds"])
                    sv.updated_at = now_local()
                    db.session.commit()
                except Exception:
                    db.session.rollback()
                    sv = db.session.get(SceneVersion, int(version_id))
                    if sv is not None:
                        sv.status = "uploaded"
                        sv.updated_at = now_local()
                        db.session.commit()

        thread = threading.Thread(target=_job, name=f"sc-preview-{version_id}", daemon=True)
        thread.start()

    def _build_episode_detail_context(
        p: Project,
        episode_number: int,
        *,
        active_tab: str,
        is_episode_x: bool = False,
        is_establishing_collection: bool = False,
    ) -> dict:
        episode_count = max(0, int(p.number_of_episodes or 0))
        special_collection = is_episode_x or is_establishing_collection
        if special_collection:
            if episode_count < 1:
                abort(404)
        elif episode_number < 1 or episode_number > episode_count:
            abort(404)
        pe = None
        script_scene_count = 0
        has_script = False
        if not special_collection:
            pipeline_by_num = ensure_production_episode_rows(p)
            pe = pipeline_by_num.get(episode_number)
            if pe and (pe.script_file or "").strip() and not (pe.script_analysis_status or "").strip():
                run_script_analysis_for_episode(pe)
                try:
                    db.session.commit()
                except Exception:
                    db.session.rollback()
            script_scene_count = int(pe.script_scene_count or 0) if pe else 0
            has_script = bool(pe and (pe.script_file or "").strip())
        scene_q = ShootingDayScene.query.options(
            joinedload(ShootingDayScene.shooting_day),
            selectinload(ShootingDayScene.vfx_shots).selectinload(VfxShot.versions),
            selectinload(ShootingDayScene.vfx_shots).selectinload(VfxShot.assigned_artist),
        ).join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id).filter(
            ShootingDay.project_id == p.id
        )
        if is_episode_x:
            scenes = scene_q.filter(ShootingDayScene.is_episode_unassigned.is_(True)).all()
        elif is_establishing_collection:
            scenes = [
                sc
                for sc in scene_q.all()
                if shooting_items_mod.is_establishing_shot_row(sc)
            ]
        else:
            scenes = (
                scene_q.filter(
                    ShootingDayScene.episode_number == episode_number,
                    ShootingDayScene.is_episode_unassigned.is_(False),
                    ShootingDayScene.is_establishing_shots_pool.is_(False),
                )
                .all()
            )
        scenes = ed.sort_shooting_day_scenes_for_display(scenes)
        day_ids: set[int] = set()
        for sc in scenes:
            if sc.shooting_day_id:
                day_ids.add(int(sc.shooting_day_id))
        shooting_days = (
            ShootingDay.query.filter(ShootingDay.id.in_(sorted(day_ids))).order_by(
                ShootingDay.shooting_date, ShootingDay.id
            ).all()
            if day_ids
            else []
        )
        scenes_by_day: dict[int, list[ShootingDayScene]] = defaultdict(list)
        for sc in scenes:
            scenes_by_day[int(sc.shooting_day_id)].append(sc)
        hdd_by_day: dict[int, list[dict]] = defaultdict(list)
        if day_ids:
            for usage in (
                HardDiskUsage.query.options(joinedload(HardDiskUsage.hard_disk))
                .filter(HardDiskUsage.shooting_day_id.in_(day_ids))
                .all()
            ):
                hd = usage.hard_disk
                hdd_by_day[int(usage.shooting_day_id)].append(
                    {
                        "label": (hd.name or f"HDD {hd.id}") if hd else "HDD",
                        "video_tb": float(usage.video_size_tb or 0),
                        "audio_tb": float(usage.audio_size_tb or 0),
                    }
                )
        shooting_day_cards = []
        for day in shooting_days:
            day_scenes = scenes_by_day.get(day.id, [])
            ep_dur = sum(
                ed.shooting_day_scene_duration_seconds(s)
                for s in day_scenes
                if shooting_items_mod.counts_toward_episode_runtime(s)
            )
            shooting_day_cards.append(
                {
                    "day": day,
                    "scenes": day_scenes,
                    "episode_duration_seconds": ep_dur,
                    "hdd": hdd_by_day.get(day.id, []),
                    "day_url": url_for("project_production_day", project_id=p.id, day_id=day.id),
                }
            )
        shooting_units = _group_shooting_day_cards_by_unit(shooting_day_cards)
        # ---- Editorial scene set (this episode's CURRENT editorial cut) ------
        # The Episode page represents the EDITORIAL version of the project. Every
        # statistic below is computed from the scenes editorially assigned to this
        # episode, using the SAME shared membership function the Episode List cards
        # use (calculate_editorial_episode_scene_set) — so runtime / scene count /
        # VFX / progress always match between the list and the detail page.
        # Production data (shooting days above, shooting-day records, and
        # production reports) is never modified. If nothing is assigned to this
        # editorial episode, every statistic is zero (no stale production values).
        if not special_collection and episode_number:
            _ed_set = calculate_editorial_episode_scene_set(
                p, int(episode_number), production_rows=scenes
            )
            editorial_scenes = _ed_set["rows"]
            assigned_in_scenes = _ed_set["assigned_in"]
            assigned_in_id_set = _ed_set["assigned_in_ids"]
            assigned_in_reason = _ed_set["assigned_in_reason"]
            reassigned_ids = _ed_set["reassigned_ids"]
            used_in_map = _ed_set["used_in_map"]
            # SINGLE source of truth shared with the Episode List cards.
            ep_stats = build_editorial_episode_statistics(
                p, int(episode_number), membership=_ed_set
            )
            _log_editorial_stats_debug("DETAIL", p, int(episode_number), ep_stats)
        else:
            editorial_scenes = scenes
            assigned_in_scenes = []
            assigned_in_id_set = set()
            assigned_in_reason = {}
            reassigned_ids = set()
            used_in_map = {}
            ep_stats = None
        ed_scene_ids = [int(sc.id) for sc in editorial_scenes]

        # VFX aggregation (editorial).
        vfx_by_scene: list[dict] = []
        all_shots: list[VfxShot] = []
        for sc in editorial_scenes:
            shots = sorted(sc.vfx_shots or [], key=lambda s: (s.shot_number, s.id))
            if shots:
                all_shots.extend(shots)
                vfx_by_scene.append({"scene": sc, "shots": shots})
        vfx_linked_scene_ids: set[int] = set()
        vfx_item_ids_for_episode: set[int] = set()
        if ed_scene_ids:
            for r in (
                db.session.query(
                    VfxSceneItemSource.shooting_day_scene_id,
                    VfxSceneItemSource.vfx_scene_item_id,
                )
                .filter(
                    VfxSceneItemSource.shooting_day_scene_id.in_(ed_scene_ids),
                    VfxSceneItemSource.is_active.is_(True),
                )
                .all()
            ):
                vfx_linked_scene_ids.add(int(r[0]))
                if r[1] is not None:
                    vfx_item_ids_for_episode.add(int(r[1]))

        # Scene versions for the editorial scenes (by scene id so scenes assigned
        # in from other production episodes are covered too).
        scene_versions = (
            SceneVersion.query.filter(
                SceneVersion.project_id == p.id,
                SceneVersion.scene_id.in_(ed_scene_ids),
            )
            .order_by(SceneVersion.scene_id, SceneVersion.version_number.desc())
            .all()
            if ed_scene_ids
            else []
        )
        sv_by_scene: dict[int, list[SceneVersion]] = defaultdict(list)
        for sv in scene_versions:
            sv_by_scene[int(sv.scene_id)].append(sv)

        def _make_scene_card(sc, *, sv_list=None, linked_ids=None):
            day = sc.shooting_day
            sv_list = sv_list if sv_list is not None else []
            latest_sv = sv_list[0] if sv_list else None
            in_item = bool(linked_ids is not None and int(sc.id) in linked_ids)
            return {
                "scene": sc,
                "day": day,
                "has_vfx": in_item or bool(sc.vfx_shots),
                "in_vfx_item": in_item,
                "vfx_count": len(sc.vfx_shots or []),
                "latest_version": latest_sv,
                "version_count": len(sv_list),
                "day_url": (
                    url_for("project_production_day", project_id=p.id, day_id=day.id)
                    if day
                    else None
                ),
                # Editorial layer annotations (defaults; filled below).
                "used_in_episodes": [],
                "editorial_origin": None,
                "editorial_assignment_reason": "",
            }

        scene_cards = []
        for sc in editorial_scenes:
            card = _make_scene_card(
                sc, sv_list=sv_by_scene.get(sc.id, []), linked_ids=vfx_linked_scene_ids
            )
            if int(sc.id) in assigned_in_id_set:
                card["editorial_origin"] = _scene_production_episode_key(sc)
                card["editorial_assignment_reason"] = assigned_in_reason.get(int(sc.id), "")
            scene_cards.append(card)
        # All editorial cards now live in scene_cards; this stays for template
        # compatibility (the grid renders scene_cards + editorial_scene_cards).
        editorial_scene_cards: list[dict] = []
        # Informational counts for the statistics panel.
        editorial_assigned_count = (
            shooting_items_mod.count_unique_real_scenes(assigned_in_scenes)
            if assigned_in_scenes
            else 0
        )
        editorial_runtime_seconds = sum(
            ed.shooting_day_scene_duration_seconds(s)
            for s in assigned_in_scenes
            if shooting_items_mod.counts_toward_episode_runtime(s)
        )
        episode_versions = (
            []
            if special_collection
            else EpisodeVersion.query.options(joinedload(EpisodeVersion.uploader))
            .filter_by(project_id=p.id, episode_number=episode_number, edit_scope="full")
            .order_by(EpisodeVersion.version_number.desc(), EpisodeVersion.id.desc())
            .all()
        )
        latest_ev = episode_versions[0] if episode_versions else None
        notes = (
            []
            if special_collection
            else EpisodeNote.query.options(joinedload(EpisodeNote.author))
            .filter_by(project_id=p.id, episode_number=episode_number)
            .order_by(EpisodeNote.created_at.desc(), EpisodeNote.id.desc())
            .all()
        )
        if is_establishing_collection:
            shooting_scene_count = len(editorial_scenes)
            real_scene_list = []
        elif is_episode_x:
            real_scene_list = [
                r
                for r in editorial_scenes
                if shooting_items_mod.counts_toward_shooting_day_sync_edit(r)
            ]
            shooting_scene_count = shooting_items_mod.count_unique_real_scenes_on_day(
                editorial_scenes, include_unassigned=True
            )
        else:
            # PRODUCTION progress ("Shooting completed", Sync, First edit, VFX)
            # is measured against the immutable shooting-day scenes shot for THIS
            # episode (production origin), never the editorial cut — shooting days
            # do not change when a scene is editorially reassigned.
            real_scene_list = shooting_items_mod.real_scene_rows(scenes)
            shooting_scene_count = shooting_items_mod.count_unique_real_scenes(scenes)
        real_scene_row_count = len(real_scene_list)
        total_scenes = shooting_scene_count
        total_dur_sec = sum(
            ed.shooting_day_scene_duration_seconds(s)
            for s in editorial_scenes
            if shooting_items_mod.counts_toward_episode_runtime(s)
        )
        reshoot_count = shooting_items_mod.count_reshoot_versions(editorial_scenes)
        runtime_selection_needed = shooting_items_mod.episode_runtime_selection_needed(
            editorial_scenes
        )
        # VFX progress row (Production progress) tracks the shooting-day scenes
        # that need VFX for this episode's production origin.
        vfx_scenes = [s for s in scenes if bool(s.needs_vfx)]
        # VFX Item Count is editorial: the active VFX items that contain at least
        # one scene currently assigned to this editorial episode.
        vfx_items_count = 0
        if is_episode_x:
            vfx_items_count = VfxSceneItem.query.filter_by(
                project_id=p.id,
                episode_number=0,
                is_active=True,
            ).count()
        elif vfx_item_ids_for_episode:
            vfx_items_count = VfxSceneItem.query.filter(
                VfxSceneItem.id.in_(vfx_item_ids_for_episode),
                VfxSceneItem.is_active.is_(True),
            ).count()
        vfx_shot_count = len(all_shots)
        pending_vfx = sum(1 for sh in all_shots if not ed.vfx_shot_is_terminal(sh))
        approved_vfx = vfx_shot_count - pending_vfx
        # For a numbered editorial episode, all summary figures come from the
        # shared statistics function so the detail page and the list card are
        # guaranteed to match (same scene ids -> same runtime / VFX numbers).
        vfx_scenes_display_count = len(vfx_scenes)
        if ep_stats is not None:
            # Editorial summary tiles (Total scenes / Runtime / VFX) come from the
            # shared editorial statistics. shooting_scene_count is intentionally
            # NOT overridden here — it stays production (shooting-day) based.
            total_scenes = ep_stats["scene_count"]
            total_dur_sec = ep_stats["runtime_seconds"]
            vfx_items_count = ep_stats["vfx_item_count"]
            vfx_shot_count = ep_stats["vfx_shot_count"]
            pending_vfx = ep_stats["pending_vfx_count"]
            approved_vfx = ep_stats["completed_vfx_count"]
            vfx_scenes_display_count = ep_stats["scenes_with_vfx"]
        critical_scene_count = sum(1 for s in editorial_scenes if bool(s.is_critical))
        editorial_day_ids = {
            int(s.shooting_day_id) for s in editorial_scenes if s.shooting_day_id
        }
        critical_note_count = 0
        if editorial_day_ids:
            critical_note_count = (
                ShootingDayCriticalNote.query.filter(
                    ShootingDayCriticalNote.shooting_day_id.in_(editorial_day_ids),
                    ShootingDayCriticalNote.solved_at.is_(None),
                    ShootingDayCriticalNote.is_critical.is_(True),
                ).count()
            )
        critical_count = int(critical_scene_count) + int(critical_note_count)
        sync_done_n = sum(1 for s in real_scene_list if bool(s.sync_done))
        first_edit_n = sum(1 for s in real_scene_list if bool(s.first_edit_done))
        vfx_done_n = sum(1 for s in vfx_scenes if ed.scene_vfx_done(s))
        estimated_episode_duration_seconds = max(
            0, int(p.estimated_episode_duration_minutes or 0)
        ) * 60
        if script_scene_count > 0:
            shooting_progress_pct = ed.pct(shooting_scene_count, script_scene_count)
        else:
            shooting_progress_pct = 0
        if estimated_episode_duration_seconds > 0:
            duration_progress_pct = min(
                100, ed.pct(total_dur_sec, estimated_episode_duration_seconds)
            )
        else:
            duration_progress_pct = 0
        overview = {
            "episode_number": episode_number if not special_collection else None,
            "is_episode_x": is_episode_x,
            "is_establishing_collection": is_establishing_collection,
            "total_scenes": total_scenes,
            "shooting_days_count": len(shooting_days),
            "total_duration_seconds": total_dur_sec,
            "runtime_display": format_duration_day_total(total_dur_sec),
            "reshoot_count": reshoot_count,
            "runtime_selection_needed": runtime_selection_needed,
            "vfx_scenes_count": vfx_scenes_display_count,
            "vfx_items_count": vfx_items_count,
            "vfx_shot_count": vfx_shot_count,
            "pending_vfx": pending_vfx,
            "approved_vfx": approved_vfx,
            "latest_episode_version": latest_ev,
            "script_scene_count": script_scene_count,
            "has_script": has_script,
            "script_label": (
                (lambda _name: _name if re.search(r"[A-Za-z]", (_name.rsplit(".", 1)[0] if "." in _name else _name)) else "")(
                    (pe.script_original_name or "").strip()
                )
                if pe
                else ""
            ),
            "script_url": (
                url_for(
                    "project_episode_script_file",
                    project_id=p.id,
                    episode_number=episode_number,
                )
                if has_script and not special_collection and episode_number
                else None
            ),
            "shooting_scene_count": shooting_scene_count,
            "critical_count": critical_count,
            # Editorial layer: all counts above are already editorial. This is how
            # many of the displayed scenes were assigned in from other episodes.
            "editorial_assigned_count": editorial_assigned_count,
            "displayed_scene_count": int(total_scenes),
            "editorial_runtime_seconds": editorial_runtime_seconds,
            "estimated_episode_duration_seconds": estimated_episode_duration_seconds,
            "sync_done_count": sync_done_n,
            "first_edit_done_count": first_edit_n,
            "vfx_scenes_done_count": vfx_done_n,
            "progress": {
                "shooting": shooting_progress_pct,
                "sync": ed.pct(sync_done_n, real_scene_row_count),
                "first_edit": ed.pct(first_edit_n, real_scene_row_count),
                "vfx": ed.pct(vfx_done_n, len(vfx_scenes)),
                "duration": duration_progress_pct,
            },
            "progress_ratios": {
                "shooting": {
                    "done": shooting_scene_count,
                    "total": script_scene_count,
                    "suffix": "script scenes",
                },
                "sync": {
                    "done": sync_done_n,
                    "total": real_scene_row_count,
                    "suffix": "scenes",
                },
                "first_edit": {
                    "done": first_edit_n,
                    "total": real_scene_row_count,
                    "suffix": "scenes",
                },
                "vfx": {
                    "done": vfx_done_n,
                    "total": len(vfx_scenes),
                    "suffix": "VFX scenes",
                },
                "duration": {
                    "done_seconds": total_dur_sec,
                    "total_seconds": estimated_episode_duration_seconds,
                },
            },
        }
        move_target_episodes = [
            {"number": n, "label": f"Episode {n:02d}"}
            for n in range(1, max(0, int(p.number_of_episodes or 0)) + 1)
        ]
        return {
            "project": p,
            "episode_number": episode_number,
            "is_episode_x": is_episode_x,
            "is_establishing_collection": is_establishing_collection,
            "production_episode": pe,
            "move_target_episodes": move_target_episodes,
            "linked_editing_item": (
                EditingItem.query.filter_by(
                    project_id=int(p.id),
                    linked_episode_id=int(pe.id),
                    is_active=True,
                ).first()
                if pe
                else None
            ),
            "active_tab": active_tab,
            "overview": overview,
            "shooting_day_cards": shooting_day_cards,
            "shooting_units": shooting_units,
            "scene_cards": scene_cards,
            "editorial_scene_cards": editorial_scene_cards,
            "vfx_by_scene": vfx_by_scene,
            "episode_versions": episode_versions,
            "scene_versions": scene_versions,
            "sv_by_scene": dict(sv_by_scene),
            "notes": notes,
            "workflow_active": "episodes",
            "vfx_url": url_for("project_vfx", project_id=p.id),
            "production_url": url_for("project_production", project_id=p.id),
            "episodes_url": url_for("project_episodes", project_id=p.id),
        }

