    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/versions/full",
        methods=["POST"],
    )
    def project_episode_version_upload(project_id: int, episode_number: int):
        acc = account_from_session()
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id) or not _episode_detail_perm(acc, "upload_episode_version"):
            abort(403)
        episode_count = max(0, int(p.number_of_episodes or 0))
        if episode_number < 1 or episode_number > episode_count:
            flash("Invalid episode.", "error")
            return redirect(url_for("project_episodes", project_id=p.id))
        upload_part = request.files.get("media_file")
        if not upload_part or not upload_part.filename:
            flash("Choose a file to upload.", "error")
            return redirect(
                url_for(
                    "project_episode_detail",
                    project_id=p.id,
                    episode_number=episode_number,
                    tab="episode-versions",
                )
            )
        orig = secure_filename(upload_part.filename) or "episode.mp4"
        ext = os.path.splitext(orig)[1].lower()
        if ext not in ed.EPISODE_MEDIA_ALLOWED_EXT:
            flash("Unsupported file type.", "error")
            return redirect(
                url_for(
                    "project_episode_detail",
                    project_id=p.id,
                    episode_number=episode_number,
                    tab="episode-versions",
                )
            )
        raw = upload_part.read()
        if len(raw) > ed.EPISODE_MEDIA_MAX_BYTES:
            flash("File is too large (max 500 MB).", "error")
            return redirect(
                url_for(
                    "project_episode_detail",
                    project_id=p.id,
                    episode_number=episode_number,
                    tab="episode-versions",
                )
            )
        ver_num = _next_episode_version_number(p.id, episode_number)
        ed.ensure_episode_media_dirs(episode_media_upload_root, p.id, episode_number)
        stored_name = f"ep{episode_number:02d}_full_{ver_num:03d}_{uuid.uuid4().hex[:8]}{ext}"
        rel_path = (
            f"projects/project_{p.id}/episodes/ep_{episode_number:02d}/full_versions/{stored_name}"
        )
        dest = _episode_version_disk_path(rel_path)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        try:
            with open(dest, "wb") as out:
                out.write(raw)
        except OSError:
            flash("Could not save file.", "error")
            return redirect(
                url_for(
                    "project_episode_detail",
                    project_id=p.id,
                    episode_number=episode_number,
                    tab="episode-versions",
                )
            )
        notes = (request.form.get("notes") or "").strip()[:5000]
        status = (request.form.get("status") or "uploaded").strip().lower()
        if status not in ed.EPISODE_VERSION_STATUSES:
            status = "uploaded"
        uid = directory_user_id_for_account(acc)
        ev = EpisodeVersion(
            project_id=p.id,
            episode_number=episode_number,
            version_number=ver_num,
            title=f"Episode {episode_number:02d} - {ed.format_version_label(ver_num)}",
            file_path=rel_path,
            original_filename=orig[:255],
            mime_type=vp.guess_mime_type(ext),
            file_size_bytes=len(raw),
            status="processing" if vp.is_video_extension(ext) else status,
            notes=notes,
            uploaded_by=uid,
            uploaded_at=now_local(),
            edit_scope="full",
        )
        db.session.add(ev)
        db.session.commit()
        color_hooks = app.extensions.get("color_hooks") or {}
        on_edit = color_hooks.get("on_edit_version_uploaded")
        if callable(on_edit):
            try:
                on_edit(int(p.id), int(episode_number), int(ev.id))
                db.session.commit()
            except Exception:
                db.session.rollback()
        if vp.is_video_extension(ext):
            _enqueue_episode_version_preview(ev.id)
        flash(f"Episode version {ed.format_version_label(ver_num)} uploaded.", "success")
        return redirect(
            url_for(
                "project_episode_detail",
                project_id=p.id,
                episode_number=episode_number,
                tab="episode-versions",
            )
        )

    @app.route(
        "/projects/<int:project_id>/episodes/<int:episode_number>/versions/scene",
        methods=["POST"],
    )
    def project_scene_version_upload(project_id: int, episode_number: int):
        acc = account_from_session()
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(acc, p.id) or not _episode_detail_perm(acc, "upload_scene_version"):
            abort(403)
        return_tab = (request.form.get("return_tab") or "scene-versions").strip().lower()
        try:
            scene_id = int(request.form.get("scene_id") or 0)
        except ValueError:
            scene_id = 0
        scene = shooting_day_scene_for_project(scene_id, p.id)
        if scene is None or int(scene.episode_number) != episode_number:
            flash("Invalid scene.", "error")
            return _episode_detail_redirect(p, episode_number, return_tab)
        upload_part = request.files.get("media_file")
        if not upload_part or not upload_part.filename:
            flash("Choose a file to upload.", "error")
            return _episode_detail_redirect(p, episode_number, return_tab)
        orig = secure_filename(upload_part.filename) or "scene.mp4"
        ext = os.path.splitext(orig)[1].lower()
        if ext not in ed.EPISODE_MEDIA_ALLOWED_EXT:
            flash("Unsupported file type.", "error")
            return _episode_detail_redirect(p, episode_number, return_tab)
        raw = upload_part.read()
        if len(raw) > ed.EPISODE_MEDIA_MAX_BYTES:
            flash("File too large.", "error")
            return _episode_detail_redirect(p, episode_number, return_tab)
        sc_num = int(scene.scene_number or 1)
        ver_num = _next_scene_version_number(p.id, episode_number, scene_id)
        ed.ensure_episode_media_dirs(episode_media_upload_root, p.id, episode_number)
        stored_name = f"sc{sc_num:02d}_v{ver_num:03d}_{uuid.uuid4().hex[:8]}{ext}"
        rel_path = (
            f"projects/project_{p.id}/episodes/ep_{episode_number:02d}"
            f"/scene_versions/{stored_name}"
        )
        dest = _episode_version_disk_path(rel_path)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as out:
            out.write(raw)
        notes = (request.form.get("notes") or "").strip()[:5000]
        uid = directory_user_id_for_account(acc)
        sv = SceneVersion(
            project_id=p.id,
            episode_number=episode_number,
            scene_id=scene_id,
            scene_number=sc_num,
            version_number=ver_num,
            title=ed.scene_version_title(episode_number, sc_num, ver_num),
            file_path=rel_path,
            original_filename=orig[:255],
            mime_type=vp.guess_mime_type(ext),
            file_size_bytes=len(raw),
            status="processing" if vp.is_video_extension(ext) else "uploaded",
            notes=notes,
            uploaded_by=uid,
            uploaded_at=now_local(),
        )
        db.session.add(sv)
        db.session.commit()
        if vp.is_video_extension(ext):
            _enqueue_scene_version_preview(sv.id)
        flash(f"Scene version {ed.format_version_label(ver_num)} uploaded.", "success")
        return _episode_detail_redirect(p, episode_number, return_tab)

