    def _scene_version_comment_rows(sv: SceneVersion) -> list[dict[str, object]]:
        rows = (
            SceneVersionComment.query.options(joinedload(SceneVersionComment.author))
            .filter_by(scene_version_id=sv.id)
            .order_by(SceneVersionComment.created_at.asc(), SceneVersionComment.id.asc())
            .all()
        )
        out: list[dict[str, object]] = []
        upload_notes = (sv.notes or "").strip()
        if upload_notes:
            out.append(
                {
                    "id": None,
                    "body": upload_notes,
                    "authorName": _episode_detail_user_name(sv.uploaded_by),
                    "createdAt": sv.uploaded_at.isoformat() if sv.uploaded_at else "",
                    "isUploadNote": True,
                }
            )
        for c in rows:
            out.append(
                {
                    "id": c.id,
                    "body": c.body,
                    "authorName": _episode_detail_user_name(c.created_by),
                    "createdAt": c.created_at.isoformat() if c.created_at else "",
                    "isUploadNote": False,
                }
            )
        return out

    def _scene_version_media_meta(
        sv: SceneVersion, *, project_id: int, episode_number: int
    ) -> dict[str, object]:
        preview_rel = (sv.preview_file_path or "").strip() or (sv.file_path or "").strip()
        preview_url = None
        is_video = False
        if preview_rel:
            ext = os.path.splitext(preview_rel)[1].lower()
            is_video = vp.is_video_extension(ext)
            preview_url = url_for(
                "project_scene_version_preview_file",
                project_id=project_id,
                episode_number=episode_number,
                version_id=sv.id,
            )
        return {"previewUrl": preview_url, "isVideo": is_video}

    def _scene_version_summary(
        sv: SceneVersion, *, project_id: int, episode_number: int
    ) -> dict[str, object]:
        media = _scene_version_media_meta(
            sv, project_id=project_id, episode_number=episode_number
        )
        return {
            "id": sv.id,
            "title": sv.title,
            "status": sv.status,
            "versionNumber": int(sv.version_number or 0),
            "previewUrl": media["previewUrl"],
            "isVideo": media["isVideo"],
            "uploadedAt": sv.uploaded_at.isoformat() if sv.uploaded_at else "",
        }

    def _scene_version_history(
        scene_id: int, *, project_id: int, episode_number: int
    ) -> list[dict[str, object]]:
        versions = (
            SceneVersion.query.filter_by(
                project_id=project_id,
                episode_number=episode_number,
                scene_id=scene_id,
            )
            .order_by(SceneVersion.version_number.desc(), SceneVersion.id.desc())
            .all()
        )
        return [
            _scene_version_summary(sv, project_id=project_id, episode_number=episode_number)
            for sv in versions
        ]

    def _scene_version_preview_payload(
        sv: SceneVersion, *, acc: Account | None, project_id: int, episode_number: int
    ) -> dict[str, object]:
        media = _scene_version_media_meta(
            sv, project_id=project_id, episode_number=episode_number
        )
        return {
            "id": sv.id,
            "title": sv.title,
            "status": sv.status,
            "versionNumber": int(sv.version_number or 0),
            "previewUrl": media["previewUrl"],
            "isVideo": media["isVideo"],
            "comments": _scene_version_comment_rows(sv),
            "canComment": _episode_detail_perm(acc, "edit_notes"),
        }

