    @app.route(
        "/projects/<int:project_id>/production/days/<int:day_id>/assign-scene",
        methods=["POST"],
    )
    def shooting_day_assign_scene(project_id: int, day_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        require_production_edit(acc, project_id)
        if not account_can_access_project(acc, project_id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        d = shooting_day_in_project(day_id, project_id)
        if d is None:
            abort(404)
        is_tv_project = _project_type_is_tv_series(d.project.project_type)
        max_episode = max(0, int(d.project.number_of_episodes or 0)) if is_tv_project else 1
        if is_tv_project and max_episode < 1:
            flash("Set Number of episodes on the project before adding rows.", "error")
            return redirect(url_for("project_production_day", project_id=project_id, day_id=day_id))
        raw_ep = (request.form.get("episode_number") or "").strip()
        raw_scene = (request.form.get("scene_label") or request.form.get("scene_number") or "").strip()
        raw_duration = (request.form.get("duration") or "").strip()
        raw_item_type = request.form.get("shooting_item_type")
        item_type = shooting_items_mod.coerce_shooting_item_type(raw_item_type)
        notes = (request.form.get("notes") or "").strip()
        sync_done = request.form.get("sync_done") == "1"
        first_edit_done = request.form.get("first_edit_done") == "1"
        needs_vfx = shooting_items_mod.apply_auto_vfx_for_type(
            item_type, request.form.get("needs_vfx") == "1"
        )
        is_critical = request.form.get("is_critical") == "1"
        ep_num, scene_label, id_err, is_episode_unassigned, is_establishing_shots_pool = (
            shooting_items_mod.parse_shooting_row_identity(
                item_type,
                raw_ep,
                raw_scene,
                is_tv_project=is_tv_project,
                max_episode=max_episode,
            )
        )
        if id_err:
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": id_err}), 400
            flash(id_err, "error")
            return redirect(url_for("project_production_day", project_id=project_id, day_id=day_id))
        if shooting_items_mod.should_check_episode_scene_duplicate(item_type):
            duplicate = find_episode_scene_label_duplicate(
                project_id,
                ep_num,
                scene_label,
                is_episode_unassigned=is_episode_unassigned,
                is_establishing_shots_pool=is_establishing_shots_pool,
            )
            if duplicate is not None:
                if _assign_scene_wants_json():
                    return (
                        jsonify(
                            _shooting_scene_conflict_payload(
                                project_id,
                                ep_num,
                                scene_label,
                                duplicate,
                                is_episode_unassigned=is_episode_unassigned,
                                is_establishing_shots_pool=is_establishing_shots_pool,
                            )
                        ),
                        409,
                    )
                if is_episode_unassigned:
                    ep_label = "Episode X"
                elif is_establishing_shots_pool:
                    ep_label = "Establishing Shots"
                else:
                    ep_label = f"Episode {ep_num:02d}"
                flash(
                    f"Scene {scene_label} already exists in {ep_label}. "
                    "Use Reshoot if you are shooting it again.",
                    "error",
                )
                conflict_ep = (
                    "X"
                    if is_episode_unassigned
                    else ("establishing" if is_establishing_shots_pool else ep_num)
                )
                return redirect(
                    url_for(
                        "project_production_day",
                        project_id=project_id,
                        day_id=day_id,
                        conflict_ep=conflict_ep,
                        conflict_scene=scene_label,
                    )
                )
        dur_sec = parse_shooting_day_duration_seconds(raw_duration)
        if dur_sec is None:
            msg = "Duration must be mm:ss, H:MM:SS, whole minutes (1–3 digits), or compact MMSS (4+ digits, e.g. 0315 = 3:15)."
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(url_for("project_production_day", project_id=project_id, day_id=day_id))
        if len(notes) > 20_000:
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": "Notes are too long."}), 400
            flash("Notes are too long.", "error")
            return redirect(url_for("project_production_day", project_id=project_id, day_id=day_id))
        dur_sec_i = max(0, int(dur_sec))
        dur_min = (dur_sec_i + 59) // 60 if dur_sec_i else 0
        row = ShootingDayScene(
            shooting_day_id=day_id,
            scene_id=next_legacy_scene_id_for_day(day_id),
            episode_number=ep_num,
            is_episode_unassigned=is_episode_unassigned,
            is_establishing_shots_pool=is_establishing_shots_pool,
            scene_label=scene_label,
            scene_number=1,
            duration=dur_min,
            duration_seconds=dur_sec_i,
            actual_duration_minutes=dur_min,
            notes=notes,
            status="done" if (sync_done and first_edit_done) else "pending",
            sync_done=sync_done,
            first_edit_done=first_edit_done,
            needs_vfx=needs_vfx,
            is_critical=is_critical,
            shooting_item_type=item_type,
        )
        db.session.add(row)
        db.session.flush()
        siblings = shooting_day_scene_runtime_siblings(project_id, row, exclude_link_id=row.id)
        shooting_items_mod.apply_runtime_selection_for_new_row(row, siblings)
        thumb_err = persist_shooting_scene_thumbnail_frame(
            row, request.files.get("scene_thumbnail_frame")
        )
        if thumb_err:
            stale_thumb = (row.scene_thumbnail_frame or "").strip()
            db.session.rollback()
            if stale_thumb:
                remove_shooting_scene_thumbnail_file(stale_thumb)
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": thumb_err}), 400
            flash(thumb_err, "error")
            return redirect(url_for("project_production_day", project_id=project_id, day_id=day_id))
        import project_activity_hooks as pah

        pah.log_shooting_item_created(row, d)
        db.session.commit()
        if needs_vfx:
            _ensure_vfx_bridge_for_project(project_id)
        redirect_url = url_for(
            "project_production_day", project_id=project_id, day_id=day_id, new=row.id
        )
        if _assign_scene_wants_json():
            return jsonify({"ok": True, "row_id": int(row.id), "redirect": redirect_url})
        flash("Row added to this shooting day.", "success")
        return redirect(redirect_url)

