    @app.route(
        "/projects/<int:project_id>/shooting-day-scenes/<int:link_id>/runtime-take",
        methods=["POST"],
    )
    def shooting_day_scene_set_runtime_take(project_id: int, link_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_can_access_project(acc, project_id):
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": "forbidden"}), 403
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        link = shooting_day_scene_for_project(link_id, project_id)
        if link is None:
            abort(404)
        if not shooting_items_mod.is_runtime_eligible_row(link):
            msg = "Only scene versions can be used for episode runtime."
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(
                url_for(
                    "project_production_day",
                    project_id=project_id,
                    day_id=link.shooting_day_id,
                )
            )
        siblings = shooting_day_scene_runtime_siblings(project_id, link, exclude_link_id=link.id)
        try:
            shooting_items_mod.set_runtime_take(link, siblings)
        except ValueError as exc:
            if _assign_scene_wants_json():
                return jsonify({"ok": False, "error": str(exc)}), 400
            flash(str(exc), "error")
            return redirect(
                url_for(
                    "project_production_day",
                    project_id=project_id,
                    day_id=link.shooting_day_id,
                )
            )
        db.session.commit()
        redirect_url = url_for(
            "project_production_day", project_id=project_id, day_id=link.shooting_day_id
        )
        if _assign_scene_wants_json():
            return jsonify({"ok": True, "redirect": redirect_url})
        flash("Episode runtime take updated.", "success")
        return redirect(redirect_url)

    def _purge_shooting_day_scene_dependencies(scene_id: int) -> None:
        """Clear bookings, VFX files/rows, scene refs, and scene versions for one row.

        Does not delete the scene row. Required before removing a day or row so
        ``vfx_shot.scene_id`` and ``scene_version.scene_id`` are never set NULL.
        """
        sid = int(scene_id)
        Booking.query.filter_by(scene_id=sid).update(
            {Booking.scene_id: None},
            synchronize_session=False,
        )
        for mk in VfxSceneMarker.query.filter_by(scene_id=sid).all():
            seen_paths: set[str] = set()
            for attr in ("thumbnail", "thumbnail_full"):
                t = (getattr(mk, attr, None) or "").strip()
                if t and not _vfx_media_is_remote(t) and t not in seen_paths:
                    seen_paths.add(t)
                    remove_vfx_version_file(t)
        VfxSceneMarker.query.filter_by(scene_id=sid).delete(synchronize_session=False)
        shot_rows = VfxShot.query.filter(VfxShot.scene_id == sid).all()
        shot_ids = [int(s.id) for s in shot_rows]
        if shot_ids:
            for sh in shot_rows:
                rf = (sh.shot_ref_frame or "").strip()
                if rf and not _vfx_media_is_remote(rf):
                    remove_vfx_version_file(rf)
                ann = (sh.shot_annotation or "").strip()
                if ann and not _vfx_media_is_remote(ann):
                    remove_vfx_version_file(ann)
            for ver in VfxVersion.query.filter(VfxVersion.shot_id.in_(shot_ids)).all():
                img = (ver.image or "").strip()
                if img and not (
                    img.lower().startswith("http://") or img.lower().startswith("https://")
                ):
                    remove_vfx_version_file(img)
            VfxShotComment.query.filter(VfxShotComment.shot_id.in_(shot_ids)).delete(
                synchronize_session=False
            )
            VfxVersion.query.filter(VfxVersion.shot_id.in_(shot_ids)).delete(synchronize_session=False)
            VfxShot.query.filter(VfxShot.id.in_(shot_ids)).delete(synchronize_session=False)
        for rf in SceneReference.query.filter_by(scene_id=sid).all():
            remove_scene_reference_file(rf.video_url)
        SceneReference.query.filter_by(scene_id=sid).delete(synchronize_session=False)
        scene_version_rows = SceneVersion.query.filter_by(scene_id=sid).all()
        scene_version_ids = [int(sv.id) for sv in scene_version_rows]
        if scene_version_ids:
            SceneVersionComment.query.filter(
                SceneVersionComment.scene_version_id.in_(scene_version_ids)
            ).delete(synchronize_session=False)
            for sv in scene_version_rows:
                seen_paths: set[str] = set()
                for attr in ("file_path", "preview_file_path"):
                    rel = (getattr(sv, attr, None) or "").strip()
                    if not rel or rel in seen_paths:
                        continue
                    seen_paths.add(rel)
                    try:
                        disk_path = _episode_version_disk_path(rel)
                    except ValueError:
                        continue
                    if os.path.isfile(disk_path):
                        try:
                            os.remove(disk_path)
                        except OSError:
                            pass
            SceneVersion.query.filter(SceneVersion.id.in_(scene_version_ids)).delete(
                synchronize_session=False
            )

    @app.route(
        "/projects/<int:project_id>/shooting-day-scenes/<int:link_id>/delete",
        methods=["POST"],
    )
    def shooting_day_scene_delete(project_id: int, link_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        require_production_edit(acc, project_id)
        if not account_can_access_project(acc, project_id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        link = shooting_day_scene_for_project(link_id, project_id)
        if link is None:
            abort(404)
        # Safe Delete is required for this destructive action.
        if not safe_delete_request_present():
            wants_json = (
                request.is_json
                or "application/json" in (request.headers.get("Accept") or "")
                or (request.headers.get("X-VFX-Response") or "").strip().lower() == "json"
            )
            if wants_json:
                return (
                    jsonify(
                        {
                            "ok": False,
                            "error": "safe_delete_required",
                            "message": "Confirm with Safe Delete before removing this scene.",
                        }
                    ),
                    400,
                )
            flash("Confirm with Safe Delete before removing this scene.", "error")
            return redirect(
                url_for(
                    "project_production_day",
                    project_id=project_id,
                    day_id=link.shooting_day_id,
                )
            )
        safe_challenge, sd_err = safe_delete_guard(
            "scene", link_id, project_id=project_id
        )
        if sd_err is not None:
            return sd_err
        day_id = link.shooting_day_id
        thumb = (link.scene_thumbnail_frame or "").strip()
        import project_activity_hooks as pah

        pah.log_shooting_item_deleted(link, project_id=project_id, day=link.shooting_day)
        if thumb:
            remove_shooting_scene_thumbnail_file(thumb)
        _purge_shooting_day_scene_dependencies(link_id)
        db.session.delete(link)
        safe_delete_service.consume(safe_challenge)
        db.session.commit()
        log_security_event(
            "safe_delete_executed",
            account_id=acc.id if acc else None,
            entity_type="scene",
            entity_id=link_id,
            project_id=project_id,
            details={"challenge_id": safe_challenge.id, "delete_kind": "permanent"},
        )
        return jsonify(
            {
                "ok": True,
                "redirect": url_for(
                    "project_production_day", project_id=project_id, day_id=day_id
                ),
                "message": "Scene row removed from this day.",
            }
        )

