    @app.route("/projects/<int:project_id>/chat/search", methods=["GET"])
    def project_chat_search(project_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_may_use_project_chat(acc, project_id):
            return jsonify({"error": "forbidden"}), 403
        q = (request.args.get("q") or "").strip()
        if len(q) < 2:
            return jsonify({"ok": True, "results": [], "total": 0, "page": 1, "has_next": False})
        limit = min(max(request.args.get("limit", type=int) or 50, 1), 100)
        page = max(request.args.get("page", type=int) or 1, 1)
        like = f"%{q}%"
        base = ChatMessage.query.filter(
            ChatMessage.project_id == project_id,
            ChatMessage.is_deleted.is_(False),
            or_(
                ChatMessage.message.ilike(like),
                and_(ChatMessage.message.is_(None), ChatMessage.image_path.isnot(None)),
                and_(ChatMessage.message.is_(None), ChatMessage.audio_path.isnot(None)),
            ),
        )
        total = base.count()
        rows = (
            base.order_by(ChatMessage.id.desc())
            .offset((page - 1) * limit)
            .limit(limit)
            .all()
        )
        proj = Project.query.get(project_id)
        pname = (proj.name or "Project").strip() if proj else "Project"
        results = []
        for m in rows:
            u = m.user
            sender = (u.name or "Unknown").strip() if u else "Unknown"
            excerpt = chat_sup.message_search_excerpt(m.message, q)
            if not excerpt:
                excerpt = chat_sup.attachment_excerpt(
                    m.message, has_image=bool(m.image_path), has_audio=bool(m.audio_path)
                )
            results.append(
                {
                    "message_id": m.id,
                    "project_id": project_id,
                    "project_name": pname,
                    "sender_name": sender,
                    "message": excerpt,
                    "created_at": isoformat_stored_instant(m.created_at),
                    "has_image": bool(m.image_path),
                    "has_audio": bool(m.audio_path),
                    "url": chat_sup.chat_message_deep_link(project_id, m.id),
                }
            )
        return jsonify(
            {
                "ok": True,
                "results": results,
                "total": total,
                "page": page,
                "has_next": page * limit < total,
            }
        )

    @app.route("/chat/search", methods=["GET"])
    def chat_global_search():
        acc = account_from_session()
        if acc is None:
            return jsonify({"error": "forbidden"}), 403
        q = (request.args.get("q") or "").strip()
        if len(q) < 2:
            return jsonify({"ok": True, "results": [], "total": 0, "page": 1, "has_next": False})
        limit = min(max(request.args.get("limit", type=int) or 50, 1), 100)
        page = max(request.args.get("page", type=int) or 1, 1)
        accessible_threads = build_chat_threads_for_dashboard(acc)
        thread_ids = [int(t["thread_id"]) for t in accessible_threads if t.get("thread_id") is not None]
        if not thread_ids:
            return jsonify({"ok": True, "results": [], "total": 0, "page": 1, "has_next": False})
        tmap = {int(t["thread_id"]): t for t in accessible_threads if t.get("thread_id") is not None}
        like = f"%{q}%"
        base = ChatMessage.query.filter(
            ChatMessage.thread_id.in_(thread_ids),
            ChatMessage.is_deleted.is_(False),
            ChatMessage.message.ilike(like),
        )
        total = base.count()
        rows = (
            base.order_by(ChatMessage.id.desc())
            .offset((page - 1) * limit)
            .limit(limit)
            .all()
        )
        results = []
        for m in rows:
            meta = tmap.get(int(m.thread_id or 0), {})
            u = m.user
            sender = (u.name or "Unknown").strip() if u else "Unknown"
            thread_title = (meta.get("title") or "Chat").strip()
            thread_type = meta.get("thread_type") or "project"
            results.append(
                {
                    "message_id": m.id,
                    "thread_id": m.thread_id,
                    "thread_type": thread_type,
                    "thread_title": thread_title,
                    "project_id": meta.get("project_id"),
                    "project_name": thread_title if thread_type == chat_thr.THREAD_TYPE_PROJECT else None,
                    "sender_name": sender,
                    "message": chat_sup.message_search_excerpt(m.message, q),
                    "created_at": isoformat_stored_instant(m.created_at),
                    "has_image": bool(m.image_path),
                    "has_audio": bool(m.audio_path),
                    "url": url_for("chat_page", thread_id=m.thread_id, message_id=m.id),
                }
            )
        return jsonify(
            {
                "ok": True,
                "results": results,
                "total": total,
                "page": page,
                "has_next": page * limit < total,
            }
        )

    @app.route("/projects/<int:project_id>/chat/messages/<int:message_id>/pin", methods=["POST"])
    def project_chat_message_pin(project_id: int, message_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_may_use_project_chat(acc, project_id):
            return jsonify({"error": "forbidden"}), 403
        m = ChatMessage.query.filter_by(id=message_id, project_id=project_id).first()
        if m is None:
            return jsonify({"error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        note = (data.get("note") or "").strip() or None
        pin = ChatPinnedMessage.query.filter_by(project_id=project_id, message_id=message_id).first()
        if pin is None:
            pin = ChatPinnedMessage(
                project_id=project_id,
                message_id=message_id,
                pinned_by_account_id=acc.id,
                note=note,
            )
            db.session.add(pin)
        else:
            pin.is_active = True
            pin.pinned_by_account_id = acc.id
            pin.pinned_at = now_local()
            pin.note = note
        db.session.commit()
        emit_chat_updated(project_id, message_id, directory_user_id_for_account(acc), kind="pin")
        return jsonify({"ok": True})

