    @app.route(
        "/projects/<int:project_id>/chat/messages/<int:message_id>/create-action",
        methods=["POST"],
    )
    def project_chat_message_create_action(project_id: int, message_id: int):
        acc = db.session.get(Account, session.get("account_id"))
        if not account_may_use_project_chat(acc, project_id):
            return jsonify({"error": "forbidden"}), 403
        m = ChatMessage.query.filter_by(id=message_id, project_id=project_id).first()
        if m is None or m.is_deleted:
            return jsonify({"error": "not_found"}), 404
        data = request.get_json(silent=True) or {}
        msg_text = (m.message or "").strip()
        default_title = (msg_text[:80] + "…") if len(msg_text) > 80 else (msg_text or "Chat follow-up")
        title = (data.get("title") or default_title).strip()[:300]
        item_type = "note"
        priority = ab.normalize_priority(data.get("priority") or "normal")
        assignee = data.get("assigned_to_user_id")
        try:
            assignee_id = int(assignee) if assignee not in (None, "") else None
        except (TypeError, ValueError):
            assignee_id = None
        due = ab.parse_due_date(data.get("due_date"))
        creator_uid = directory_user_id_for_account(acc)
        if creator_uid is None:
            return jsonify({"error": "no_profile"}), 403
        chat_link = chat_sup.chat_message_deep_link(project_id, message_id)
        body_text = msg_text or chat_sup.attachment_excerpt(
            None, has_image=bool(m.image_path), has_audio=bool(m.audio_path)
        )
        body = f"{body_text}\n\nFrom chat: {chat_link}".strip()
        item = ActionItem(
            item_type=item_type,
            title=title,
            body=ab.normalize_action_board_body(body) or body,
            status="open",
            priority=priority,
            due_date=due,
            project_id=project_id,
            assigned_to_user_id=assignee_id or creator_uid,
            created_by_user_id=creator_uid,
            source_chat_message_id=message_id,
        )
        ab.apply_type_defaults(item, item_type)
        db.session.add(item)
        db.session.commit()
        emit_chat_updated(project_id, message_id, creator_uid, kind="action_created")
        return jsonify(
            {
                "ok": True,
                "message": "Action item created.",
                "action_item_id": item.id,
                "url": url_for("actions_page") + f"?highlight={item.id}",
            }
        )

