    @app.route("/chat/mentions", methods=["GET"])
    def chat_mentions_list():
        acc = account_from_session()
        if acc is None:
            return jsonify({"error": "forbidden"}), 403
        status = (request.args.get("status") or "all").strip().lower()
        q = ChatMention.query.filter_by(mentioned_account_id=acc.id)
        if status == "open":
            q = q.filter(ChatMention.is_resolved.is_(False))
        elif status == "resolved":
            q = q.filter(ChatMention.is_resolved.is_(True))
        rows = q.order_by(ChatMention.created_at.desc()).limit(200).all()
        results = []
        for row in rows:
            m = db.session.get(ChatMessage, row.message_id)
            proj = Project.query.get(row.project_id)
            sender_acc = db.session.get(Account, row.created_by_account_id)
            sender_name = "Someone"
            if sender_acc:
                suid = directory_user_id_for_account(sender_acc)
                if suid:
                    su = User.query.get(suid)
                    if su:
                        sender_name = (su.name or sender_name).strip()
            excerpt = ""
            if m and not m.is_deleted:
                excerpt = chat_sup.message_search_excerpt(m.message, "")
            results.append(
                {
                    "id": row.id,
                    "project_id": row.project_id,
                    "project_name": (proj.name or "Project").strip() if proj else "Project",
                    "message_id": row.message_id,
                    "sender_name": sender_name,
                    "message_excerpt": excerpt,
                    "created_at": isoformat_stored_instant(row.created_at),
                    "is_resolved": bool(row.is_resolved),
                    "url": chat_sup.chat_message_deep_link(row.project_id, row.message_id),
                }
            )
        return jsonify({"ok": True, "mentions": results})

