    def _notification_management_guard(action: str = "view") -> Account:
        acc = account_from_session()
        if acc is None:
            abort(403)
        if acc.is_admin:
            return acc
        if not perm_svc.can(acc, "notification_management", action):
            abort(403)
        return acc

    def _rule_config_from_form() -> tuple[dict, list[str]]:
        errors: list[str] = []
        event_key = (request.form.get("event_key") or "").strip()
        label = (request.form.get("label") or "").strip()
        category = (request.form.get("category") or "general").strip()
        priority = (request.form.get("priority") or "normal").strip()
        recipient_mode = (request.form.get("recipient_mode") or "mixed").strip()
        title_template = (request.form.get("title_template") or "").strip()
        body_template = (request.form.get("body_template") or "").strip()
        if not event_key:
            errors.append("Event key is required.")
        if not label:
            errors.append("Label is required.")
        if not title_template:
            errors.append("Title template is required.")
        if not body_template:
            errors.append("Body template is required.")
        if category not in NOTIFICATION_RULE_CATEGORIES:
            errors.append("Invalid category.")
        if priority not in NOTIFICATION_RULE_PRIORITIES:
            errors.append("Invalid priority.")
        if recipient_mode not in NOTIFICATION_RULE_RECIPIENT_MODES:
            errors.append("Invalid recipient mode.")
        try:
            dedupe_window = max(0, int(request.form.get("dedupe_window_minutes") or 0))
        except (TypeError, ValueError):
            dedupe_window = 30
            errors.append("Dedupe window must be a number.")
        recipient_config = {
            "user_ids": [int(x) for x in request.form.getlist("user_ids") if str(x).isdigit()],
            "job_titles": [x.strip() for x in request.form.getlist("job_titles") if x.strip()],
            "post_scopes": [x.strip() for x in request.form.getlist("post_scopes") if x.strip()],
            "project_roles": [x.strip() for x in request.form.getlist("project_roles") if x.strip()],
            "dynamic": [x.strip() for x in request.form.getlist("dynamic") if x.strip()],
        }
        preset_key = (request.form.get("recipient_preset") or "").strip()
        preset = notif_events.RECIPIENT_PRESETS.get(preset_key, {}) if preset_key else {}
        for key, values in preset.items():
            if isinstance(values, list):
                merged = list(recipient_config.get(key, []))
                for val in values:
                    if val not in merged:
                        merged.append(val)
                recipient_config[key] = merged
        raw_conditions = (request.form.get("condition_config_json") or "{}").strip() or "{}"
        try:
            parsed_conditions = json.loads(raw_conditions)
            if not isinstance(parsed_conditions, dict):
                errors.append("Conditions JSON must be an object.")
        except ValueError:
            parsed_conditions = {}
            errors.append("Conditions JSON is invalid.")
        return (
            {
                "event_key": event_key,
                "label": label,
                "description": (request.form.get("description") or "").strip(),
                "category": category,
                "is_enabled": bool(request.form.get("is_enabled")),
                "priority": priority,
                "title_template": title_template,
                "body_template": body_template,
                "cta_label_template": (request.form.get("cta_label_template") or "").strip() or None,
                "cta_url_template": (request.form.get("cta_url_template") or "").strip() or None,
                "recipient_mode": recipient_mode,
                "recipient_config_json": json.dumps(recipient_config),
                "condition_config_json": json.dumps(parsed_conditions),
                "exclude_actor": bool(request.form.get("exclude_actor")),
                "dedupe_enabled": bool(request.form.get("dedupe_enabled")),
                "dedupe_window_minutes": dedupe_window,
            },
            errors,
        )

    def _notification_rule_admin_choices() -> dict:
        from project_settings import POST_SCOPE_FIELDS, post_scope_labels

        scope_labels = post_scope_labels()
        return {
            "users": User.query.order_by(User.name.asc()).all(),
            "job_titles": JobTitle.query.order_by(JobTitle.name.asc()).all(),
            "post_scopes": [
                (key, scope_labels.get(key, label or key.replace("_", " ").title()))
                for key, label, _hint in POST_SCOPE_FIELDS
            ],
            "project_roles": NOTIFICATION_PROJECT_ROLES,
            "dynamic": NOTIFICATION_DYNAMIC_RECIPIENTS,
            "categories": NOTIFICATION_RULE_CATEGORIES,
            "priorities": NOTIFICATION_RULE_PRIORITIES,
            "recipient_modes": NOTIFICATION_RULE_RECIPIENT_MODES,
            "projects": Project.query.order_by(Project.name.asc()).all(),
        }

    def _notification_rule_summary(rule: NotificationRule) -> str:
        cfg = _notification_json(rule.recipient_config_json, {})
        bits = []
        if cfg.get("user_ids"):
            bits.append(f"{len(cfg.get('user_ids') or [])} users")
        if cfg.get("job_titles"):
            bits.append("Titles: " + ", ".join(cfg["job_titles"][:3]))
        if cfg.get("post_scopes"):
            bits.append("Scopes: " + ", ".join(cfg["post_scopes"][:3]))
        if cfg.get("project_roles"):
            bits.append("Roles: " + ", ".join(cfg["project_roles"][:3]))
        if cfg.get("dynamic"):
            bits.append("Dynamic: " + ", ".join(cfg["dynamic"][:3]))
        return " · ".join(bits) or rule.recipient_mode

    @app.route("/admin/notification-management")
    def admin_notification_management():
        _notification_management_guard("view")
        sync_registered_notification_events_to_rules()
        active_tab = (request.args.get("tab") or "rules").strip().lower()
        if active_tab not in ("rules", "events", "audit"):
            active_tab = "rules"
        today_start = datetime.combine(today_cairo(), datetime.min.time())
        q = NotificationRule.query
        search = (request.args.get("search") or "").strip()
        category = (request.args.get("category") or "").strip()
        enabled = (request.args.get("enabled") or "").strip()
        if search:
            like = f"%{search}%"
            q = q.filter(or_(NotificationRule.event_key.ilike(like), NotificationRule.label.ilike(like), NotificationRule.description.ilike(like)))
        if category:
            q = q.filter(NotificationRule.category == category)
        if enabled == "enabled":
            q = q.filter(NotificationRule.is_enabled.is_(True))
        elif enabled == "disabled":
            q = q.filter(NotificationRule.is_enabled.is_(False))
        rules = q.order_by(NotificationRule.category.asc(), NotificationRule.event_key.asc()).all()
        total_rules = NotificationRule.query.count()
        enabled_rules = NotificationRule.query.filter(NotificationRule.is_enabled.is_(True)).count()
        sent_today = NotificationRuleAuditLog.query.filter(NotificationRuleAuditLog.created_at >= today_start, NotificationRuleAuditLog.status.in_(("sent", "sent_test"))).count()
        skipped_today = NotificationRuleAuditLog.query.filter(NotificationRuleAuditLog.created_at >= today_start, NotificationRuleAuditLog.status.like("skipped%")).count()
        failed_today = NotificationRuleAuditLog.query.filter(NotificationRuleAuditLog.created_at >= today_start, NotificationRuleAuditLog.status == "failed").count()
        default_keys = {x["event_key"] for x in DEFAULT_NOTIFICATION_RULES}
        rules_by_key = {r.event_key: r for r in NotificationRule.query.all()}
        registered_rows = []
        for event_key, event in get_registered_notification_events().items():
            rule = rules_by_key.get(event_key)
            last = (
                NotificationRuleAuditLog.query.filter_by(event_key=event_key)
                .order_by(NotificationRuleAuditLog.created_at.desc(), NotificationRuleAuditLog.id.desc())
                .first()
            )
            registered_rows.append(
                {
                    "event_key": event_key,
                    "label": event.get("label") or event_key.replace("_", " ").title(),
                    "category": event.get("category", "general"),
                    "source": event.get("source") or event.get("source_feature") or "System",
                    "source_file": event.get("source_file") or "",
                    "source_function": event.get("source_function") or "",
                    "variables": event.get("variables") or [],
                    "connected": bool(event.get("is_active", True)),
                    "status": event.get("status") or ("active" if event.get("is_active", True) else "not connected"),
                    "rule": rule,
                    "rule_exists": rule is not None,
                    "rule_enabled": bool(rule and rule.is_enabled),
                    "last_sent": format_datetime_cairo(last.created_at) if last is not None else "—",
                    "last_status": last.status if last is not None else "not sent",
                }
            )
        return render_template(
            "admin_notification_management.html",
            rules=rules,
            recipient_summary=_notification_rule_summary,
            filters={"search": search, "category": category, "enabled": enabled},
            summary={
                "total": total_rules,
                "enabled": enabled_rules,
                "disabled": max(0, total_rules - enabled_rules),
                "sent_today": sent_today,
                "skipped_today": skipped_today,
                "failed_today": failed_today,
            },
            categories=NOTIFICATION_RULE_CATEGORIES,
            default_keys=default_keys,
            registered_events=registered_rows,
            discovered_events=registered_rows,
            active_tab=active_tab,
        )

    @app.route("/admin/notification-management/rules/new", methods=["GET", "POST"])
    @app.route("/admin/notification-management/rules/<int:rule_id>", methods=["GET", "POST"])
    def admin_notification_rule_edit(rule_id: int | None = None):
        acc = _notification_management_guard("edit" if rule_id else "create")
        rule = db.session.get(NotificationRule, int(rule_id)) if rule_id else None
        if rule_id and rule is None:
            abort(404)
        if request.method == "POST":
            data, errors = _rule_config_from_form()
            exists = NotificationRule.query.filter(NotificationRule.event_key == data["event_key"])
            if rule is not None:
                exists = exists.filter(NotificationRule.id != int(rule.id))
            if exists.first() is not None:
                errors.append("A rule with this event key already exists.")
            if not errors:
                if rule is None:
                    rule = NotificationRule(created_at=now_local(), source="Custom", registered_event=False)
                    db.session.add(rule)
                for key, value in data.items():
                    setattr(rule, key, value)
                rule.updated_at = now_local()
                rule.updated_by_id = directory_user_id_for_account(acc)
                db.session.commit()
                flash("Notification rule saved.", "success")
                return redirect(url_for("admin_notification_management"))
            for msg in errors:
                flash(msg, "error")
        return render_template(
            "admin_notification_rule_edit.html",
            rule=rule,
            choices=_notification_rule_admin_choices(),
            config=_notification_json(rule.recipient_config_json, {}) if rule else {},
            condition_json=(rule.condition_config_json if rule else "{}"),
            registered_event=get_registered_notification_event(rule.event_key) if rule else None,
            available_variables=_notification_json(rule.available_variables_json, []) if rule else [],
            recipient_presets=notif_events.RECIPIENT_PRESETS,
        )

