    @app.post("/admin/notification-management/rules/<int:rule_id>/duplicate")
    def admin_notification_rule_duplicate(rule_id: int):
        _notification_management_guard("create")
        rule = db.session.get(NotificationRule, int(rule_id)) or abort(404)
        base_key = f"{rule.event_key}_copy"
        key = base_key
        i = 2
        while NotificationRule.query.filter_by(event_key=key).first() is not None:
            key = f"{base_key}_{i}"
            i += 1
        copy = NotificationRule(
            event_key=key,
            label=f"{rule.label} copy",
            description=rule.description,
            category=rule.category,
            is_enabled=False,
            priority=rule.priority,
            title_template=rule.title_template,
            body_template=rule.body_template,
            cta_label_template=rule.cta_label_template,
            cta_url_template=rule.cta_url_template,
            recipient_mode=rule.recipient_mode,
            recipient_config_json=rule.recipient_config_json,
            condition_config_json=rule.condition_config_json,
            exclude_actor=rule.exclude_actor,
            dedupe_enabled=rule.dedupe_enabled,
            dedupe_window_minutes=rule.dedupe_window_minutes,
            created_at=now_local(),
        )
        db.session.add(copy)
        db.session.commit()
        flash("Rule duplicated. It is disabled until you enable it.", "success")
        return redirect(url_for("admin_notification_rule_edit", rule_id=copy.id))

    @app.post("/admin/notification-management/rules/<int:rule_id>/restore-default")
    def admin_notification_rule_restore_default(rule_id: int):
        acc = _notification_management_guard("restore_defaults")
        rule = db.session.get(NotificationRule, int(rule_id)) or abort(404)
        event = get_registered_notification_event(rule.event_key)
        if event is None:
            flash("This rule has no default definition.", "error")
            return redirect(url_for("admin_notification_management"))
        spec = _registry_rule_spec(rule.event_key, event)
        for key, value in spec.items():
            if key != "event_key":
                setattr(rule, key, value)
        rule.updated_by_id = directory_user_id_for_account(acc)
        rule.updated_at = now_local()
        db.session.commit()
        flash("Default rule restored.", "success")
        return redirect(url_for("admin_notification_rule_edit", rule_id=rule_id))

