    @app.route("/admin/notification-management/rules/<int:rule_id>/test", methods=["GET", "POST"])
    def admin_notification_rule_test(rule_id: int):
        acc = _notification_management_guard("test")
        rule = db.session.get(NotificationRule, int(rule_id)) or abort(404)
        choices = _notification_rule_admin_choices()
        preview = None
        if request.method == "POST":
            project = db.session.get(Project, int(request.form.get("project_id"))) if str(request.form.get("project_id") or "").isdigit() else None
            actor_acc = acc
            actor_user_id = request.form.get("actor_user_id")
            if str(actor_user_id or "").isdigit():
                actor_user = db.session.get(User, int(actor_user_id))
                if actor_user and actor_user.account_id:
                    actor_acc = db.session.get(Account, int(actor_user.account_id)) or acc
            context = {
                "project_id": int(project.id) if project else "",
                "project_name": project.name if project else "Example Project",
                "editing_item_id": request.form.get("editing_item_id") or 0,
                "editing_item_code": request.form.get("editing_item_code") or "EP01",
                "editing_item_title": request.form.get("editing_item_title") or "Example Item",
                "task_id": request.form.get("task_id") or 0,
                "task_title": request.form.get("task_title") or "Example Task",
                "task_priority": request.form.get("task_priority") or "normal",
                "handoff_file_label": request.form.get("handoff_file_label") or "XML · example.xml",
                "guide_video_label": request.form.get("guide_video_label") or "guide.mov",
                "failure_reason": request.form.get("failure_reason") or "",
                "failure_types": request.form.get("failure_types") or "",
            }
            recipients = resolve_notification_recipients(rule, project, actor_acc, context)
            title = render_notification_template(rule.title_template, context)
            body = render_notification_template(rule.body_template, context)
            cta_label = render_notification_template(rule.cta_label_template, context)
            cta_url = render_notification_template(rule.cta_url_template, context)
            used_vars = {
                m.group(1)
                for template in (rule.title_template, rule.body_template, rule.cta_label_template, rule.cta_url_template)
                for m in _NOTIFICATION_TEMPLATE_RE.finditer(template or "")
            }
            missing_vars = sorted(v for v in used_vars if context.get(v) in (None, ""))
            preview = {
                "recipients": recipients,
                "title": title,
                "body": body,
                "cta_label": cta_label,
                "cta_url": cta_url,
                "missing_variables": missing_vars,
            }
            if request.form.get("send_test"):
                send_ids = [int(x) for x in request.form.getlist("test_recipient_ids") if str(x).isdigit()]
                if not send_ids:
                    current_uid = directory_user_id_for_account(acc)
                    send_ids = [int(current_uid)] if current_uid else []
                sent = send_managed_notification(
                    rule.event_key,
                    project=project,
                    actor=actor_acc,
                    context=context,
                    test_recipient_user_ids=send_ids,
                    is_test=True,
                )
                db.session.commit()
                flash(f"Sent test notification to {len(sent)} user(s).", "success")
        return render_template(
            "admin_notification_rule_test.html",
            rule=rule,
            choices=choices,
            preview=preview,
        )

