    @app.post("/api/notifications/events/<event_key>/send")
    def api_send_registered_notification_event(event_key: str):
        acc = account_from_session()
        if acc is None:
            return jsonify({"ok": False, "error": "auth"}), 401
        key = (event_key or "").strip()
        registered = get_registered_notification_event(key)
        rule = NotificationRule.query.filter_by(event_key=key).first()
        if registered is None and rule is None:
            return jsonify({"ok": False, "error": "unknown_event"}), 404
        if registered is not None and rule is None:
            rule = ensure_notification_rule_for_event(key)
            db.session.commit()
        payload = request.get_json(silent=True) or {}
        try:
            project_id = int(payload.get("project_id") or 0)
        except (TypeError, ValueError):
            project_id = 0
        project = db.session.get(Project, project_id) if project_id else None
        if project is not None and not account_can_access_project(acc, int(project.id)):
            return jsonify({"ok": False, "error": "forbidden"}), 403
        if project is None and not (acc.is_admin or perm_svc.can(acc, "notification_management", "test")):
            return jsonify({"ok": False, "error": "project_required"}), 400
        context = payload.get("context") or {}
        if not isinstance(context, dict):
            return jsonify({"ok": False, "error": "bad_context"}), 400
        sent = send_managed_notification(
            key,
            project=project,
            actor=acc,
            context=context,
        )
        db.session.commit()
        return jsonify({"ok": True, "sent": len(sent), "recipient_ids": [int(u.id) for u in sent]})

    @app.route("/admin/task-log")
    def admin_task_log():
        import admin_task_log_support as atl

        acc = account_from_session()
        if acc is None or not acc.is_admin:
            abort(403)
        if not perm_svc.can(acc, "task_log", "view"):
            abort(403)

        filters = atl.parse_task_log_filters(request.args)
        per_page = 50
        q = Task.query.options(
            joinedload(Task.project),
            joinedload(Task.assignee),
            joinedload(Task.requested_by),
            joinedload(Task.task_notes),
        )
        q = atl.apply_task_log_filters(q, Task=Task, Project=Project, User=User, filters=filters)
        summary = atl.compute_task_log_summary_from_query(q, Task=Task)
        total = int(summary["total"])
        pages = max(1, math.ceil(total / per_page)) if total else 1
        page = min(int(filters["page"]), pages)
        tasks = (
            q.order_by(*atl.task_log_sort_clauses(Task))
            .offset((page - 1) * per_page)
            .limit(per_page)
            .all()
        )
        rows = [
            atl.serialize_task_log_row(
                t,
                format_datetime=format_datetime_cairo,
                format_date=lambda d: format_datetime_cairo(d, "%Y-%m-%d") if d else "—",
                url_for=url_for,
            )
            for t in tasks
        ]
        filters_for_urls = {**filters, "page": page}
        prev_url = atl.task_log_page_url("admin_task_log", filters_for_urls, page=page - 1, url_for=url_for)
        next_url = atl.task_log_page_url("admin_task_log", filters_for_urls, page=page + 1, url_for=url_for)
        projects = Project.query.order_by(Project.name.asc()).all()
        users = User.query.order_by(User.name.asc()).all()
