    def _chat_orphan_attachment_files() -> tuple[list[dict], int]:
        referenced: set[str] = set()
        for path_col in (ChatMessage.image_path, ChatMessage.audio_path):
            for row in db.session.query(path_col).filter(path_col.isnot(None)).all():
                val = (row[0] or "").strip()
                if val:
                    referenced.add(val)
        orphans: list[dict] = []
        total_size = 0
        if os.path.isdir(chat_upload_root):
            for fname in os.listdir(chat_upload_root):
                if fname.startswith("."):
                    continue
                if fname not in referenced:
                    fpath = os.path.join(chat_upload_root, fname)
                    if os.path.isfile(fpath):
                        sz = os.path.getsize(fpath)
                        total_size += sz
                        orphans.append(
                            {
                                "filename": fname,
                                "size_bytes": sz,
                                "created_at": isoformat_stored_instant(
                                    datetime.fromtimestamp(os.path.getmtime(fpath))
                                ),
                            }
                        )
        return orphans, total_size

