    def admin_chat_attachment_orphans():
        acc = account_from_session()
        if acc is None or not acc.is_admin:
            return jsonify({"error": "forbidden"}), 403
        orphans, total_size = _chat_orphan_attachment_files()
        return jsonify(
            {"ok": True, "orphans": orphans, "total_size_bytes": total_size}
        )

    @app.route("/admin/chat/attachments/orphans/delete", methods=["POST"])
    def admin_chat_attachment_orphans_delete():
        acc = account_from_session()
        if acc is None or not acc.is_admin:
            return jsonify({"error": "forbidden"}), 403
        data = request.get_json(silent=True) or {}
        if not data.get("confirm"):
            return jsonify({"error": "confirm_required"}), 400
        orphans, _ = _chat_orphan_attachment_files()
        removed = 0
        for item in orphans:
            fname = (item.get("filename") or "").strip()
            if fname:
                remove_chat_upload_file(fname)
                removed += 1
        return jsonify({"ok": True, "removed": removed})

    def _max_episode_number_in_use(project_id: int) -> int:
        mx_scene = (
            db.session.query(db.func.max(ShootingDayScene.episode_number))
            .join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
            .filter(ShootingDay.project_id == project_id)
            .scalar()
        )
        mx_pipe = (
            db.session.query(db.func.max(ProductionEpisode.episode_number))
            .filter_by(project_id=project_id)
            .scalar()
        )
        return max(int(mx_scene or 0), int(mx_pipe or 0))

    @app.route("/projects/<int:project_id>/settings", methods=["GET", "POST"])
    def project_settings(project_id: int):
        from project_settings import (
            DELIVERY_AUDIO_FORMAT_OPTIONS,
            DELIVERY_COLOR_SPACE_OPTIONS,
            DELIVERY_FRAME_RATE_OPTIONS,
            DELIVERY_RESOLUTION_OPTIONS,
            LIFECYCLE_STATUS_LABELS,
            LIFECYCLE_STATUS_VALUES,
            POST_SCOPE_FIELDS,
            PRIORITY_LABELS,
            PRIORITY_VALUES,
            PROJECT_TYPE_LABELS,
            PROJECT_TYPE_SLUGS,
            apply_settings_to_project,
            normalize_project_type_slug,
            parse_settings_form,
            project_type_display_label,
        )

        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_view_project_settings_for(actor, project_id):
            flash(
                "Only administrators, super users, producers, Post-production Team, or Editing Team members on this project can open project settings.",
                "error",
            )
            return redirect(url_for("project_detail", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))

        settings_editable = account_can_edit_project_settings_for(actor, project_id)
        can_manage_delivery_docs = account_can_manage_delivery_documents_for(
            actor, project_id
        )
        max_ep_in_use = _max_episode_number_in_use(p.id)
        type_slug = normalize_project_type_slug(p.project_type)

        if request.method == "POST":
            if not settings_editable:
                flash(
                    "Editing Team can preview project settings only. Ask a producer or administrator to make changes.",
                    "error",
                )
                return redirect(url_for("project_settings", project_id=p.id))
            ok, errors, data = parse_settings_form(
                request.form,
                current_type_slug=type_slug,
                max_episode_in_use=max_ep_in_use,
            )
            if not ok:
                for err in errors:
                    flash(err, "error")
                return redirect(url_for("project_settings", project_id=p.id))

            pm_id = data.get("project_manager_id")
            if pm_id is not None:
                if User.query.get(pm_id) is None:
                    flash("Selected project manager was not found.", "error")
                    return redirect(url_for("project_settings", project_id=p.id))

            try:
                import project_activity_hooks as pah
                import project_activity_service as pas

                before_settings = pas.project_settings_snapshot(p)
                apply_settings_to_project(p, data)
                after_settings = pas.project_settings_snapshot(p, data)
                settings_changes = pas.build_change_set(
                    before_settings, after_settings, pas.PROJECT_SETTINGS_TRACKED_FIELDS
                )
                pah.log_settings_updated(p.id, settings_changes)
                p.settings_updated_at = now_local()
                editor_uid = directory_user_id_for_account(actor)
                p.settings_updated_by_id = editor_uid
                db.session.commit()
                if _project_type_is_tv_series(p.project_type):
                    ensure_production_episode_rows(p)
            except Exception:
                db.session.rollback()
                app.logger.exception("project_settings save failed")
                flash("Could not save settings. Check the server log or try again.", "error")
                return redirect(url_for("project_settings", project_id=p.id))
            flash("Project settings saved.", "success")
            sync_scope = app.extensions.get("editing_items_sync_post_scope")
            if sync_scope:
                try:
                    sync_scope(p)
                    db.session.commit()
                except Exception:
                    db.session.rollback()
                    app.logger.exception("editing items post-scope sync failed")
            return redirect(url_for("project_settings", project_id=p.id))

        member_ids = {m.user_id for m in p.memberships}
        member_users = []
        if member_ids:
            member_users = (
                User.query.options(joinedload(User.job_title))
                .filter(User.id.in_(member_ids))
                .order_by(User.name)
                .all()
            )
        manager_candidates = (
            User.query.options(joinedload(User.job_title))
            .filter(User.id.in_(member_ids))
            .order_by(User.name)
            .all()
            if member_ids
            else []
        )
        creator_user = None
        if p.created_at:
            first_member = (
                ProjectMember.query.filter_by(project_id=p.id)
                .order_by(ProjectMember.id.asc())
                .first()
            )
            if first_member:
                creator_user = db.session.get(User, first_member.user_id)

        settings_meta_user = p.settings_updated_by
        production_company = (p.production_company or p.production_house or "")

        import job_titles_master_support as jtms_settings
        from project_settings import (
            count_project_team_members_for_scope,
            project_enabled_post_scope_fields,
        )
        import folder_structure_support as fs_support

        project_team_structure = []
        for key, label, _hint in project_enabled_post_scope_fields(p):
            eligible = jtms_settings.get_users_eligible_for_post_scope(
                key,
                User=User,
                UserJobTitle=UserJobTitle,
                JobTitle=JobTitle,
                SystemMasterEntry=SystemMasterEntry,
                JobTitlePostScopeLink=JobTitlePostScopeLink,
                JobCategoryPostScopeLink=JobCategoryPostScopeLink,
                project_id=int(p.id),
                active_only=True,
            )
            project_team_structure.append(
                {
                    "scope_key": key,
                    "scope_label": label,
                    "eligible_count": len(eligible),
                    "member_count": count_project_team_members_for_scope(member_users, key),
                }
            )

        return render_template(
            "project_settings.html",
            project=p,
            workflow_active="settings",
            type_slug=type_slug,
            type_label=project_type_display_label(p.project_type),
            production_company=production_company,
            project_type_slugs=PROJECT_TYPE_SLUGS,
            project_type_labels=PROJECT_TYPE_LABELS,
            lifecycle_status_values=LIFECYCLE_STATUS_VALUES,
            lifecycle_status_labels=LIFECYCLE_STATUS_LABELS,
            priority_values=PRIORITY_VALUES,
            priority_labels=PRIORITY_LABELS,
            post_scope_fields=POST_SCOPE_FIELDS,
            delivery_resolution_options=DELIVERY_RESOLUTION_OPTIONS,
            delivery_frame_rate_options=DELIVERY_FRAME_RATE_OPTIONS,
            delivery_color_space_options=DELIVERY_COLOR_SPACE_OPTIONS,
            delivery_audio_format_options=DELIVERY_AUDIO_FORMAT_OPTIONS,
            member_users=member_users,
            manager_candidates=manager_candidates,
            creator_user=creator_user,
            settings_meta_user=settings_meta_user,
            max_episode_in_use=max_ep_in_use,
            project_status_label=project_status_label(p.project_status),
            project_team_structure=project_team_structure,
            folder_template_options=fs_support.folder_template_options_for_project(p),
            custom_folder_templates=fs_support.list_custom_templates_for_project(p),
            can_manage_project_folders=account_can_manage_project_folders_for(actor, p.id),
            default_safe_folder_name=fs_support.safe_project_folder_name(p.name, p.id),
            display_project_root_path=fs_support.sanitize_project_root_path(
                p.project_root_path, fs_support.effective_project_folder_name(p)
            ),
            legacy_storage_paths=fs_support.legacy_storage_paths_for_settings_form(p),
            storage_summary=fs_support.storage_summary_for_project(p),
            delivery_documents=(
                ProjectDeliveryDocument.query.filter_by(project_id=p.id)
                .order_by(ProjectDeliveryDocument.uploaded_at.desc(), ProjectDeliveryDocument.id.desc())
                .all()
            ),
            settings_editable=settings_editable,
            can_manage_delivery_docs=can_manage_delivery_docs,
        )

    @app.route("/projects/<int:project_id>/settings/delivery-docs", methods=["POST"])
    def project_delivery_document_upload(project_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_manage_delivery_documents_for(actor, project_id):
            flash("You do not have permission to upload delivery documents.", "error")
            return redirect(url_for("project_detail", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        upload_part = request.files.get("delivery_doc")
        if not upload_part or not str(upload_part.filename or "").strip():
            flash("Choose a PDF file to upload.", "error")
            return redirect(url_for("project_settings", project_id=p.id))
        orig = secure_filename(upload_part.filename) or "requirements.pdf"
        ext = os.path.splitext(orig)[1].lower()
        if ext not in DELIVERY_DOC_ALLOWED_EXT:
            flash("Technical requirements must be PDF files.", "error")
            return redirect(url_for("project_settings", project_id=p.id))
        raw = upload_part.read()
        if len(raw) > DELIVERY_DOC_UPLOAD_MAX_BYTES:
            flash("File is too large (max 50 MB).", "error")
            return redirect(url_for("project_settings", project_id=p.id))
        if not raw.startswith(b"%PDF"):
            flash("The file does not look like a valid PDF.", "error")
            return redirect(url_for("project_settings", project_id=p.id))
        stored = f"p{p.id}-delivery-{uuid.uuid4().hex}{ext}"
        dest = os.path.join(delivery_doc_upload_root, stored)
        try:
            with open(dest, "wb") as out:
                out.write(raw)
        except OSError:
            flash("Could not save the file.", "error")
            return redirect(url_for("project_settings", project_id=p.id))
        doc = ProjectDeliveryDocument(
            project_id=p.id,
            stored_file=stored,
            original_name=orig[:255],
            size_bytes=len(raw),
            uploaded_by_id=directory_user_id_for_account(actor),
        )
        db.session.add(doc)
        try:
            db.session.commit()
            flash(f"Uploaded “{orig}”.", "success")
        except Exception:
            db.session.rollback()
            remove_delivery_document_file(stored)
            app.logger.exception("delivery document upload failed")
            flash("Could not save the file.", "error")
        return redirect(url_for("project_settings", project_id=p.id))

    @app.route("/projects/<int:project_id>/settings/delivery-docs/<int:doc_id>", methods=["GET"])
    def project_delivery_document_file(project_id: int, doc_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None:
            abort(404)
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            abort(403)
        doc = ProjectDeliveryDocument.query.filter_by(id=doc_id, project_id=p.id).first_or_404()
        basename = (doc.stored_file or "").strip()
        if not basename or "/" in basename or "\\" in basename or basename.startswith("."):
            abort(404)
        download_name = (doc.original_name or "technical-requirements.pdf").strip()
        if not download_name.lower().endswith(".pdf"):
            download_name = f"{download_name}.pdf"
        return send_from_directory(
            delivery_doc_upload_root,
            basename,
            mimetype="application/pdf",
            as_attachment=False,
            download_name=download_name,
        )

