    @app.route("/projects/<int:project_id>/edit", methods=["GET", "POST"])
    def project_edit(project_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_may_full_control_project(actor, project_id):
            flash(
                "Only administrators, super users, producers, or Post-production Team members on this project can edit project details.",
                "error",
            )
            return redirect(url_for("project_detail", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        if request.method == "POST":
            name = (request.form.get("name") or "").strip()
            project_type = (request.form.get("project_type") or "").strip()
            production_house = (request.form.get("production_house") or "").strip()
            director = (request.form.get("director") or "").strip()
            if not name or not project_type or not production_house or not director:
                flash("All fields are required.", "error")
                return redirect(url_for("project_edit", project_id=p.id))
            try:
                number_of_episodes = max(
                    0, int((request.form.get("number_of_episodes") or "0").strip() or 0)
                )
            except (TypeError, ValueError):
                number_of_episodes = 0
            if not _project_type_is_tv_series(project_type):
                number_of_episodes = 0
            try:
                estimated_shooting_days = max(
                    0, int((request.form.get("estimated_shooting_days") or "0").strip() or 0)
                )
            except (TypeError, ValueError):
                estimated_shooting_days = 0
            try:
                estimated_episode_duration_minutes = max(
                    0,
                    int(
                        (request.form.get("estimated_episode_duration_minutes") or "0").strip()
                        or 0
                    ),
                )
            except (TypeError, ValueError):
                estimated_episode_duration_minutes = 0
            try:
                p.name = name
                p.project_type = project_type
                p.production_house = production_house
                p.director = director
                p.number_of_episodes = number_of_episodes
                p.estimated_shooting_days = estimated_shooting_days
                p.estimated_episode_duration_minutes = estimated_episode_duration_minutes
                db.session.commit()
            except Exception:
                db.session.rollback()
                app.logger.exception("project_edit save failed")
                flash("Could not save changes. Check the server log or try again.", "error")
                return redirect(url_for("project_edit", project_id=p.id))
            flash("Project updated.", "success")
            raw_next = (request.form.get("next") or "").strip()
            if raw_next.startswith("/projects") and not raw_next.startswith("//"):
                return redirect(raw_next)
            return redirect(url_for("project_detail", project_id=p.id))
        return render_template("project_edit.html", project=p)

    @app.route("/projects/<int:project_id>/members/add", methods=["GET", "POST"])
    def project_members_add(project_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_manage_project_team_for(actor, project_id):
            flash(
                "Only administrators, super users, producers, or Post-production Team members on this project can change project teams.",
                "error",
            )
            return redirect(url_for("projects_list"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        if request.method == "GET":
            return redirect(url_for("project_team", project_id=p.id))
        raw_ids = request.form.getlist("user_ids")
        if not raw_ids:
            single = request.form.get("user_id")
            if single:
                raw_ids = [single]
        candidate_ids: list[int] = []
        for raw in raw_ids:
            try:
                uid = int(raw)
            except (TypeError, ValueError):
                continue
            if uid not in candidate_ids:
                candidate_ids.append(uid)
        if not candidate_ids:
            flash("Choose at least one user from the list to add.", "error")
            return redirect(url_for("project_team", project_id=p.id))

        scope_filter = (request.form.get("assigned_post_scope_code") or "").strip() or None
        assignment_role = (request.form.get("assignment_role_type") or "").strip() or None
        employment_override = request.form.get("employment_override") in ("1", "on", "true", True)
        eligibility_override = request.form.get("eligibility_override") in ("1", "on", "true", True)
        override_reason = (request.form.get("employment_override_reason") or "").strip() or None
        if not override_reason:
            override_reason = (request.form.get("eligibility_override_reason") or "").strip() or None
        import employment_structure_support as esup
        import job_titles_master_support as jtms_add
        from project_settings import post_scope_key_set

        valid_scope_keys = post_scope_key_set()
        if scope_filter and scope_filter not in valid_scope_keys:
            scope_filter = None

        existing_members = {
            int(m.user_id): m
            for m in ProjectMember.query.filter_by(project_id=p.id).all()
            if m.user_id is not None
        }
        known_member_ids = set(existing_members.keys())
        users_by_id = {
            int(u.id): u
            for u in User.query.options(joinedload(User.account))
            .filter(User.id.in_(candidate_ids))
            .all()
        }
        added = 0
        updated = 0
        skipped_missing = 0
        skipped_existing = 0
        skipped_machine_room = 0
        skipped_ineligible = 0
        skipped_account_restricted = 0
        try:
            for uid in candidate_ids:
                if uid not in users_by_id:
                    skipped_missing += 1
                    continue
                u = users_by_id[uid]
                u_acc = getattr(u, "account", None)
                if u_acc is not None and not account_approval_support_mod.account_may_use_app(
                    u_acc
                ):
                    skipped_account_restricted += 1
                    continue
                if _directory_user_is_machine_room_role(uid):
                    skipped_machine_room += 1
                    continue

                existing = existing_members.get(uid)
                if existing is None and uid not in known_member_ids:
                    existing = ProjectMember.query.filter_by(
                        project_id=int(p.id), user_id=int(uid)
                    ).first()
                    if existing is not None:
                        existing_members[uid] = existing
                        known_member_ids.add(uid)

                if scope_filter and scope_filter in valid_scope_keys:
                    elig = jtms_add.get_scope_eligibility_for_user(
                        u, scope_filter, SystemMasterEntry=SystemMasterEntry
                    )
                    emp_policy = esup.user_employment_policy_summary(
                        db,
                        SystemMasterEntry,
                        EmploymentScopeLink,
                        u,
                        getattr(u, "account", None),
                    )
                    emp_ok = esup.employment_allows_project_scope_key(
                        emp_policy, scope_filter
                    )
                    if not elig.get("eligible") and not eligibility_override:
                        skipped_ineligible += 1
                        continue
                    if not emp_ok and not employment_override:
                        skipped_ineligible += 1
                        continue
                    reason = (
                        override_reason
                        if (not elig.get("eligible") or not emp_ok)
                        else None
                    )
                    if existing is not None:
                        before_scope = (existing.assigned_post_scope_code or "").strip() or None
                        before_role = (existing.assignment_role_type or "").strip() or None
                        existing.assigned_post_scope_code = scope_filter
                        if assignment_role:
                            existing.assignment_role_type = assignment_role
                        existing.eligibility_override_reason = reason
                        updated += 1
                        import project_activity_hooks as pah

                        chg = {}
                        after_scope = (existing.assigned_post_scope_code or "").strip() or None
                        after_role = (existing.assignment_role_type or "").strip() or None
                        if before_scope != after_scope:
                            chg["assigned_post_scope_code"] = {"old": before_scope, "new": after_scope}
                        if before_role != after_role:
                            chg["assignment_role_type"] = {"old": before_role, "new": after_role}
                        pah.log_member_updated(
                            p.id,
                            user_id=uid,
                            user_name=(u.name or u.email or f"User {uid}"),
                            changes=chg,
                        )
                        continue
                    db.session.add(
                        ProjectMember(
                            project_id=p.id,
                            user_id=uid,
                            assigned_post_scope_code=scope_filter,
                            assignment_role_type=assignment_role,
                            eligibility_override_reason=reason,
                        )
                    )
                else:
                    if existing is not None or uid in known_member_ids:
                        skipped_existing += 1
                        continue
                    db.session.add(ProjectMember(project_id=p.id, user_id=uid))
                known_member_ids.add(uid)
                added += 1
                import project_activity_hooks as pah

                pah.log_member_added(
                    p.id,
                    user_id=uid,
                    user_name=(u.name or u.email or f"User {uid}"),
                    scope=scope_filter,
                )
            db.session.commit()
        except sa_exc.IntegrityError:
            db.session.rollback()
            flash(
                "Could not add one or more team members — they may already be on this project.",
                "error",
            )
            return redirect(url_for("project_team", project_id=p.id))
        if added:
            flash(f"Added {added} team member(s) to the project.", "success")
        if updated:
            flash(f"Updated scope for {updated} existing team member(s).", "success")
        if skipped_existing:
            flash(f"{skipped_existing} selected user(s) were already on this project.", "warning")
        if skipped_missing:
            flash(f"{skipped_missing} selected user(s) were not found.", "error")
        if skipped_machine_room:
            flash(
                "Machine Room users cannot be added to project teams.",
                "warning",
            )
        if skipped_ineligible:
            flash(
                f"{skipped_ineligible} user(s) skipped — job title or employment not eligible for this scope. Use admin override to add anyway.",
                "warning",
            )
        if skipped_account_restricted:
            flash(
                f"{skipped_account_restricted} user(s) skipped — their account is suspended/disabled/pending approval.",
                "warning",
            )
        return redirect(url_for("project_team", project_id=p.id))

