    @app.route("/project/<int:project_id>/audio-library/link-folder", methods=["POST"])
    def project_audio_library_link_folder(project_id: int):
        wants_json = "application/json" in (request.headers.get("Accept") or "").lower()
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None:
            msg = "Please sign in to continue."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            msg = "You do not have access to that project."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("projects_list"))
        payload = request.get_json(silent=True) or {}
        library_id = request.form.get("library_id", type=int) or payload.get("library_id")
        mount_id = request.form.get("mount_id", type=int) or payload.get("mount_id")
        folder_path = (request.form.get("folder_path") or payload.get("folder_path") or "").strip().replace(
            "\\", "/"
        )
        raw_episode_id = request.form.get("episode_id") or payload.get("episode_id")
        raw_scene_id = request.form.get("scene_id") or payload.get("scene_id")
        usage_type = ml.parse_link_usage_type(request.form.get("usage_type") or payload.get("usage_type"))
        episode_id: int | None = None
        scene_id: int | None = None
        try:
            if raw_episode_id not in (None, ""):
                episode_id = int(raw_episode_id)
        except (TypeError, ValueError):
            episode_id = None
        try:
            if raw_scene_id not in (None, ""):
                scene_id = int(raw_scene_id)
        except (TypeError, ValueError):
            scene_id = None
        if library_id is not None:
            library_id = int(library_id)
        if mount_id is not None:
            mount_id = int(mount_id)
        if library_id is None or mount_id is None:
            msg = "Library and mount are required."
            if wants_json:
                return jsonify({"ok": False, "error": "invalid", "message": msg}), 400
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        lib = db.session.get(ProjectAudioLibrary, int(library_id))
        if lib is None or int(lib.project_id) != int(p.id):
            msg = "Invalid target library."
            if wants_json:
                return jsonify({"ok": False, "error": "invalid_library", "message": msg}), 400
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        mount = db.session.get(MusicMount, int(mount_id))
        if mount is None:
            msg = "Invalid mount."
            if wants_json:
                return jsonify({"ok": False, "error": "invalid_mount", "message": msg}), 400
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        # A source folder belongs to a project only once, regardless of which
        # project audio library was selected as its destination.
        exists = ProjectAudioFolder.query.filter_by(
            project_id=p.id,
            mount_id=mount.id,
            folder_path=folder_path,
        ).first()
        if episode_id is not None:
            ep_row = db.session.get(ProductionEpisode, int(episode_id))
            if ep_row is None or int(ep_row.project_id) != int(p.id):
                msg = "Invalid episode for this project."
                if wants_json:
                    return jsonify(ml.music_json_err(msg, error="invalid_episode")), 400
                flash(msg, "error")
                return redirect(url_for("project_audio_library", project_id=p.id))
        if scene_id is not None:
            sc_row = db.session.get(ProductionScene, int(scene_id))
            if sc_row is None:
                msg = "Invalid scene."
                if wants_json:
                    return jsonify(ml.music_json_err(msg, error="invalid_scene")), 400
                flash(msg, "error")
                return redirect(url_for("project_audio_library", project_id=p.id))
            if episode_id is not None and int(sc_row.episode_id) != int(episode_id):
                msg = "Scene does not belong to the selected episode."
                if wants_json:
                    return jsonify(ml.music_json_err(msg, error="invalid_scene")), 400
                flash(msg, "error")
                return redirect(url_for("project_audio_library", project_id=p.id))
        if exists is None:
            db.session.add(
                ProjectAudioFolder(
                    project_id=p.id,
                    library_id=lib.id,
                    mount_id=mount.id,
                    folder_path=folder_path,
                    episode_id=episode_id,
                    scene_id=scene_id,
                    usage_type=usage_type or "",
                )
            )
            db.session.commit()
            msg = "Indexed folder linked to project library."
            sample_file = (
                MusicFile.query.filter_by(mount_id=mount.id, folder=folder_path)
                .order_by(MusicFile.id.asc())
                .first()
            )
            if sample_file is not None:
                try:
                    _music_record_usage(
                        file_id=int(sample_file.id),
                        action="link_folder_to_project",
                        actor=actor,
                        project_id=int(p.id),
                        episode_id=episode_id,
                        scene_id=scene_id,
                        notes=f"folder={folder_path}",
                    )
                except Exception:
                    app.logger.exception("link_folder usage track")
            if wants_json:
                return jsonify(ml.music_json_ok(msg, data={"linked": True}))
            flash(msg, "success")
        else:
            msg = "That folder is already linked to this project."
            if wants_json:
                return jsonify(ml.music_json_err(msg, error="already_linked")), 409
            flash(msg, "warning")
        return redirect(url_for("project_audio_library", project_id=p.id))

    @app.route("/project/<int:project_id>/audio-library/unlink-folder/<int:link_id>", methods=["POST"])
    def project_audio_library_unlink_folder(project_id: int, link_id: int):
        wants_json = "application/json" in (request.headers.get("Accept") or "").lower()
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_manage_project_team_for(actor, project_id):
            msg = "Only administrators, super users, producers, or Post-production Team members on this project can manage project audio libraries."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            msg = "You do not have access to that project."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("projects_list"))
        link = db.session.get(ProjectAudioFolder, link_id)
        if link is None or int(link.project_id) != int(p.id):
            msg = "Linked folder not found."
            if wants_json:
                return jsonify({"ok": False, "error": "not_found", "message": msg}), 404
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        db.session.delete(link)
        db.session.commit()
        msg = "Folder removed from project audio library."
        if wants_json:
            return jsonify({"ok": True, "message": msg})
        flash(msg, "success")
        return redirect(url_for("project_audio_library", project_id=p.id))

    @app.route("/project/<int:project_id>/audio-library/move-folder/<int:link_id>", methods=["POST"])
    def project_audio_library_move_folder(project_id: int, link_id: int):
        wants_json = "application/json" in (request.headers.get("Accept") or "").lower()
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_move_project_audio_folders_for(actor, project_id):
            msg = "You do not have permission to move folders in this project audio library."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=project_id))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            msg = "You do not have access to that project."
            if wants_json:
                return jsonify({"ok": False, "error": "forbidden", "message": msg}), 403
            flash(msg, "error")
            return redirect(url_for("projects_list"))
        link = db.session.get(ProjectAudioFolder, int(link_id))
        if link is None or int(link.project_id) != int(p.id):
            msg = "Linked folder not found."
            if wants_json:
                return jsonify({"ok": False, "error": "not_found", "message": msg}), 404
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        payload = request.get_json(silent=True) or {}
        target_library_id = payload.get("target_library_id", request.form.get("target_library_id", type=int))
        try:
            target_library_id = int(target_library_id)
        except (TypeError, ValueError):
            target_library_id = 0
        target_lib = db.session.get(ProjectAudioLibrary, target_library_id)
        if target_lib is None or int(target_lib.project_id) != int(p.id):
            msg = "Target library not found."
            if wants_json:
                return jsonify({"ok": False, "error": "invalid_library", "message": msg}), 400
            flash(msg, "error")
            return redirect(url_for("project_audio_library", project_id=p.id))
        if int(link.library_id) == int(target_lib.id):
            msg = "Folder is already in that library."
            if wants_json:
                return jsonify({"ok": True, "moved": False, "message": msg})
            flash(msg, "warning")
            return redirect(url_for("project_audio_library", project_id=p.id))

        dupe = ProjectAudioFolder.query.filter_by(
            project_id=p.id,
            library_id=target_lib.id,
            mount_id=link.mount_id,
            folder_path=link.folder_path,
        ).first()
        if dupe is not None and int(dupe.id) != int(link.id):
            db.session.delete(link)
            db.session.commit()
            msg = "Folder already existed in target library. Duplicate link removed."
            if wants_json:
                return jsonify({"ok": True, "moved": True, "deduped": True, "message": msg})
            flash(msg, "success")
            return redirect(url_for("project_audio_library", project_id=p.id))

        link.library_id = int(target_lib.id)
        db.session.commit()
        msg = "Folder moved to target library."
        if wants_json:
            return jsonify({"ok": True, "moved": True, "message": msg})
        flash(msg, "success")
        return redirect(url_for("project_audio_library", project_id=p.id))

    @app.route("/project/<int:project_id>/audio-library/<int:library_id>/files")
    def project_audio_library_files(project_id: int, library_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_access_project(actor, project_id):
            return jsonify({"error": "forbidden"}), 403
        lib = db.session.get(ProjectAudioLibrary, library_id)
        if lib is None or int(lib.project_id) != int(project_id):
            return jsonify({"error": "not_found"}), 404
        rows = (
            MusicFile.query.options(joinedload(MusicFile.mount))
            .join(
                ProjectAudioFolder,
                and_(
                    MusicFile.mount_id == ProjectAudioFolder.mount_id,
                    MusicFile.folder == ProjectAudioFolder.folder_path,
                ),
            )
            .filter(ProjectAudioFolder.project_id == project_id)
            .filter(ProjectAudioFolder.library_id == library_id)
            .order_by(MusicFile.name.asc())
            .all()
        )
        return jsonify(
            {
                "ok": True,
                "selection": {"kind": "library", "library_id": int(library_id)},
                "files": _serialize_project_audio_files(rows),
            }
        )

    @app.route("/project/<int:project_id>/audio-library/files")
    def project_audio_library_files_query(project_id: int):
        actor = db.session.get(Account, session.get("account_id"))
        if actor is None or not account_can_access_project(actor, project_id):
            return jsonify({"error": "forbidden"}), 403
        library_id = request.args.get("library_id", type=int)
        link_id = request.args.get("link_id", type=int)
        if link_id:
            link = (
                ProjectAudioFolder.query.options(joinedload(ProjectAudioFolder.mount))
                .filter_by(id=link_id, project_id=project_id)
                .first()
            )
            if link is None:
                return jsonify({"error": "not_found"}), 404
            rows = (
                MusicFile.query.options(joinedload(MusicFile.mount))
                .filter(
                    MusicFile.mount_id == link.mount_id,
                    MusicFile.folder == (link.folder_path or ""),
                )
                .order_by(MusicFile.name.asc())
                .all()
            )
            return jsonify(
                {
                    "ok": True,
                    "selection": {
                        "kind": "link",
                        "link_id": int(link.id),
                        "library_id": int(link.library_id or 0),
                        "folder_path": link.folder_path or "",
                        "mount_id": int(link.mount_id or 0),
                        "mount_name": (link.mount.name if link.mount else "Mount") or "Mount",
                    },
                    "files": _serialize_project_audio_files(rows),
                }
            )
        if library_id:
            lib = db.session.get(ProjectAudioLibrary, library_id)
            if lib is None or int(lib.project_id) != int(project_id):
                return jsonify({"error": "not_found"}), 404
            rows = (
                MusicFile.query.options(joinedload(MusicFile.mount))
                .join(
                    ProjectAudioFolder,
                    and_(
                        MusicFile.mount_id == ProjectAudioFolder.mount_id,
                        MusicFile.folder == ProjectAudioFolder.folder_path,
                    ),
                )
                .filter(ProjectAudioFolder.project_id == project_id)
                .filter(ProjectAudioFolder.library_id == library_id)
                .order_by(MusicFile.name.asc())
                .all()
            )
            return jsonify(
                {
                    "ok": True,
                    "selection": {"kind": "library", "library_id": int(library_id)},
                    "files": _serialize_project_audio_files(rows),
                }
            )
        return jsonify({"error": "library_id or link_id required"}), 400

    def _purge_project_dependents(project: Project) -> None:
        """Delete rows that block project removal (NOT NULL project_id or audio library FKs)."""
        pid = int(project.id)

        lib_ids = [
            int(l.id) for l in ProjectAudioLibrary.query.filter_by(project_id=pid).all()
        ]
        if lib_ids:
            ActionItem.query.filter(ActionItem.audio_library_id.in_(lib_ids)).update(
                {ActionItem.audio_library_id: None}, synchronize_session=False
            )
        ActionItem.query.filter_by(project_id=pid).update(
            {ActionItem.audio_library_id: None}, synchronize_session=False
        )
        ProjectAudioFolder.query.filter_by(project_id=pid).delete(synchronize_session=False)
        for lib in ProjectAudioLibrary.query.filter_by(project_id=pid).all():
            lib.parent_id = None
        db.session.flush()
        ProjectAudioLibrary.query.filter_by(project_id=pid).delete(synchronize_session=False)

        ce_ids = [
            int(ce.id) for ce in ColorEpisode.query.filter_by(project_id=pid).all()
        ]
        if ce_ids:
            ColorEpisode.query.filter(ColorEpisode.id.in_(ce_ids)).update(
                {
                    ColorEpisode.final_version_id: None,
                    ColorEpisode.locked_version_id: None,
                    ColorEpisode.editing_item_id: None,
                    ColorEpisode.edit_version_id: None,
                    ColorEpisode.source_edit_version_id_at_start: None,
                },
                synchronize_session=False,
            )
            ColorEpisodeGalleryShare.query.filter(
                ColorEpisodeGalleryShare.color_episode_id.in_(ce_ids)
            ).delete(synchronize_session=False)
            ColorActivity.query.filter(ColorActivity.color_episode_id.in_(ce_ids)).delete(
                synchronize_session=False
            )
            ColorDelivery.query.filter(ColorDelivery.color_episode_id.in_(ce_ids)).delete(
                synchronize_session=False
            )
            ColorReviewNote.query.filter(ColorReviewNote.color_episode_id.in_(ce_ids)).delete(
                synchronize_session=False
            )
            ColorEpisodeGalleryFrame.query.filter(
                ColorEpisodeGalleryFrame.color_episode_id.in_(ce_ids)
            ).delete(synchronize_session=False)
            ColorEpisodeGalleryBatch.query.filter(
                ColorEpisodeGalleryBatch.color_episode_id.in_(ce_ids)
            ).delete(synchronize_session=False)
            ColorVersion.query.filter(ColorVersion.color_episode_id.in_(ce_ids)).delete(
                synchronize_session=False
            )
            ColorEpisode.query.filter(ColorEpisode.id.in_(ce_ids)).delete(synchronize_session=False)
        ColorEpisodeGalleryShare.query.filter_by(project_id=pid).delete(synchronize_session=False)
        ColorActivity.query.filter_by(project_id=pid).delete(synchronize_session=False)
        for color_item in ColorItem.query.filter_by(project_id=pid).all():
            db.session.delete(color_item)
        ColorLookReference.query.filter_by(project_id=pid).delete(synchronize_session=False)

        item_ids = [
            int(i.id) for i in EditingItem.query.filter_by(project_id=pid).all()
        ]
        if item_ids:
            EditingItemDelivery.query.filter(
                EditingItemDelivery.editing_item_id.in_(item_ids)
            ).delete(synchronize_session=False)
            EditingItemReviewNote.query.filter(
                EditingItemReviewNote.editing_item_id.in_(item_ids)
            ).delete(synchronize_session=False)
            EditingItemSceneLink.query.filter(
                EditingItemSceneLink.editing_item_id.in_(item_ids)
            ).delete(synchronize_session=False)
            EditingItemDepartmentRoute.query.filter(
                EditingItemDepartmentRoute.editing_item_id.in_(item_ids)
            ).delete(synchronize_session=False)
            EditingItemVersion.query.filter(
                EditingItemVersion.editing_item_id.in_(item_ids)
            ).delete(synchronize_session=False)
            EditingItem.query.filter(EditingItem.id.in_(item_ids)).delete(
                synchronize_session=False
            )

        VfxProjectDiscussion.query.filter_by(project_id=pid).delete(synchronize_session=False)
        VfxMgmtActivity.query.filter_by(project_id=pid).delete(synchronize_session=False)
        for link in VfxClientReviewLink.query.filter_by(project_id=pid).all():
            db.session.delete(link)

        for disk in HardDisk.query.filter_by(project_id=pid).all():
            db.session.delete(disk)

        ActionItem.query.filter_by(project_id=pid).delete(synchronize_session=False)
        TodoItem.query.filter_by(project_id=pid).delete(synchronize_session=False)
        StickyNote.query.filter_by(project_id=pid).delete(synchronize_session=False)
        ScriptDocument.query.filter_by(project_id=pid).delete(synchronize_session=False)
        AudioUsage.query.filter_by(project_id=pid).delete(synchronize_session=False)

        sv_ids = [
            int(sv.id) for sv in SceneVersion.query.filter_by(project_id=pid).all()
        ]
        if sv_ids:
            SceneVersionComment.query.filter(
                SceneVersionComment.scene_version_id.in_(sv_ids)
            ).delete(synchronize_session=False)
            SceneVersion.query.filter(SceneVersion.id.in_(sv_ids)).delete(
                synchronize_session=False
            )
        EpisodeVersion.query.filter_by(project_id=pid).delete(synchronize_session=False)
        EpisodeNote.query.filter_by(project_id=pid).delete(synchronize_session=False)

    @app.route("/projects/<int:project_id>/delete", methods=["POST"])
    def projects_delete(project_id: int):
        actor = account_from_session()
        if actor is None or not actor.is_admin:
            abort(403)
        p = db.session.get(Project, project_id)
        if p is None:
            flash("That project no longer exists.", "info")
            return redirect(url_for("projects_list"))
        _purge_project_dependents(p)
        # Remove dependent rows first before deleting the project.
        for b in Booking.query.filter_by(project_id=p.id).all():
            db.session.delete(b)
        scene_ids = [
            int(sc.id)
            for sc in (
                ShootingDayScene.query.join(ShootingDay, ShootingDayScene.shooting_day_id == ShootingDay.id)
                .filter(ShootingDay.project_id == p.id)
                .all()
            )
        ]
        if scene_ids:
            for mk in VfxSceneMarker.query.filter(VfxSceneMarker.scene_id.in_(scene_ids)).all():
                seen_paths: set[str] = set()
                for attr in ("thumbnail", "thumbnail_full"):
                    t = (getattr(mk, attr, None) or "").strip()
                    if t and not _vfx_media_is_remote(t) and t not in seen_paths:
                        seen_paths.add(t)
                        remove_vfx_version_file(t)
            VfxSceneMarker.query.filter(VfxSceneMarker.scene_id.in_(scene_ids)).delete(
                synchronize_session=False
            )
            shot_rows = VfxShot.query.filter(VfxShot.scene_id.in_(scene_ids)).all()
            shot_ids = [int(s.id) for s in shot_rows]
            if shot_ids:
                for sh in shot_rows:
                    rf = (sh.shot_ref_frame or "").strip()
                    if rf and not _vfx_media_is_remote(rf):
                        remove_vfx_version_file(rf)
                for ver in VfxVersion.query.filter(VfxVersion.shot_id.in_(shot_ids)).all():
                    img = (ver.image or "").strip()
                    if img and not (
                        img.lower().startswith("http://") or img.lower().startswith("https://")
                    ):
                        remove_vfx_version_file(img)
                VfxShotComment.query.filter(VfxShotComment.shot_id.in_(shot_ids)).delete(
                    synchronize_session=False
                )
                VfxVersion.query.filter(VfxVersion.shot_id.in_(shot_ids)).delete(synchronize_session=False)
            VfxShot.query.filter(VfxShot.scene_id.in_(scene_ids)).delete(synchronize_session=False)
            for rf in SceneReference.query.filter(SceneReference.scene_id.in_(scene_ids)).all():
                remove_scene_reference_file(rf.video_url)
            SceneReference.query.filter(SceneReference.scene_id.in_(scene_ids)).delete(
                synchronize_session=False
            )

        for cm in ChatMessage.query.filter_by(project_id=p.id).all():
            if cm.image_path:
                remove_chat_upload_file(cm.image_path)
            if cm.audio_path:
                remove_chat_upload_file(cm.audio_path)
            db.session.delete(cm)
        for rs in ProjectChatReadState.query.filter_by(project_id=p.id).all():
            db.session.delete(rs)
        for t in Task.query.filter_by(project_id=p.id).all():
            db.session.delete(t)
        for m in ProjectMember.query.filter_by(project_id=p.id).all():
            db.session.delete(m)
        deleted_name = (p.name or "").strip()
        deleted_pid = int(p.id)
        db.session.delete(p)
        db.session.commit()
        log_security_event(
            "project_delete",
            account_id=actor.id if actor else None,
            entity_type="project",
            entity_id=deleted_pid,
            project_id=deleted_pid,
            details={"name": deleted_name},
        )
        flash("Project and its tasks were removed.", "success")
        return redirect(url_for("projects_list"))

    @app.route("/projects/<int:project_id>/archive", methods=["POST"])
    def projects_archive(project_id: int):
        actor = account_from_session()
        if actor is None or not account_is_elevated(actor):
            flash("Only administrators and super users can archive projects.", "error")
            return redirect(url_for("projects_list"))
        p = Project.query.get_or_404(project_id)
        if not account_can_access_project(actor, p.id):
            flash("You do not have access to that project.", "error")
            return redirect(url_for("projects_list"))
        p.project_status = PROJECT_STATUS_ARCHIVED
        db.session.commit()
        flash("Project archived.", "success")
        return redirect(url_for("projects_list"))

    def _normalize_update_category(raw: str | None) -> str:
        s = str(raw or "").strip().lower().replace(" ", "_")
        if s in UPDATE_CATEGORIES:
            return s
        for key, label in UPDATE_CATEGORY_LABELS.items():
            if s == label.lower().replace(" ", "_"):
                return key
        return "feature"

    def _normalize_update_importance(raw: str | None) -> str:
        s = str(raw or "").strip().lower()
        return s if s in UPDATE_IMPORTANCE_LEVELS else "normal"

    def serialize_product_update(row: ProductUpdate) -> dict:
        cat = _normalize_update_category(row.category)
        imp = _normalize_update_importance(row.importance)
        proj = row.project
        author = row.author
        return {
            "id": int(row.id),
            "title": row.title or "",
            "description": row.description or "",
            "category": cat,
            "categoryLabel": UPDATE_CATEGORY_LABELS.get(cat, cat.title()),
            "importance": imp,
            "isPublishedToDashboard": bool(row.is_published_to_dashboard),
            "createdAt": isoformat_stored_instant(
                row.created_at if isinstance(row.created_at, datetime) else None
            ),
            "createdAtDisplay": format_datetime_cairo(
                row.created_at if isinstance(row.created_at, datetime) else None,
                "%d %b %Y · %H:%M",
            ),
            "createdById": int(row.created_by),
            "createdByName": (
                (author.display_name or author.email or "Admin").strip()
                if author is not None
                else "Admin"
            ),
            "projectId": int(row.project_id) if row.project_id else None,
            "projectName": (proj.name or "").strip() if proj is not None else "",
            "source": (row.source or "manual").strip().lower(),
        }

    def queue_draft_product_update(
        *,
        title: str,
        description: str = "",
        category: str = "feature",
        importance: str = "normal",
        created_by_account_id: int,
        project_id: int | None = None,
    ) -> ProductUpdate:
        """Create an unpublished draft entry (future Cursor/agent automation — not wired yet)."""
        row = ProductUpdate(
            title=str(title or "").strip()[:240],
            description=str(description or "").strip(),
            category=_normalize_update_category(category),
            importance=_normalize_update_importance(importance),
            is_published_to_dashboard=False,
            created_by=int(created_by_account_id),
            created_at=now_local(),
            project_id=project_id,
            source="draft_auto",
        )
        db.session.add(row)
        db.session.flush()
        return row

    def fetch_dashboard_whats_new(limit: int = 12) -> list[dict]:
        rows = (
            ProductUpdate.query.filter(ProductUpdate.is_published_to_dashboard.is_(True))
            .options(joinedload(ProductUpdate.author), joinedload(ProductUpdate.project))
            .order_by(ProductUpdate.created_at.desc(), ProductUpdate.id.desc())
            .limit(max(1, min(int(limit), 50)))
            .all()
        )
        return [serialize_product_update(r) for r in rows]

    def build_updates_admin_payload() -> dict:
        rows = (
            ProductUpdate.query.options(
                joinedload(ProductUpdate.author), joinedload(ProductUpdate.project)
            )
            .order_by(ProductUpdate.created_at.desc(), ProductUpdate.id.desc())
            .all()
        )
        projects = Project.query.order_by(Project.name.asc()).all()
        return {
            "updates": [serialize_product_update(r) for r in rows],
            "categories": [
                {"key": k, "label": UPDATE_CATEGORY_LABELS[k]} for k in UPDATE_CATEGORIES
            ],
            "importanceLevels": list(UPDATE_IMPORTANCE_LEVELS),
            "projects": [{"id": int(p.id), "name": p.name or ""} for p in projects],
        }

