    USERS_PER_PAGE = 50

    @app.route("/users/<int:user_id>/avatar")
    def user_avatar_file(user_id: int):
        actor = account_from_session()
        if actor is None:
            abort(404)
        target = db.session.get(User, user_id)
        if target is None:
            abort(404)
        kind = (target.avatar_kind or "preset").lower()
        if kind == "upload" and (target.avatar_upload or "").strip():
            filename = target.avatar_upload.strip()
            if "/" in filename or "\\" in filename or ".." in filename or filename.startswith("."):
                abort(404)
            resp = send_from_directory(
                upload_root,
                filename,
                mimetype=avatar_mimetype_for_filename(filename),
            )
            resp.headers["Cache-Control"] = "private, max-age=3600"
            return resp
        preset_name = preset_avatar_static_path(target.avatar_preset)
        resp = send_from_directory(
            os.path.join(app.root_path, "static"),
            preset_name,
            mimetype="image/svg+xml",
        )
        resp.headers["Cache-Control"] = "private, max-age=3600"
        return resp

    @app.route("/users")
    def users_list():
        actor = account_from_session()
        if not account_can_access_admin_settings(actor):
            flash("Only administrators can access the Users page.", "error")
            return redirect(url_for("index"))
        try:
            page = max(1, int(request.args.get("page") or 1))
        except (TypeError, ValueError):
            page = 1
        total_users = User.query.count()
        pages = max(1, math.ceil(total_users / USERS_PER_PAGE)) if total_users else 1
        if page > pages:
            page = pages
        from project_settings import POST_SCOPE_FIELDS, collect_user_post_scope_keys

        users = (
            User.query.options(
                joinedload(User.job_title).joinedload(JobTitle.category),
                joinedload(User.account),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.category),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.post_scope_links)
                .joinedload(JobTitlePostScopeLink.post_scope_entry),
                joinedload(User.user_job_title_links)
                .joinedload(UserJobTitle.job_title)
                .joinedload(JobTitle.category)
                .joinedload(JobCategory.post_scope_links)
                .joinedload(JobCategoryPostScopeLink.post_scope_entry),
            )
            .order_by(User.name)
            .offset((page - 1) * USERS_PER_PAGE)
            .limit(USERS_PER_PAGE)
            .all()
        )
        user_post_scope_keys = {
            int(u.id): sorted(collect_user_post_scope_keys(u)) for u in users
        }
        categories = (
            JobCategory.query.options(joinedload(JobCategory.job_titles))
            .order_by(JobCategory.sort_order.asc(), JobCategory.name.asc())
            .all()
        )
        job_title_groups = job_title_picker_groups(categories)
        orphan_titles = [
            jt
            for jt in JobTitle.query.filter(JobTitle.category_id.is_(None))
            .order_by(JobTitle.name.asc())
            .all()
            if getattr(jt, "is_active", True)
        ]
        if orphan_titles:
            job_title_groups.append((UNCLASSIFIED_JOB_CATEGORY_NAME, orphan_titles))
        from user_role_mapping import access_config_for_job_titles, user_access_state_for_edit

        all_titles = JobTitle.query.options(joinedload(JobTitle.category)).order_by(JobTitle.name).all()
        user_access_config = access_config_for_job_titles(all_titles)
        user_access_by_id = {}
        for u in users:
            if not u.account_id or not u.account:
                continue
            primary = u.assigned_job_titles()
            primary_title = primary[0] if primary else None
            primary_name = primary_title.name if primary_title else None
            user_access_by_id[int(u.id)] = user_access_state_for_edit(
                u.account.role,
                getattr(u.account, "guest_access_level", None),
                primary_name,
                job_title=primary_title,
            )
        import employment_structure_support as esup
        import job_titles_master_support as jtms

        job_title_meta = jtms.job_title_metadata_for_picker(
            db, JobTitle, JobTitleEmploymentTypeLink, JobTitlePostScopeLink, SystemMasterEntry
        )

        user_employment_policy = {
            int(u.id): esup.user_employment_policy_summary(
                db, SystemMasterEntry, EmploymentScopeLink, u, getattr(u, "account", None)
            )
            for u in users
        }
        user_job_title_scope_chips = {
            int(u.id): jtms.job_title_eligible_scope_chips(u, SystemMasterEntry) for u in users
        }
        user_account_status = {
            int(u.id): account_approval_support_mod.normalized_account_status(
                getattr(u.account, "status", None) if u.account else None
            )
            for u in users
            if u.account_id and u.account
        }
        return render_template(
            "users.html",
            users=users,
            job_title_groups=job_title_groups,
            job_title_picker_data=job_title_picker_json(job_title_groups, categories, job_title_meta),
            user_post_scope_keys=user_post_scope_keys,
            user_employment_policy=user_employment_policy,
            user_job_title_scope_chips=user_job_title_scope_chips,
            post_scope_fields=POST_SCOPE_FIELDS,
            page=page,
            pages=pages,
            total_users=total_users,
            users_per_page=USERS_PER_PAGE,
            user_access_config=user_access_config,
            user_access_by_id=user_access_by_id,
            user_account_status=user_account_status,
        )

    @app.route("/users/<int:user_id>/role", methods=["POST"])
    def users_set_role(user_id: int):
        actor = account_from_session()
        if not account_can_access_admin_settings(actor):
            flash("Only administrators can change user roles.", "error")
            return redirect(url_for("index"))
        u = User.query.get_or_404(user_id)
        if not u.account_id:
            flash("External users are not linked to an account — there is no role to change.", "error")
            return redirect(url_for("users_list"))
        acc = db.session.get(Account, u.account_id)
        if acc is None:
            flash("Account not found.", "error")
            return redirect(url_for("users_list"))
        role = (request.form.get("role") or "").strip().lower()
        if role not in ACCOUNT_ROLES:
            flash("Invalid role.", "error")
            return redirect(url_for("users_list"))
        if role == ROLE_ADMIN and not actor.is_admin:
            flash("Only administrators may assign the administrator role.", "error")
            return redirect(url_for("users_list"))
        if acc.is_admin and role != ROLE_ADMIN:
            if Account.query.filter_by(role=ROLE_ADMIN).count() <= 1:
                flash("Cannot demote the last administrator.", "error")
                return redirect(url_for("users_list"))
        acc.role = role
        if role == ROLE_GUEST:
            level = _normalized_guest_access_level(
                request.form.get("guest_access_level") or getattr(acc, "guest_access_level", None)
            )
            acc.guest_access_level = level
        else:
            acc.guest_access_level = GUEST_ACCESS_VIEWER
        db.session.commit()
        log_security_event(
            "role_change",
            account_id=actor.id if actor else None,
            entity_type="account",
            entity_id=acc.id,
            details={"user_id": user_id, "role": role},
        )
        flash("User role updated.", "success")
        return redirect(url_for("users_list"))

    @app.route("/users/<int:user_id>/access", methods=["POST"])
    def users_set_access(user_id: int):
        from user_role_mapping import (
            USER_TYPES,
            job_title_audience_matches,
            resolve_user_access,
            role_label,
            user_access_state_for_edit,
        )

        actor = account_from_session()
        wants_json = "application/json" in (request.headers.get("Accept") or "").lower()
        if not account_can_access_admin_settings(actor):
            msg = "Only administrators can change user access."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 403
            flash(msg, "error")
            return redirect(url_for("index"))
        u = User.query.get_or_404(user_id)
        if not u.account_id:
            msg = "External users are not linked to an account — there is no access role to change."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(url_for("users_list"))
        acc = db.session.get(Account, u.account_id)
        if acc is None:
            msg = "Account not found."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 404
            flash(msg, "error")
            return redirect(url_for("users_list"))

        user_type = (request.form.get("user_type") or "").strip().lower()
        if user_type not in USER_TYPES:
            msg = "User type is required."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(url_for("users_list"))

        raw_jt_id = request.form.get("job_title_id")
        title_ids_raw = request.form.getlist("job_title_ids")
        if not title_ids_raw and raw_jt_id:
            title_ids_raw = [raw_jt_id]
        titles: list[JobTitle] = []
        seen_ids: set[int] = set()
        for raw in title_ids_raw:
            try:
                tid = int(raw)
            except (TypeError, ValueError):
                continue
            if tid <= 0 or tid in seen_ids:
                continue
            jt_row = JobTitle.query.get(tid)
            if jt_row is None:
                continue
            seen_ids.add(tid)
            titles.append(jt_row)
        if not titles:
            msg = "At least one job title is required."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(url_for("users_list"))

        for jt in titles:
            if not getattr(jt, "is_active", True):
                msg = "Selected job title is inactive."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))
            cat = getattr(jt, "category", None)
            if cat is not None and not getattr(cat, "is_active", True):
                msg = "Selected job title belongs to an inactive category."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))
            audience = getattr(jt, "user_type", None) or "employee"
            if not job_title_audience_matches(user_type, audience):
                msg = "Selected job title does not match the chosen user type."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))

        jt = titles[0]

        override_enabled = (request.form.get("role_override") or "").strip().lower() in (
            "1",
            "true",
            "on",
            "yes",
        )
        manual_role = (request.form.get("role") or "").strip().lower() or None
        if override_enabled and not actor.is_admin:
            msg = "Only administrators may override automatic role assignment."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 403
            flash(msg, "error")
            return redirect(url_for("users_list"))

        primary = u.assigned_job_titles()
        current_state = user_access_state_for_edit(
            acc.role,
            getattr(acc, "guest_access_level", None),
            primary[0].name if primary else None,
            job_title=primary[0] if primary else None,
        )
        try:
            resolved = resolve_user_access(
                user_type=user_type,
                job_title_name=jt.name,
                job_title=jt,
                override_enabled=override_enabled,
                manual_role=manual_role,
                current_logical_role=current_state.get("logical_role"),
            )
        except ValueError:
            msg = "Invalid user type."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 400
            flash(msg, "error")
            return redirect(url_for("users_list"))

        logical_role = resolved["logical_role"]
        mapped_role = resolved["mapped_role"]
        account_role = resolved["account_role"]
        guest_level = resolved["guest_access_level"]

        if not override_enabled:
            if user_type == "employee" and logical_role in (
                "guest_viewer",
                "guest_reviewer",
                "guest_approver",
            ):
                msg = "Employee users cannot receive guest access roles without an override."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))
            if user_type == "client" and logical_role not in (
                "guest_viewer",
                "guest_reviewer",
                "guest_approver",
            ):
                msg = "Client / guest users must have a guest access role."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))

        if account_role == ROLE_ADMIN and not actor.is_admin:
            msg = "Only administrators may assign the administrator role."
            if wants_json:
                return jsonify({"ok": False, "error": msg}), 403
            flash(msg, "error")
            return redirect(url_for("users_list"))
        if acc.is_admin and account_role != ROLE_ADMIN:
            if Account.query.filter_by(role=ROLE_ADMIN).count() <= 1:
                msg = "Cannot demote the last administrator."
                if wants_json:
                    return jsonify({"ok": False, "error": msg}), 400
                flash(msg, "error")
                return redirect(url_for("users_list"))

        requested_payload = {
            "account_id": int(acc.id),
            "user_id": int(u.id),
            "requested": {
                "user_type": user_type,
                "job_title_id": int(jt.id),
                "job_title_ids": [int(t.id) for t in titles],
                "role": account_role,
                "guest_access_level": guest_level,
                "logical_role": logical_role,
                "mapped_role": mapped_role,
                "department_code": getattr(u, "department_code", None),
                "company": getattr(u, "company", None),
                "employment_type_code": getattr(u, "employment_type_code", None),
            },
            "current": account_approval_support_mod.profile_snapshot(u, acc),
        }
        existing_permission = None
        if PermissionChangeRequest is not None:
            existing_permission = PermissionChangeRequest.query.filter_by(
                account_id=int(acc.id),
                status=account_approval_support_mod.REQUEST_PENDING,
            ).order_by(PermissionChangeRequest.id.desc()).first()
        if existing_permission is None and PermissionChangeRequest is not None:
            existing_permission = PermissionChangeRequest(account_id=int(acc.id))
            db.session.add(existing_permission)
        if existing_permission is not None:
            existing_permission.status = account_approval_support_mod.REQUEST_PENDING
            existing_permission.requested_values_json = json.dumps(
                requested_payload["requested"], ensure_ascii=False, sort_keys=True
            )
            existing_permission.admin_notes = None
            existing_permission.reviewed_by_account_id = None
            existing_permission.reviewed_at = None
            db.session.flush()

        acc.status = account_approval_support_mod.STATUS_PENDING_PERMISSION_APPROVAL
        acc.is_active = True
        acc.status_notes = None
        wf_req = workflow_engine.create_request(
            request_type=workflow_types_mod.REQUEST_TYPE_PERMISSION_CHANGE,
            created_by=actor,
            target_user_id=int(u.id),
            title=f"Permission change: {u.name}",
            description="Access role / permission-affecting change awaiting approval.",
            payload=requested_payload,
            priority=workflow_types_mod.PRIORITY_HIGH,
            legacy_request_type="permission_change_request",
            legacy_request_id=int(existing_permission.id) if existing_permission is not None else None,
            request=request,
            replace_existing_pending=True,
        )
        account_approval_support_mod.write_approval_audit(
            db,
            AccountApprovalAuditLog,
            action="permission_change_requested",
            actor_account_id=actor.id if actor else None,
            target_account_id=acc.id,
            target_user_id=u.id,
            entity_type="approval_request",
            entity_id=int(wf_req.id),
            old_values=requested_payload.get("current") or {},
            new_values=requested_payload.get("requested") or {},
            request=request,
        )
        db.session.commit()

        pending_msg = "Permission change request submitted for approval."
        if wants_json:
            return jsonify(
                {
                    "ok": True,
                    "pending_approval": True,
                    "message": pending_msg,
                    "user_id": u.id,
                    "user_type": user_type,
                    "job_title_id": jt.id,
                    "job_title_ids": [int(t.id) for t in titles],
                    "job_title_name": jt.name,
                    "job_titles": [
                        {
                            "id": int(t.id),
                            "name": t.name,
                            "category_name": ((t.category.name if t.category else None) or "").strip(),
                        }
                        for t in titles
                    ],
                    "logical_role": logical_role,
                    "mapped_role": mapped_role,
                    "role_label": role_label(logical_role),
                    "role_description": current_state.get("role_description", ""),
                    "role_mismatch": False,
                    "account_role": acc.role,
                    "guest_access_level": acc.guest_access_level,
                }
            )
        flash(pending_msg, "success")
        return redirect(url_for("users_list"))

