    @app.route("/control/titles/new", methods=["POST"])
    def control_title_new():
        title = (request.form.get("title") or "").strip()
        description = (request.form.get("description") or "").strip()
        post_scope_key = (request.form.get("post_scope_key") or "").strip()
        import task_preset_support as tps

        if not title or not post_scope_key:
            flash("Task title and post-production scope are required.", "error")
            return redirect(url_for("control_panel", section="post-scopes"))
        valid_keys = post_scope_key_set() | tps.preset_scope_key_set()
        if post_scope_key not in valid_keys:
            flash("Invalid post-production scope.", "error")
            return redirect(url_for("control_panel", section="post-scopes"))
        group = TaskGroup.query.filter_by(post_scope_key=post_scope_key).first()
        if not group:
            flash("Scope is not configured yet. Refresh the page and try again.", "error")
            return redirect(url_for("control_panel", section="post-scopes"))
        if TaskGroupTitle.query.filter_by(group_id=group.id, title=title).first():
            flash("That task title already exists in this scope.", "error")
            return redirect(url_for("control_panel", section="post-scopes"))
        mx = (
            db.session.query(db.func.max(TaskGroupTitle.sort_order))
            .filter(TaskGroupTitle.group_id == group.id)
            .scalar()
        )
        nxt = (mx if mx is not None else -1) + 1
        db.session.add(
            TaskGroupTitle(
                group_id=group.id,
                title=title,
                description=description,
                sort_order=nxt,
            )
        )
        db.session.commit()
        flash("Task title added.", "success")
        return redirect(url_for("control_panel", section="post-scopes"))

