    def _delete_job_title_row(jt: JobTitle) -> None:
        affected_user_ids = {
            int(row.user_id)
            for row in UserJobTitle.query.filter_by(job_title_id=jt.id).all()
        }
        UserJobTitle.query.filter_by(job_title_id=jt.id).delete()
        for uid in affected_user_ids:
            u = db.session.get(User, uid)
            if u is not None:
                resync_primary_job_title_id(u)
        for u in User.query.filter_by(job_title_id=jt.id).all():
            u.job_title_id = None
        db.session.delete(jt)

    @app.route("/control/job-titles/bulk-delete", methods=["POST"])
    def control_job_titles_bulk_delete():
        actor = account_from_session()
        if not account_can_access_admin_settings(actor):
            flash("Only administrators can manage job titles.", "error")
            return redirect(url_for("index"))
        try:
            category_id = int(request.form.get("category_id") or 0)
        except (TypeError, ValueError):
            category_id = 0
        ids_raw = request.form.getlist("job_title_ids")
        title_ids: list[int] = []
        for raw in ids_raw:
            try:
                title_ids.append(int(raw))
            except (TypeError, ValueError):
                continue
        title_ids = sorted(set(title_ids))
        if not title_ids:
            flash("Select at least one job title to delete.", "error")
            return employment_structure_redirect(category_id or None)
        deleted = 0
        redirect_cat = category_id or None
        for jtid in title_ids:
            jt = JobTitle.query.get(jtid)
            if jt is None:
                continue
            if redirect_cat is None and jt.category_id is not None:
                redirect_cat = int(jt.category_id)
            _delete_job_title_row(jt)
            deleted += 1
        db.session.commit()
        if deleted == 1:
            flash("1 job title removed. Users with that title had their selection cleared.", "success")
        else:
            flash(
                f"{deleted} job titles removed. Users with those titles had their selections cleared.",
                "success",
            )
        return employment_structure_redirect(redirect_cat)

